_UNCOPYABLE_LITERAL_TYPES: set[str] = set()


_TEMPORAL_LOOP_ARGUMENT_BINDINGS = frozenset({
    "loop_carried_seed",
    "loop_carried",
    "loop_continue_carried",
    "loop_latch_carried",
    "loop_result_port",
})


def _loop_rebound_value_ids(function: Any) -> frozenset:
    """Caller ids a loop rebinds, so a bare id cannot name them.

    Empty when the function declares no loop scope, which is the common
    case and costs one page lookup.
    """

    try:
        from .identity_concordance import (
            current_identity_book, loop_scope_declarations,
        )

        return frozenset(
            int(rebind["outer"])
            for declaration in loop_scope_declarations(
                current_identity_book(), str(function.name),
            )
            for rebind in declaration["rebinds"]
        )
    except Exception:
        return frozenset()


def _concordant_function_aliases(
    function: Any, *, include_output_identities: bool = False,
) -> dict[int, int]:
    """Read every exact alias receipt through the shared concordance.

    Function metadata is the durable snapshot used after compilation.  The
    planning page is the live authority used while regions and call frames
    are still changing.  Late compiler passes must consult both or a fact
    proved after region construction can disappear at precisely that stage.
    ``resolved_concordant_alias_bindings`` compares terminal residents, so
    equivalent one-hop and transitive spellings agree while genuinely
    different storage still refuses.
    """

    from .identity_concordance import resolved_concordant_alias_bindings

    metadata = dict(getattr(function, "metadata", {}) or {})
    ledgers: list[Any] = []
    if include_output_identities:
        ledgers.append(metadata.get("output_identity_aliases", ()) or ())
    ledgers.append(dict(metadata.get("value_aliases", {}) or {}))
    return resolved_concordant_alias_bindings(str(function.name), *ledgers)


def _publish_concordant_function_aliases(
    function: Any, bindings: Mapping[int, int],
) -> dict[int, int]:
    """Advance the live page and durable alias snapshot together."""

    from .identity_concordance import (
        current_identity_book,
        resolved_concordant_alias_bindings,
    )

    aliases = _concordant_function_aliases(function)
    page = current_identity_book().page("planning_value_concordance")
    aliases = resolved_concordant_alias_bindings(
        str(function.name), aliases, bindings, page=page,
    )
    for alias_id, resident_id in aliases.items():
        alias_id = int(alias_id)
        resident_id = int(resident_id)
        if page.latest((str(function.name), alias_id)) != resident_id:
            page.bind_alias(str(function.name), alias_id, resident_id)
    if aliases:
        function.metadata["value_aliases"] = aliases
    return aliases


def _concordant_function_resident(function: Any, value_id: int) -> int:
    """Return the terminal physical resident for one function-local value."""

    value_id = int(value_id)
    return int(_concordant_function_aliases(function).get(value_id, value_id))


def _debug_loop_carried_operands(
    functions: Mapping[str, Any], stage: str,
) -> None:
    """Report loop-carried operand object provenance at selected shell stages."""

    if not os.environ.get("TURING_DEBUG_LOOP_ALIAS_PUBLICATION"):
        return
    for function_name, function in functions.items():
        if "run_superstep__specialized" not in str(function_name):
            continue
        rows = []
        for block_name, block in function.blocks.items():
            for instruction_index, instruction in enumerate(block.instrs):
                attributes = dict(instruction.attributes or {})
                if (
                    instruction.op != "Phi"
                    or attributes.get("binding") != "loop_carried"
                    or attributes.get("updated_value_id") not in {274, 286}
                ):
                    continue
                rows.append((
                    str(block_name),
                    int(instruction_index),
                    int(instruction.res.id),
                    tuple((
                        int(argument.id),
                        id(argument),
                        tuple(sorted(dict(argument.accounting or {}).items())),
                    ) for argument in instruction.args),
                    int(attributes["updated_value_id"]),
                ))
        if rows:
            print(
                f"DEBUG-LOOP-CARRIED-STAGE {stage} {function_name}: {rows!r}",
                file=sys.stderr,
                flush=True,
            )


def _copy_literal_payload(payload: Any) -> Any:
    """Deep-copy a literal payload captured off a graph node, if it can be.

    Ingested stdlib source (``re._compiler`` and friends) puts objects behind
    ``Constant`` nodes whose payloads are not always deep-copyable. Sharing
    the original reference is the honest fallback: the payload already had
    that identity everywhere upstream, so aliasing here adds no hazard a copy
    would have removed.
    """

    try:
        return copy.deepcopy(payload)
    except Exception:
        type_name = type(payload).__qualname__
        if type_name not in _UNCOPYABLE_LITERAL_TYPES:
            _UNCOPYABLE_LITERAL_TYPES.add(type_name)
            import warnings

            warnings.warn(
                f"literal payload of type {type_name} is not deep-copyable; "
                "sharing the original reference",
                RuntimeWarning,
                stacklevel=3,
            )
        return payload


