@dataclass(frozen=True)
class FortranCShellExecutable:
    directory: Path
    executable_path: Path
    fortran_source_path: Path
    c_source_path: Path
    api_path: Path
    initial_state_path: Path
    final_outputs_path: Path
    entrypoint: str

    def run(
        self,
        *,
        frames: int = 1,
        files: Mapping[str, str | Path] | None = None,
        stream_frames: bool = False,
        capture_output: bool = True,
    ) -> subprocess.CompletedProcess[str]:
        if frames < 0:
            raise ValueError("native C shell frame count cannot be negative")
        arguments = [str(self.executable_path), str(frames)]
        if stream_frames:
            arguments.append("--stream-frames")
        for name, path in sorted(dict(files or {}).items()):
            arguments.extend(("--file-" + _identifier(name).replace("_", "-"), str(Path(path).resolve())))
        return subprocess.run(
            arguments,
            cwd=str(self.directory),
            env=dict(os.environ),
            capture_output=capture_output,
            text=True,
            check=True,
        )


# The product was originally reached through the Fortran backend.  Its host is
# now backend-neutral; retain the old class name as the compatibility spelling.
NativeCShellExecutable = FortranCShellExecutable


def _retained_parameter_identity(
    parameter_name: str,
    identity_history: Iterable[int],
    retained_parameters: Iterable[tuple[str, int]],
) -> int | None:
    """Select the physical formal retained for one authored parameter.

    Source identity history includes structural placeholders as well as the
    later physical projection that survives repository-SSA lowering.  The
    function's ``parameter_names`` receipt identifies that retained formal;
    using the first historical id can bind a call to a discarded aggregate
    wrapper and leave the real scalar formal backed by zeroed scratch storage.
    """

    retained = tuple(
        int(value_id)
        for name, value_id in retained_parameters
        if str(name) == str(parameter_name)
    )
    if len(set(retained)) == 1:
        return retained[0]
    history = tuple(map(int, identity_history))
    return history[0] if history else None


def _drop_unused_private_sequences(function: Any, sequence_table: Any) -> int:
    """Remove compiler-owned sequence arenas with no semantic consumer.

    Lowering initializes every local sequence length defensively. That store
    alone must not make an otherwise unused list into public native storage:
    it is scaffolding for a sequence operation, not an observation. Authored
    parameters/outputs and any non-initialization SSA use keep the descriptor.
    """

    if sequence_table is None:
        return 0
    public_ids = {
        int(value_id)
        for _name, value_id in (
            getattr(function, "metadata", {}) or {}
        ).get("named_outputs", ())
    }
    public_ids.update(
        int(value_id)
        for _name, value_id in (
            getattr(function, "metadata", {}) or {}
        ).get("parameter_names", ())
    )
    public_ids.update(
        int(argument.id)
        for argument in getattr(function, "args", ())
        if (argument.accounting or {}).get("program_abi_parameter")
    )
    removed_ids: set[int] = set()
    removed_addresses: set[int] = set()
    removed_sequences: list[int] = []
    instructions = tuple(
        instruction
        for block in getattr(function, "blocks", {}).values()
        for instruction in getattr(block, "instrs", ())
    )
    for sequence_id, descriptor in tuple(sequence_table.sequences.items()):
        resident_ids = {
            int(descriptor.sequence_id),
            *map(int, descriptor.column_value_ids),
            int(descriptor.length_address_id),
            int(descriptor.capacity_value_id),
            *((int(descriptor.status_address_id),)
              if descriptor.status_address_id is not None else ()),
            *((int(descriptor.live_flags_value_id),)
              if descriptor.live_flags_value_id is not None else ()),
        }
        if resident_ids & public_ids:
            continue
        init_addresses = {
            int(instruction.res.id)
            for instruction in instructions
            if (
                instruction.op in {"GetElementPtr", "getelementptr"}
                and instruction.res is not None
                and instruction.args
                and int(instruction.args[0].id)
                == int(descriptor.length_address_id)
                and instruction.attributes.get("binding")
                == "ssa_local_sequence_length"
            )
        }
        meaningful = False
        for instruction in instructions:
            if (
                instruction.res is not None
                and int(instruction.res.id) in init_addresses
            ):
                continue
            if (
                instruction.op in {"Store", "store"}
                and any(int(value.id) in init_addresses for value in instruction.args)
            ):
                continue
            referenced = {
                *(int(value.id) for value in instruction.args),
                *((int(instruction.res.id),) if instruction.res is not None else ()),
            }
            if referenced & resident_ids:
                meaningful = True
                break
        if meaningful:
            continue
        removed_sequences.append(int(sequence_id))
        removed_ids.update(resident_ids)
        removed_addresses.update(init_addresses)
    if not removed_sequences:
        return 0
    function.args = [
        argument for argument in function.args
        if int(argument.id) not in removed_ids
    ]
    for block in function.blocks.values():
        block.instrs = [
            instruction
            for instruction in block.instrs
            if not (
                instruction.res is not None
                and int(instruction.res.id) in removed_addresses
            )
            if not (
                instruction.op in {"Store", "store"}
                and any(
                    int(value.id) in removed_addresses
                    for value in instruction.args
                )
            )
        ]
    for sequence_id in removed_sequences:
        sequence_table.sequences.pop(sequence_id, None)
    metadata = dict(getattr(function, "metadata", {}) or {})
    if "sequence_array_argument_ids" in metadata:
        metadata["sequence_array_argument_ids"] = tuple(
            value_id
            for value_id in metadata["sequence_array_argument_ids"]
            if int(value_id) not in removed_ids
        )
    if "sequence_value_names" in metadata:
        metadata["sequence_value_names"] = tuple(
            item for item in metadata["sequence_value_names"]
            if int(item[0]) not in removed_sequences
        )
    function.metadata = metadata
    return len(removed_sequences)


def _drop_unused_root_private_formals(function: Any) -> int:
    """Erase late compiler frame formals that the root never references."""

    metadata = dict(getattr(function, "metadata", {}) or {})
    protected = {
        int(value_id)
        for _name, value_id in (
            *metadata.get("parameter_names", ()),
            *metadata.get("named_outputs", ()),
        )
    }
    used = {
        int(value.id)
        for block in function.blocks.values()
        for instruction in block.instrs
        for value in (
            *instruction.args,
            *((instruction.res,) if instruction.res is not None else ()),
        )
    }
    locally_defined = {
        int(instruction.res.id)
        for block in function.blocks.values()
        for instruction in block.instrs
        if instruction.res is not None
    }
    removable = {
        int(argument.id)
        for argument in function.args
        if (
            int(argument.id) not in used | protected
            or (
                int(argument.id) in locally_defined
                and (argument.accounting or {}).get("ssa_call_result_from")
            )
        )
        and not (argument.accounting or {}).get("program_abi_parameter")
    }
    if removable:
        function.args = [
            argument for argument in function.args
            if int(argument.id) not in removable
        ]
        if "sequence_array_argument_ids" in metadata:
            metadata["sequence_array_argument_ids"] = tuple(
                value_id
                for value_id in metadata["sequence_array_argument_ids"]
                if int(value_id) not in removable
            )
        function.metadata = metadata
    return len(removable)


def _exact_source_literal_values(graph_obj: Any) -> dict[int, Any]:
    """Snapshot exact-node authored literals before deployment mutates graphs."""

    literals: dict[int, Any] = {}
    for node_id, data in graph_obj.nodes(data=True):
        value_id = int(data.get("value_id", node_id))
        if int(node_id) != value_id:
            continue
        expression = data.get("expr_obj")
        operation = str(data.get("op") or data.get("type") or "").casefold()
        if isinstance(expression, ast.Constant):
            literal = expression.value
        elif operation in {"const", "constant"}:
            literal = (data.get("attributes") or {}).get(
                "value", data.get("constant")
            )
        else:
            continue
        if isinstance(literal, (str, bool, int, float, type(None))):
            literals[value_id] = literal
    return literals


def _recover_late_source_literals(
    function: Any,
    graph_obj: Any | None = None,
    *,
    literal_values: Mapping[int, Any] | None = None,
) -> tuple[tuple[int, Any], ...]:
    """Define exact authored literals exposed only by late call expansion.

    Sequence/record call linking can add a use after the ordinary control
    constant pass has run.  A literal at that seam is still an internal source
    producer, never a caller input.  Materialize only exact AST constants;
    computed expressions remain rejected until their real lowering is linked.
    """

    if not function.blocks:
        return ()
    produced = {
        int(instruction.res.id)
        for block in function.blocks.values()
        for instruction in block.instrs
        if instruction.res is not None
    }
    parameters = {
        int(value_id)
        for _name, value_id in (function.metadata or {}).get("parameter_names", ())
    }
    authored_constants = dict(literal_values or {})
    authored_constants.update(dict(
        (function.metadata or {}).get("authored_constant_values", ())
    ))
    source_candidates: dict[int, list[tuple[int, Mapping[str, Any]]]] = {}
    if graph_obj is not None:
        for node_id, data in graph_obj.nodes(data=True):
            value_id = int(data.get("value_id", node_id))
            source_candidates.setdefault(value_id, []).append((int(node_id), data))
    recovered = []
    instructions = []
    retained_args = []
    from .string_table import string_token
    from ..transmogrifier.ssa import Instr

    for formal in function.args:
        value_id = int(formal.id)
        candidates = source_candidates.get(value_id, ())
        exact = tuple(data for node_id, data in candidates if node_id == value_id)
        # Structural folding may leave aliases that share a value_id.  The
        # graph node whose own identity equals the SSA value is the authoritative
        # authored occurrence; insertion order of an alias is not provenance.
        data = exact[0] if len(exact) == 1 else (
            candidates[0][1] if len(candidates) == 1 else {}
        )
        expression = data.get("expr_obj")
        operation = str(data.get("op") or data.get("type") or "").casefold()
        has_authored_ledger = value_id in authored_constants
        is_literal = has_authored_ledger or isinstance(expression, ast.Constant) or operation in {
            "const", "constant",
        }
        if value_id in produced or value_id in parameters or not is_literal:
            retained_args.append(formal)
            continue
        literal = authored_constants[value_id] if has_authored_ledger else (
            expression.value
            if isinstance(expression, ast.Constant)
            else (data.get("attributes") or {}).get("value", data.get("constant"))
        )
        if isinstance(literal, str):
            formal.dtype = "int64"
            instruction = Instr(
                "string_token", [], formal,
                attributes={"token": string_token(literal), "text": literal},
            )
        elif literal is None:
            formal.dtype = "none"
            instruction = Instr("NoneValue", [], formal)
        elif isinstance(literal, (bool, int, float)):
            formal.dtype = (
                "bool" if isinstance(literal, bool)
                else "int64" if isinstance(literal, int)
                else "float64"
            )
            instruction = Instr("Const", [], formal, attributes={"value": literal})
        else:
            retained_args.append(formal)
            continue
        formal.accounting = {
            **dict(formal.accounting or {}), "authored_constant": True,
        }
        instructions.append(instruction)
        recovered.append((value_id, literal))
    if instructions:
        next(iter(function.blocks.values())).instrs[0:0] = instructions
        function.args = retained_args
    return tuple(recovered)


def _recover_late_source_slice_offsets(
    function: Any,
    graph_obj: Any,
) -> tuple[tuple[int, int, int | None, int], ...]:
    """Materialize static index slices as their integer base offsets.

    Numerical region addressing represents a shaped source subscript as
    ``GetElementPtr(base, selectors...)`` followed by a shaped ``Load``.  The
    result shape retains each slice extent; the address selector itself is the
    slice's lower bound.  A source ``ast.Slice`` must therefore become an
    integer constant rather than an anonymous runtime formal.

    Only exact, non-negative, unit-stride slices used exclusively in an index
    role are accepted.  Dynamic bounds, negative normalization, non-unit
    strides, aliases, and slices used as ordinary Python values remain
    unresolved.  The complete static bounds stay on the instruction as the
    provenance receipt even though address arithmetic consumes only ``lower``.
    """

    from ..transmogrifier.ssa import Instr

    if not function.blocks:
        return ()
    produced = {
        int(instruction.res.id)
        for block in function.blocks.values()
        for instruction in block.instrs
        if instruction.res is not None
    }
    parameters = {
        int(value_id)
        for _name, value_id in (function.metadata or {}).get(
            "parameter_names", ()
        )
    }
    recovered: list[tuple[int, int, int | None, int]] = []
    instructions = []
    retained_args = []

    def static_integer(expression: ast.AST | None) -> int | None:
        if expression is None:
            return None
        if not (
            isinstance(expression, ast.Constant)
            and isinstance(expression.value, int)
            and not isinstance(expression.value, bool)
        ):
            raise ValueError
        return int(expression.value)

    for formal in function.args:
        value_id = int(formal.id)
        data = graph_obj.nodes.get(value_id, {})
        expression = data.get("expr_obj")
        operation = str(data.get("op") or data.get("type") or "").casefold()
        children = tuple(data.get("children") or ())
        if (
            value_id in produced
            or value_id in parameters
            or operation != "slice"
            or not isinstance(expression, ast.Slice)
            or not children
            or any(str(role) != "index" for _child, role in children)
        ):
            retained_args.append(formal)
            continue
        try:
            lower = static_integer(expression.lower)
            upper = static_integer(expression.upper)
            step = static_integer(expression.step)
        except ValueError:
            retained_args.append(formal)
            continue
        lower = 0 if lower is None else lower
        step = 1 if step is None else step
        if lower < 0 or step != 1 or upper is not None and upper < lower:
            retained_args.append(formal)
            continue
        formal.dtype = "int64"
        formal.shape = ()
        formal.accounting = {
            **dict(formal.accounting or {}),
            "authored_static_slice": True,
            "source_value_id": value_id,
        }
        instructions.append(Instr(
            "Const", [], formal,
            attributes={
                "value": lower,
                "static_slice_bounds": (lower, upper, step),
                "source_slice_value_id": value_id,
            },
        ))
        recovered.append((value_id, lower, upper, step))
    if instructions:
        next(iter(function.blocks.values())).instrs[0:0] = instructions
        function.args = retained_args
    return tuple(recovered)


def _recover_late_source_unary_operations(
    function: Function,
    graph: Any,
) -> tuple[tuple[int, int, str], ...]:
    """Define pure source unary operations externalized during frame linking.

    Structural/control planning can retain a tensor operation only as an
    operand of a later control expression.  Call-frame linking then sees that
    operand before a repository-SSA instruction has claimed it and creates a
    provisional function formal.  That formal is not an ABI input: the source
    graph still names both the reduction and its tensor operand.

    Recover only dominance-proof cases here. A reduction may consume an
    entry-produced tensor. A scalar ``item()`` inside a retained loop must
    instead consume the loop-carried Phi whose ``initial_value_id`` names the
    source operand. Reuse the placeholder object held by consumers, insert its
    producer after the exact operand producer, and remove it from the function
    signature. More involved branch-local operations are deliberately refused.
    """

    from ..transmogrifier.ssa import Instr

    if not function.blocks:
        return ()
    entry = next(iter(function.blocks.values()))
    produced = {
        int(instruction.res.id): (block, index, instruction.res)
        for block in function.blocks.values()
        for index, instruction in enumerate(block.instrs)
        if instruction.res is not None
    }
    block_names = {id(block): name for name, block in function.blocks.items()}
    predecessors = {name: set() for name in function.blocks}
    for name, block in function.blocks.items():
        for successor in block.successors:
            if successor in predecessors:
                predecessors[successor].add(name)
    entry_name = block_names[id(entry)]
    dominators = {
        name: ({name} if name == entry_name else set(function.blocks))
        for name in function.blocks
    }
    changed = True
    while changed:
        changed = False
        for name in function.blocks:
            if name == entry_name:
                continue
            incoming = predecessors[name]
            updated = {name} | (
                set.intersection(*(dominators[parent] for parent in incoming))
                if incoming else set()
            )
            if updated != dominators[name]:
                dominators[name] = updated
                changed = True
    recovered: list[tuple[int, int, str]] = []
    for placeholder in tuple(function.args):
        value_id = int(placeholder.id)
        data = graph.nodes.get(value_id, {})
        operation = str(
            data.get("op") or data.get("type") or ""
        ).casefold()
        if operation not in {"all", "any", "item"} or value_id in produced:
            continue
        operands = tuple(
            int(parent)
            for parent, role in data.get("parents") or ()
            if str(role) in {"operand", "arg:0", "value"}
        )
        if len(operands) != 1:
            continue
        operand_id = int(operands[0])
        source = produced.get(operand_id)
        if operation == "item":
            carried = tuple(
                (block, index, instruction.res)
                for block in function.blocks.values()
                for index, instruction in enumerate(block.instrs)
                if (
                    instruction.op == "Phi"
                    and instruction.res is not None
                    and int((instruction.attributes or {}).get(
                        "initial_value_id", -1
                    )) == operand_id
                    and (instruction.attributes or {}).get("binding")
                    == "loop_carried"
                )
            )
            if len(carried) == 1:
                source = carried[0]
            elif carried:
                continue
        if source is None:
            continue
        producer_block, producer_index, operand = source
        producer_name = block_names[id(producer_block)]
        consumer_names = {
            name
            for name, block in function.blocks.items()
            for instruction in block.instrs
            if any(int(argument.id) == value_id for argument in instruction.args)
        }
        if (
            not consumer_names
            or any(producer_name not in dominators[name]
                   for name in consumer_names)
            or operation in {"all", "any"} and producer_block is not entry
            or operation == "item" and tuple(operand.shape or ())
        ):
            continue
        function.args.remove(placeholder)
        placeholder.dtype = (
            "bool" if operation in {"all", "any"} else operand.dtype
        )
        placeholder.shape = ()
        placeholder.accounting = {
            **dict(placeholder.accounting or {}),
            "recovered_structural_source": operation,
            "source_value_id": value_id,
            "source_operand_id": operand_id,
        }
        opcode = operation if operation in {"all", "any"} else "Cast"
        instruction = Instr(
            opcode,
            [operand],
            placeholder,
            attributes={
                "tensor_operation": operation,
                "structural_operation": (
                    "tensor_reduction"
                    if operation in {"all", "any"} else "scalar_item"
                ),
                **({"target_dtype": operand.dtype}
                   if operation == "item" else {}),
                "late_call_feed_recovery": True,
            },
        )
        insertion_index = producer_index + 1
        while (
            insertion_index < len(producer_block.instrs)
            and producer_block.instrs[insertion_index].op == "Phi"
        ):
            insertion_index += 1
        producer_block.instrs.insert(insertion_index, instruction)
        # Subsequent recoveries must use positions in the expanded block.
        for resident_id, (owner, offset, resident) in tuple(produced.items()):
            if owner is producer_block and offset >= insertion_index:
                produced[resident_id] = (owner, offset + 1, resident)
        produced[value_id] = (
            producer_block, insertion_index, placeholder,
        )
        recovered.append((value_id, operand_id, operation))
    return tuple(recovered)


def _recover_late_source_pure_expressions(
    function: Function,
    graph: Any,
) -> tuple[tuple[int, int, str], ...]:
    """Materialize exact scalar source expressions lost at frame linking.

    Linking may expose a complete, pure source expression as a provisional
    formal even though none of its interior nodes reached repository SSA. A
    backend must not accept that internal value as a new ABI input. Rebuild a
    deliberately small, backend-neutral scalar expression closure when all of
    its runtime leaves have one proven placement which dominates every use.

    Constants come from their exact source nodes. ``item()`` over a loop input
    binds to the unique loop-carried Phi naming that input, so reconstruction
    observes the current iteration rather than the entry value. Expressions
    with non-dominating branch-dependent leaves, multiple possible carried
    versions, shaped intermediates, or unsupported/effectful operations are
    left for the provenance gate to reject.
    """

    from ..transmogrifier.ssa import Instr, SSAValue

    if not function.blocks:
        return ()
    blocks = function.blocks
    entry_name = next(iter(blocks))
    predecessors = {name: set() for name in blocks}
    for name, block in blocks.items():
        for successor in block.successors:
            if successor in predecessors:
                predecessors[successor].add(name)
    dominators = {
        name: ({name} if name == entry_name else set(blocks))
        for name in blocks
    }
    changed = True
    while changed:
        changed = False
        for name in blocks:
            if name == entry_name:
                continue
            incoming = predecessors[name]
            updated = {name} | (
                set.intersection(*(dominators[parent] for parent in incoming))
                if incoming else set()
            )
            if updated != dominators[name]:
                dominators[name] = updated
                changed = True

    values: dict[int, SSAValue] = {}
    conflicting_value_ids: set[int] = set()

    def remember(value: SSAValue | None) -> None:
        if value is None:
            return
        value_id = int(value.id)
        resident = values.setdefault(value_id, value)
        if resident is not value:
            conflicting_value_ids.add(value_id)

    for argument in function.args:
        remember(argument)
    produced: dict[int, tuple[str, int, SSAValue]] = {}
    for block_name, block in blocks.items():
        for index, instruction in enumerate(block.instrs):
            for argument in instruction.args:
                remember(argument)
            remember(instruction.res)
            if instruction.res is not None:
                produced[int(instruction.res.id)] = (
                    block_name, index, instruction.res,
                )

    binary_operations = {
        "add": "Add",
        "sub": "Sub",
        "mul": "Mul",
        "mult": "Mul",
        "div": "Div",
        "truediv": "Div",
    }

    def source_operation(value_id: int) -> tuple[dict[str, Any], str]:
        data = graph.nodes.get(int(value_id), {})
        operation = str(data.get("op") or data.get("type") or "").casefold()
        return data, operation

    def exact_parents(
        data: Mapping[str, Any], roles: tuple[str, ...],
    ) -> tuple[int, ...]:
        by_role: dict[str, list[int]] = {role: [] for role in roles}
        for parent, role in data.get("parents") or ():
            role = str(role)
            if role in by_role:
                by_role[role].append(int(parent))
        if any(len(by_role[role]) != 1 for role in roles):
            return ()
        return tuple(by_role[role][0] for role in roles)

    def literal_value(data: Mapping[str, Any]) -> Any:
        expression = data.get("expr_obj")
        if isinstance(expression, ast.Constant):
            return expression.value
        attributes = data.get("attributes") or {}
        return attributes.get("value", data.get("constant"))

    recovered: list[tuple[int, int, str]] = []
    for placeholder in tuple(function.args):
        root_id = int(placeholder.id)
        _root_data, root_operation = source_operation(root_id)
        if root_operation not in binary_operations or root_id in produced:
            continue

        planned: list[tuple[str, list[SSAValue], SSAValue, dict[str, Any]]] = []
        runtime_leaves: list[tuple[str, int, SSAValue]] = []
        source_roots: set[int] = set()
        visiting: set[int] = set()
        built: dict[int, SSAValue] = {}
        failed = [False]

        def result_value(value_id: int, dtype: str) -> SSAValue:
            existing = values.get(int(value_id))
            if existing is not None:
                if int(value_id) in conflicting_value_ids:
                    failed[0] = True
                return existing
            created = SSAValue(int(value_id), dtype, shape=())
            values[int(value_id)] = created
            return created

        def build(value_id: int) -> SSAValue | None:
            value_id = int(value_id)
            if value_id in built:
                return built[value_id]
            if value_id in visiting:
                failed[0] = True
                return None
            data, operation = source_operation(value_id)
            attributes = data.get("attributes") or {}
            # A sequence arena may have a scalar storage handle. That does
            # not make authored list replication numeric multiplication.
            if attributes.get("aggregate_kind") in {"list", "tuple", "dict", "set"}:
                failed[0] = True
                return None
            existing_producer = produced.get(value_id)
            if existing_producer is not None:
                block_name, index, value = existing_producer
                if tuple(value.shape or ()):
                    failed[0] = True
                    return None
                runtime_leaves.append((block_name, index, value))
                source_roots.add(value_id)
                built[value_id] = value
                return value
            visiting.add(value_id)
            try:
                if operation in {"const", "constant"}:
                    literal = literal_value(data)
                    if not isinstance(literal, (bool, int, float)):
                        failed[0] = True
                        return None
                    dtype = (
                        "bool" if isinstance(literal, bool)
                        else "int64" if isinstance(literal, int)
                        else "float64"
                    )
                    result = result_value(value_id, dtype)
                    result.dtype = dtype
                    result.shape = ()
                    planned.append((
                        "Const", [], result,
                        {"value": literal, "late_source_expression": True},
                    ))
                    built[value_id] = result
                    return result
                if operation == "item":
                    parents = exact_parents(data, ("operand",))
                    if not parents:
                        failed[0] = True
                        return None
                    initial_id = int(parents[0])
                    carried = tuple(
                        (block_name, index, instruction.res)
                        for block_name, block in blocks.items()
                        for index, instruction in enumerate(block.instrs)
                        if (
                            instruction.op == "Phi"
                            and instruction.res is not None
                            and int((instruction.attributes or {}).get(
                                "initial_value_id", -1
                            )) == initial_id
                            and (instruction.attributes or {}).get("binding")
                            == "loop_carried"
                        )
                    )
                    if len(carried) == 1:
                        block_name, index, operand = carried[0]
                    elif carried:
                        failed[0] = True
                        return None
                    else:
                        source = produced.get(initial_id)
                        if source is None:
                            failed[0] = True
                            return None
                        block_name, index, operand = source
                    if tuple(operand.shape or ()):
                        failed[0] = True
                        return None
                    runtime_leaves.append((block_name, index, operand))
                    source_roots.add(initial_id)
                    result = result_value(
                        value_id, str(operand.dtype or "float64"),
                    )
                    result.dtype = operand.dtype
                    result.shape = ()
                    planned.append((
                        "Cast", [operand], result,
                        {
                            "tensor_operation": "item",
                            "structural_operation": "scalar_item",
                            "target_dtype": operand.dtype,
                            "late_source_expression": True,
                            "source_operand_id": initial_id,
                        },
                    ))
                    built[value_id] = result
                    return result
                opcode = binary_operations.get(operation)
                if opcode is None:
                    failed[0] = True
                    return None
                parents = exact_parents(data, ("lhs", "rhs"))
                if not parents:
                    failed[0] = True
                    return None
                left = build(parents[0])
                right = build(parents[1])
                if left is None or right is None:
                    failed[0] = True
                    return None
                dtypes = {str(left.dtype or ""), str(right.dtype or "")}
                dtype = (
                    "float64"
                    if opcode == "Div" or any("float" in item for item in dtypes)
                    else "int64"
                )
                result = result_value(value_id, dtype)
                result.dtype = dtype
                result.shape = ()
                planned.append((
                    opcode, [left, right], result,
                    {
                        "structural_operation": "pure_scalar_expression",
                        "source_operation": operation,
                        "late_source_expression": True,
                    },
                ))
                built[value_id] = result
                return result
            finally:
                visiting.discard(value_id)

        result = build(root_id)
        if failed[0] or result is not placeholder or not planned or not runtime_leaves:
            continue
        consumer_positions = tuple(
            (block_name, index)
            for block_name, block in blocks.items()
            for index, instruction in enumerate(block.instrs)
            if any(int(argument.id) == root_id for argument in instruction.args)
        )
        if not consumer_positions:
            continue
        candidate_names = tuple(
            name for name in blocks
            if (
                all(producer_name in dominators[name]
                    for producer_name, _index, _value in runtime_leaves)
                and all(name in dominators[consumer_name]
                        for consumer_name, _index in consumer_positions)
            )
        )
        if not candidate_names:
            continue
        placement = max(candidate_names, key=lambda name: len(dominators[name]))
        insertion_index = 0
        for producer_name, producer_index, _value in runtime_leaves:
            if producer_name == placement:
                insertion_index = max(insertion_index, producer_index + 1)
        while (
            insertion_index < len(blocks[placement].instrs)
            and blocks[placement].instrs[insertion_index].op == "Phi"
        ):
            insertion_index += 1
        local_consumers = tuple(
            index for block_name, index in consumer_positions
            if block_name == placement
        )
        if local_consumers and insertion_index > min(local_consumers):
            continue
        instructions = [
            Instr(opcode, arguments, result_, attributes=attributes)
            for opcode, arguments, result_, attributes in planned
        ]
        blocks[placement].instrs[insertion_index:insertion_index] = instructions
        for resident_id, (owner, offset, resident) in tuple(produced.items()):
            if owner == placement and offset >= insertion_index:
                produced[resident_id] = (owner, offset + len(instructions), resident)
        function.args.remove(placeholder)
        placeholder.accounting = {
            **dict(placeholder.accounting or {}),
            "recovered_structural_source": root_operation,
            "source_value_id": root_id,
            "source_root_ids": tuple(sorted(source_roots)),
        }
        for offset, instruction in enumerate(instructions):
            produced[int(instruction.res.id)] = (
                placement, insertion_index + offset, instruction.res,
            )
        primary_root = min(source_roots) if source_roots else root_id
        recovered.append((root_id, primary_root, root_operation))
    return tuple(recovered)


def _index_source_graph_spellings(
    indexed: dict[str, Any],
    function_graph: Any,
    *symbols: Any,
) -> None:
    """Index one graph by repository, local, and qualified source spellings."""

    for symbol in (
        *symbols,
        function_graph.graph.get("function_name"),
        function_graph.graph.get("qualified_name"),
    ):
        if symbol:
            indexed.setdefault(str(symbol), function_graph)


def _resolved_source_graphs_by_symbol(resolved_graph: Any) -> dict[str, Any]:
    """Index final resolved function graphs by every authored symbol spelling.

    The whole-program wrapper owns the resolved project graph, while the
    deployment helper has its own shell-to-symbol table. Final provenance
    reconciliation must use the former rather than reaching into a helper's
    local table. Function-table entries preserve both the local and qualified
    authored names, so either repository-SSA spelling resolves to the same
    exact post-reduction graph.
    """

    indexed: dict[str, Any] = {}
    for entry in getattr(resolved_graph, "function_table", ()):
        function_graph = getattr(getattr(entry, "graph", None), "G", None)
        if function_graph is None:
            continue
        _index_source_graph_spellings(
            indexed,
            function_graph,
            getattr(entry, "name", None),
            getattr(entry, "qualified_name", None),
        )
    return indexed


def _source_graph_for_lowered_function(
    source_graphs: Mapping[str, Any],
    function_symbol: str,
    function: Any,
) -> Any | None:
    """Resolve a specialized SSA function back to its authored graph."""

    source_symbol = str(
        (getattr(function, "metadata", None) or {}).get(
            "source_qualified_name"
        )
        or function_symbol
    )
    return (
        source_graphs.get(str(function_symbol))
        or source_graphs.get(source_symbol)
        or source_graphs.get(source_symbol.rsplit(".", 1)[-1])
    )


def _settle_nonlive_structural_shortfalls(
    function: Any,
    shortfalls: Iterable[Any],
    *,
    authoritative_output_ids: Iterable[int] = (),
    required_source_ids: Iterable[int] = (),
) -> tuple[Any, ...]:
    """Discard failed recursive probes that are absent from the final SSA.

    Structural recovery explores source dependencies speculatively. A nested
    call handle can be unavailable as one Python object even though its linked
    physical fields satisfy the enclosing output, and an evaporated collection
    can disappear before its ``sorted``/``tuple`` wrappers are needed. Those
    failed probes are not defects once no formal, instruction operand, required
    source, or authoritative output names the identity. Direct live failures
    remain hard findings.
    """
    live_ids = {
        *(int(value.id) for value in function.args),
        *(int(argument.id)
          for block in function.blocks.values()
          for instruction in block.instrs
          for argument in instruction.args),
        *map(int, authoritative_output_ids),
        *map(int, required_source_ids),
    }
    retained = []
    settled = []
    for finding in shortfalls:
        if (
            isinstance(finding, tuple)
            and len(finding) == 3
            and isinstance(finding[0], int)
            and int(finding[0]) not in live_ids
        ):
            settled.append({
                "value_id": int(finding[0]),
                "operation": str(finding[1]),
                "reason": str(finding[2]),
                "resolution": "absent_from_final_ssa",
                "priority": "exact_live_value_surface",
                "tie_policy": "incumbent",
            })
            continue
        retained.append(finding)
    if settled:
        prior = tuple(function.metadata.get(
            "settled_nonlive_structural_shortfalls", ()
        ))
        function.metadata["settled_nonlive_structural_shortfalls"] = (
            *prior,
            *(receipt for receipt in settled if receipt not in prior),
        )
    return tuple(retained)


def _rebind_recorded_scalar_identities(
    function: Any, source_graph: Any | None = None,
) -> tuple[dict[str, Any], ...]:
    """Apply proven scalar ``item()`` identities to every stale SSA object.

    Structural recovery can retire one provisional formal while planned-region
    calls still hold distinct ``SSAValue`` objects carrying the same source
    id.  ``control_identity_receipts`` is the proof that the rank-zero item is
    exactly its operand.  Rebind only an unambiguous receipt to one canonical
    formal or definition; conflicting receipts and duplicate definitions keep
    the incumbent.
    """
    receipts_by_source: dict[int, set[int]] = {}
    for receipt in function.metadata.get("control_identity_receipts", ()):
        if len(receipt) != 3 or str(receipt[2]) != "scalar_item_identity":
            continue
        source_id, replacement_id = map(int, receipt[:2])
        if source_id != replacement_id:
            receipts_by_source.setdefault(source_id, set()).add(replacement_id)

    candidates: dict[int, list[Any]] = {}
    for value in function.args:
        candidates.setdefault(int(value.id), []).append(value)
    for block in function.blocks.values():
        for instruction in block.instrs:
            if instruction.res is not None:
                bucket = candidates.setdefault(int(instruction.res.id), [])
                if all(instruction.res is not value for value in bucket):
                    bucket.append(instruction.res)

    canonical: dict[int, Any] = {}
    for source_id, replacement_ids in receipts_by_source.items():
        if len(replacement_ids) != 1:
            continue
        replacement_id = next(iter(replacement_ids))
        choices = candidates.get(replacement_id, ())
        if len(choices) == 1:
            canonical[source_id] = choices[0]

    changes = []
    for block_name, block in function.blocks.items():
        for instruction_index, instruction in enumerate(block.instrs):
            replaced_positions = []
            rewritten = []
            for position, argument in enumerate(instruction.args):
                replacement = canonical.get(int(argument.id))
                if replacement is None or replacement is argument:
                    rewritten.append(argument)
                    continue
                rewritten.append(replacement)
                replaced_positions.append((
                    position, int(argument.id), int(replacement.id)
                ))
            if not replaced_positions:
                continue
            instruction.args = rewritten
            if "feed_ids" in instruction.attributes:
                instruction.attributes["feed_ids"] = tuple(
                    int(argument.id) for argument in rewritten
                )
            for position, source_id, replacement_id in replaced_positions:
                changes.append({
                    "block": str(block_name),
                    "instruction_index": int(instruction_index),
                    "operand_index": int(position),
                    "value_id": source_id,
                    "replacement_value_id": replacement_id,
                    "priority": "exact_structural_identity",
                    "tie_policy": "incumbent",
                })
    if changes:
        prior = tuple(function.metadata.get(
            "structural_identity_rebindings", ()
        ))
        function.metadata["structural_identity_rebindings"] = (
            *prior,
            *(change for change in changes if change not in prior),
        )
        rebound_targets = {
            int(change["replacement_value_id"]) for change in changes
        }
        existing_names = tuple(function.metadata.get("parameter_names", ()))
        names_by_id = {int(value_id): str(name) for name, value_id in existing_names}
        ids_by_name = {str(name): int(value_id) for name, value_id in existing_names}
        recovered_names = []
        for replacement_id in sorted(rebound_targets):
            replacement = canonical.get(next((
                source_id for source_id, value in canonical.items()
                if int(value.id) == replacement_id
            ), -1))
            if replacement not in function.args or source_graph is None:
                continue
            matching_nodes = tuple(
                data
                for node_id, data in source_graph.nodes(data=True)
                if int(data.get("value_id", node_id)) == replacement_id
            )
            if len(matching_nodes) != 1:
                continue
            attributes = matching_nodes[0].get("attributes") or {}
            if str(attributes.get("binding_kind")) != "parameter":
                continue
            name = str(attributes.get("binding_name") or "")
            if not name:
                continue
            if replacement_id in names_by_id or name in ids_by_name:
                continue
            existing_names = (*existing_names, (name, replacement_id))
            names_by_id[replacement_id] = name
            ids_by_name[name] = replacement_id
            recovered_names.append({
                "name": name,
                "value_id": replacement_id,
                "priority": "exact_source_parameter_identity",
                "tie_policy": "incumbent",
            })
        if recovered_names:
            function.metadata["parameter_names"] = existing_names
            prior_names = tuple(function.metadata.get(
                "recovered_structural_parameter_names", ()
            ))
            function.metadata["recovered_structural_parameter_names"] = (
                *prior_names,
                *(entry for entry in recovered_names if entry not in prior_names),
            )
    return tuple(changes)


def _resolved_source_literals_by_symbol(
    resolved_graph: Any,
) -> dict[str, dict[int, Any]]:
    """Freeze literal provenance while the resolved function graphs exist."""

    return {
        symbol: _exact_source_literal_values(function_graph)
        for symbol, function_graph in _resolved_source_graphs_by_symbol(
            resolved_graph
        ).items()
    }


def _record_module_closure_formals(
    module: Any,
    source_graphs: Mapping[str, Any] | None = None,
) -> tuple[tuple[str, str, int], ...]:
    """Name the formals a function reads but never declares or produces.

    A nested function consumes bindings from its enclosing scope:
    ``_wrench_force`` reads ``wrench_k`` and ``plane_normal_q``. Those are
    real formals the caller must supply, but they are not authored
    parameters, so the signature looked as though it had grown values no
    caller could name. The source graph marks each one as an ``Input`` with
    an external/closure binding, which is the exact discriminator: an
    escaped local temporary is not such an input and keeps announcing
    itself.
    """

    source_graphs = dict(source_graphs or {})
    if not source_graphs:
        return ()
    recorded: list[tuple[str, str, int]] = []
    for function_symbol, function in module.functions.items():
        graph = _source_graph_for_lowered_function(
            source_graphs, str(function_symbol), function,
        )
        if graph is None:
            continue
        metadata = function.metadata or {}
        named = {
            int(value_id)
            for _name, value_id in metadata.get("parameter_names", ())
        }
        authored = set(map(str, metadata.get("authored_parameters", ()) or ()))
        captures: dict[int, str] = {}
        for node_id, data in graph.nodes(data=True):
            attributes = data.get("attributes") or {}
            if str(data.get("type") or "") != "Input":
                continue
            if str(attributes.get("binding_kind") or "") not in {
                "closure", "external",
            }:
                continue
            name = str(attributes.get("binding_name") or "")
            if not name or name in authored:
                continue
            value_id = int(data.get("value_id", node_id))
            if value_id in named:
                continue
            captures.setdefault(value_id, name)
        entries = tuple(
            {
                "name": captures[int(argument.id)],
                "value_id": int(argument.id),
                "priority": "exact_source_capture_identity",
                "tie_policy": "incumbent",
            }
            for argument in function.args
            if int(argument.id) in captures
        )
        if not entries:
            continue
        function.metadata["closure_formals"] = entries
        recorded.extend(
            (str(function_symbol), entry["name"], int(entry["value_id"]))
            for entry in entries
        )
    return tuple(recorded)


def _recover_module_late_source_literals(
    module: Any,
    resolved_graph: Any | None = None,
    *,
    source_literals_by_symbol: Mapping[str, Mapping[int, Any]] | None = None,
) -> tuple[tuple[str, int, Any], ...]:
    """Reconcile final specialized signatures with exact authored constants."""

    source_graphs = (
        {} if resolved_graph is None
        else _resolved_source_graphs_by_symbol(resolved_graph)
    )
    literal_catalogue = dict(source_literals_by_symbol or {})
    recovered: list[tuple[str, int, Any]] = []
    for function_symbol, function in module.functions.items():
        source_symbol = str(
            (function.metadata or {}).get("source_qualified_name")
            or function_symbol
        )
        function_graph = _source_graph_for_lowered_function(
            source_graphs, str(function_symbol), function,
        )
        literal_values = (
            literal_catalogue.get(source_symbol)
            or literal_catalogue.get(source_symbol.rsplit(".", 1)[-1])
        )
        if function_graph is None and literal_values is None:
            continue
        rows = _recover_late_source_literals(
            function, function_graph, literal_values=literal_values,
        )
        if not rows:
            continue
        function.metadata["recovered_late_source_literals"] = tuple(
            dict.fromkeys((
                *function.metadata.get("recovered_late_source_literals", ()),
                *(value_id for value_id, _literal in rows),
            ))
        )
        recovered.extend(
            (str(function_symbol), int(value_id), literal)
            for value_id, literal in rows
        )
    module.metadata["final_recovered_source_literals"] = tuple(
        (function_symbol, value_id)
        for function_symbol, value_id, _literal in recovered
    )
    return tuple(recovered)


def _reconcile_region_local_view_shortfalls(
    symbol: str,
    graph: Any,
    function: Any,
    all_functions: Mapping[str, Any],
    all_tensor_tables: Mapping[str, Any],
    structural_shortfalls: Iterable[Any],
    semantic_output_ids: Iterable[int],
) -> tuple[tuple[Any, ...], tuple[tuple[Any, ...], ...]]:
    """Close view findings already proved inside an owned numerical region.

    Region lowering deliberately erases a reshape instruction when its result
    is only a different static view of the same resident allocation.  The
    region tensor table is the durable proof of that transformation: it names
    the source identity, storage identity, allocation owner, byte extent and
    target shape.  A later wrapper-only structural scan cannot see the erased
    instruction and used to report the identity as missing.

    Consume only exact ``reshape``/``view`` ``operator`` findings for values
    which are internal to the wrapper and have one complete owned-region
    receipt.  Public semantic outputs and wrapper-visible values still require
    an actual wrapper definition.  Equal candidate receipts do not replace an
    incumbent: ambiguity leaves the finding open.
    """

    semantic_outputs = {int(value_id) for value_id in semantic_output_ids}
    wrapper_value_ids = {int(value.id) for value in function.args}
    wrapper_value_ids.update(
        int(instruction.res.id)
        for block in function.blocks.values()
        for instruction in block.instrs
        if instruction.res is not None
    )
    region_prefix = f"{symbol}__planned_region_"
    remaining: list[Any] = []
    receipts: list[tuple[Any, ...]] = []

    for finding in structural_shortfalls:
        if not (
            isinstance(finding, tuple)
            and len(finding) == 3
            and isinstance(finding[0], int)
            and str(finding[1]).casefold() in {"reshape", "view"}
            and str(finding[2]) == "operator"
        ):
            remaining.append(finding)
            continue
        value_id = int(finding[0])
        if value_id in semantic_outputs or value_id in wrapper_value_ids:
            remaining.append(finding)
            continue
        node = graph.nodes.get(value_id, {})
        operation = str(
            node.get("op") or node.get("type") or ""
        ).casefold()
        if operation not in {"reshape", "view"}:
            remaining.append(finding)
            continue

        candidates: list[tuple[Any, ...]] = []
        for region_symbol, tensor_table in all_tensor_tables.items():
            region_symbol = str(region_symbol)
            if not region_symbol.startswith(region_prefix):
                continue
            descriptor = tensor_table.by_id(value_id)
            if descriptor is None or descriptor.storage != "view":
                continue
            storage_id = int(descriptor.data_value_id)
            if (
                descriptor.owns_allocation
                or descriptor.alias_of is None
                or int(descriptor.alias_of) != storage_id
                or descriptor.allocation_owner is None
            ):
                continue
            storage = tensor_table.by_id(storage_id)
            region = all_functions.get(region_symbol)
            if storage is None or region is None:
                continue
            if int(storage.data_value_id) != storage_id:
                continue
            if descriptor.dtype != storage.dtype:
                continue
            if (
                descriptor.byte_size is not None
                and storage.byte_size is not None
                and int(descriptor.byte_size) != int(storage.byte_size)
            ):
                continue
            region_value_ids = {int(value.id) for value in region.args}
            region_value_ids.update(
                int(instruction.res.id)
                for block in region.blocks.values()
                for instruction in block.instrs
                if instruction.res is not None
            )
            if storage_id not in region_value_ids:
                continue
            candidates.append((
                value_id,
                operation,
                region_symbol,
                storage_id,
                tuple(map(int, descriptor.shape)),
            ))

        # One proof owns the identity. Multiple regions bearing the same
        # integer are not interchangeable scopes, so a tie keeps the open
        # finding as the incumbent state.
        candidates = list(dict.fromkeys(candidates))
        if len(candidates) != 1:
            remaining.append(finding)
            continue
        receipts.append(candidates[0])

    return tuple(remaining), tuple(dict.fromkeys(receipts))


def _intern_writable_region_outputs(function: Any, tensor_table: Any = None) -> None:
    """Keep declared writable output storage attached to its SSA producer."""
    region_integral = dict(
        (function.metadata or {}).get("source_region_integral") or {}
    )
    declared_region_inouts = (
        set(map(int, region_integral.get("capture_value_ids", ())))
        & set(map(int, region_integral.get("output_value_ids", ())))
    )
    tensor_outputs = {
        int(descriptor.data_value_id)
        for descriptor in (() if tensor_table is None else tensor_table.tensors.values())
        if descriptor.storage == "output" and descriptor.writable
    }
    writable_formals = {
        int(argument.id): argument
        for argument in function.args
        if (
            int(argument.id) in declared_region_inouts
            or (
                bool((argument.accounting or {}).get("program_abi_mutable"))
                and (
                    int(argument.id) in tensor_outputs
                    or bool((argument.accounting or {}).get(
                        "program_abi_field_written"
                    ))
                )
                and (argument.accounting or {}).get("program_abi_storage")
            )
        )
    }
    if not writable_formals:
        return
    replacements: dict[int, Any] = {}
    for block in function.blocks.values():
        for instruction in block.instrs:
            result = instruction.res
            if result is None:
                continue
            formal = writable_formals.get(int(result.id))
            if formal is None or result is formal:
                continue
            replacements[id(result)] = formal
            if formal.dtype in {None, "unknown"} and result.dtype:
                formal.dtype = result.dtype
            if not tuple(formal.shape or ()) and tuple(result.shape or ()):
                formal.shape = tuple(result.shape)
            formal.accounting = {
                **dict(result.accounting or {}),
                **dict(formal.accounting or {}),
            }
            instruction.res = formal
    if not replacements:
        return
    for block in function.blocks.values():
        for instruction in block.instrs:
            instruction.args = [
                replacements.get(id(argument), argument)
                for argument in instruction.args
            ]
    function.metadata["interned_program_abi_output_ids"] = tuple(
        sorted({int(value.id) for value in replacements.values()})
    )


def _retain_forwarded_aggregate_storage(call: Any, callee: Any) -> bool:
    """A return of the exact input frame does not define that frame again."""

    if call.attributes.get("result_convention") != "ssa.aggregate":
        return False
    outputs = tuple(call.attributes.get("output_ids", ()))
    selected = tuple(call.attributes.get("callee_output_ids", ()))
    if not outputs or len(outputs) != len(selected):
        return False
    formals = tuple(int(value.id) for value in callee.args)
    returned = tuple(
        int(value.id) for block in callee.blocks.values()
        for instruction in block.instrs if instruction.op == "Ret"
        for value in instruction.args
    )
    if not returned or any(value_id not in formals for value_id in returned):
        return False
    declared = tuple(call.attributes.get("callee_input_ids", formals))
    if len(declared) != len(call.args) or len(set(declared)) != len(declared):
        return False
    bound = dict(zip(declared, call.args))
    if any(callee_id not in formals or callee_id not in bound
           or int(bound[callee_id].id) != int(caller_id)
           for callee_id, caller_id in zip(selected, outputs)):
        return False
    call.attributes["forwarded_output_bindings"] = tuple(zip(selected, outputs))
    for key in ("result_convention", "output_ids", "output_positions", "output_slots", "callee_output_ids"):
        call.attributes.pop(key, None)
    call.res = None
    return True


def _resolve_repeated_aggregate_output_positions(
    native_ids: Sequence[int],
    position_to_output: Mapping[int, int],
) -> tuple[dict[int, int], tuple[tuple[int, int, int, str, str], ...]]:
    """Recover logical result positions omitted by physical deduplication.

    An aggregate result may use the same SSA value in several record fields.
    Legalization emits that value once and records only its retained position.
    The missing logical positions have exact identity evidence: they carry the
    same callee result id.  Resolve them to the first emitted physical output;
    an equal-priority later occurrence cannot displace that incumbent.
    """

    native_ids = tuple(map(int, native_ids))
    resolved = {
        int(position): int(output_id)
        for position, output_id in position_to_output.items()
    }
    output_by_identity = {}
    receipts = []
    for position, callee_output_id in enumerate(native_ids):
        emitted = resolved.get(position)
        incumbent = output_by_identity.get(callee_output_id)
        if incumbent is None and emitted is not None:
            output_by_identity[callee_output_id] = emitted
            continue
        if incumbent is None:
            continue
        if emitted == incumbent:
            continue
        resolved[position] = incumbent
        receipts.append((
            position, callee_output_id, incumbent,
            "exact_repeated_callee_result_identity",
            "incumbent_on_equal_priority",
        ))
    return resolved, tuple(receipts)


def _linked_frame_physical_shape(formal: Any) -> tuple[int, ...]:
    """Return the declared physical shape for linked ProgramABI storage."""

    if formal is None:
        return ()
    accounting = dict(formal.accounting or {})
    rank = accounting.get("program_abi_rank")
    if (
        accounting.get("program_abi_storage") == "scalar"
        and rank in (None, 0)
    ):
        return ()
    return tuple(formal.shape or ())


def _same_declared_span_storage(left: Any, right: Any) -> bool:
    """Recognize two SSA occurrences of one declared span arena.

    Scalar value ids are versions and must remain exact. A ProgramABI span's
    nonempty storage identity names its arena across call-frame occurrences;
    equal schema and arity therefore prove that two ids are views of the same
    physical field.
    """

    from ..transmogrifier.ssa import SSARecordFieldStorage

    return (
        left.storage is SSARecordFieldStorage.SPAN
        and right.storage is SSARecordFieldStorage.SPAN
        and bool(left.storage_identity)
        and left.storage_identity == right.storage_identity
        and left.name == right.name
        and left.record_id == right.record_id
        and left.offset == right.offset
        and left.dtype == right.dtype
        and len(left.value_ids) == len(right.value_ids)
    )


def _linked_frame_storage_role(
    accounting: Mapping[str, Any],
) -> str | None:
    """Return the physical role of one declared frame field.

    Optional presence is a separate Boolean slot and is always marked
    explicitly.  The ordinary scalar field is the payload slot, including
    read-only propagated copies made before optional lowering stamps the
    redundant ``program_abi_optional_payload`` marker.  Treating an absent
    marker as a third role splits one declared field across linked frames.
    """

    if accounting.get("program_abi_optional_presence"):
        return "presence"
    if (
        accounting.get("program_abi_record") is not None
        and accounting.get("program_abi_field") is not None
        and accounting.get("program_abi_storage") == "scalar"
    ):
        return "payload"
    return None


def _preferred_linked_field_candidates(candidates: Iterable[Any]) -> list[Any]:
    """Select the incumbent physical resident for one declared scalar field.

    A writable resident owns mutable storage more strongly than a read-only
    forwarding copy.  Otherwise an authored/non-callsite resident outranks a
    compiler-generated call-frame copy.  Original argument order breaks an
    equal-priority tie, so the incumbent remains stable. Aggregate storage can
    legitimately expose several physical members and retains every candidate.
    """

    candidates = list(candidates)
    if not candidates:
        return []
    if any(
        (value.accounting or {}).get("program_abi_storage") != "scalar"
        for value in candidates
    ):
        return candidates

    def priority(value: Any) -> tuple[int, int]:
        accounting = dict(value.accounting or {})
        return (
            int(bool(accounting.get("program_abi_field_written"))),
            int(accounting.get("callsite_id") is None),
        )

    best = max(map(priority, candidates))
    return [next(value for value in candidates if priority(value) == best)]


def _prune_dead_entry_field_aliases(
    functions: Mapping[str, Any],
    call_records: Mapping[str, Iterable[Any]],
) -> int:
    """Remove superseded generated field slots from top-level signatures.

    Internal callees need transactional call-signature pruning.  A function
    with no incoming repository calls has no caller signature to rewrite, so a
    dead generated duplicate can be removed directly once both instructions
    and call-record receipts have stopped naming it.  Authored residents and
    distinct parameters remain untouched.
    """

    called = {
        str(instruction.attributes.get("callee") or "")
        for function in functions.values()
        for block in function.blocks.values()
        for instruction in block.instrs
        if instruction.op in {"Call", "call"}
    }
    removed = 0
    for function_name, function in functions.items():
        if str(function_name) in called:
            continue
        referenced = {
            int(argument.id)
            for block in function.blocks.values()
            for instruction in block.instrs
            for argument in instruction.args
        }
        receipt_sources = {
            int(source)
            for record in call_records.get(str(function_name), ())
            for _callee_id, kind, source in record.frame_bindings
            if str(kind) in {
                "caller_storage", "caller_value", "caller_alias",
            }
        }
        groups: dict[tuple[Any, ...], list[Any]] = {}
        for argument in function.args:
            accounting = dict(argument.accounting or {})
            record = accounting.get("program_abi_record")
            parameter = accounting.get("program_abi_parameter")
            field = accounting.get("program_abi_field")
            if (
                record is None or parameter is None or field is None
                or accounting.get("program_abi_storage") != "scalar"
            ):
                continue
            key = (
                str(record), str(parameter), str(field),
                _linked_frame_storage_role(accounting),
                argument.dtype, _linked_frame_physical_shape(argument),
            )
            groups.setdefault(key, []).append(argument)

        removable = set()
        # A specialized record identity call can disappear after its declared
        # span fields have been forwarded. The linker-created receiver then has
        # no physical use; unlike an authored parameter, it is not an ABI slot.
        authored = {int(value_id) for _name, value_id in (
            *function.metadata.get("parameter_names", ()),
            *function.metadata.get("named_outputs", ()),
        )}
        removable.update(
            int(argument.id) for argument in function.args
            if (argument.accounting or {}).get("linked_method_receiver_storage")
            and not (argument.accounting or {}).get("program_abi_parameter")
            and int(argument.id) not in referenced | receipt_sources | authored
        )
        # A top-level function has no incoming call transaction to prune an
        # identity-call placeholder from its signature. Once that generated
        # formal is unreferenced, unauthored, and owns no declared storage, it
        # has no native ABI meaning and no caller could supply it.
        removable.update(
            int(argument.id) for argument in function.args
            if int(argument.id) not in referenced | receipt_sources | authored
            and not any(
                (argument.accounting or {}).get(key) not in {None, ""}
                for key in (
                    "program_abi_parameter",
                    "program_abi_field",
                    "program_abi_storage",
                    "linked_call_frame_storage",
                    "returned_record_storage",
                    "compiler_frame_storage",
                )
            )
        )
        for candidates in groups.values():
            if len(candidates) < 2:
                continue
            incumbent = _preferred_linked_field_candidates(candidates)[0]
            for candidate in candidates:
                accounting = dict(candidate.accounting or {})
                candidate_id = int(candidate.id)
                generated = (
                    accounting.get("callsite_id") is not None
                    or "linked_call_frame_storage" in accounting
                )
                if (
                    candidate is not incumbent
                    and generated
                    and candidate_id not in referenced
                    and candidate_id not in receipt_sources
                ):
                    removable.add(candidate_id)
        if not removable:
            continue
        function.args = [
            argument for argument in function.args
            if int(argument.id) not in removable
        ]
        function.metadata.setdefault(
            "pruned_dead_entry_field_aliases", ()
        )
        function.metadata["pruned_dead_entry_field_aliases"] = (
            *function.metadata["pruned_dead_entry_field_aliases"],
            *tuple(sorted(removable)),
        )
        removed += len(removable)
    return removed


def _linked_frame_storage_owner(
    formal: Any,
    storage_identity: str | None,
    callee_symbol: str,
    callee_id: int,
) -> tuple[str, Any]:
    """Name a frame slot by its strongest stable physical identity.

    Propagated nested-call formals can carry complete ProgramABI field
    accounting before a record descriptor includes their local SSA id.  Using
    the numeric id as fallback in that state invents a second owner for the
    same field and forces an irreversible split.  The declared record field,
    optional role, dtype, and shape are the cross-call identity; receiver
    parameter spelling is deliberately absent.
    """

    accounting = {} if formal is None else dict(formal.accounting or {})
    record = accounting.get("program_abi_record")
    field = accounting.get("program_abi_field")
    role = _linked_frame_storage_role(accounting)
    if (
        record is not None
        and field is not None
        and accounting.get("program_abi_storage") == "scalar"
        and not _linked_frame_physical_shape(formal)
    ):
        return (
            "program_abi_field",
            (
                str(record), str(field), role,
                None if formal is None else formal.dtype,
                _linked_frame_physical_shape(formal),
            ),
        )
    if storage_identity is not None:
        return "record", str(storage_identity)
    return "value", (str(callee_symbol), int(callee_id))


def _reconcile_post_aggregate_record_results(module: Any) -> tuple[dict, ...]:
    """Carry legalized result positions into records and later call frames."""

    receipts = []
    for caller_symbol, caller in module.functions.items():
        caller_table = module.record_tables.get(str(caller_symbol))
        records = list(module.call_table.get(str(caller_symbol), ()))
        if caller_table is None or not records:
            continue
        record_by_site = {int(record.callsite_id): record for record in records}
        aliases = _concordant_function_aliases(
            caller, include_output_identities=True,
        )

        for block in caller.blocks.values():
            for call in block.instrs:
                attributes = call.attributes or {}
                if call.op not in {"Call", "call"}:
                    continue
                native_ids = tuple(
                    int(row[0])
                    for row in attributes.get("native_result_contract", ())
                )
                if not native_ids:
                    continue
                position_to_output = dict(zip(
                    map(int, attributes.get("output_positions", ())),
                    map(int, attributes.get("output_ids", ())),
                ))
                for row in attributes.get(
                    "aggregate_output_passthrough_bindings", ()
                ):
                    position_to_output.setdefault(int(row[0]), int(row[3]))
                position_to_output, duplicate_receipts = (
                    _resolve_repeated_aggregate_output_positions(
                        native_ids, position_to_output,
                    )
                )
                record = record_by_site.get(int(attributes.get(
                    "plan_callsite_id", -1
                )))
                callee_symbol = str(attributes.get("callee") or "")
                callee = module.functions.get(callee_symbol)
                callee_table = module.record_tables.get(callee_symbol)
                if record is None or callee is None or callee_table is None:
                    continue
                return_layouts = dict(callee.metadata.get(
                    "record_return_layouts", ()
                ))
                for callee_record_id, caller_record_id in record.result_bindings:
                    callee_descriptor = callee_table.records.get(
                        int(callee_record_id)
                    )
                    layout = tuple(map(int, return_layouts.get(
                        int(callee_record_id), ()
                    )))
                    callee_layout = tuple(
                        int(value_id)
                        for field in (
                            () if callee_descriptor is None
                            else callee_descriptor.fields
                        )
                        for value_id in field.value_ids
                    )
                    if not layout or layout != callee_layout:
                        continue
                    starts = tuple(
                        start
                        for start in range(len(native_ids) - len(layout) + 1)
                        if native_ids[start:start + len(layout)] == layout
                    )
                    if len(starts) != 1:
                        continue
                    start = starts[0]
                    if not all(
                        start + offset in position_to_output
                        for offset in range(len(layout))
                    ):
                        continue
                    mapped_by_storage = {}
                    cursor = 0
                    for field in callee_descriptor.fields:
                        width = len(field.value_ids)
                        mapped_by_storage[str(field.storage_identity)] = tuple(
                            int(position_to_output[start + cursor + offset])
                            for offset in range(width)
                        )
                        cursor += width
                    target_record_ids = []
                    current = int(caller_record_id)
                    seen = set()
                    while current not in seen:
                        seen.add(current)
                        if current in caller_table.records:
                            target_record_ids.append(current)
                        if current not in aliases:
                            break
                        current = int(aliases[current])
                    for target_record_id in target_record_ids:
                        descriptor = caller_table.records[target_record_id]
                        fields = tuple(
                            replace(
                                field,
                                value_ids=mapped_by_storage.get(
                                    str(field.storage_identity),
                                    tuple(map(int, field.value_ids)),
                                ),
                            )
                            for field in descriptor.fields
                        )
                        if fields == tuple(descriptor.fields):
                            continue
                        caller_table.records[target_record_id] = replace(
                            descriptor, fields=fields,
                        )
                        receipt = {
                            "function": str(caller_symbol),
                            "callsite_id": int(record.callsite_id),
                            "callee_record_id": int(callee_record_id),
                            "caller_record_id": int(target_record_id),
                            "positions": tuple(sorted(position_to_output.items())),
                            "duplicate_positions": duplicate_receipts,
                            "priority": "exact_legalized_aggregate_position",
                            "tie_policy": "incumbent",
                        }
                        receipts.append(receipt)

        rebuilt = []
        for record in records:
            callee_table = module.record_tables.get(str(record.callee_symbol))
            exact = {}
            if callee_table is not None:
                for caller_record_id, callee_record_id in record.argument_bindings:
                    caller_descriptor = caller_table.records.get(
                        int(caller_record_id)
                    )
                    callee_descriptor = callee_table.records.get(
                        int(callee_record_id)
                    )
                    if (
                        caller_descriptor is None
                        or callee_descriptor is None
                        or caller_descriptor.identity != callee_descriptor.identity
                    ):
                        continue
                    caller_fields = {
                        str(field.storage_identity): field
                        for field in caller_descriptor.fields
                    }
                    for callee_field in callee_descriptor.fields:
                        caller_field = caller_fields.get(str(
                            callee_field.storage_identity
                        ))
                        if (
                            caller_field is None
                            or len(callee_field.value_ids)
                            != len(caller_field.value_ids)
                        ):
                            continue
                        for callee_id, caller_id in zip(
                            map(int, callee_field.value_ids),
                            map(int, caller_field.value_ids),
                            strict=True,
                        ):
                            exact.setdefault(callee_id, caller_id)
            frame_bindings = tuple(
                (
                    int(callee_id), str(kind),
                    exact.get(int(callee_id), source)
                    if str(kind) in {
                        "caller_storage", "caller_value", "caller_alias",
                    }
                    else source,
                )
                for callee_id, kind, source in record.frame_bindings
            )
            if frame_bindings != tuple(record.frame_bindings):
                receipts.append({
                    "function": str(caller_symbol),
                    "callsite_id": int(record.callsite_id),
                    "frame_rebindings": tuple(
                        (int(old[0]), int(old[2]), int(new[2]))
                        for old, new in zip(
                            record.frame_bindings, frame_bindings, strict=True
                        )
                        if old != new
                    ),
                    "priority": "exact_post_aggregate_record_field",
                    "tie_policy": "incumbent",
                })
                record = replace(record, frame_bindings=frame_bindings)
            rebuilt.append(record)
        module.call_table[str(caller_symbol)] = tuple(rebuilt)
    if receipts:
        module.metadata["post_aggregate_record_result_receipts"] = tuple(receipts)
    return tuple(receipts)


def _resident_call_inputs(call: Any, caller_values: Mapping[int, Any]) -> dict[int, Any]:
    """Keep exact formal-to-resident bindings through late frame expansion.

    A frame record names the authored pre-loop value; the scheduled call may
    already read its current Phi. Reconstructing every argument from that
    record discards ordinary SSA flow. Only missing/nonresident bindings need
    recovery from the frame record.
    """
    declared = tuple(call.attributes.get("callee_input_ids", ()))
    if len(declared) != len(call.args) or len(set(declared)) != len(declared):
        return {}
    return {
        int(formal): caller_values[int(actual.id)]
        for formal, actual in zip(declared, call.args)
        if int(actual.id) in caller_values
    }


def _complete_propagated_frame_tails(functions: Mapping[str, Any]) -> int:
    """Complete every call whose callee's signature grew a frame-storage tail.

    Linking a callee to ITS callees can append propagated frame-storage
    formals to its signature after a call into it was already built.
    Such a call is not malformed; it is incomplete by exactly the
    appended tail.  Complete it the way the linker propagates every
    unbound callee formal: the caller receives one storage slot per
    appended formal (stamped ``propagated_formal_id``, the identity
    `_call_argument_identity` reads for it) and passes it through.
    Completing a call appends the same tail to the CALLER's own signature,
    so its callers are now short by that tail too: iterate to a fixed
    point, never a single pass in dictionary order (tick ->
    tire_recurrence -> balloon_tire was left two arguments short exactly
    that way).

    This ran only inside `_prune_unused_callee_formals`, at the very end
    of lowering -- after `_harmonize_call_argument_shapes` had already
    seen the grown callee and reported the tail as an "unidentified
    remainder" that "must already agree in count" (diagnosed against the
    real managed-tire compile: `_no_exchange_observed` gained one
    `linked_call_frame_storage` formal for its own `_scalar` call the
    moment its result became live, and `_apply_energy_sidechain`'s call
    into it was one operand short).  It is the same technique
    `_propagate_record_field_demand` already runs early for record
    fields; run it early for frame storage too.  Returns the number of
    slots appended.
    """

    from ..transmogrifier.ssa import SSAValue

    def calls_into(callee_name: str) -> list[tuple[Any, Any]]:
        return [
            (caller, instruction)
            for caller in functions.values()
            for block in caller.blocks.values()
            for instruction in block.instrs
            if (
                instruction.op in {"Call", "call"}
                and str(instruction.attributes.get("callee") or "")
                == str(callee_name)
            )
        ]

    appended = 0
    completed_any = True
    while completed_any:
        completed_any = False
        for callee_name, callee in functions.items():
            for owner, call in calls_into(callee_name):
                declared = call.attributes.get("callee_input_ids")
                if declared is not None:
                    if len(declared) != len(call.args) or len(set(declared)) != len(declared):
                        raise ValueError(
                            f"invalid native input binding receipt for {owner.name} -> {callee_name}: "
                            f"receipt={len(declared)}, operands={len(call.args)}, "
                            f"unique_formals={len(set(declared))}"
                        )
                    bound = dict(zip(declared, call.args))
                    live = [formal for formal in callee.args if int(formal.id) in bound]
                    call.args = [bound[int(formal.id)] for formal in live]
                    call.attributes["callee_input_ids"] = tuple(int(formal.id) for formal in live)
                    tail = [formal for formal in callee.args if int(formal.id) not in bound]
                else:
                    tail = callee.args[len(call.args):]
                if len(call.args) >= len(callee.args):
                    continue
                if not all(
                    (formal.accounting or {}).get("linked_call_frame_storage")
                    or (formal.accounting or {}).get("compiler_frame_storage")
                    for formal in tail
                ):
                    continue
                for formal in tail:
                    slot = SSAValue(
                        GLOBAL_MONOTONIC_IDS.mint(),
                        dtype=formal.dtype,
                        shape=tuple(formal.shape or ()),
                        device=formal.device,
                        accounting={
                            "linked_call_frame_storage": str(callee_name),
                            "callsite_id": call.attributes.get(
                                "plan_callsite_id"
                            ),
                            "propagated_formal_id": int(formal.id),
                        },
                    )
                    owner.args.append(slot)
                    call.args.append(slot)
                    if declared is not None:
                        call.attributes["callee_input_ids"] += (int(formal.id),)
                    completed_any = True
                    appended += 1
                if declared is not None:
                    bound = dict(zip(call.attributes["callee_input_ids"], call.args))
                    call.args = [bound[int(formal.id)] for formal in callee.args]
                    call.attributes["callee_input_ids"] = tuple(int(formal.id) for formal in callee.args)
    return appended


def _prune_unused_callee_formals(
    functions: Mapping[str, Any],
    call_records: Mapping[str, list[Any]] | None = None,
) -> int:
    """Rewrite dead callee formals and every call operand as one transaction.

    Region construction initially publishes its dependency frontier. Later
    constant folding and DCE can make some captures dead, but deleting only a
    formal or only an actual leaves the repository call ABI malformed. This
    pass owns both sides and updates the source-call receipt at the same seam.
    Authored/public parameters and declared storage remain stable even when an
    implementation happens not to read them.
    """

    from ..transmogrifier.ssa import SSAValue

    records = call_records or {}
    removed_total = 0
    def calls_into(callee_name: str) -> list[tuple[Any, Any]]:
        return [
            (caller, instruction)
            for caller in functions.values()
            for block in caller.blocks.values()
            for instruction in block.instrs
            if (
                instruction.op in {"Call", "call"}
                and str(instruction.attributes.get("callee") or "")
                == str(callee_name)
            )
        ]

    _complete_propagated_frame_tails(functions)
    for callee_name, callee in functions.items():
        caller_calls = calls_into(callee_name)
        callers = [instruction for _caller, instruction in caller_calls]
        if not callers:
            continue
        metadata = dict(getattr(callee, "metadata", {}) or {})
        protected = {
            int(value_id)
            for _name, value_id in (
                *metadata.get("parameter_names", ()),
                *metadata.get("named_outputs", ()),
            )
        }
        protected.update(
            int(item["value_id"])
            for item in metadata.get("storage_formals", ())
            if item.get("value_id") is not None
        )
        protected.update(map(
            int, metadata.get("sequence_array_argument_ids", ())
        ))
        record_parameter_names = set(map(
            str, dict(metadata.get("parameter_record_abi") or {}),
        ))
        record_parameter_ids = {
            int(value_id)
            for name, value_id in metadata.get("parameter_names", ())
            if str(name) in record_parameter_names
        }

        def conceptual_record_formal(formal: Any) -> bool:
            accounting = dict(formal.accounting or {})
            declared_parameter = accounting.get("program_abi_parameter")
            return (
                not tuple(formal.shape or ())
                and accounting.get("program_abi_field") is None
                and accounting.get("program_abi_storage") is None
                and (
                    int(formal.id) in record_parameter_ids
                    or (
                        declared_parameter is not None
                        and str(declared_parameter) in record_parameter_names
                    )
                )
            )
        referenced = {
            int(value.id)
            for block in callee.blocks.values()
            for instruction in block.instrs
            for value in (
                *instruction.args,
                *((instruction.res,) if instruction.res is not None else ()),
            )
        }
        removable_indices = tuple(
            index
            for index, formal in enumerate(callee.args)
            if int(formal.id) not in referenced
            and (
                int(formal.id) not in protected
                or (formal.accounting or {}).get("unbound_variant_source_id")
                is not None
                or conceptual_record_formal(formal)
            )
            and (
                not (formal.accounting or {}).get("program_abi_parameter")
                or conceptual_record_formal(formal)
            )
            and not any(
                (formal.accounting or {}).get(key) not in {None, ""}
                for key in (
                    "linked_call_frame_storage",
                    "returned_record_storage",
                    "compiler_frame_storage",
                )
            )
        )
        if not removable_indices:
            continue
        original_arity = len(callee.args)
        removed_index_set = set(removable_indices)
        keep_indices = tuple(
            index for index in range(original_arity)
            if index not in removed_index_set
        )
        removed_ids = {
            int(callee.args[index].id) for index in removable_indices
        }
        for call in callers:
            if len(call.args) < original_arity:
                raise ValueError(
                    "call has fewer operands than the callee signature while "
                    f"pruning {callee_name!r}: operands={len(call.args)} "
                    f"formals={original_arity}"
                )
            call.args = [
                argument for index, argument in enumerate(call.args)
                if index >= original_arity or index in keep_indices
            ]
            for attribute_name in (
                "feed_ids", "feed_shapes", "feed_dtypes", "input_ids", "callee_input_ids",
            ):
                values = call.attributes.get(attribute_name)
                if values is None or len(tuple(values)) != original_arity:
                    continue
                call.attributes[attribute_name] = tuple(
                    values[index] for index in keep_indices
                )
        callee.args = [callee.args[index] for index in keep_indices]
        integral = dict(metadata.get("source_region_integral") or {})
        if integral.get("capture_value_ids") is not None:
            integral["capture_value_ids"] = tuple(
                value_id for value_id in integral["capture_value_ids"]
                if int(value_id) not in removed_ids
            )
            metadata["source_region_integral"] = integral
        if "scalar_variant_argument_ids" in metadata:
            metadata["scalar_variant_argument_ids"] = tuple(
                value_id for value_id in metadata["scalar_variant_argument_ids"]
                if int(value_id) not in removed_ids
            )
        if "sequence_array_argument_ids" in metadata:
            metadata["sequence_array_argument_ids"] = tuple(
                value_id for value_id in metadata["sequence_array_argument_ids"]
                if int(value_id) not in removed_ids
            )
        callee.metadata = metadata
        for caller_records in records.values():
            for record_index, record in enumerate(tuple(caller_records)):
                if str(record.callee_symbol or "") != str(callee_name):
                    continue
                caller_records[record_index] = replace(
                    record,
                    argument_bindings=tuple(
                        binding for binding in record.argument_bindings
                        if int(binding[1]) not in removed_ids
                    ),
                    callee_storage_value_ids=tuple(
                        value_id for value_id in record.callee_storage_value_ids
                        if int(value_id) not in removed_ids
                    ),
                    frame_bindings=tuple(
                        binding for binding in record.frame_bindings
                        if int(binding[0]) not in removed_ids
                    ),
                    unresolved_frame_value_ids=tuple(
                        value_id for value_id in record.unresolved_frame_value_ids
                        if int(value_id) not in removed_ids
                    ),
                )
        removed_total += len(removable_indices)
    return removed_total


def _is_dead_conceptual_record_argument(
    argument: Any,
    record_ids: Collection[int],
    consumed_ids: Collection[int],
) -> bool:
    """Distinguish record correlation from physical record storage.

    Late scalar type settlement can give a conceptual record handle the dtype
    of one of its projected fields.  Dtype is therefore not identity evidence.
    ProgramABI field/storage accounting is: a physical field carries one of
    those durable markers, while the aggregate handle does not.
    """

    value_id = int(argument.id)
    accounting = dict(argument.accounting or {})
    physical = any(
        accounting.get(key) not in {None, ""}
        for key in (
            "program_abi_field",
            "program_abi_storage",
            "linked_call_frame_storage",
            "returned_record_storage",
            "compiler_frame_storage",
        )
    )
    return (
        value_id in set(map(int, record_ids))
        and value_id not in set(map(int, consumed_ids))
        and not tuple(argument.shape or ())
        and not physical
    )


def _lower_planned_region_record_projection_captures(
    functions: Mapping[str, Any],
    record_tables: Mapping[str, Any],
) -> int:
    """Pass proven scalar record fields into numerical regions explicitly.

    A planned numerical region cannot interpret a conceptual Python record
    handle.  Late record linking can nevertheless leave an initial-state
    ``getattr`` in such a region after the owner has already resolved that
    projection to one physical scalar field.  Move that exact resident value
    across the region boundary and replace the projection with a scalar cast.

    The proof is deliberately closed: the region names one owner, every
    projection result reaches a finite owner alias chain, the call's receiver
    names an owner record, and that record's named scalar field contains the
    alias incumbent.  Cycles, ambiguity, and incompatible candidates make no
    change.  Equal evidence reuses the first capture already installed for
    the resident field.
    """

    from ..transmogrifier.ssa import Instr, SSARecordFieldStorage, SSAValue

    def function_values(function: Any) -> dict[int, Any]:
        values = {int(value.id): value for value in function.args}
        values.update(
            (int(instruction.res.id), instruction.res)
            for block in function.blocks.values()
            for instruction in block.instrs
            if instruction.res is not None
        )
        return values

    def alias_incumbent(function: Any, value_id: int) -> int | None:
        aliases = _concordant_function_aliases(function)
        current = int(value_id)
        seen: set[int] = set()
        followed = False
        while current in aliases:
            if current in seen:
                return None
            seen.add(current)
            current = aliases[current]
            followed = True
        return current if followed else None

    def record_incumbent(function: Any, value_id: int) -> int | None:
        aliases = _concordant_function_aliases(
            function, include_output_identities=True,
        )
        current = int(value_id)
        seen: set[int] = set()
        while current in aliases:
            if current in seen:
                return None
            seen.add(current)
            current = aliases[current]
        return current

    def calls_into(callee_name: str) -> list[tuple[Any, Any]]:
        return [
            (caller, instruction)
            for caller in functions.values()
            for block in caller.blocks.values()
            for instruction in block.instrs
            if (
                str(instruction.op).casefold() == "call"
                and str(instruction.attributes.get("callee") or "")
                == str(callee_name)
            )
        ]

    lowered = 0
    for region_name, region in functions.items():
        integral = dict(
            (region.metadata or {}).get("source_region_integral") or {}
        )
        owner_name = str(integral.get("owner") or "")
        owner = functions.get(owner_name)
        owner_records = record_tables.get(owner_name)
        caller_calls = calls_into(str(region_name))
        if owner is None or owner_records is None or not caller_calls:
            continue
        if any(caller is not owner for caller, _call in caller_calls):
            continue

        owner_values = function_values(owner)
        region_values = function_values(region)
        formal_positions = {
            int(formal.id): index for index, formal in enumerate(region.args)
        }
        candidates: list[tuple[Any, int, str, int, Any]] = []
        for block in region.blocks.values():
            for instruction in block.instrs:
                if (
                    str(instruction.op).casefold() != "getattr"
                    or instruction.res is None
                    or len(instruction.args) != 1
                ):
                    continue
                receiver_id = int(instruction.args[0].id)
                receiver_position = formal_positions.get(receiver_id)
                attribute = str(
                    instruction.attributes.get("attribute")
                    or instruction.attributes.get("name")
                    or ""
                )
                resident_id = alias_incumbent(owner, int(instruction.res.id))
                resident = (
                    None if resident_id is None
                    else owner_values.get(resident_id)
                )
                if (
                    receiver_position is None
                    or resident is None
                    or tuple(resident.shape or ())
                ):
                    continue

                proven = True
                for _caller, call in caller_calls:
                    if len(call.args) != len(region.args):
                        proven = False
                        break
                    declared = call.attributes.get("callee_input_ids")
                    if declared is not None:
                        declared = tuple(map(int, declared))
                        if (
                            len(declared) != len(call.args)
                            or receiver_id not in declared
                        ):
                            proven = False
                            break
                        actual = call.args[declared.index(receiver_id)]
                    else:
                        actual = call.args[receiver_position]
                    actual_record_id = int(actual.id)
                    same_receiver = (
                        record_incumbent(owner, actual_record_id)
                        == record_incumbent(owner, receiver_id)
                    )
                    descriptor = owner_records.records.get(actual_record_id)
                    if descriptor is None and same_receiver:
                        # An exact returned-record identity call has no native
                        # scalar result: the call mutates the receiver fields
                        # in place. Region planning still names the authored
                        # result handle while its scheduled call operand names
                        # the receiver handle. The owner's identity ledgers are
                        # the proof that these are the same record; use the
                        # descriptor already registered for either spelling.
                        descriptor = (
                            owner_records.records.get(receiver_id)
                            or owner_records.records.get(
                                int(record_incumbent(owner, receiver_id))
                            )
                        )
                    if not attribute and descriptor is not None:
                        # Region lowering can consume the source-only getattr
                        # annotation after assigning the projection its SSA
                        # result. The record table and the owner's exact result
                        # alias survive. Recover the name only when that
                        # resident belongs to one scalar field of this exact
                        # receiver descriptor.
                        resident_fields = tuple(
                            field.name for field in descriptor.fields
                            if (
                                field.storage is SSARecordFieldStorage.SCALAR
                                and resident_id in map(int, field.value_ids)
                            )
                        )
                        if len(resident_fields) == 1:
                            attribute = str(resident_fields[0])
                    matching = tuple(
                        field for field in (() if descriptor is None else descriptor.fields)
                        if (
                            field.name == attribute
                            and field.storage is SSARecordFieldStorage.SCALAR
                            and resident_id in map(int, field.value_ids)
                        )
                    )
                    if descriptor is not None and len(matching) != 1:
                        proven = False
                        break
                    if descriptor is None and not same_receiver:
                        proven = False
                        break
                if proven:
                    candidates.append((
                        instruction, receiver_id, attribute,
                        int(resident_id), resident,
                    ))

        captures: dict[int, Any] = {}
        receipts: list[tuple[int, str, int, int]] = []
        for instruction, receiver_id, attribute, resident_id, resident in candidates:
            capture = captures.get(resident_id)
            if capture is None:
                occupied = region_values.get(resident_id)
                if occupied is not None:
                    # A pre-existing definition has priority.  It is usable
                    # only when it is already the same formal capture.
                    if occupied not in region.args:
                        continue
                    capture = occupied
                else:
                    capture = SSAValue(
                        resident_id,
                        dtype=resident.dtype,
                        shape=tuple(resident.shape or ()),
                        device=resident.device,
                        accounting={
                            **dict(resident.accounting or {}),
                            "source_record_field_capture": attribute,
                            "source_record_receiver_id": receiver_id,
                            "source_value_id": resident_id,
                            "capture_owner": owner_name,
                        },
                    )
                    region.args.append(capture)
                    region_values[resident_id] = capture
                    for _caller, call in caller_calls:
                        old_arity = len(call.args)
                        call.args.append(resident)
                        for key, value in (
                            ("feed_ids", resident_id),
                            ("feed_shapes", tuple(resident.shape or ())),
                            ("feed_dtypes", resident.dtype),
                            ("input_ids", resident_id),
                            ("callee_input_ids", resident_id),
                        ):
                            sequence = call.attributes.get(key)
                            if sequence is not None and len(tuple(sequence)) == old_arity:
                                call.attributes[key] = (*tuple(sequence), value)
                    capture_ids = list(map(
                        int, integral.get("capture_value_ids") or ()
                    ))
                    if resident_id not in capture_ids:
                        capture_ids.append(resident_id)
                    integral["capture_value_ids"] = tuple(capture_ids)
                captures.setdefault(resident_id, capture)

            instruction.op = "Cast"
            instruction.args = [capture]
            instruction.arg_roles = []
            instruction.attributes = {
                "target_dtype": str(
                    instruction.res.dtype or capture.dtype or "float64"
                ),
                "resolved_record_field_projection": True,
                "record_receiver_id": receiver_id,
                "record_field": attribute,
                "resident_value_id": resident_id,
                "tie_policy": "incumbent",
            }
            receipts.append((
                int(instruction.res.id), attribute, receiver_id, resident_id,
            ))
            lowered += 1

        if receipts:
            replaced_receivers = {receipt[2] for receipt in receipts}
            still_consumed = {
                int(argument.id)
                for block in region.blocks.values()
                for instruction in block.instrs
                for argument in instruction.args
            }
            integral["capture_value_ids"] = tuple(
                value_id
                for value_id in integral.get("capture_value_ids", ())
                if (
                    int(value_id) not in replaced_receivers
                    or int(value_id) in still_consumed
                )
            )
            region_metadata = dict(region.metadata or {})
            region_metadata["source_region_integral"] = integral
            existing = tuple(
                region_metadata.get("lowered_record_projection_captures", ())
            )
            region_metadata["lowered_record_projection_captures"] = tuple(
                dict.fromkeys((*existing, *receipts))
            )
            region.metadata = region_metadata
    return lowered


def _loop_carried_storage_aliases(graph_obj) -> dict[int, int]:
    """Graph-derived storage aliases for loop-carried in-place mutation.

    A loop that mutates an array through ``IndexedStore`` leaves a
    LOOPRESULT node as the array's post-loop identity. That identity is
    the SAME STORAGE as the array it mutated -- in-place is the point --
    but the planner schedules later consumers against the loopresult id,
    and a lowering that cannot link it materializes a fresh, unconnected
    FORMAL: the second of two sequential loops over one array then reads
    the original buffer and the first loop's stores silently vanish (the
    sequential same-array store defect, pinned in
    ``test_compiled_linalg.py``).

    The chase is deliberately narrow, one level per node, composed by the
    builder's existing alias-chain walk (``external_value``):

    * a ``loopresult``/``loopexit`` node aliases its preferred-role parent
      ONLY when that parent is itself an ``IndexedStore`` version or
      another loop identity -- scalar carried results (a ``total``) are
      genuine values with carried-port machinery of their own and are
      never touched;
    * an ``IndexedStore`` node aliases its ``base`` -- the store versions
      resident memory, it does not mint storage (the same rule
      ``ir_indexing`` applies inside a function, extended to the graph
      so it holds ACROSS loops).
    """

    aliases: dict[int, int] = {}
    chainable = {"indexedstore", "loopresult", "loopexit"}

    def node_kind(node_id) -> str:
        data = graph_obj.nodes.get(node_id) or {}
        return str(data.get("op") or data.get("type") or "").casefold()

    def value_id_of(node_id) -> int:
        data = graph_obj.nodes.get(node_id) or {}
        return int(data.get("value_id", node_id))

    for node_id, data in graph_obj.nodes(data=True):
        kind = str(data.get("op") or data.get("type") or "").casefold()
        parents = tuple(data.get("parents") or ())
        if kind == "indexedstore":
            base = next(
                (parent for parent, role in parents
                 if str(role) == "base" and parent in graph_obj),
                None,
            )
            if base is not None:
                aliases[value_id_of(node_id)] = value_id_of(base)
            continue
        if kind in {"loopresult", "loopexit"}:
            for preferred_role in (
                "updated", "value", "body", "initial", "orelse"
            ):
                parent = next(
                    (parent for parent, role in parents
                     if str(role) == preferred_role
                     and parent in graph_obj),
                    None,
                )
                if parent is None:
                    continue
                if node_kind(parent) in chainable:
                    aliases[value_id_of(node_id)] = value_id_of(parent)
                break
    def root(value):
        seen = set()
        while value in aliases and value not in seen:
            seen.add(value)
            value = aliases[value]
        return value

    changed = True
    while changed:
        changed = False
        for node_id, data in graph_obj.nodes(data=True):
            if node_kind(node_id) != "phi":
                continue
            parents = [root(value_id_of(parent)) for parent, role in data.get("parents") or ()
                       if role in {"body", "orelse"} and parent in graph_obj]
            if len(parents) != 2 or parents[0] != parents[1]:
                continue
            resident = parents[0]
            if (graph_obj.nodes.get(resident, {}).get("attributes") or {}).get("aggregate_kind") != "dict":
                continue
            value = value_id_of(node_id)
            if value != resident and aliases.get(value) != resident:
                aliases[value] = resident
                changed = True
    aliases = {source: root(target) for source, target in aliases.items()}
    # Never allow a cycle to reach the builder's chase (it guards with a
    # seen-set, but a self-alias is meaningless regardless).
    return {
        source: target for source, target in aliases.items()
        if source != target
    }


def _identifier(value: str) -> str:
    result = re.sub(r"[^A-Za-z0-9_]", "_", str(value))
    if not result or result[0].isdigit():
        result = "turing_" + result
    return result


def _record_receipts_for_function(
    program_abi: Mapping[str, Any],
    function_name: str,
    parameters: Iterable[str],
    *,
    method_owner: str | None = None,
) -> dict[str, Mapping[str, Any]]:
    """Select explicit record bindings plus an exact method receiver schema.

    The receipt form is used after the extraction contract object has been
    reduced to serializable graph metadata.  Keep its selection semantics in
    step with :meth:`ProgramABIContract.records_for_function`: an unannotated
    ``self`` is safely identifiable from ``method_owner`` only when exactly
    one declared record has that class identity.
    """

    parameter_names = set(map(str, parameters))
    records = dict(program_abi.get("records") or {})
    selected: dict[str, Mapping[str, Any]] = {}
    for binding in tuple(program_abi.get("bindings") or ()):
        parameter = str(binding.get("parameter") or "")
        record_name = str(binding.get("record") or "")
        if (
            parameter in parameter_names
            and fnmatchcase(str(function_name), str(binding.get("function") or ""))
            and record_name in records
        ):
            selected[parameter] = records[record_name]
    if (
        method_owner is not None
        and "self" in parameter_names
        and "self" not in selected
    ):
        owner = str(method_owner)
        candidates = tuple(
            record
            for name, record in records.items()
            if (
                str(name) == owner
                or str(record.get("identity") or "") == owner
                or str(record.get("identity") or "").rsplit(".", 1)[-1]
                == owner
            )
        )
        if len(candidates) == 1:
            selected["self"] = candidates[0]
    return selected


def _record_field_read(graph: Any, node_id: Any, data: Mapping[str, Any]):
    """Return ``(result, owner, field)`` for either spelling of a field read.

    Python's ``obj.field`` is already a GetAttr graph node.  The equivalent
    ``getattr(obj, "field", default)`` remains an intrinsic Call until SSA
    lowering, but it names the same ProgramABI storage and presence bit.
    Recognize both from exact graph roles and the literal field name.
    """

    operation = str(data.get("type") or data.get("op") or "").casefold()
    parents = tuple(data.get("parents") or ())
    if operation == "getattr":
        field = (data.get("attributes") or {}).get("attribute")
        owner = next((
            parent for parent, role in parents
            if str(role) in {"value", "object", "base", "receiver"}
        ), None)
    elif (
        operation in {"call", "plancall"}
        and str((data.get("attributes") or {}).get(
            "static_python_reference"
        ) or "") in {"getattr", "builtins.getattr"}
    ):
        owner = next((
            parent for parent, role in parents if str(role) == "arg:0"
        ), None)
        field_node = next((
            parent for parent, role in parents if str(role) == "arg:1"
        ), None)
        field_data = graph.nodes.get(field_node, {})
        field_attributes = field_data.get("attributes") or {}
        field = field_attributes.get(
            "value", field_data.get("constant")
        )
    else:
        return None
    if owner is None or not isinstance(field, str):
        return None
    return (
        int(data.get("value_id", node_id)),
        int(graph.nodes[owner].get("value_id", owner)),
        field,
    )


def _lower_optional_record_presence_graph(graph_obj: Any) -> int:
    """Give each optional record field one explicit presence identity.

    Source ``is None``/``is not None`` tests are identity tests, not numeric
    comparisons against the payload.  Before region planning, replace every
    such test with a read of one canonical Boolean input for the field (or its
    logical negation).  All occurrences in a function therefore observe the
    same caller-owned cell, including after a mutable field write.
    """

    graph = graph_obj
    if (graph.graph.get("optional_record_presence_lowered") is not None):
        return int(graph.graph.get("optional_record_presence_lowered") or 0)
    # A discovery graph can be visited before its ProgramABI receipt is
    # reattached after topology reduction.  That visit is not a completed
    # lowering: leave the marker unset so the canonical pre-planning graph
    # can still acquire and lower its optional fields later.
    if not graph.graph.get("parameter_record_abi"):
        return 0
    identities = graph.graph.get("identity_table") or {}
    receipts: list[dict[str, Any]] = []

    def value_id(node_id: Any) -> int:
        return int(graph.nodes[node_id].get("value_id", node_id))

    def is_none_node(node_id: Any) -> bool:
        if node_id not in graph:
            return False
        data = graph.nodes[node_id]
        attributes = data.get("attributes") or {}
        return (
            str(data.get("type") or data.get("op") or "").casefold()
            in {"constant", "const", "none", "nonevalue"}
            and attributes.get("value", data.get("constant")) is None
        )

    def detach_inputs(node_id: Any) -> None:
        data = graph.nodes[node_id]
        for parent, role in tuple(data.get("parents") or ()):
            if parent in graph:
                graph.nodes[parent]["children"] = [
                    item for item in graph.nodes[parent].get("children") or ()
                    if not (int(item[0]) == int(node_id) and item[1] == role)
                ]
                if graph.has_edge(parent, node_id):
                    graph.remove_edge(parent, node_id)
        data["parents"] = []

    def replace_uses(old_id: Any, new_id: Any) -> None:
        for child in tuple(graph.successors(old_id)):
            edge = dict(graph.get_edge_data(old_id, child) or {})
            role = edge.get("role")
            child_data = graph.nodes[child]
            child_data["parents"] = [
                (new_id if parent == old_id else parent, held_role)
                for parent, held_role in child_data.get("parents") or ()
            ]
            graph.add_edge(new_id, child, **edge)
            children = graph.nodes[new_id].setdefault("children", [])
            if (child, role) not in children:
                children.append((child, role))
            graph.remove_edge(old_id, child)
        graph.nodes[old_id]["children"] = []

    from .process_graph_value_ids import next_process_value_id

    for parameter, record in dict(
        graph.graph.get("parameter_record_abi") or {}
    ).items():
        owner_ids = set(map(int, identities.get(str(parameter), ())))
        if not owner_ids:
            continue
        for field_name, field in dict(record.get("fields") or {}).items():
            if not bool(field.get("optional", False)):
                continue
            comparisons: list[tuple[Any, bool]] = []
            for getter_id, getter in tuple(graph.nodes(data=True)):
                field_read = _record_field_read(
                    graph, getter_id, getter
                )
                if field_read is None:
                    continue
                _result_id, owner_id, read_field = field_read
                if read_field != str(field_name) or owner_id not in owner_ids:
                    continue
                for compare_id in tuple(graph.successors(getter_id)):
                    compare = graph.nodes[compare_id]
                    expression = compare.get("expr_obj")
                    if not (
                        isinstance(expression, ast.Compare)
                        and len(expression.ops) == 1
                        and isinstance(expression.ops[0], (ast.Is, ast.IsNot))
                        and any(
                            is_none_node(parent)
                            for parent, _role in compare.get("parents") or ()
                            if parent != getter_id
                        )
                    ):
                        continue
                    comparisons.append((
                        compare_id, isinstance(expression.ops[0], ast.IsNot),
                    ))
            comparisons = list(dict.fromkeys(comparisons))
            positive = next((
                node_id for node_id, present_when in comparisons if present_when
            ), None)
            if positive is None:
                positive = next_process_value_id(graph)
                graph.add_node(
                    positive,
                    label=f"{parameter}.{field_name}.__present",
                    type="Input",
                    op="input",
                    expr_obj=None,
                    parents=[],
                    children=[],
                    attributes={},
                    value_id=positive,
                    tensor={"shape": (), "dtype": "bool"},
                )
            else:
                detach_inputs(positive)
            positive_data = graph.nodes[positive]
            positive_data.update({
                "label": f"{parameter}.{field_name}.__present",
                "type": "Input",
                "op": "input",
                "expr_obj": None,
                "parents": [],
                "constant": None,
                "tensor": {"shape": (), "dtype": "bool"},
                "attributes": {
                    **dict(positive_data.get("attributes") or {}),
                    "binding_kind": "program_abi_optional_presence",
                    "program_abi_parameter": str(parameter),
                    "program_abi_field": str(field_name),
                    "program_abi_optional_presence": True,
                    "program_abi_optional_present_when": True,
                },
            })
            for compare_id, present_when in comparisons:
                if compare_id == positive:
                    continue
                if present_when:
                    replace_uses(compare_id, positive)
                    detach_inputs(compare_id)
                    graph.remove_node(compare_id)
                    continue
                detach_inputs(compare_id)
                compare = graph.nodes[compare_id]
                compare.update({
                    "label": "logical_not",
                    "type": "logical_not",
                    "op": "logical_not",
                    "expr_obj": None,
                    "parents": [(positive, "operand")],
                    "constant": None,
                    "tensor": {"shape": (), "dtype": "bool"},
                    "attributes": {
                        **dict(compare.get("attributes") or {}),
                        "optional_presence_negation": True,
                        "program_abi_parameter": str(parameter),
                        "program_abi_field": str(field_name),
                    },
                })
                graph.add_edge(positive, compare_id, role="operand")
                children = positive_data.setdefault("children", [])
                if (compare_id, "operand") not in children:
                    children.append((compare_id, "operand"))
            receipts.append({
                "parameter": str(parameter),
                "field": str(field_name),
                "presence_value_id": value_id(positive),
                "test_count": len(comparisons),
                "mutable": bool(field.get("mutable", False)),
            })
    graph.graph["optional_record_presence_receipts"] = tuple(receipts)
    graph.graph["optional_record_presence_lowered"] = len(receipts)
    return len(receipts)


def _lower_optional_record_presence_catalogue(graph: Any) -> int:
    """Lower optional-field identity tests throughout one function table.

    Control planning consumes the post-reduction function catalogue, so this
    pass must run on those graphs before deployment strategy is selected.
    The per-graph marker makes repeated catalogue visits finite and stable.
    """

    lowered = 0
    seen: set[int] = set()
    for candidate in (
        graph,
        *(getattr(entry, "graph", None) for entry in graph.function_table),
    ):
        graph_obj = getattr(candidate, "G", None)
        if graph_obj is None or id(graph_obj) in seen:
            continue
        seen.add(id(graph_obj))
        lowered += _lower_optional_record_presence_graph(graph_obj)
    return lowered


def _authored_annotation_field_receipt(
    annotation: ast.AST,
    python_bindings: Mapping[str, Any] | None = None,
) -> Mapping[str, Any] | None:
    """Return the exact scalar/fixed-span ABI stated by an annotation."""

    if isinstance(annotation, ast.BinOp) and isinstance(annotation.op, ast.BitOr):
        members = (annotation.left, annotation.right)
        concrete = tuple(
            member for member in members
            if not (isinstance(member, ast.Constant) and member.value is None)
            and not (isinstance(member, ast.Name) and member.id == "None")
        )
        if len(concrete) == 1 and len(concrete) != len(members):
            receipt = _authored_annotation_field_receipt(
                concrete[0], python_bindings,
            )
            if receipt is not None:
                return {**dict(receipt), "optional": True}

    # A frontend ``Tensor`` annotation states an abstract tensor value.  Its
    # native storage is the repository's span ABI; neither the frontend class
    # nor an opaque object handle survives AST ingestion.  The annotation does
    # not state logical extents, so keep the physical flat-span rank here and
    # let ordinary tensor shape SSA carry the logical rank and extents.
    from ..transmogrifier.graph.node_special_cases import (
        tensor_annotation_identity,
    )

    tensor_identity = tensor_annotation_identity(annotation, python_bindings)
    if tensor_identity is not None:
        return {
            "storage": "span",
            "dtype": "unknown",
            "rank": 1,
            "mutable": False,
            "python_type": str(tensor_identity),
        }

    if isinstance(annotation, ast.Name):
        scalar = {
            "int": "int64", "float": "float64", "bool": "bool",
        }.get(annotation.id)
        if scalar is not None:
            return {
                "storage": "scalar", "dtype": scalar, "rank": 0,
                "mutable": False,
            }
        if annotation.id in {"bytes", "bytearray", "str"}:
            return {
                "storage": "span", "dtype": "int64", "rank": 1,
                "mutable": False,
                "aggregate_kind": annotation.id,
            }
        return None
    if not isinstance(annotation, ast.Subscript):
        return None
    container = (
        annotation.value.id
        if isinstance(annotation.value, ast.Name)
        else annotation.value.attr
        if isinstance(annotation.value, ast.Attribute)
        else ""
    )
    if container == "Literal":
        members = (
            tuple(annotation.slice.elts)
            if isinstance(annotation.slice, ast.Tuple)
            else (annotation.slice,)
        )
        vocabulary = tuple(
            str(member.value)
            for member in members
            if isinstance(member, ast.Constant)
            and isinstance(member.value, str)
        )
        if len(vocabulary) == len(members) and vocabulary:
            return {
                "storage": "scalar", "dtype": "int64", "rank": 0,
                "mutable": False, "token_vocabulary": vocabulary,
            }
        return None
    if container == "Optional":
        receipt = _authored_annotation_field_receipt(
            annotation.slice, python_bindings,
        )
        return (
            None if receipt is None
            else {**dict(receipt), "optional": True}
        )
    if container == "Callable":
        # A callable is an authored native reference, not an opaque Python
        # object and not a scalar guessed from its eventual use.  Keep the
        # exact signature on the source-derived record receipt so later call
        # planning can correlate the field with the function-table identity
        # stored by the constructor.  ``reference`` is the repository's
        # existing ABI storage class for an externally materialized address.
        return {
            "storage": "reference",
            "dtype": "int64",
            "rank": 0,
            "mutable": False,
            "callable_signature": ast.unparse(annotation),
        }
    if container in {"dict", "Dict", "Mapping", "MutableMapping"}:
        columns = (
            tuple(annotation.slice.elts)
            if isinstance(annotation.slice, ast.Tuple)
            else (annotation.slice,)
        )
        if len(columns) != 2:
            return None
        key_annotation, value_annotation = columns
        key_name = (
            key_annotation.id
            if isinstance(key_annotation, ast.Name)
            else key_annotation.attr
            if isinstance(key_annotation, ast.Attribute)
            else ""
        )
        key_encoding = {
            "str": "string_token",
            "int": "integer_identity",
        }.get(str(key_name))
        if key_encoding is None:
            return None
        value_optional = False
        if isinstance(value_annotation, ast.BinOp) and isinstance(
            value_annotation.op, ast.BitOr
        ):
            concrete = tuple(
                member
                for member in (value_annotation.left, value_annotation.right)
                if not (
                    isinstance(member, ast.Constant)
                    and member.value is None
                )
                and not (
                    isinstance(member, ast.Name) and member.id == "None"
                )
            )
            if len(concrete) != 1:
                return None
            value_annotation = concrete[0]
            value_optional = True
        value_name = (
            value_annotation.id
            if isinstance(value_annotation, ast.Name)
            else value_annotation.attr
            if isinstance(value_annotation, ast.Attribute)
            else ""
        )
        from ..transmogrifier.graph.node_special_cases import (
            tensor_annotation_identity,
        )

        value_is_tensor = tensor_annotation_identity(
            value_annotation, python_bindings,
        ) is not None
        value_dtype = {
            "bool": "bool", "int": "int64", "float": "float64",
            "str": "int64",
        }.get(str(value_name))
        value_record = None
        if value_is_tensor:
            value_dtype = "unknown"
        elif value_dtype is None and value_name:
            value_dtype = "int64"
            value_record = str(value_name)
        if value_dtype is None:
            return None
        return {
            "storage": "keyed",
            "dtype": value_dtype,
            "rank": 1,
            "mutable": container in {"dict", "Dict", "MutableMapping"},
            "key_encoding": key_encoding,
            **({
                "value_tensor": True,
                "value_python_type": "AbstractTensor",
            } if value_is_tensor else {}),
            **({"value_record": value_record} if value_record else {}),
            **({"optional": True} if value_optional else {}),
        }
    if container not in {"list", "tuple", "Sequence", "Iterable"}:
        return None
    element = annotation.slice
    fixed_length = None
    if isinstance(element, ast.Tuple) and element.elts:
        if container == "tuple" and not any(
            isinstance(item, ast.Constant) and item.value is Ellipsis
            for item in element.elts
        ):
            element_dtypes = tuple(
                item.id if isinstance(item, ast.Name) else None
                for item in element.elts
            )
            if len(set(element_dtypes)) != 1:
                return None
            fixed_length = len(element.elts)
        element = element.elts[0]
    if not isinstance(element, ast.Name):
        return None
    dtype = {
        "int": "int64", "float": "float64", "bool": "bool",
        "bytes": "int64", "bytearray": "int64", "str": "int64",
    }.get(element.id)
    if dtype is None:
        return None
    receipt = {
        "storage": "span", "dtype": dtype, "rank": 1,
        "mutable": False,
        "aggregate_kind": container.casefold(),
    }
    if fixed_length is not None:
        receipt["fixed_length"] = int(fixed_length)
    return receipt


def _authored_complete_record_schemas(
    tree: ast.Module,
) -> dict[str, Mapping[str, Any]]:
    """Publish dataclass constructors only when every field has a physical ABI.

    Per-function record views may safely expose only fields a function uses.
    Construction is stricter: a partial class layout would silently discard
    authored state, so one unsupported declared field refuses the whole schema.
    """

    schemas: dict[str, Mapping[str, Any]] = {}
    for statement in tree.body:
        if not isinstance(statement, ast.ClassDef):
            continue
        decorators = {
            target.id
            if isinstance(target, ast.Name)
            else target.attr
            if isinstance(target, ast.Attribute)
            else ""
            for decorator in statement.decorator_list
            for target in (
                decorator.func if isinstance(decorator, ast.Call) else decorator,
            )
        }
        if "dataclass" not in decorators:
            continue
        declared = [
            field for field in statement.body
            if isinstance(field, ast.AnnAssign)
            and isinstance(field.target, ast.Name)
        ]
        if not declared:
            continue
        fields: dict[str, Mapping[str, Any]] = {}
        complete = True
        for field in declared:
            receipt = _authored_annotation_field_receipt(field.annotation)
            if receipt is None:
                complete = False
                break
            receipt = dict(receipt)
            if field.value is not None:
                try:
                    receipt["default"] = ast.literal_eval(field.value)
                except (TypeError, ValueError):
                    pass
            fields[field.target.id] = receipt
        if complete:
            schemas[statement.name] = {
                "identity": statement.name,
                "fields": fields,
                "source_derived": True,
            }
    return schemas


def _authored_sequence_record_views(
    tree: ast.Module,
    schemas: Mapping[str, Mapping[str, Any]],
) -> dict[str, dict[str, Mapping[str, Any]]]:
    """Derive exact ``Sequence[Record]`` binding row contracts.

    The sequence is caller-owned columnar storage; its loop target is a row
    correlation, never a Python object crossing the native ABI. Only complete
    declared record schemas are admitted, so every projected field has a
    declared physical representation before lowering begins.
    """

    views: dict[str, dict[str, Mapping[str, Any]]] = {}

    def element_record(annotation: ast.AST | None) -> str | None:
        if not isinstance(annotation, ast.Subscript):
            return None
        container = (
            annotation.value.id
            if isinstance(annotation.value, ast.Name)
            else annotation.value.attr
            if isinstance(annotation.value, ast.Attribute)
            else ""
        )
        if container not in {"list", "tuple", "Sequence", "Iterable"}:
            return None
        element = annotation.slice
        if isinstance(element, ast.Tuple) and len(element.elts) == 1:
            element = element.elts[0]
        identity = (
            element.id if isinstance(element, ast.Name)
            else element.attr if isinstance(element, ast.Attribute)
            else None
        )
        return str(identity) if identity in schemas else None

    def visit(
        qualified_name: str,
        definition: ast.FunctionDef | ast.AsyncFunctionDef,
    ) -> None:
        def register(binding_name: str, annotation: ast.AST | None, *, mutable: bool) -> None:
            identity = element_record(annotation)
            if identity is None:
                return
            schema = dict(schemas[identity])
            views.setdefault(qualified_name, {})[str(binding_name)] = {
                "identity": str(schema.get("identity") or identity),
                "fields": copy.deepcopy(dict(schema.get("fields") or {})),
                "aggregate_kind": "tuple",
                "mutable": bool(mutable),
                "source_derived": True,
            }

        for argument in (
            *definition.args.posonlyargs,
            *definition.args.args,
            *definition.args.kwonlyargs,
        ):
            register(argument.arg, argument.annotation, mutable=False)

        class LocalAnnotations(ast.NodeVisitor):
            def visit_AnnAssign(self, node: ast.AnnAssign) -> None:
                if isinstance(node.target, ast.Name):
                    register(node.target.id, node.annotation, mutable=True)
                self.generic_visit(node)

            def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
                return

            def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
                return

            def visit_ClassDef(self, node: ast.ClassDef) -> None:
                return

        visitor = LocalAnnotations()
        for statement in definition.body:
            visitor.visit(statement)

    for statement in tree.body:
        if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef)):
            visit(statement.name, statement)
        elif isinstance(statement, ast.ClassDef):
            for member in statement.body:
                if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    visit(f"{statement.name}.{member.name}", member)
    return views


def _unwrap_optional_annotation(expression: ast.AST) -> ast.AST:
    """``X | None`` and ``Optional[X]`` declare the same row as ``X``."""

    while True:
        if (
            isinstance(expression, ast.BinOp)
            and isinstance(expression.op, ast.BitOr)
        ):
            sides = (expression.left, expression.right)
            kept = tuple(
                side for side in sides
                if not (isinstance(side, ast.Constant) and side.value is None)
            )
            if len(kept) == 1:
                expression = kept[0]
                continue
            return expression
        if (
            isinstance(expression, ast.Subscript)
            and (
                (isinstance(expression.value, ast.Name)
                 and expression.value.id == "Optional")
                or (isinstance(expression.value, ast.Attribute)
                    and expression.value.attr == "Optional")
            )
        ):
            expression = expression.slice
            continue
        return expression


def _authored_row_layout(
    annotation: Any,
    repository_records: Mapping[str, Mapping[str, Any]],
) -> tuple[tuple[str, str | None, int], ...] | None:
    """Read a fixed tuple row's physical layout from a container annotation.

    ``list[tuple[float, Metrics, tuple[str, ...]]]`` declares one row of
    three authored columns.  A column naming a repository record is not one
    physical column: the record has no physical identity of its own, so its
    row is its member fields, exactly as ``_record_row_physical_columns``
    lays out a whole-record row.  Each entry is ``(kind, identity, width)``
    with ``kind`` one of ``"scalar"``, ``"record"``, ``"value"``.
    """

    if not isinstance(annotation, str) or not annotation.strip():
        return None
    try:
        outer = ast.parse(annotation, mode="eval").body
    except SyntaxError:
        return None
    outer = _unwrap_optional_annotation(outer)
    if not isinstance(outer, ast.Subscript):
        return None
    element = outer.slice
    if not isinstance(element, ast.Subscript):
        return None
    tuple_name = element.value
    if not (
        isinstance(tuple_name, ast.Name) and tuple_name.id == "tuple"
        or isinstance(tuple_name, ast.Attribute)
        and tuple_name.attr in {"tuple", "Tuple"}
    ):
        return None
    columns = (
        tuple(element.slice.elts)
        if isinstance(element.slice, ast.Tuple)
        else (element.slice,)
    )
    if any(isinstance(column, ast.Constant) and column.value is Ellipsis
           for column in columns):
        return None
    if len(columns) < 2:
        return None
    scalar_names = {"bool", "int", "float", "str"}
    layout: list[tuple[str, str | None, int]] = []
    for column in columns:
        spelling = (
            column.id if isinstance(column, ast.Name)
            else column.attr if isinstance(column, ast.Attribute)
            else ""
        )
        if spelling in scalar_names:
            layout.append(("scalar", None, 1))
            continue
        matches = tuple(
            (str(identity), record)
            for identity, record in repository_records.items()
            if str(identity) == spelling
            or str(identity).rsplit(".", 1)[-1] == spelling
        )
        if spelling and len(matches) == 1:
            identity, record = matches[0]
            width = len(_record_row_physical_columns(record))
            if width:
                layout.append(("record", identity, width))
                continue
        layout.append(("value", None, 1))
    return tuple(layout)


def _sequence_row_record_slots(
    graph_obj: Any,
    sequence_declarations: Iterable[tuple[int, str, int, bool]],
) -> dict[int, tuple[tuple[int, str, int], ...]]:
    """Record-typed columns of each declared fixed-width row.

    Maps a resident sequence id to ``(authored column, identity, width)``
    triples.  A row insertion names the record by its semantic identity at
    that column; native-call linking, which proves the record's physical
    member fields, expands it in place (``ssa_deferred_record_slots``).
    """

    declared = {int(item[0]) for item in sequence_declarations}
    identities = graph_obj.graph.get("identity_table") or {}
    repository_records = dict(
        (graph_obj.graph.get("program_abi") or {}).get("records") or {}
    )
    result: dict[int, tuple[tuple[int, str, int], ...]] = {}
    for parameter_name, annotation in (
        _current_authored_parameter_annotations(graph_obj).items()
    ):
        layout = _authored_row_layout(annotation, repository_records)
        if layout is None or not any(kind == "record" for kind, _i, _w in layout):
            continue
        slots = tuple(
            (position, str(identity), int(width))
            for position, (kind, identity, width) in enumerate(layout)
            if kind == "record"
        )
        # Every declared resident in the binding's history is the same
        # authored row: the parameter, its ``[]`` replacement and the merge
        # a mutation resolves to.
        for value_id in identities.get(str(parameter_name), ()):
            if int(value_id) in declared:
                result[int(value_id)] = slots
    return result


def _record_row_physical_columns(
    record: Mapping[str, Any],
) -> tuple[tuple[str, str], ...]:
    """Return the exact flat ABI columns for one declared record row."""

    columns: list[tuple[str, str]] = []
    for field_name, receipt_value in dict(record.get("fields") or {}).items():
        receipt = dict(receipt_value)
        storage = str(receipt.get("storage") or "scalar")
        dtype = str(receipt.get("dtype") or "unknown")
        if storage == "keyed":
            columns.extend((
                (f"{field_name}.length", "int64"),
                (f"{field_name}.keys", "int64"),
                (f"{field_name}.values", dtype),
            ))
            continue
        if bool(receipt.get("optional")):
            columns.append((f"{field_name}.__present", "bool"))
        columns.append((str(field_name), dtype))
    return tuple(columns)


def _graph_sequence_record_abi(graph_obj: Any) -> dict[str, Mapping[str, Any]]:
    """Resolve local/parameter sequence annotations against repository ABI."""

    resolved = copy.deepcopy(dict(
        graph_obj.graph.get("sequence_record_abi")
        or graph_obj.graph.get("parameter_sequence_record_abi")
        or {}
    ))
    repository_records = dict(
        (graph_obj.graph.get("program_abi") or {}).get("records") or {}
    )
    for binding_name, annotation in dict(
        graph_obj.graph.get("type_annotations") or {}
    ).items():
        if str(binding_name) in resolved or not isinstance(annotation, str):
            continue
        try:
            outer = ast.parse(annotation, mode="eval").body
        except SyntaxError:
            continue
        if not isinstance(outer, ast.Subscript):
            continue
        container = (
            outer.value.id if isinstance(outer.value, ast.Name)
            else outer.value.attr if isinstance(outer.value, ast.Attribute)
            else ""
        )
        if container not in {"list", "tuple", "Sequence", "Iterable"}:
            continue
        element = outer.slice
        element_name = (
            element.id if isinstance(element, ast.Name)
            else element.attr if isinstance(element, ast.Attribute)
            else ""
        )
        matches = tuple(
            (str(identity), record)
            for identity, record in repository_records.items()
            if str(identity) == str(element_name)
            or str(identity).rsplit(".", 1)[-1] == str(element_name)
        )
        if len(matches) != 1:
            continue
        identity, record = matches[0]
        resolved[str(binding_name)] = {
            **copy.deepcopy(dict(record)),
            "identity": identity,
            "aggregate_kind": "tuple",
            "mutable": str(binding_name) not in set(map(
                str, graph_obj.graph.get("function_parameters") or ()
            )),
            "source_derived": True,
        }
    return resolved


def _authored_dataclass_record_views(
    tree: ast.Module,
) -> dict[str, dict[str, Mapping[str, Any]]]:
    """Derive exact per-method record views from authored class fields.

    This is deliberately conservative.  Dataclass annotations and ordinary
    ``__init__`` assignments are admitted only when they have an unambiguous
    physical scalar/span representation.  A method that touches an unsupported
    field receives no inferred receiver view.  Per-method views include only
    fields that method reads or writes (plus fields required by same-receiver
    method calls), so compiling a small method does not manufacture ABI
    obligations for unrelated state.  Mutation is recorded in that view; the
    initializer's construction writes do not make every field mutable forever.

    The historical function name is retained because it is imported by tests
    and downstream tooling, but ordinary authored classes are intentionally
    part of the same source-derived ABI faculty.
    """

    classes = {
        statement.name: statement
        for statement in tree.body
        if isinstance(statement, ast.ClassDef)
    }

    def field_receipt(annotation: ast.AST) -> Mapping[str, Any] | None:
        return _authored_annotation_field_receipt(annotation)

    def initialized_field_receipt(value: ast.AST) -> Mapping[str, Any] | None:
        """Prove a scalar field from its authored initializer, without guessing."""

        scalar_type = None
        if (
            isinstance(value, ast.Call)
            and isinstance(value.func, ast.Name)
            and value.func.id in {"int", "float", "bool"}
        ):
            scalar_type = value.func.id
        elif isinstance(value, ast.Constant):
            # bool is an int subclass, so order is significant here.
            if isinstance(value.value, bool):
                scalar_type = "bool"
            elif isinstance(value.value, int):
                scalar_type = "int"
            elif isinstance(value.value, float):
                scalar_type = "float"
        dtype = {
            "int": "int64", "float": "float64", "bool": "bool",
        }.get(scalar_type or "")
        if dtype is None:
            return None
        return {
            "storage": "scalar", "dtype": dtype, "rank": 0,
            "mutable": False,
        }

    class_fields: dict[str, dict[str, Mapping[str, Any]]] = {}
    class_methods: dict[str, dict[str, ast.FunctionDef | ast.AsyncFunctionDef]] = {}
    for class_name, definition in classes.items():
        fields = {}
        methods = {}
        for statement in definition.body:
            if isinstance(statement, ast.AnnAssign) and isinstance(
                statement.target, ast.Name
            ):
                receipt = field_receipt(statement.annotation)
                if receipt is not None:
                    fields[statement.target.id] = receipt
            elif isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef)):
                methods[statement.name] = statement
        initializer = methods.get("__init__")
        if initializer is not None:
            for node in ast.walk(initializer):
                target = None
                receipt = None
                if isinstance(node, ast.AnnAssign):
                    target = node.target
                    receipt = field_receipt(node.annotation)
                elif isinstance(node, ast.Assign) and len(node.targets) == 1:
                    target = node.targets[0]
                    receipt = initialized_field_receipt(node.value)
                if not (
                    isinstance(target, ast.Attribute)
                    and isinstance(target.value, ast.Name)
                    and target.value.id == "self"
                    and receipt is not None
                ):
                    continue
                previous = fields.get(target.attr)
                if previous is None:
                    fields[target.attr] = receipt
                elif dict(previous) != dict(receipt):
                    # Conflicting physical declarations are not a proven ABI.
                    fields.pop(target.attr, None)
        class_fields[class_name] = fields
        class_methods[class_name] = methods

    required_cache: dict[tuple[str, str], dict[str, bool] | None] = {}

    def method_fields(
        class_name: str, method_name: str, active=(),
    ) -> dict[str, bool] | None:
        key = (class_name, method_name)
        if key in required_cache:
            return required_cache[key]
        if key in active:
            return {}
        method = class_methods.get(class_name, {}).get(method_name)
        if method is None:
            return None
        direct: dict[str, bool] = {}
        nested_calls: set[str] = set()
        for node in ast.walk(method):
            if not isinstance(node, ast.Attribute):
                continue
            if not (
                isinstance(node.value, ast.Name)
                and node.value.id in {"self", "cls"}
            ):
                continue
            if node.attr in class_methods.get(class_name, {}):
                if isinstance(getattr(node, "ctx", None), ast.Load):
                    nested_calls.add(node.attr)
            else:
                direct[node.attr] = bool(
                    direct.get(node.attr, False)
                    or isinstance(getattr(node, "ctx", None), ast.Store)
                )
        if not set(direct) <= set(class_fields.get(class_name, {})):
            required_cache[key] = None
            return None
        for callee in sorted(nested_calls):
            inherited = method_fields(class_name, callee, (*active, key))
            if inherited is None:
                required_cache[key] = None
                return None
            for field_name, mutable in inherited.items():
                direct[field_name] = bool(
                    direct.get(field_name, False) or mutable
                )
        required_cache[key] = direct
        return direct

    views: dict[str, dict[str, Mapping[str, Any]]] = {}
    for class_name, methods in class_methods.items():
        for method_name in methods:
            fields = method_fields(class_name, method_name)
            if fields is None or not fields:
                continue
            views[f"{class_name}.{method_name}"] = {
                "self": {
                    "identity": class_name,
                    "fields": {
                        name: dict(class_fields[class_name][name])
                        for name in sorted(fields)
                    },
                }
            }
            for name, mutable in fields.items():
                views[f"{class_name}.{method_name}"]["self"]["fields"][name][
                    "mutable"
                ] = mutable

    def annotation_class_name(annotation: ast.AST | None) -> str | None:
        if isinstance(annotation, ast.Name):
            return annotation.id
        if isinstance(annotation, ast.Attribute):
            return annotation.attr
        return None

    def add_annotated_parameter_views(
        qualified_name: str,
        method: ast.FunctionDef | ast.AsyncFunctionDef,
    ) -> None:
        arguments = (
            *method.args.posonlyargs,
            *method.args.args,
            *method.args.kwonlyargs,
        )
        for argument in arguments:
            if argument.arg in {"self", "cls"}:
                continue
            record_name = annotation_class_name(argument.annotation)
            if record_name not in class_fields:
                continue
            used: dict[str, bool] = {}
            nested_calls: set[str] = set()
            for node in ast.walk(method):
                if not (
                    isinstance(node, ast.Attribute)
                    and isinstance(node.value, ast.Name)
                    and node.value.id == argument.arg
                ):
                    continue
                if node.attr in class_methods.get(record_name, {}):
                    if isinstance(getattr(node, "ctx", None), ast.Load):
                        nested_calls.add(node.attr)
                else:
                    used[node.attr] = bool(
                        used.get(node.attr, False)
                        or isinstance(getattr(node, "ctx", None), ast.Store)
                    )
            for callee in sorted(nested_calls):
                inherited = method_fields(record_name, callee)
                if inherited is None:
                    used = {}
                    break
                for field_name, mutable in inherited.items():
                    used[field_name] = bool(
                        used.get(field_name, False) or mutable
                    )
            if not used:
                continue
            if not set(used) <= set(class_fields[record_name]):
                # The annotation names the class, but this function needs a
                # field whose physical representation was not proven. Do not
                # publish a partial parameter ABI.
                continue
            fields = {
                name: {
                    **dict(class_fields[record_name][name]),
                    "mutable": bool(mutable),
                }
                for name, mutable in sorted(used.items())
            }
            views.setdefault(qualified_name, {})[argument.arg] = {
                "identity": record_name,
                "fields": fields,
            }

    for statement in tree.body:
        if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef)):
            add_annotated_parameter_views(statement.name, statement)
        elif isinstance(statement, ast.ClassDef):
            for member in statement.body:
                if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    add_annotated_parameter_views(
                        f"{statement.name}.{member.name}", member,
                    )
    return views


def _entrypoint(module: Any, name: str | None = None) -> Any:
    selected = name or module.api.entry
    if selected is None:
        raise ValueError("Fortran module has no selected entry point")
    return module.api.entry_point(str(selected))


def _extent_values(
    entry: Any,
    overrides: Mapping[str, int] | None,
) -> dict[str, int]:
    values: dict[str, int] = {}
    unresolved: set[str] = set()
    for parameter in entry.parameters:
        if parameter.role != "extent":
            continue
        name = str(parameter.name)
        fixed = re.fullmatch(r"extent_([1-9][0-9]*)", name)
        if fixed is None:
            unresolved.add(name)
        else:
            values[name] = int(fixed.group(1))
    for name, value in dict(overrides or {}).items():
        if name not in values and name not in unresolved:
            raise ValueError(f"unknown Fortran extent override {name!r}")
        if int(value) < 1:
            raise ValueError(f"Fortran extent {name!r} must be positive")
        values[name] = int(value)
        unresolved.discard(name)
    if unresolved:
        names = ", ".join(sorted(unresolved))
        raise ValueError(
            "shape-dynamic Fortran extents require explicit positive "
            f"extent_overrides: {names}"
        )
    return values


def _element_count(parameter: Any, extents: Mapping[str, int]) -> int:
    dynamic_dimensions = tuple(getattr(parameter, "extents", ()) or ())
    if dynamic_dimensions:
        count = 1
        for dimension in dynamic_dimensions:
            count *= int(extents[str(dimension)])
        return max(count, 1)
    if not tuple(parameter.shape or ()) and parameter.extent is not None:
        return max(int(extents[str(parameter.extent)]), 1)
    count = 1
    for extent in tuple(parameter.shape or ()):
        count *= int(extents.get(f"extent_{int(extent)}", extent))
    return max(count, 1)


def _source_name(parameter: Any) -> str:
    return str(parameter.source_name or parameter.name)


def _fortran_storage_index(
    parameter: Any,
    extents: Mapping[str, int],
    linear_index: str,
) -> str:
    """Map one C-row-major logical index to Fortran array storage.

    The API shape is semantic and remains in Python/NumPy dimension order.
    A ``bind(C)`` Fortran dummy with that shape stores its first dimension
    fastest, so the outer shell must perform this boundary permutation once.
    Resident feedback arenas stay in Fortran order and require no copies.
    """

    dynamic_dimensions = tuple(getattr(parameter, "extents", ()) or ())
    shape = (
        tuple(int(extents[str(name)]) for name in dynamic_dimensions)
        if dynamic_dimensions
        else tuple(
            int(extents.get(f"extent_{int(size)}", size))
            for size in tuple(parameter.shape or ())
        )
    )
    if len(shape) <= 1:
        return linear_index
    terms = []
    for dimension, size in enumerate(shape):
        c_stride = 1
        for following in shape[dimension + 1:]:
            c_stride *= int(following)
        fortran_stride = 1
        for preceding in shape[:dimension]:
            fortran_stride *= int(preceding)
        coordinate = (
            f"(({linear_index}) / {c_stride}) % {size}"
            if c_stride != 1
            else f"({linear_index}) % {size}"
        )
        terms.append(
            coordinate
            if fortran_stride == 1
            else f"({coordinate}) * {fortran_stride}"
        )
    return " + ".join(terms)


def _c_string(value: str) -> str:
    return json.dumps(str(value))


# Pixel formats the native C shell's presenter understands, and whether each
# carries a per-pixel alpha channel.  ``rgba_f64_planar_layered`` is the only
# multi-layer format; its layer count comes from the request's own
# ``layer_count`` attribute rather than the format name.
_DISPLAY_PIXEL_FORMATS = {
    "rgb_f64_planar": False,
    "rgba_f64_planar": True,
    "rgba_f64_planar_layered": True,
}


_C_FILE_BROKER_SOURCE = r'''
#define TURING_FILE_HANDLE_CAPACITY 256
static FILE *turing_file_handles[TURING_FILE_HANDLE_CAPACITY] = {0};

static char *turing_file_span_string(const uint8_t *data, int64_t length) {
    char *text;
    if (data == NULL || length < 0 || (uint64_t)length >= SIZE_MAX) return NULL;
    text = (char *)malloc((size_t)length + 1);
    if (text == NULL) return NULL;
    memcpy(text, data, (size_t)length);
    text[length] = '\0';
    return text;
}

static FILE *turing_file_handle(int64_t handle) {
    if (handle < 1 || handle >= TURING_FILE_HANDLE_CAPACITY) return NULL;
    return turing_file_handles[handle];
}

int64_t turing_shell_file_open(
    const uint8_t *path_data, int64_t path_length,
    const uint8_t *mode_data, int64_t mode_length
) {
    char *path = turing_file_span_string(path_data, path_length);
    char *mode = turing_file_span_string(mode_data, mode_length);
    FILE *stream = NULL;
    int64_t handle;
    if (path != NULL && mode != NULL && mode_length > 0 && mode_length < 8) {
        stream = fopen(path, mode);
    }
    free(path);
    free(mode);
    if (stream == NULL) return 0;
    for (handle = 1; handle < TURING_FILE_HANDLE_CAPACITY; ++handle) {
        if (turing_file_handles[handle] == NULL) {
            turing_file_handles[handle] = stream;
            return handle;
        }
    }
    fclose(stream);
    return 0;
}

int64_t turing_shell_file_read(
    int64_t handle, uint8_t *destination, int64_t capacity
) {
    FILE *stream = turing_file_handle(handle);
    size_t count;
    if (stream == NULL || destination == NULL || capacity < 0) return -1;
    count = fread(destination, 1, (size_t)capacity, stream);
    return ferror(stream) ? -1 : (int64_t)count;
}

int64_t turing_shell_file_write(
    int64_t handle, const uint8_t *source, int64_t length
) {
    FILE *stream = turing_file_handle(handle);
    size_t count;
    if (stream == NULL || source == NULL || length < 0) return -1;
    count = fwrite(source, 1, (size_t)length, stream);
    return count == (size_t)length ? (int64_t)count : -1;
}

int32_t turing_shell_file_seek(int64_t handle, int64_t offset, int32_t origin) {
    FILE *stream = turing_file_handle(handle);
    if (stream == NULL || origin < SEEK_SET || origin > SEEK_END) return 0;
#if defined(_WIN32)
    return _fseeki64(stream, offset, origin) == 0;
#else
    return fseeko(stream, (off_t)offset, origin) == 0;
#endif
}

int64_t turing_shell_file_tell(int64_t handle) {
    FILE *stream = turing_file_handle(handle);
    if (stream == NULL) return -1;
#if defined(_WIN32)
    return (int64_t)_ftelli64(stream);
#else
    return (int64_t)ftello(stream);
#endif
}

int32_t turing_shell_file_flush(int64_t handle) {
    FILE *stream = turing_file_handle(handle);
    return stream != NULL && fflush(stream) == 0;
}

int32_t turing_shell_file_close(int64_t handle) {
    FILE *stream = turing_file_handle(handle);
    int status;
    if (stream == NULL) return 0;
    turing_file_handles[handle] = NULL;
    status = fclose(stream);
    return status == 0;
}

int64_t turing_shell_file_stat_size(
    const uint8_t *path_data, int64_t path_length
) {
    char *path = turing_file_span_string(path_data, path_length);
    FILE *stream;
    int64_t size = -1;
    if (path == NULL) return -1;
    stream = fopen(path, "rb");
    free(path);
    if (stream == NULL) return -1;
#if defined(_WIN32)
    if (_fseeki64(stream, 0, SEEK_END) == 0) size = (int64_t)_ftelli64(stream);
#else
    if (fseeko(stream, 0, SEEK_END) == 0) size = (int64_t)ftello(stream);
#endif
    fclose(stream);
    return size;
}

static void turing_shell_file_close_all(void) {
    int64_t handle;
    for (handle = 1; handle < TURING_FILE_HANDLE_CAPACITY; ++handle) {
        if (turing_file_handles[handle] != NULL) {
            fclose(turing_file_handles[handle]);
            turing_file_handles[handle] = NULL;
        }
    }
}

static int turing_shell_file_fail(int status) {
    turing_shell_file_close_all();
    return status;
}
'''


def _requires_file_broker(module: Any) -> bool:
    metadata = dict(getattr(module.api, "metadata", {}) or {})
    shell_io = dict(metadata.get("shell_io") or {})
    requirements = dict(shell_io.get("requirements") or {})
    if shell_io.get("boundary_plans"):
        return True
    return any(
        request.get("capability") == "files"
        for request in requirements.get("requests", ())
    )


def _native_shell_boundary_lines(
    module: Any,
    entry: Any,
    values: tuple[Any, ...],
    slot_by_parameter: Mapping[str, int],
    extents: Mapping[str, int],
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    """Render file-boundary plans as native-shell C statements.

    The target entry remains an ordinary numerical/control ABI. These lines
    run in the enclosing C shell after that entry and use its already allocated
    parameter slots. No Python file implementation and no filesystem operator
    is admitted to Fortran/LLVM/GLSL emission.
    """

    shell_io = dict((getattr(module.api, "metadata", {}) or {}).get(
        "shell_io"
    ) or {})
    plans = tuple(shell_io.get("boundary_plans") or ())
    if not plans:
        return (), (), ()
    if shell_io.get("boundary_plan_schema") != "turing.shell-boundary-plan.v1":
        raise ValueError("native shell received an unknown boundary-plan schema")

    parameters_by_source: dict[str, list[Any]] = {}
    for parameter in values:
        parameters_by_source.setdefault(
            str(parameter.source_name or parameter.name), []
        ).append(parameter)
        parameters_by_source.setdefault(str(parameter.name), []).append(parameter)

    globals_: list[str] = []
    declarations: list[str] = []
    actions: list[str] = []
    locals_by_name: dict[str, str] = {}
    public_by_name = {
        str(parameter.source_name or parameter.name): parameter
        for parameter in values
        if parameter.role in {"output", "inout"}
    }
    literal_index = 0

    def local(name: str) -> str:
        key = str(name)
        existing = locals_by_name.get(key)
        if existing is not None:
            return existing
        identifier = "turing_shell_value_" + _identifier(key)
        if identifier in locals_by_name.values():
            identifier += "_" + hashlib.sha256(key.encode("utf-8")).hexdigest()[:8]
        locals_by_name[key] = identifier
        declarations.append(f"    int64_t {identifier} = 0;")
        return identifier

    def publish(name: str, expression: str) -> list[str]:
        target = public_by_name.get(str(name))
        if target is None:
            return []
        slot = slot_by_parameter[target.name]
        return [
            f"        *(({target.c_type} *)slots[{slot}]) = "
            f"({target.c_type})({expression});"
        ]

    def scalar(operand: Mapping[str, Any]) -> str:
        kind = str(operand.get("kind") or "")
        if kind == "name":
            return local(str(operand["name"]))
        if kind == "literal" and isinstance(operand.get("value"), (int, bool)):
            return str(int(operand["value"]))
        raise ValueError(f"native shell cannot resolve scalar operand {operand!r}")

    def span(operand: Mapping[str, Any]) -> tuple[str, str]:
        nonlocal literal_index
        kind = str(operand.get("kind") or "")
        if kind in {"literal", "bytes"}:
            if kind == "bytes":
                payload = bytes.fromhex(str(operand.get("hex") or ""))
            else:
                value = operand.get("value")
                if not isinstance(value, str):
                    raise ValueError(
                        f"native shell span literal must be text/bytes: {operand!r}"
                    )
                payload = value.encode("utf-8")
            literal_index += 1
            identifier = f"turing_shell_literal_{literal_index}"
            elements = ", ".join(str(byte) for byte in payload) or "0"
            globals_.append(
                f"static const uint8_t {identifier}[] = {{{elements}}};"
            )
            return identifier, str(len(payload))
        if kind != "name":
            raise ValueError(f"native shell cannot resolve span operand {operand!r}")
        source_name = str(operand["name"])
        candidates = list(dict.fromkeys(parameters_by_source.get(source_name, ())))
        data = next((
            parameter for parameter in candidates
            if str(parameter.c_type) == "uint8_t"
            and parameter.passing == "reference"
        ), None)
        if data is None:
            raise ValueError(
                f"shell boundary name {source_name!r} has no uint8 span parameter"
            )
        data_slot = slot_by_parameter[data.name]
        length_candidates = tuple(dict.fromkeys((
            *candidates,
            *parameters_by_source.get(source_name + "_length", ()),
        )))
        length = next((
            parameter for parameter in length_candidates
            if parameter is not data
            and str(parameter.c_type) in {"int32_t", "int64_t"}
            and (
                str(parameter.source_transform or "").endswith("length")
                or str(parameter.name).casefold().endswith("length")
            )
        ), None)
        if length is not None:
            length_slot = slot_by_parameter[length.name]
            length_expression = (
                f"*(({length.c_type} *)slots[{length_slot}])"
            )
        else:
            length_expression = str(_element_count(data, extents))
        return f"(const uint8_t *)slots[{data_slot}]", length_expression

    for plan in plans:
        function_name = plan.get("function")
        if function_name not in {None, "", entry.name, entry.symbol}:
            continue
        operations = tuple(sorted(
            (dict(item) for item in plan.get("operations", ())),
            key=lambda item: int(item.get("sequence", -1)),
        ))
        if [int(item.get("sequence", -1)) for item in operations] != list(
            range(len(operations))
        ):
            raise ValueError("shell boundary operations are not contiguous and ordered")
        if any(str(item.get("operation")) == "read" for item in operations):
            raise ValueError(
                "native read boundary requires a pre-entry span publication plan"
            )
        for operation in operations:
            name = str(operation.get("operation") or "")
            arguments = tuple(operation.get("arguments") or ())
            result_name = operation.get("result")
            if name == "open" and len(arguments) == 2:
                path_data, path_length = span(arguments[0])
                mode_data, mode_length = span(arguments[1])
                if not result_name:
                    raise ValueError("shell file open must publish its handle")
                target = local(str(result_name))
                actions.append(
                    f"        {target} = turing_shell_file_open("
                    f"{path_data}, {path_length}, {mode_data}, {mode_length});"
                )
                actions.append(
                    f"        if ({target} == 0) "
                    "return turing_shell_file_fail(10);"
                )
            elif name == "write" and len(arguments) == 2:
                handle = scalar(arguments[0])
                data, length = span(arguments[1])
                target = local(str(result_name or (
                    f"discard_write_{operation.get('sequence')}"
                )))
                actions.append(
                    f"        {target} = turing_shell_file_write("
                    f"{handle}, {data}, {length});"
                )
                actions.append(
                    f"        if ({target} < 0) "
                    "return turing_shell_file_fail(11);"
                )
                if result_name:
                    actions.extend(publish(str(result_name), target))
            elif name in {"flush", "close"} and len(arguments) == 1:
                handle = scalar(arguments[0])
                actions.append(
                    f"        if (!turing_shell_file_{name}({handle})) "
                    "return turing_shell_file_fail(12);"
                )
            elif name == "tell" and len(arguments) == 1:
                if not result_name:
                    raise ValueError("shell file tell must publish its result")
                target = local(str(result_name))
                actions.append(
                    f"        {target} = turing_shell_file_tell("
                    f"{scalar(arguments[0])});"
                )
                actions.append(
                    f"        if ({target} < 0) "
                    "return turing_shell_file_fail(13);"
                )
                actions.extend(publish(str(result_name), target))
            elif name == "seek" and len(arguments) in {2, 3}:
                origin = scalar(arguments[2]) if len(arguments) == 3 else "0"
                actions.append(
                    "        if (!turing_shell_file_seek("
                    f"{scalar(arguments[0])}, {scalar(arguments[1])}, "
                    f"(int32_t)({origin}))) "
                    "return turing_shell_file_fail(14);"
                )
            else:
                raise ValueError(
                    f"native shell does not implement boundary operation {name!r}"
                )
    return tuple(globals_), tuple(declarations), tuple(actions)


def _display_configuration(module: Any, entry: Any) -> dict[str, Any] | None:
    """Resolve an optional declarative display request from the shared IO ABI.

    Three presenter shapes share one physical contract (a caller-owned
    per-layer red/green/blue[/alpha] output array, resolved by name):
    a plain opaque blit (``rgb_f64_planar``), an alpha-blended single-layer
    blit (``rgba_f64_planar``), and an alpha-composited stack of layers
    (``rgba_f64_planar_layered``, back-to-front "over" compositing, one
    request attribute ``layer_count``).  ``prefers_compute``/
    ``prefers_accelerator`` are declared deployment hints, not consumed by
    this presenter (the only backend registered today is host-native GDI,
    which has no compute/accelerator distinction to honor) -- they are
    validated and carried through so a future GL/compute-capable wrapper can
    read them without a second display-request format.
    """

    metadata = dict(getattr(module.api, "metadata", {}) or {})
    shell_io = metadata.get("shell_io") or {}
    requirements = shell_io.get("requirements") or {}
    requests = [
        request for request in requirements.get("requests", ())
        if request.get("capability") == "display_double_buffer"
    ]
    if not requests:
        return None
    if len(requests) != 1:
        raise ValueError("C shell requires one display_double_buffer request")
    attributes = dict(requests[0].get("attributes") or {})
    pixel_format = str(attributes.get("pixel_format", "rgb_f64_planar"))
    has_alpha = _DISPLAY_PIXEL_FORMATS.get(pixel_format)
    if has_alpha is None:
        raise ValueError(
            "native C shell currently supports display pixel formats "
            + ", ".join(map(repr, sorted(_DISPLAY_PIXEL_FORMATS)))
            + f"; got {pixel_format!r}"
        )
    if pixel_format == "rgba_f64_planar_layered":
        layer_count = int(attributes.get("layer_count", 0))
        if layer_count < 1:
            raise ValueError(
                "rgba_f64_planar_layered display requires a positive "
                "layer_count attribute"
            )
    else:
        layer_count = 1
    width = int(attributes.get("width", 0))
    height = int(attributes.get("height", 0))
    if width < 1 or height < 1:
        raise ValueError("native display request needs positive width and height")
    bindings = {
        str(binding.get("resource")): str(binding.get("parameter"))
        for binding in requirements.get("bindings", ())
        if str(binding.get("entry_point")) == str(entry.name)
        and str(binding.get("resource", "")).startswith("display.")
    }
    layered = pixel_format == "rgba_f64_planar_layered"
    # Every layer needs red/green/blue.  Alpha is mandatory for the
    # single-layer alpha format (that is the whole point of requesting it)
    # but optional per layer within a layered stack -- a layer with no
    # alpha binding is simply opaque, matching the presenter's own
    # ``alpha_layers[layer] ? ... : 1.0`` fallback.
    required_channels = ("red", "green", "blue", "alpha") if (
        has_alpha and not layered
    ) else ("red", "green", "blue")
    optional_channels = ("alpha",) if layered else ()

    def _resource(layer: int, channel: str) -> str:
        return f"display.layer{layer}.{channel}" if layered else f"display.{channel}"

    missing = {
        _resource(layer, channel)
        for layer in range(layer_count)
        for channel in required_channels
    } - set(bindings)
    if missing:
        raise ValueError(
            f"{pixel_format} display lacks bindings: " + ", ".join(sorted(missing))
        )
    parameters = {parameter.name: parameter for parameter in entry.parameters}
    layers = []
    for layer in range(layer_count):
        channels = {}
        for channel in (*required_channels, *optional_channels):
            resource = _resource(layer, channel)
            if resource not in bindings:
                continue
            parameter = parameters.get(bindings[resource])
            if parameter is None or parameter.role != "output":
                raise ValueError(f"{resource} must bind an output ABI parameter")
            if str(parameter.c_type) != "double":
                raise ValueError(f"{resource} must bind a float64 output")
            channels[channel] = parameter.name
        layers.append(channels)
    return {
        "width": width,
        "height": height,
        "title": str(attributes.get("title", "Turing native display")),
        "pixel_format": pixel_format,
        "has_alpha": has_alpha,
        # One dict per layer, {"red": param_name, "green": ..., ...};
        # opaque formats simply omit the "alpha" key per layer.
        "layers": tuple(layers),
        # Back-compat single-layer accessor: every existing caller reads
        # ``display["channels"]`` for the (always exactly rgb) case.
        "channels": (
            tuple(layers[0][channel] for channel in ("red", "green", "blue"))
            if layer_count == 1 else ()
        ),
        "frame_delay_ms": max(0, int(attributes.get("frame_delay_ms", 0))),
        "prefers_compute": bool(attributes.get("prefers_compute", False)),
        "prefers_accelerator": bool(attributes.get("prefers_accelerator", False)),
    }


def _system_file_configurations(module: Any, entry: Any) -> tuple[dict[str, Any], ...]:
    metadata = dict(getattr(module.api, "metadata", {}) or {})
    requirements = dict((metadata.get("shell_io") or {}).get("requirements") or {})
    parameters = {parameter.name: parameter for parameter in entry.parameters}
    configurations = []
    for port in requirements.get("system_ports", ()):
        if port.get("kind") != "file" or port.get("direction") not in {
            "input", "bidirectional",
        }:
            continue
        if str(port.get("entry_point")) != str(entry.name):
            continue
        fields = {
            str(field.get("name")): str(field.get("parameter"))
            for field in port.get("fields", ())
        }
        if set(fields) < {"data", "length"}:
            raise ValueError(f"native file port {port.get('name')!r} lacks data/length fields")
        data = parameters.get(fields["data"])
        length = parameters.get(fields["length"])
        if data is None or length is None:
            raise ValueError(f"native file port {port.get('name')!r} has unknown parameters")
        if str(data.c_type) != "uint8_t" or data.passing != "reference":
            raise ValueError("native file data parameter must be a uint8 reference")
        if str(length.c_type) not in {"int32_t", "int64_t"}:
            raise ValueError("native file length parameter must be int32 or int64")
        attributes = dict(port.get("attributes") or {})
        capacity = int(attributes.get("maximum_bytes", _element_count(data, _extent_values(entry, None))))
        if capacity < 1:
            raise ValueError("native input file capacity must be positive")
        configurations.append({
            "name": str(port["name"]),
            "flag": "--file-" + _identifier(str(port["name"])).replace("_", "-"),
            "data": data,
            "length": length,
            "capacity": capacity,
            "optional": bool(port.get("optional")),
        })
    return tuple(configurations)


def emit_native_c_shell_source(
    module: Any,
    *,
    entrypoint: str | None = None,
    state_feedback: Mapping[str, str] | None = None,
    extent_overrides: Mapping[str, int] | None = None,
    initial_state_filename: str = "initial-state.bin",
    final_outputs_filename: str = "final-outputs.bin",
    trace: bool = False,
    trace_capacity: int = 4096,
    private_cpython_runtime_dll: str | None = None,
    private_cpython_opaque_inputs: Mapping[str, str] | None = None,
) -> str:
    """Emit a standalone C main around one compiled-program API entry.

    The selected symbol may be implemented by Fortran ``bind(C)``, emitted C,
    LLVM object code, or a mixed object graph.  This renderer reads the shared
    compiled-program API only; it does not select or reschedule the program.

    ``trace`` compiles the launch digest IN. It is a compile-time decision,
    not a runtime flag: with it off the ring, its logger and the hook that
    would call it are absent from the binary entirely, so a launch pays
    nothing for a facility it was not built with. With it on, every launch
    writes one fixed-size record -- sequence, shell ns, device ns, region,
    status -- into a ring the executable owns, and main drains it at the
    end. Nothing crosses a language boundary while the program runs.
    """

    entry = _entrypoint(module, entrypoint)
    parameters = tuple(entry.parameters)
    extents = _extent_values(entry, extent_overrides)
    values = tuple(item for item in parameters if item.role != "extent")
    inputs = tuple(item for item in values if item.role in {"input", "inout"})
    outputs = tuple(item for item in values if item.role in {"output", "inout"})
    unsupported = tuple(
        item
        for item in values
        if item.role not in {"input", "inout", "workspace", "output"}
    )
    if unsupported:
        raise ValueError(
            "C shell cannot allocate parameter roles "
            + ", ".join(sorted({item.role for item in unsupported}))
        )
    slot_by_name = {
        _source_name(parameter): index
        for index, parameter in enumerate(values)
    }
    slot_by_parameter = {
        parameter.name: index for index, parameter in enumerate(values)
    }
    (
        shell_boundary_globals,
        shell_boundary_declarations,
        shell_boundary_actions,
    ) = _native_shell_boundary_lines(
        module, entry, values, slot_by_parameter, extents,
    )
    external_reference_thunks = tuple(
        (getattr(module, "api", None).metadata or {}).get(
            "external_reference_thunks", ()
        )
        if getattr(module, "api", None) is not None else ()
    )
    unsupported_external_abis = sorted({
        str(thunk.get("native_abi") or "")
        for thunk in external_reference_thunks
        if str(thunk.get("native_abi") or "") != "cpython-c-api"
    })
    if unsupported_external_abis:
        raise FortranEmissionError(
            "C/Fortran shell has no adapter for external native ABIs: "
            + ", ".join(map(repr, unsupported_external_abis))
        )
    private_cpython_adapter = ""
    if external_reference_thunks:
        if private_cpython_runtime_dll is None:
            raise ValueError(
                "C shell external references require an artifact-owned "
                "private CPython runtime"
            )
        from .cpython_runtime import emit_private_cpython_adapter

        private_cpython_adapter = emit_private_cpython_adapter(
            external_reference_thunks,
            runtime_dll=private_cpython_runtime_dll,
        )
    opaque_input_files = dict(private_cpython_opaque_inputs or {})
    display = _display_configuration(module, entry)
    file_ports = _system_file_configurations(module, entry)
    system_parameters = {
        parameter.name
        for port in file_ports
        for parameter in (port["data"], port["length"])
    }
    if display is not None:
        expected_pixels = int(display["width"]) * int(display["height"])
        for layer in display["layers"]:
            for parameter_name in layer.values():
                parameter = next(
                    item for item in values if item.name == parameter_name
                )
                if _element_count(parameter, extents) != expected_pixels:
                    raise ValueError(
                        f"display channel {parameter_name!r} has "
                        f"{_element_count(parameter, extents)} elements; expected "
                        f"{expected_pixels}"
                    )
    feedback = dict(state_feedback or {})
    missing_feedback = {
        name
        for pair in feedback.items()
        for name in pair
        if name not in slot_by_name
    }
    if missing_feedback:
        raise ValueError(
            "state feedback references absent Fortran ABI names: "
            + ", ".join(sorted(missing_feedback))
        )

    prototype_arguments = []
    call_arguments = []
    value_index = 0
    for parameter in parameters:
        c_type = str(parameter.c_type)
        if parameter.role == "extent":
            prototype_arguments.append(c_type)
            call_arguments.append(str(extents[parameter.name]))
            continue
        pointer = parameter.passing == "reference"
        prototype_arguments.append(c_type + (" *" if pointer else ""))
        slot = f"slots[{value_index}]"
        call_arguments.append(
            f"({c_type} *){slot}" if pointer
            else f"*(({c_type} *){slot})"
        )
        value_index += 1

    allocation_lines = []
    input_read_lines = []
    for index, parameter in enumerate(values):
        c_type = str(parameter.c_type)
        file_port = next((port for port in file_ports if port["data"].name == parameter.name), None)
        count = int(file_port["capacity"]) if file_port else _element_count(parameter, extents)
        allocation_lines.extend((
            f"    slots[{index}] = calloc({count}, sizeof({c_type}));",
            f"    if (!slots[{index}]) return 3;",
        ))
        if parameter.role in {"input", "inout"} and parameter.name not in system_parameters:
            if len(
                tuple(getattr(parameter, "extents", ()) or parameter.shape or ())
            ) <= 1:
                input_read_lines.extend((
                    f"    if (fread(slots[{index}], sizeof({c_type}), {count}, state) "
                    f"!= {count}) {{",
                    f"        fprintf(stderr, \"short initial state at {_c_string(_source_name(parameter))[1:-1]}\\n\");",
                    "        return 4;",
                    "    }",
                ))
            else:
                storage_index = _fortran_storage_index(
                    parameter, extents, "logical_index"
                )
                input_read_lines.extend((
                    "    { size_t logical_index;",
                    f"      for (logical_index = 0; logical_index < {count}; ++logical_index) {{",
                    f"        {c_type} element;",
                    f"        if (fread(&element, sizeof({c_type}), 1, state) != 1) {{",
                    f"          fprintf(stderr, \"short initial state at {_c_string(_source_name(parameter))[1:-1]}\\n\");",
                    "          return 4;",
                    "        }",
                    f"        (({c_type} *)slots[{index}])[{storage_index}] = element;",
                    "      }",
                    "    }",
                ))

    file_load_lines = []
    for port in file_ports:
        data_slot = slot_by_parameter[port["data"].name]
        length_slot = slot_by_parameter[port["length"].name]
        variable = _identifier("file_" + port["name"])
        file_load_lines.extend((
            f"    const char *{variable} = turing_argument_value(argc, argv, {_c_string(port['flag'])});",
            *(
                (f"    if ({variable} == NULL) {{ fprintf(stderr, \"missing {port['flag']}\\n\"); return 8; }}",)
                if not port["optional"] else ()
            ),
            f"    if ({variable} != NULL) {{",
            "        size_t loaded_bytes = 0;",
            f"        if (!turing_read_file({variable}, (uint8_t *)slots[{data_slot}], {port['capacity']}, &loaded_bytes)) return 9;",
            f"        *(({port['length'].c_type} *)slots[{length_slot}]) = ({port['length'].c_type})loaded_bytes;",
            "    }",
        ))

    opaque_input_lines = []
    for parameter_name, filename in opaque_input_files.items():
        if parameter_name not in slot_by_parameter:
            raise ValueError(
                f"opaque CPython input {parameter_name!r} is not in the entry ABI"
            )
        slot = slot_by_parameter[parameter_name]
        variable = _identifier("opaque_input_" + parameter_name)
        opaque_input_lines.extend((
            "    {",
            f"      FILE *{variable} = turing_open_artifact(argv[0], {_c_string(filename)}, \"rb\");",
            "      long opaque_size; uint8_t *opaque_data; int64_t opaque_handle;",
            f"      if ({variable} == NULL || fseek({variable}, 0, SEEK_END) != 0 ||",
            f"          (opaque_size = ftell({variable})) < 0 || fseek({variable}, 0, SEEK_SET) != 0) return 10;",
            "      opaque_data = (uint8_t *)malloc((size_t)opaque_size);",
            f"      if (opaque_data == NULL || fread(opaque_data, 1, (size_t)opaque_size, {variable}) != (size_t)opaque_size) return 10;",
            f"      fclose({variable});",
            "      opaque_handle = turing_cpython_retain_bytes(opaque_data, (size_t)opaque_size);",
            "      free(opaque_data); if (opaque_handle == 0) return 10;",
            f"      *((int64_t *)slots[{slot}]) = opaque_handle;",
            "    }",
        ))

    feedback_lines = []
    feedback_finalize_lines = []
    for input_name, output_name in feedback.items():
        input_slot = slot_by_name[input_name]
        output_slot = slot_by_name[output_name]
        input_parameter = values[input_slot]
        output_parameter = values[output_slot]
        if (
            input_parameter.c_type != output_parameter.c_type
            or _element_count(input_parameter, extents)
            != _element_count(output_parameter, extents)
        ):
            raise ValueError(
                f"state feedback {input_name!r}->{output_name!r} has "
                "incompatible storage"
            )
        swap = (
            f"{{ void *feedback_arena = slots[{input_slot}]; "
            f"slots[{input_slot}] = slots[{output_slot}]; "
            f"slots[{output_slot}] = feedback_arena; }}"
        )
        feedback_lines.append(f"        {swap}")
        # After the last frame the latest value is in the input address. Swap
        # once more so the public output name still denotes the final result
        # for serialization and caller inspection.
        feedback_finalize_lines.append(f"    {swap}")

    output_lines = []
    frame_output_lines = []
    output_write_lines = []
    for output_index, parameter in enumerate(outputs):
        # Several native parameters may retain the same authored source_name
        # after whole-program linking.  Publication must address this exact
        # output parameter, not whichever same-source argument happened to be
        # last in the signature.
        slot = slot_by_parameter[parameter.name]
        count = _element_count(parameter, extents)
        separator = "" if output_index == 0 else ","
        output_lines.extend((
            f"    {{ double sum = 0.0; size_t i;",
            f"      for (i = 0; i < {count}; ++i) sum += (({parameter.c_type} *)slots[{slot}])[i];",
            f"      printf(\"{separator}\\\"{_source_name(parameter)}\\\":{{\\\"first\\\":%.17g,\\\"sum\\\":%.17g}}\",",
            f"             (double)(({parameter.c_type} *)slots[{slot}])[0], sum); }}",
        ))
        frame_output_lines.extend((
            f"        {{ double sum = 0.0; size_t i;",
            f"          for (i = 0; i < {count}; ++i) sum += (({parameter.c_type} *)slots[{slot}])[i];",
            f"          printf(\"{separator}\\\"{_source_name(parameter)}\\\":{{\\\"first\\\":%.17g,\\\"sum\\\":%.17g}}\",",
            f"                 (double)(({parameter.c_type} *)slots[{slot}])[0], sum); }}",
        ))
        if len(
            tuple(getattr(parameter, "extents", ()) or parameter.shape or ())
        ) <= 1:
            output_write_lines.append(
                f"    fwrite(slots[{slot}], sizeof({parameter.c_type}), {count}, outputs_file);"
            )
        else:
            storage_index = _fortran_storage_index(
                parameter, extents, "logical_index"
            )
            output_write_lines.extend((
                "    { size_t logical_index;",
                f"      for (logical_index = 0; logical_index < {count}; ++logical_index) {{",
                f"        const {parameter.c_type} *element = &(({parameter.c_type} *)slots[{slot}])[{storage_index}];",
                f"        fwrite(element, sizeof({parameter.c_type}), 1, outputs_file);",
                "      }",
                "    }",
            ))

    display_source = ""
    display_open_lines: list[str] = []
    display_loop_condition = "frame < frames"
    display_message_lines: list[str] = []
    display_present_lines: list[str] = []
    display_close_lines: list[str] = []
    default_frames = "1"
    if display is not None:
        layer_slots = [
            {
                channel: slot_by_parameter[name]
                for channel, name in layer.items()
            }
            for layer in display["layers"]
        ]
        width = int(display["width"])
        height = int(display["height"])
        title = _c_string(display["title"])
        default_frames = "0"
        display_loop_condition = "turing_display_running && (frames == 0 || frame < frames)"
