# Compatibility spelling for the original Fortran-first caller.  This is an
# alias, deliberately, so there is only one C host implementation to maintain.
emit_fortran_c_shell_source = emit_native_c_shell_source


def emit_fortran_packed_library_source(entry: Any) -> tuple[str, str]:
    """Emit a bounded-arity C entry over an arbitrary Fortran frame.

    Every published ABI parameter owns one pointer-array slot. Reference
    parameters use the slot directly; value parameters are dereferenced using
    their published C type. This preserves the complete typed ABI while
    avoiding host FFI and platform call surfaces with fixed argument-count
    limits.
    """

    symbol = f"{entry.symbol}__packed"
    prototype_arguments = []
    call_arguments = []
    for index, parameter in enumerate(entry.parameters):
        c_type = str(parameter.c_type)
        pointer = parameter.passing == "reference"
        prototype_arguments.append(c_type + (" *" if pointer else ""))
        call_arguments.append(
            f"({c_type} *)arguments[{index}]" if pointer
            else f"*(({c_type} *)arguments[{index}])"
        )
    prototype = ", ".join(prototype_arguments) or "void"
    call = ", ".join(call_arguments)
    source = "\n".join((
        "#include <stddef.h>",
        "#include <stdint.h>",
        "#include <stdbool.h>",
        "#if defined(_WIN32)",
        "#  define TURING_EXPORT __declspec(dllexport)",
        "#else",
        "#  define TURING_EXPORT __attribute__((visibility(\"default\")))",
        "#endif",
        f"extern void {entry.symbol}({prototype});",
        "",
        f"TURING_EXPORT int {symbol}(void **arguments, size_t argument_count) {{",
        f"    if (argument_count != {len(entry.parameters)}) return 0;",
        "    if (argument_count != 0 && arguments == NULL) return 0;",
        f"    {entry.symbol}({call});",
        "    return 1;",
        "}",
        "",
    ))
    return source, symbol


@dataclass(frozen=True)
class NativeObjectSection:
    """One compiler-emitted object linked into the native program.

    ``language`` is contract evidence, not a linker switch: after C, Fortran,
    or LLVM has emitted an object, the platform linker consumes them alike.
    Keeping the producer recorded lets the shell manifest describe a mixed
    program without teaching the shell backend-specific calling behavior.
    """

    path: Path
    language: str
    symbols: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        language = str(self.language).casefold()
        if language not in {"c", "fortran", "llvm"}:
            raise ValueError(
                "native object language must be c, fortran, or llvm; "
                f"received {self.language!r}"
            )
        object.__setattr__(self, "language", language)
        object.__setattr__(self, "path", Path(self.path).resolve())
        object.__setattr__(self, "symbols", tuple(map(str, self.symbols)))


def compile_fortran_module_c_shell(
    module: Any,
    inputs: Mapping[str, Any],
    directory: str | Path,
    *,
    entrypoint: str | None = None,
    state_feedback: Mapping[str, str] | None = None,
    extent_overrides: Mapping[str, int] | None = None,
    name: str = "turing_fortran_c_shell",
    standalone: bool = True,
    library: bool = False,
    trace: bool = False,
    cpython_runtime: str | Path | None = None,
    repository_root: str | Path | None = None,
    native_object_sections: Sequence[NativeObjectSection] = (),
    native_libraries: Sequence[str | Path] = (),
) -> FortranCShellExecutable:
    """Compile generated Fortran plus the generic profiled C main.

    ``native_object_sections`` are already-emitted C, Fortran, or LLVM object
    files linked into the same program. They resolve ordinary C-ABI calls in
    the compiled graph; the shell neither schedules them nor calls a private
    backend API. ``native_libraries`` supplies explicit archive/shared-library
    link inputs under the same rule.

    ``library=True`` instead builds a SHARED LIBRARY (.dll/.so) from just the
    Fortran module -- the compiled section exported for other programs to link
    against, "recognize without lowering". It skips the C-shell main and all of
    the runtime input/state machinery (a DLL of a section has no run harness and
    no initial state), so a parameterful section compiles without feeds.
    """

    primary_fortran_source = str(getattr(module, "source", "") or "")
    has_primary_fortran = bool(primary_fortran_source.strip())
    discovered_fortran = fortran_compiler()
    if has_primary_fortran and discovered_fortran is None:
        raise FortranEmissionError("no Fortran compiler found")
    compiler = (
        str(Path(discovered_fortran).resolve())
        if discovered_fortran is not None else None
    )
    adjacent_gcc = (
        Path(compiler).with_name("gcc.exe" if os.name == "nt" else "gcc")
        if compiler is not None else None
    )
    discovered_gcc = (
        str(adjacent_gcc)
        if adjacent_gcc is not None and adjacent_gcc.is_file()
        else shutil.which("gcc")
    )
    if discovered_gcc is None:
        raise FortranEmissionError("no native C compiler found for the shell")
    gcc = str(Path(discovered_gcc).resolve())
    output = Path(directory).resolve()
    output.mkdir(parents=True, exist_ok=True)
    native_object_sections = tuple(native_object_sections)
    missing_native_objects = tuple(
        section.path for section in native_object_sections
        if not section.path.is_file()
    )
    if missing_native_objects:
        raise FortranEmissionError(
            "native object section(s) do not exist: "
            + ", ".join(map(str, missing_native_objects))
        )
    native_library_paths = tuple(Path(path).resolve() for path in native_libraries)
    missing_native_libraries = tuple(
        path for path in native_library_paths if not path.is_file()
    )
    if missing_native_libraries:
        raise FortranEmissionError(
            "native link library/libraries do not exist: "
            + ", ".join(map(str, missing_native_libraries))
        )
    external_reference_thunks = tuple(
        (getattr(module, "api", None).metadata or {}).get(
            "external_reference_thunks", ()
        )
        if getattr(module, "api", None) is not None else ()
    )
    unsupported_external_abis = sorted({
        str(thunk.get("native_abi") or "")
        for thunk in external_reference_thunks
        if str(thunk.get("native_abi") or "") != "cpython-c-api"
    })
    if unsupported_external_abis:
        raise FortranEmissionError(
            "C/Fortran shell has no adapter for external native ABIs: "
            + ", ".join(map(repr, unsupported_external_abis))
        )
    selected_cpython = None
    if external_reference_thunks:
        from .cpython_runtime import discover_cpython_runtime

        selected_cpython = discover_cpython_runtime(
            cpython_runtime,
            repository=(repository_root or Path(__file__).resolve().parents[2]),
        )
    entry = _entrypoint(module, entrypoint)
    # A shared library exports the emitted ABI directly: dynamic extents are
    # ordinary runtime arguments supplied by its eventual caller. Requiring
    # concrete values here applies the standalone shell's allocation concern
    # to a product that has no shell and makes otherwise valid shape-dynamic
    # libraries impossible to build. Standalone products still need every
    # extent resolved because their generated C harness owns the allocations.
    extents = {} if library else _extent_values(entry, extent_overrides)
    values = tuple(item for item in entry.parameters if item.role != "extent")
    input_parameters = tuple(
        item for item in values if item.role in {"input", "inout"}
    )
    file_ports = () if library else _system_file_configurations(module, entry)
    system_parameters = {
        parameter.name
        for port in file_ports
        for parameter in (port["data"], port["length"])
    }
    state_bytes = bytearray()
    opaque_input_payloads: dict[str, bytes] = {}
    if not library:
        missing = {
            _source_name(parameter)
            for parameter in input_parameters
            if parameter.name not in system_parameters
            if _source_name(parameter) not in inputs
        }
        if missing:
            raise ValueError(
                "missing C-shell inputs: " + ", ".join(sorted(missing))
            )

        for parameter in input_parameters:
            if parameter.name in system_parameters:
                continue
            source_name = _source_name(parameter)
            if str(parameter.dtype).casefold() == "opaque_ref":
                supplied_value = inputs[source_name]
                if not isinstance(supplied_value, (bytes, bytearray, memoryview)):
                    raise ValueError(
                        f"opaque CPython input {source_name!r} must be a byte payload"
                    )
                opaque_input_payloads[parameter.name] = bytes(supplied_value)
                state_bytes.extend(np.asarray(0, dtype=np.int64).tobytes())
                continue
            dtype = _NUMPY_DTYPES.get(str(parameter.dtype).casefold())
            if dtype is None:
                raise ValueError(f"unsupported C-shell dtype {parameter.dtype!r}")
            value = np.asarray(inputs[source_name], dtype=dtype)
            expected = _element_count(parameter, extents)
            if value.size != expected:
                raise ValueError(
                    f"input {source_name!r} has {value.size} elements; "
                    f"compiled ABI requires {expected}"
                )
            state_bytes.extend(np.ascontiguousarray(value).tobytes())

    fortran_path = output / f"{name}.f90"
    c_path = output / f"{name}.c"
    api_path = output / f"{name}.api.yaml"
    state_path = output / "initial-state.bin"
    final_outputs_path = output / "final-outputs.bin"
    opaque_input_files = {
        parameter_name: f"opaque-input-{index}.bin"
        for index, parameter_name in enumerate(opaque_input_payloads)
    }
    for parameter_name, payload in opaque_input_payloads.items():
        (output / opaque_input_files[parameter_name]).write_bytes(payload)
    fortran_path.write_text(primary_fortran_source, encoding="utf-8")
    packed_symbol = None
    if library:
        c_source, packed_symbol = emit_fortran_packed_library_source(entry)
        if selected_cpython is not None:
            from .cpython_runtime import emit_private_cpython_adapter

            c_source += "\n" + emit_private_cpython_adapter(
                external_reference_thunks,
                runtime_dll=selected_cpython.dll.name,
            )
    else:
        c_source = emit_native_c_shell_source(
            module,
            trace=trace,
            entrypoint=entry.name,
            state_feedback=state_feedback,
            extent_overrides=extents,
            initial_state_filename=state_path.name,
            final_outputs_filename=final_outputs_path.name,
            private_cpython_runtime_dll=(
                selected_cpython.dll.name if selected_cpython is not None else None
            ),
            private_cpython_opaque_inputs=opaque_input_files,
        )
    c_path.write_text(c_source, encoding="utf-8")
    # Pack runtime dependencies into the contract at compile time. The
    # producer knows them here -- the compiler's own bin directory is where a
    # gfortran-built library's support DLLs live -- and a consumer must never
    # rediscover them by loader archaeology (nodus boundary error register,
    # E15: a missing libgfortran presented as a silent LoadLibrary failure
    # that mimicked an ABI bug).
    # The compiled product's public contract must name the entry point that
    # was actually selected above.  A repository module can contain linked
    # dependency controls before its authored root, so preserving the
    # emitter's incidental first-control default here can advertise a helper
    # (for example ``uleb``) as the callable product instead of the requested
    # root.  Keep every exported entry, but make the shell/library selection
    # authoritative for this artifact.
    api = replace(module.api, entry=entry.name)
    if native_object_sections or native_library_paths:
        metadata = dict(api.metadata)
        metadata["native_link_sections"] = [
            {
                "language": section.language,
                "object": section.path.as_posix(),
                "symbols": list(section.symbols),
            }
            for section in native_object_sections
        ]
        metadata["native_link_libraries"] = [
            path.as_posix() for path in native_library_paths
        ]
        api = replace(api, metadata=metadata)
    runtime_dependencies = []
    if os.name == "nt" and compiler is not None:
        toolchain_bin = Path(compiler).parent
        for dll_name in (
            "libgfortran-5.dll",
            "libquadmath-0.dll",
            "libgcc_s_seh-1.dll",
            "libwinpthread-1.dll",
        ):
            candidate = toolchain_bin / dll_name
            if candidate.exists():
                runtime_dependencies.append(
                    {"name": dll_name, "path": candidate.as_posix()}
                )
    if runtime_dependencies:
        metadata = dict(api.metadata)
        metadata["runtime_dependencies"] = runtime_dependencies
        api = replace(api, metadata=metadata)
    if selected_cpython is not None:
        from .cpython_runtime import stage_cpython_runtime

        staged_cpython = stage_cpython_runtime(
            selected_cpython,
            output,
            module_identities=(
                str(thunk["identity"]) for thunk in external_reference_thunks
            ),
        )
        metadata = dict(api.metadata)
        dependencies = list(metadata.get("runtime_dependencies") or ())
        dependencies.extend({
            "name": path.name,
            "path": path.as_posix(),
            "owner": "private-cpython",
        } for path in staged_cpython.files if path.parent == output)
        metadata["runtime_dependencies"] = dependencies
        metadata["private_cpython_runtime"] = {
            "schema": "turing.private-cpython-runtime.v1",
            "abi_tag": selected_cpython.abi_tag,
            "provenance": selected_cpython.provenance,
            "manifest": staged_cpython.manifest_path.name,
        }
        api = replace(api, metadata=metadata)
    if packed_symbol is not None:
        metadata = dict(api.metadata)
        packed_entrypoints = dict(metadata.get("packed_entrypoints") or {})
        packed_entrypoints[str(entry.name)] = {
            "schema": "turing.packed-pointer-array.v1",
            "symbol": str(packed_symbol),
            "parameter_count": len(entry.parameters),
        }
        metadata["packed_entrypoints"] = packed_entrypoints
        api = replace(api, metadata=metadata)
    api.write(api_path)
    state_path.write_bytes(bytes(state_bytes))

    if library:
        suffix = ".dll" if os.name == "nt" else ".so"
    else:
        suffix = ".exe" if os.name == "nt" else ""
    executable = output / f"{name}{suffix}"
    fortran_object = output / f"{name}.fortran.o"
    c_object = output / f"{name}.shell.o"
    environment = dict(os.environ)
    if compiler is not None:
        environment["PATH"] = (
            str(Path(compiler).parent) + os.pathsep
            + environment.get("PATH", "")
        )
    uses_fortran_runtime = has_primary_fortran or any(
        section.language == "fortran" for section in native_object_sections
    )
    if uses_fortran_runtime and compiler is None:
        raise FortranEmissionError(
            "a Fortran object section requires a Fortran link driver"
        )
    link_driver = compiler if uses_fortran_runtime else gcc
    c_flags = aggressive_c_flags(compiler or gcc)
    commands: list[list[str]] = []
    if has_primary_fortran:
        fortran_flags = aggressive_fortran_flags(
            compiler,
            precision_sections=bool(
                getattr(module, "precision_sections", False)
            ),
        )
        commands.append([
            compiler, *fortran_flags, "-c", str(fortran_path),
            "-o", str(fortran_object),
        ])
    commands.append([
        gcc, *c_flags, "-std=c11", "-c", str(c_path), "-o", str(c_object),
    ])
    linked_objects = [
        str(c_object),
        *((str(fortran_object),) if has_primary_fortran else ()),
        *(str(section.path) for section in native_object_sections),
    ]
    runtime_shims = (
        standalone_runtime_shim_sources(compiler, output, standalone)
        if uses_fortran_runtime else ()
    )
    if uses_fortran_runtime:
        try:
            link_flags = (
                standalone_fortran_link_flags(compiler)
                if standalone else ("-flto",)
            )
        except ValueError as error:
            raise FortranEmissionError(str(error)) from error
    else:
        link_flags = ()
    link_command = [
        link_driver,
        *(("-shared",) if library else ()),
        *linked_objects,
        *(str(path) for path in native_library_paths),
        *runtime_shims,
        "-o", str(executable),
        *link_flags,
    ]
    if library and os.name == "nt":
        link_command.append("-Wl,--export-all-symbols")
    if not library and _display_configuration(module, entry):
        link_command.extend(("-mwindows", "-lgdi32", "-luser32"))
    commands.append(link_command)
    for command in commands:
        completed = subprocess.run(
            command,
            cwd=str(output),
            env=environment,
            capture_output=True,
            text=True,
        )
        if completed.returncode != 0:
            raise FortranEmissionError(
                "native Fortran/C-shell compilation failed:\n"
                + (completed.stderr or completed.stdout)
            )
    return FortranCShellExecutable(
        directory=output,
        executable_path=executable,
        fortran_source_path=fortran_path,
        c_source_path=c_path,
        api_path=api_path,
        initial_state_path=state_path,
        final_outputs_path=final_outputs_path,
        entrypoint=entry.name,
    )


@dataclass(frozen=True)
class NativeCompiledProgram:
    """Backend-neutral API carrier for an already-emitted native object graph."""

    api: Any
    source: str = ""
    precision_sections: bool = False


def compile_native_program_c_shell(
    api: Any,
    inputs: Mapping[str, Any],
    directory: str | Path,
    *,
    object_sections: Sequence[NativeObjectSection],
    libraries: Sequence[str | Path] = (),
    entrypoint: str | None = None,
    state_feedback: Mapping[str, str] | None = None,
    extent_overrides: Mapping[str, int] | None = None,
    name: str = "turing_native_c_shell",
    trace: bool = False,
) -> NativeCShellExecutable:
    """Link C/Fortran/LLVM objects behind the shared native C host.

    The object containing the selected entry point is not privileged: all
    sections are peers and may resolve one another's ordinary C-ABI symbols.
    A Fortran section selects the Fortran link driver for its runtime; a pure
    C/LLVM graph uses the C driver.  Program storage and invocation remain
    described by ``CompiledProgramAPI``.
    """

    sections = tuple(object_sections)
    if not sections:
        raise ValueError("native C shell requires at least one object section")
    return compile_fortran_module_c_shell(
        NativeCompiledProgram(api),
        inputs,
        directory,
        entrypoint=entrypoint,
        state_feedback=state_feedback,
        extent_overrides=extent_overrides,
        name=name,
        standalone=True,
        library=False,
        trace=trace,
        native_object_sections=sections,
        native_libraries=libraries,
    )


def _current_authored_parameter_annotations(
    graph_obj: Any,
) -> dict[str, str]:
    """Return the exact annotation spellings for this function graph."""

    catalogue = dict(
        graph_obj.graph.get("function_parameter_annotations") or {}
    )
    if catalogue and all(isinstance(value, str) for value in catalogue.values()):
        return {str(name): str(value) for name, value in catalogue.items()}
    function_name = str(graph_obj.graph.get("function_name") or "")
    owner = graph_obj.graph.get("method_owner")
    candidates = (
        f"{owner}.{function_name}" if owner else None,
        str(graph_obj.graph.get("qualified_name") or "") or None,
        function_name or None,
    )
    for identity in candidates:
        annotations = catalogue.get(identity) if identity is not None else None
        if isinstance(annotations, Mapping):
            return {
                str(name): str(value)
                for name, value in annotations.items()
            }
    return {}


def _authored_tensor_parameter_value_abi(
    graph_obj: Any,
) -> dict[str, dict[str, Any]]:
    """Return the native value ABI stated by tensor parameter annotations.

    ``torch.Tensor``, ``numpy`` tensor spellings, and ``AbstractTensor`` all
    state the same thing at source ingestion: this parameter is tensor span
    storage.  They do not state extents, so the physical ABI remains a flat
    span while tensor shape SSA carries its logical rank and dimensions.

    This is the parameter counterpart of
    :func:`_authored_annotation_field_receipt`.  Publishing it before
    deployment planning lets exact call-frame propagation carry tensor
    identity into compositional AbstractTensor sources such as ``solve``;
    otherwise those formals are indistinguishable from scalar values until
    after the operations that need their runtime shape have already planned.
    """

    from ..transmogrifier.graph.node_special_cases import (
        tensor_annotation_identity,
    )

    receipts: dict[str, dict[str, Any]] = {}
    for parameter, spelling in _current_authored_parameter_annotations(
        graph_obj
    ).items():
        try:
            annotation = ast.parse(str(spelling), mode="eval").body
        except SyntaxError:
            continue
        identity = tensor_annotation_identity(
            annotation,
            getattr(graph_obj, "python_bindings", {}) or {},
        )
        if identity is None:
            continue
        receipts[str(parameter)] = {
            "storage": "span",
            # Native storage is flat. Logical rank is a runtime tensor-shape
            # value and is never guessed from the frontend annotation. The
            # annotation also does not state a dtype; omitting it preserves
            # the exact dtype carried by the call edge instead of allowing an
            # ``unknown`` placeholder to become a physical integer ABI.
            "rank": 1,
            "mutable": False,
            "python_type": str(identity),
        }
    return receipts


def _authored_sequence_annotation_contract(
    annotation: str,
) -> tuple[str, int, bool, tuple[str, ...]] | None:
    """Interpret only explicit homogeneous collection parameter annotations."""

    try:
        expression = ast.parse(str(annotation), mode="eval").body
    except SyntaxError:
        return None
    if not isinstance(expression, ast.Subscript):
        return None
    container = (
        expression.value.id
        if isinstance(expression.value, ast.Name)
        else expression.value.attr
        if isinstance(expression.value, ast.Attribute)
        else ""
    )
    element_nodes = (
        tuple(expression.slice.elts)
        if isinstance(expression.slice, ast.Tuple)
        else (expression.slice,)
    )
    scalar_dtypes = {
        "bool": "bool",
        "int": "int64",
        "float": "float64",
        # Repository SSA represents authored text by its deterministic token.
        "str": "int64",
    }

    def scalar_dtype(node: ast.AST) -> str | None:
        spelling = (
            node.id if isinstance(node, ast.Name)
            else node.attr if isinstance(node, ast.Attribute)
            else ""
        )
        return scalar_dtypes.get(str(spelling))

    if container in {"Mapping", "MutableMapping", "Dict", "dict"}:
        if len(element_nodes) != 2:
            return None
        dtypes = tuple(scalar_dtype(node) for node in element_nodes)
        if any(dtype is None for dtype in dtypes):
            return None
        return (
            "unique", 2,
            container in {"MutableMapping", "Dict", "dict"},
            tuple(str(dtype) for dtype in dtypes),
        )
    if container not in {
        "Sequence", "Iterable", "Collection", "List", "list",
        "Tuple", "tuple", "Set", "set", "FrozenSet", "frozenset",
    }:
        return None
    # tuple[T, ...] is one homogeneous sequence. A fixed heterogeneous tuple
    # is a record and must not be flattened through this path.
    if len(element_nodes) == 2 and isinstance(
        element_nodes[1], ast.Constant
    ) and element_nodes[1].value is Ellipsis:
        element_nodes = element_nodes[:1]
    if len(element_nodes) != 1:
        return None
    dtype = scalar_dtype(element_nodes[0])
    if dtype is None:
        return None
    return (
        "unique" if container in {"Set", "set", "FrozenSet", "frozenset"}
        else "duplicates",
        1,
        container in {"List", "list", "Set", "set"},
        (dtype,),
    )


def _authored_text_parameter_transforms(
    graph_obj: Any,
) -> tuple[tuple[int, int, str, str], ...]:
    """Represent each runtime ``str`` formal by its exact UTF-8 sequence."""

    identity = graph_obj.graph.get("identity_table") or {}
    transforms = []
    for parameter_name, annotation in (
        _current_authored_parameter_annotations(graph_obj).items()
    ):
        try:
            expression = ast.parse(str(annotation), mode="eval").body
        except SyntaxError:
            continue
        spelling = (
            expression.id
            if isinstance(expression, ast.Name)
            else expression.attr
            if isinstance(expression, ast.Attribute)
            else ""
        )
        history = tuple(map(int, identity.get(str(parameter_name), ())))
        if spelling != "str" or not history:
            continue
        source_id = int(history[0])
        transforms.append((
            source_id, source_id, str(parameter_name), "utf8",
        ))
    return tuple(transforms)


def _field_slot_ops(
    graph_obj: Any,
    *,
    contract_scope: str | None = None,
    retained_storage_identities: frozenset[str] = frozenset(),
    keyed_table_fields: frozenset[str] = frozenset(),
    keyed_writable_fields: frozenset[str] = frozenset(),
):
    """Recover a method's instance-field accesses as slot loads and stores.

    A class's field layout is declared once (``class_table[class]['fields']``),
    giving each field a fixed slot. ``self`` is that field arena. This reads the
    process graph's field-op nodes and returns, for one method:

    * ``self_value_id`` -- the value id of the ``self`` arena, or ``None``;
    * ``field_ops`` -- ``(kind, value_id, slot)`` for every field access in the
      graph's own schedule order, ``kind`` being ``"read"`` (a ``GetAttr``, whose
      ``value_id`` is the result the method already consumes) or ``"write"`` (a
      ``setattr``, whose ``value_id`` is the stored source). Keeping reads and
      writes in one ordered list preserves their interleaving, so a store and a
      later read of one slot stay in the order the source wrote them;
    * ``field_count`` -- the arena length, so ``self`` is a sized array.
    """

    class_table = dict(graph_obj.graph.get("class_table") or {})
    owner = graph_obj.graph.get("method_owner")
    record = (
        class_table.get(owner)
        if owner in class_table
        else (next(iter(class_table.values())) if len(class_table) == 1 else None)
    )
    declared_self_record = dict(
        (graph_obj.graph.get("parameter_record_abi") or {}).get("self") or {}
    )
    declared_fields = tuple(dict(declared_self_record.get("fields") or {}))
    # Once a method receiver has a ProgramABI record, that declaration is its
    # physical layout and identity. Class navigation supplies method bodies;
    # its descriptive field catalogue must not widen or reorder ABI storage.
    fields = declared_fields or tuple((record or {}).get("fields") or ())
    declared_identity = declared_self_record.get("identity")
    record_identity = (
        str(declared_identity) if declared_identity is not None else owner
    )
    slot_of = {name: index for index, name in enumerate(fields)}

    identity = dict(graph_obj.graph.get("identity_table") or {})
    sequence_contract_scope = str(
        contract_scope
        or graph_obj.graph.get("qualified_name")
        or graph_obj.graph.get("function_name")
        or "<anonymous>"
    )
    from .identity_concordance import (
        commit_sequence_contract,
        committed_sequence_contract,
    )
    self_history = identity.get("self") or ()
    self_value_id = int(self_history[-1]) if self_history else None

    # Order field ops by SOURCE order (node id), not the data-dependency
    # schedule. Memory ordering between a write and a later read of the same
    # field is a real dependency the AST wrote but the graph does not carry as a
    # data edge, so a topological sort is free to float the read ahead of the
    # write. Nodes are created in source order, so their ids preserve the order
    # the programmer wrote -- which is the order the memory operations must run.
    field_ops: list[tuple[str, int, int]] = []
    const_sources: dict[int, Any] = {}
    sequence_initializations: list[tuple[int, str, int]] = []
    sequence_declarations: list[tuple[int, str, int, bool]] = []
    sequence_memberships: list[tuple[int, int, int, bool]] = []
    table_lookups: list[tuple[int, int | tuple[int, ...], int]] = []
    table_stores: list[tuple[int, int | tuple[int, ...], int, int]] = []
    table_deletions: list[
        tuple[int, int | tuple[int, ...], int | None, str]
    ] = []
    tombstone_sequence_ids: set[int] = set()
    retained_sequence_ids: set[int] = set()
    nested_sequence_ids: set[int] = set()
    nested_tensor_sequence_ids: set[int] = set()
    nested_record_fields: dict[int, tuple[str, int]] = {}
    field_aliases = dict(graph_obj.graph.get("class_field_aliases") or {})
    field_aggregate_kinds = dict(
        graph_obj.graph.get("class_field_aggregate_kinds") or {}
    )
    # A dataclass annotation is also an exact physical record contract.  Keep
    # its span kind available to the class-field coordinator so a read such as
    # ``self.locals`` becomes the declared sequence arena, never a scalar load
    # from the receiver slot vector.  Explicit frontend aggregate evidence
    # wins when both are present.
    declared_span_kinds = {
        str(field_name): str(field.get("aggregate_kind"))
        for field_name, field in dict(
            declared_self_record.get("fields") or {}
        ).items()
        if str(field.get("storage") or "") == "span"
        and field.get("aggregate_kind") is not None
    }
    declared_parameter_table_kinds = {
        str(field_name): "list"
        for parameter_record in dict(
            graph_obj.graph.get("parameter_record_abi") or {}
        ).values()
        for field_name, field in dict(
            parameter_record.get("fields") or {}
        ).items()
        if str(field.get("storage") or "") == "table"
    }
    field_aggregate_kinds = {
        **declared_span_kinds,
        **declared_parameter_table_kinds,
        **field_aggregate_kinds,
    }
    field_value_aggregate_kinds = dict(
        graph_obj.graph.get("class_field_value_aggregate_kinds") or {}
    )

    def node_operation(data: Mapping[str, Any]) -> str:
        """Canonical ProcessGraph operation spelling for field analysis.

        Authored graph nodes carry the semantic class in ``type`` and often a
        lower-case executable spelling in ``op``.  Preferring ``op`` without
        normalizing it made ``type=GetAttr, op=getattr`` invisible to the
        whole-object resolver, exactly where object fields should become
        native record storage.
        """

        return str(data.get("op") or data.get("type") or "").casefold()

    def canonical_field(name: str) -> str:
        seen: set[str] = set()
        current = str(name)
        while current in field_aliases and current not in seen:
            seen.add(current)
            current = str(field_aliases[current])
        return current

    # A method may mention only an alias (NetworkX ``_succ``) while its record
    # storage is authored under the canonical field (``_adj``). Correlate all
    # such GetAttr occurrences to one resident sequence ID; this is storage
    # aliasing, not value copying or object dispatch.
    field_sequence_ids: dict[str, int] = {}
    lexical_sequence_ids: dict[tuple[str, str], int] = {}
    inferred_nested_table_bases: dict[int, int] = {}
    aggregate_reads: list[tuple[str, str, int]] = []

    def fixed_row_width(annotation: Any) -> int | None:
        """Read a fixed tuple row width from an authored container annotation."""

        layout = _authored_row_layout(annotation, dict(
            (graph_obj.graph.get("program_abi") or {}).get("records") or {}
        ))
        if layout is None:
            return None
        return sum(width for _kind, _identity, width in layout)

    annotated_row_widths: dict[int, int] = {}
    for binding_name, annotation in (
        *dict(graph_obj.graph.get("type_annotations") or {}).items(),
        # A parameter's authored annotation declares its row exactly as a
        # local annotation does; ``failures: list[tuple[float, Metrics,
        # tuple[str, ...]]] | None`` is the physical row of ``failures``.
        *_current_authored_parameter_annotations(graph_obj).items(),
    ):
        width = fixed_row_width(annotation)
        if width is None:
            continue
        for value_id in identity.get(str(binding_name), ()):
            annotated_row_widths[int(value_id)] = int(width)
    for parameter_name, annotation in (
        _current_authored_parameter_annotations(graph_obj).items()
    ):
        contract = _authored_sequence_annotation_contract(annotation)
        history = tuple(map(int, identity.get(str(parameter_name), ())))
        if contract is None or not history:
            continue
        policy, column_count, writable, _dtypes = contract
        commit_sequence_contract(
            sequence_contract_scope,
            int(history[0]),
            policy,
            int(column_count),
            bool(writable),
            source=f"authored parameter {parameter_name}: {annotation}",
        )
    for binding_name, record in _graph_sequence_record_abi(graph_obj).items():
        width = len(_record_row_physical_columns(record))
        for value_id in identity.get(str(binding_name), ()):
            annotated_row_widths[int(value_id)] = int(width)
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if node_operation(data) != "getattr":
            continue
        attribute = (data.get("attributes") or {}).get("attribute")
        if field_aggregate_kinds.get(str(attribute)) not in {
            "list", "set", "dict", "tuple", "bytes", "bytearray"
        }:
            continue
        aggregate_reads.append((
            str(attribute), canonical_field(str(attribute)),
            int(data.get("value_id", node_id)),
        ))
    for attribute, canonical, result_id in aggregate_reads:
        if attribute == canonical:
            field_sequence_ids[canonical] = result_id
    for _attribute, canonical, result_id in aggregate_reads:
        field_sequence_ids.setdefault(canonical, result_id)
    # Table fields on ordinary record parameters and on rows selected from a
    # Sequence[Record] are resident sequences too. They are not method-self
    # slots, so declare them from the exact receiver ABI instead of routing
    # them through `slot_of` below.
    sequence_record_by_value: dict[int, Mapping[str, Any]] = {}
    for binding_name, sequence_record in _graph_sequence_record_abi(
        graph_obj
    ).items():
        for value_id in identity.get(str(binding_name), ()):
            sequence_record_by_value[int(value_id)] = sequence_record
    parameter_record_by_value = {
        int(value_id): record
        for parameter_name, record in dict(
            graph_obj.graph.get("parameter_record_abi") or {}
        ).items()
        for value_id in identity.get(str(parameter_name), ())
    }
    for node_id, data in graph_obj.nodes(data=True):
        if node_operation(data) != "getattr":
            continue
        attribute = str((data.get("attributes") or {}).get("attribute") or "")
        receiver_id = next((
            int(parent)
            for parent, role in data.get("parents") or ()
            if str(role) in {"value", "object", "base", "receiver"}
            and int(parent) in graph_obj
        ), None)
        if receiver_id is None:
            continue
        field_record = parameter_record_by_value.get(receiver_id)
        receiver = graph_obj.nodes[receiver_id]
        if field_record is None and node_operation(receiver) in {
            "indexed", "load",
        }:
            row_source = next((
                int(parent)
                for parent, role in receiver.get("parents") or ()
                if str(role) == "base" and int(parent) in graph_obj
            ), None)
            if row_source is not None:
                field_record = sequence_record_by_value.get(row_source)
        field = (
            None if field_record is None
            else dict(field_record.get("fields") or {}).get(attribute)
        )
        if not isinstance(field, Mapping) or str(
            field.get("storage") or ""
        ) != "table":
            continue
        sequence_declarations.append((
            int(data.get("value_id", node_id)),
            "duplicates",
            len(tuple(field.get("columns") or ())),
            bool(field.get("mutable", False)),
        ))
    # A contract-declared keyed field is a lookup table too, but it is a
    # program-ABI record field, not a class-field aggregate, so it must not
    # enter ``field_sequence_ids`` (that registry engages the object-field
    # arena machinery).  Same identity convention: the GetAttr's own value id
    # names the table, one canonical id per field.
    keyed_field_sequence_ids: dict[str, int] = {}
    if keyed_table_fields:
        for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
            data = graph_obj.nodes[node_id]
            if node_operation(data) != "getattr":
                continue
            attribute = str(
                (data.get("attributes") or {}).get("attribute") or ""
            )
            if attribute not in keyed_table_fields:
                continue
            sequence_id = keyed_field_sequence_ids.setdefault(
                attribute, int(data.get("value_id", node_id))
            )
            receiver_id = next((
                int(parent)
                for parent, role in data.get("parents") or ()
                if str(role) in {"value", "object", "base", "receiver"}
                and int(parent) in graph_obj
            ), None)
            receiver_record = (
                None if receiver_id is None
                else parameter_record_by_value.get(receiver_id)
            )
            receiver_field = (
                None if receiver_record is None
                else dict(receiver_record.get("fields") or {}).get(attribute)
            )
            if bool(
                (data.get("attributes") or {}).get(
                    "mapping_value_tensor", False
                )
                or (
                    isinstance(receiver_field, Mapping)
                    and receiver_field.get("value_tensor")
                )
            ):
                # The exact Program-ABI receiver field (and, when retained,
                # the reducer's equivalent node receipt) declares
                # ``Mapping[..., Tensor]``. Carry that same structural fact
                # into the sequence contract: the outer value column stores
                # child-row handles and the child pool owns the tensor spans.
                # Treating it as the scalar-value table is the point where
                # tensor identity otherwise disappears before SSA lowering.
                nested_sequence_ids.add(int(sequence_id))
                nested_tensor_sequence_ids.add(int(sequence_id))
    # Runtime aggregates captured from a lexical/module binding are resident
    # storage exactly like aggregate fields, but they have no record slot.
    # Correlate all normalized occurrences by their authored binding identity;
    # never inspect or serialize the bound Python collection's contents.
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        attributes = data.get("attributes") or {}
        aggregate_kind = attributes.get("aggregate_kind")
        binding_name = attributes.get("binding_name")
        binding_kind = attributes.get("binding_kind")
        if (
            aggregate_kind not in {
                "list", "set", "dict", "tuple", "bytes", "bytearray"
            }
            or binding_name is None
            or binding_kind not in {"parameter", "closure", "external"}
        ):
            continue
        identity_key = (str(binding_kind), str(binding_name))
        sequence_id = lexical_sequence_ids.setdefault(
            identity_key, int(data.get("value_id", node_id))
        )
        committed = committed_sequence_contract(
            sequence_contract_scope, sequence_id
        )
        policy = (
            committed.policy if committed is not None else
            "unique" if aggregate_kind in {"set", "dict"} else "duplicates"
        )
        column_count = (
            committed.column_count if committed is not None else
            2 if aggregate_kind == "dict" else
            max(1, annotated_row_widths.get(int(sequence_id), 1))
        )
        writable = (
            committed.writable if committed is not None else
            aggregate_kind not in {"tuple", "bytes"}
        )
        sequence_declarations.append((
            sequence_id,
            policy,
            column_count,
            writable,
        ))
        commit_sequence_contract(
            sequence_contract_scope,
            sequence_id,
            policy,
            column_count,
            writable,
            source=(
                f"runtime aggregate {binding_kind}.{binding_name} "
                f"viewed as {aggregate_kind}"
            ),
        )
        storage_identity = f"{binding_kind}.{binding_name}"
        if storage_identity in retained_storage_identities:
            retained_sequence_ids.add(sequence_id)

    # An authored homogeneous collection annotation is sufficient physical
    # ABI evidence even when the Input node itself has no Python aggregate
    # value attached. This matters for detached compilation: Sequence[str]
    # is a token arena, not an untyped scalar that happens to be indexed.
    declared_sequence_ids = {
        int(sequence_id)
        for sequence_id, _policy, _columns, _writable
        in sequence_declarations
    }
    for parameter_name, annotation in (
        _current_authored_parameter_annotations(graph_obj).items()
    ):
        contract = _authored_sequence_annotation_contract(annotation)
        history = tuple(map(int, identity.get(str(parameter_name), ())))
        if contract is None or not history:
            continue
        sequence_id = int(history[0])
        if sequence_id in declared_sequence_ids:
            continue
        policy, column_count, writable, _dtypes = contract
        lexical_sequence_ids.setdefault(
            ("parameter", str(parameter_name)), sequence_id
        )
        sequence_declarations.append((
            sequence_id, policy, int(column_count), bool(writable),
        ))
        declared_sequence_ids.add(sequence_id)
        retained_sequence_ids.add(sequence_id)

    # Source-derived ``Sequence[Record]`` metadata survives graph extraction
    # independently of any one Input wrapper. Declare its caller-owned
    # columnar arena explicitly so later field projections share one physical
    # descriptor instead of minting anonymous fallback columns.
    for parameter_name, record in _graph_sequence_record_abi(graph_obj).items():
        history = tuple(map(int, identity.get(str(parameter_name), ())))
        sequence_record_fields = tuple(dict(record.get("fields") or {}))
        if not history or not sequence_record_fields:
            continue
        sequence_id = int(history[0])
        lexical_sequence_ids.setdefault(
            ("parameter", str(parameter_name)), sequence_id
        )
        sequence_declarations.append((
            sequence_id,
            "duplicates",
            len(_record_row_physical_columns(record)),
            bool(record.get("mutable", False)),
        ))

    # An unannotated parameter can still state a complete aggregate contract
    # through authored operations.  ``key in p`` plus ``p[key]`` whose result
    # is iterated proves a keyed table whose values are child sequences.  This
    # derives storage from graph structure; it does not inspect parameter
    # contents or infer from a method's spelling.
    iterated_value_ids = {
        int(graph_obj.nodes[parent].get("value_id", parent))
        for node_id in graph_obj.nodes()
        for data in (graph_obj.nodes[node_id],)
        if (data.get("op") or data.get("type")) == "For"
        for parent, role in (data.get("parents") or ())
        if str(role) == "iterable" and parent in graph_obj
    }
    inferred_by_identity: dict[tuple[str, str], list[int]] = {}
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if node_operation(data) != "indexed":
            continue
        result_id = int(data.get("value_id", node_id))
        if result_id not in iterated_value_ids:
            continue
        base_nodes = tuple(
            int(parent) for parent, role in (data.get("parents") or ())
            if str(role) == "base" and parent in graph_obj
        )
        if len(base_nodes) != 1:
            continue
        base_data = graph_obj.nodes[base_nodes[0]]
        base_attributes = base_data.get("attributes") or {}
        if base_attributes.get("binding_kind") != "parameter":
            continue
        binding_name = base_attributes.get("binding_name")
        if binding_name is None:
            continue
        inferred_by_identity.setdefault(
            ("parameter", str(binding_name)), []
        ).append(int(base_data.get("value_id", base_nodes[0])))
    for identity_key, observed_ids in inferred_by_identity.items():
        history = tuple(map(int, identity.get(identity_key[1], ())))
        sequence_id = int(history[0] if history else observed_ids[0])
        lexical_sequence_ids.setdefault(identity_key, sequence_id)
        sequence_declarations.append((sequence_id, "unique", 2, False))
        nested_sequence_ids.add(sequence_id)
        for value_id in (*history, *observed_ids):
            inferred_nested_table_bases[int(value_id)] = sequence_id

    # Locally constructed aggregates are resident storage too.  Previously the
    # record extractor declared only parameters, captures and object fields;
    # a local ``out = []`` or ``charmap = bytearray(256)`` therefore reached a
    # planned region as a shapeless scalar unless append/add happened to create
    # a descriptor as a side effect.  The source graph already owns the exact
    # producer identity, storage policy and writability, so publish that same
    # identity in the method sequence table.  Tuple values remain record rows
    # and are handled by projected-row/record lowering rather than pretending
    # the heterogeneous record itself is one homogeneous arena.
    singleton_structural_scalar_ids = {
        int(leaf_ids[0])
        for _candidate_id, candidate in graph_obj.nodes(data=True)
        for leaf_ids in (tuple(map(
            int,
            (candidate.get("attributes") or {}).get(
                "aggregate_leaf_value_ids", ()
            ),
        )),)
        if len(leaf_ids) == 1
    }
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        attributes = data.get("attributes") or {}
        aggregate_kind = attributes.get("aggregate_kind")
        snapshot = (aggregate_kind == "tuple" and
                    attributes.get("producer_kind") == "aggregate_materialization")
        if not snapshot and aggregate_kind not in {
            "list", "set", "dict", "bytes", "bytearray"
        }:
            continue
        if (
            aggregate_kind == "bytes"
            and attributes.get("producer_kind")
            == "aggregate_materialization"
        ):
            # ``bytes(local_sequence)`` is a result view over the local arena,
            # not a second independently allocated sequence.  Root authority
            # below maps it to its sole source only after that relation is
            # proven; declaring another arena here fabricates an ABI input.
            continue
        sequence_id = int(data.get("value_id", node_id))
        leaf_ids = tuple(map(int, attributes.get(
            "aggregate_leaf_value_ids", ()
        )))
        if (
            len(leaf_ids) == 1 and sequence_id == leaf_ids[0]
            or sequence_id in singleton_structural_scalar_ids
        ):
            # A singleton literal/wrapper may deliberately reuse its sole
            # scalar leaf as a reducible structural identity.  It is consumed
            # by concat lowering as ``append_scalar`` and owns no arena of its
            # own. Declaring that scalar id as a sequence turns ordinary
            # parameters such as ``section_id`` into rank-1 arrays.
            continue
        sequence_declarations.append((
            sequence_id,
            "unique" if aggregate_kind in {"set", "dict"} else "duplicates",
            (
                (
                    int(attributes.get("mapping_key_column_count", 1)) + 1
                ) if aggregate_kind == "dict"
                else max(
                    int(attributes.get("sequence_column_count", 1)),
                    annotated_row_widths.get(sequence_id, 1),
                )
            ),
            snapshot or bool(attributes.get(
                "sequence_writable", aggregate_kind != "bytes"
            )),
        ))
        mapping_items = attributes.get("compile_time_mapping_items")
        if (aggregate_kind == "dict" and mapping_items is not None
                and not isinstance(data.get("expr_obj"), ast.Dict)):
            from .string_table import string_token

            encoded_rows = tuple(
                (
                    string_token(key) if isinstance(key, str) else key,
                    string_token(item) if isinstance(item, str) else item,
                )
                for key, item in tuple(mapping_items)
            )
            sequence_initializations.append((
                sequence_id,
                f"literal_table={encoded_rows!r}",
                2,
            ))
        if attributes.get("mapping_value_aggregate_kind") in {
            "list", "set", "dict", "bytearray"
        }:
            nested_sequence_ids.add(sequence_id)
    mapping_storage_aliases = _loop_carried_storage_aliases(graph_obj)
    declared_mapping_ids = {
        int(sequence_id) for sequence_id, policy, columns, _writable in sequence_declarations
        if policy == "unique" and columns >= 2
    }
    lexical_mapping_effects = {
        int(mutation.effect_node_id) for mutation in _source_mapping_mutations(graph_obj)
        if mutation.operator == "update"
    }

    def table_sequence(base_id: int) -> tuple[int | None, str | None]:
        base_id = int(mapping_storage_aliases.get(int(base_id), base_id))
        # A defensive ``mapping or {}`` keeps the mapping's exact contents:
        # the empty fallback is selected only when the mapping is already
        # empty.  Treat that expression as the left mapping for every keyed
        # query, including ``get``. Membership lowering already applied this
        # identity rule locally; keeping it here makes all table consumers use
        # one graph rewrite and lets the normal lookup path retain its default.
        for _ in range(4):
            if base_id not in graph_obj:
                break
            base_data = graph_obj.nodes[base_id]
            expression = base_data.get("expr_obj")
            if not (
                isinstance(expression, ast.BoolOp)
                and isinstance(expression.op, ast.Or)
            ):
                break
            operands = {
                str(role): int(parent)
                for parent, role in (base_data.get("parents") or ())
            }
            left_id = operands.get("value:0")
            right_id = operands.get("value:1")
            if (
                left_id is None
                or right_id is None
                or right_id not in graph_obj
            ):
                break
            right_data = graph_obj.nodes[right_id]
            right_expression = right_data.get("expr_obj")
            if not (
                isinstance(right_expression, ast.Dict)
                and not right_expression.keys
                and not right_expression.values
            ):
                break
            base_id = int(mapping_storage_aliases.get(left_id, left_id))
        if base_id not in graph_obj:
            return None, None
        base_data = graph_obj.nodes[base_id]
        inferred_sequence_id = inferred_nested_table_bases.get(
            int(base_data.get("value_id", base_id))
        )
        if inferred_sequence_id is not None:
            return inferred_sequence_id, "parameter.inferred_nested_table"
        attributes = base_data.get("attributes") or {}
        if attributes.get("compile_time_mapping_items") is not None:
            return (
                int(base_data.get("value_id", base_id)),
                f"constant.{attributes.get('binding_name', base_id)}",
            )
        field_name = attributes.get("attribute")
        if field_aggregate_kinds.get(str(field_name)) == "dict":
            canonical = canonical_field(str(field_name))
            return (
                field_sequence_ids[canonical],
                f"{owner}.{canonical}",
            )
        if str(field_name) in keyed_field_sequence_ids:
            return (
                keyed_field_sequence_ids[str(field_name)],
                f"keyed.{field_name}",
            )
        if attributes.get("aggregate_kind") != "dict":
            return None, None
        binding_name = attributes.get("binding_name")
        binding_kind = attributes.get("binding_kind")
        identity_key = (str(binding_kind), str(binding_name))
        if binding_name is None or identity_key not in lexical_sequence_ids:
            value_id = int(base_data.get("value_id", base_id))
            if value_id in declared_mapping_ids:
                return value_id, f"materialized-mapping:{value_id}"
            return None, None
        return (
            lexical_sequence_ids[identity_key],
            f"{binding_kind}.{binding_name}",
        )

    def authored_index_values(data: Any) -> int | tuple[int, ...] | None:
        values = tuple(
            int(graph_obj.nodes[parent].get("value_id", parent))
            for parent, role in (data.get("parents") or ())
            if str(role) == "index" and parent in graph_obj
        )
        if not values:
            return None
        return values[0] if len(values) == 1 else values

    def deletes_first_live_key(data: Any) -> bool:
        expression = data.get("expr_obj")
        if not isinstance(expression, ast.Subscript):
            return False
        key = expression.slice
        return (
            isinstance(key, ast.Call)
            and isinstance(key.func, ast.Name)
            and key.func.id == "next"
            and len(key.args) == 1
            and isinstance(key.args[0], ast.Call)
            and isinstance(key.args[0].func, ast.Name)
            and key.args[0].func.id == "iter"
            and len(key.args[0].args) == 1
            and ast.dump(key.args[0].args[0], include_attributes=False)
            == ast.dump(expression.value, include_attributes=False)
        )
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        node_type = node_operation(data)
        attribute = (data.get("attributes") or {}).get("attribute")
        canonical_attribute = (
            canonical_field(str(attribute)) if attribute is not None else None
        )
        if canonical_attribute is None or canonical_attribute not in slot_of:
            continue
        if node_type == "getattr":
            result_id = data.get("value_id", node_id)
            field_ops.append((
                "read", int(result_id), slot_of[canonical_attribute]
            ))
            aggregate_kind = field_aggregate_kinds.get(str(attribute))
            if aggregate_kind in {
                "list", "set", "dict", "tuple", "bytes", "bytearray"
            }:
                sequence_id = field_sequence_ids[canonical_field(str(attribute))]
                if int(result_id) == sequence_id:
                    sequence_declarations.append((
                        sequence_id,
                        "unique" if aggregate_kind in {"set", "dict"} else "duplicates",
                        2 if aggregate_kind == "dict" else 1,
                        aggregate_kind not in {"tuple", "bytes"},
                    ))
                storage_identity = f"{owner}.{canonical_field(str(attribute))}"
                if storage_identity in retained_storage_identities:
                    retained_sequence_ids.add(sequence_id)
                if field_value_aggregate_kinds.get(str(attribute)) == "dict":
                    nested_sequence_ids.add(sequence_id)
        elif node_type == "setattr":
            source_parent = next(
                (
                    parent
                    for parent, role in (data.get("parents") or ())
                    if str(role) == "value"
                ),
                None,
            )
            if source_parent is None:
                continue
            source_data = graph_obj.nodes[source_parent]
            source_id = source_data.get("value_id", source_parent)
            field_ops.append((
                "write", int(source_id), slot_of[canonical_attribute]
            ))
            source_attributes = source_data.get("attributes") or {}
            if node_operation(source_data) == "staticreference":
                reference_identity = source_attributes.get(
                    "static_python_reference"
                )
                if reference_identity is not None:
                    from .string_table import string_token

                    identity = str(reference_identity)
                    const_sources[int(source_id)] = {
                        "ssa_reference_identity": identity,
                        "reference_kind": "static-python",
                        "reference_handle": string_token(
                            "\x00turing.reference.static-python\x00" + identity
                        ),
                        "host_resident": True,
                    }
            nested_class_identity = source_attributes.get("class_ref")
            if nested_class_identity is not None:
                nested_record_fields[slot_of[canonical_attribute]] = (
                    str(nested_class_identity), int(source_id)
                )
            aggregate_kind = (
                source_attributes.get("aggregate_kind")
                or field_aggregate_kinds.get(str(attribute))
            )
            if (
                aggregate_kind in {"list", "set", "dict", "bytearray"}
                and attribute not in field_aliases
            ):
                sequence_initializations.append((
                    int(source_id),
                    "unique" if aggregate_kind in {"set", "dict"} else "duplicates",
                    2 if aggregate_kind == "dict" else 1,
                ))
                storage_identity = f"{owner}.{canonical_field(str(attribute))}"
                if storage_identity in retained_storage_identities:
                    retained_sequence_ids.add(int(source_id))
                if field_value_aggregate_kinds.get(str(attribute)) == "dict":
                    nested_sequence_ids.add(int(source_id))
            # A constant field write (``self.x = None`` / ``5`` / ``"s"``) has
            # no producer in the control body, so carry the constant value; the
            # injection materialises it before the store (None becomes the
            # absence sentinel via the tokenizer).
            if node_operation(source_data) in {"const", "constant"}:
                attrs = source_data.get("attributes") or {}
                const_sources[int(source_id)] = attrs.get(
                    "value", source_data.get("constant")
                )
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.Compare)
            and len(expression.ops) == 1
            and isinstance(expression.ops[0], (ast.In, ast.NotIn))
        ):
            continue
        by_role = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        query_id = by_role.get("lhs")
        field_id = by_role.get("rhs")
        if query_id is None or field_id is None or field_id not in graph_obj:
            continue
        field_data = graph_obj.nodes[field_id]
        # ``x in (obj.field or {})`` (or a local alias of that expression,
        # e.g. ``channels = metrics.error_channels or {}; ... "k" in
        # channels``) is a real, common defensive idiom, not a different
        # shape of membership test: the ``or`` only ever supplies a fallback
        # when the field itself is falsy, so the field identity for
        # membership purposes is its LEFT operand. Without this, the field
        # lookup below sees a BoolOp node with no ``attribute``/
        # ``aggregate_kind`` of its own and silently fails to recognize the
        # membership test at all (diagnosed against the real managed-tire
        # compile: `_no_exchange_observed`'s `"power_w" in channels` never
        # materialized a value because of exactly this).
        for _ in range(4):
            boolop_expression = field_data.get("expr_obj")
            if not (
                isinstance(boolop_expression, ast.BoolOp)
                and isinstance(boolop_expression.op, ast.Or)
            ):
                break
            left_id = next((
                int(parent)
                for parent, role in (field_data.get("parents") or ())
                if str(role) == "value:0"
            ), None)
            if left_id is None or left_id not in graph_obj:
                break
            field_id = left_id
            field_data = graph_obj.nodes[field_id]
        field_attributes = field_data.get("attributes") or {}
        field_name = field_attributes.get("attribute")
        sequence_id = None
        if field_aggregate_kinds.get(str(field_name)) in {"dict", "set"}:
            sequence_id = field_sequence_ids[canonical_field(str(field_name))]
        elif field_attributes.get("aggregate_kind") in {"dict", "set"}:
            identity_key = (
                str(field_attributes.get("binding_kind")),
                str(field_attributes.get("binding_name")),
            )
            sequence_id = lexical_sequence_ids.get(identity_key)
        elif int(field_data.get("value_id", field_id)) in (
            inferred_nested_table_bases
        ):
            sequence_id = inferred_nested_table_bases[
                int(field_data.get("value_id", field_id))
            ]
        if sequence_id is None:
            continue
        sequence_memberships.append((
            int(data.get("value_id", node_id)),
            int(graph_obj.nodes[query_id].get("value_id", query_id)),
            int(sequence_id),
            isinstance(expression.ops[0], ast.NotIn),
        ))
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if node_operation(data) != "indexed":
            continue
        by_role = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        base_id = by_role.get("base")
        key_id = authored_index_values(data)
        if base_id is None or key_id is None or base_id not in graph_obj:
            continue
        sequence_id, _storage_identity = table_sequence(base_id)
        if sequence_id is None:
            continue
        table_lookups.append((
            int(data.get("value_id", node_id)),
            key_id,
            int(sequence_id),
        ))
    # ``d.get(key, default)`` is the same lookup ``d[key]`` is -- the key's
    # token walked against the table -- differing only in what the absent
    # branch yields.  Recognising only ``indexed`` left ``get`` unclaimed, so
    # its result crossed every backend as a producerless argument.  The
    # authored default rides beside the lookup by result id.
    table_lookup_defaults: dict[int, Any] = {}
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if node_operation(data) != "get":
            continue
        by_role = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        base_id = by_role.get("operand") or by_role.get("value")
        key_id = by_role.get("arg:0")
        if base_id is None or key_id is None or base_id not in graph_obj:
            continue
        sequence_id, _storage_identity = table_sequence(base_id)
        if sequence_id is None:
            continue
        result_id = int(data.get("value_id", node_id))
        key_id = int(graph_obj.nodes[key_id].get("value_id", key_id))
        table_lookups.append((result_id, key_id, int(sequence_id)))
        default_node = by_role.get("arg:1")
        if default_node is not None and default_node in graph_obj:
            default_data = graph_obj.nodes[default_node]
            literal = default_data.get("constant")
            if literal is None:
                literal = (
                    default_data.get("attributes") or {}
                ).get("value")
            if isinstance(literal, (int, float)) and not isinstance(
                literal, bool
            ):
                table_lookup_defaults[result_id] = float(literal)
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if node_operation(data) != "indexedstore":
            continue
        if int(data.get("value_id", node_id)) in lexical_mapping_effects:
            # These writes are emitted at their authored control position.
            continue
        by_role = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        base_id = by_role.get("base")
        key_id = authored_index_values(data)
        value_id = by_role.get("value")
        if None in (base_id, key_id, value_id) or base_id not in graph_obj:
            continue
        sequence_id, _storage_identity = table_sequence(base_id)
        if sequence_id is None:
            continue
        table_stores.append((
            int(data.get("value_id", node_id)),
            key_id,
            int(graph_obj.nodes[value_id].get("value_id", value_id)),
            int(sequence_id),
        ))
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if str(data.get("op") or data.get("type")).lower() != "delitem":
            continue
        by_role = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        base_id = by_role.get("base")
        key_id = (() if deletes_first_live_key(data)
                  else authored_index_values(data))
        if base_id is None or key_id is None or base_id not in graph_obj:
            continue
        sequence_value_id, storage_identity = table_sequence(base_id)
        if storage_identity is None:
            storage_identity = f"nested-table-value:{base_id}"
        table_deletions.append((
            int(data.get("value_id", node_id)),
            key_id,
            sequence_value_id,
            storage_identity,
        ))
    # A retained mapping ``pop`` is lowered by the control mutation identity,
    # not by this field-op table.  It nevertheless changes the table's
    # physical ABI: lookup-and-delete requires the same live-flag/tombstone
    # storage as authored ``del table[key]``.  Survey that structural fact
    # separately so it cannot accidentally emit a second deletion.
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if node_operation(data) != "pop":
            continue
        receiver_nodes = tuple(
            int(parent)
            for parent, role in (data.get("parents") or ())
            if str(role) in {"operand", "value", "object", "base", "receiver"}
            and parent in graph_obj
        )
        if not receiver_nodes:
            func_nodes = tuple(
                int(parent)
                for parent, role in (data.get("parents") or ())
                if str(role) == "func" and parent in graph_obj
            )
            if len(func_nodes) != 1:
                continue
            func_data = graph_obj.nodes[func_nodes[0]]
            func_attributes = func_data.get("attributes") or {}
            if (
                node_operation(func_data) != "getattr"
                or str(func_attributes.get("attribute") or "") != "pop"
            ):
                continue
            receiver_nodes = tuple(
                int(parent)
                for parent, role in (func_data.get("parents") or ())
                if str(role) in {"value", "object", "base", "receiver"}
                and parent in graph_obj
            )
        if len(receiver_nodes) != 1:
            continue
        receiver_data = graph_obj.nodes[receiver_nodes[0]]
        receiver_attributes = receiver_data.get("attributes") or {}
        if receiver_attributes.get("aggregate_kind") == "dict":
            tombstone_sequence_ids.add(int(
                receiver_data.get("value_id", receiver_nodes[0])
            ))
        sequence_id, _storage_identity = table_sequence(receiver_nodes[0])
        if sequence_id is not None:
            tombstone_sequence_ids.add(int(sequence_id))
    # Runtime sequence replication (``[x] * count``) is a fill of resident
    # caller storage, not numerical multiplication and not a Python literal.
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        attributes = data.get("attributes") or {}
        if attributes.get("producer_kind") != "sequence_replication":
            continue
        parents = tuple(data.get("parents") or ())
        sequence_parents = tuple(
            int(parent) for parent, role in parents
            if str(role) in {"lhs", "rhs"}
            and parent in graph_obj
            and (graph_obj.nodes[parent].get("attributes") or {}).get(
                "aggregate_kind"
            ) in {"list", "tuple"}
        )
        fill_ids = tuple(
            int(leaf_id)
            for parent in sequence_parents
            for leaf_id in (
                graph_obj.nodes[parent].get("attributes") or {}
            ).get("aggregate_leaf_value_ids", ())
        )
        count_ids = tuple(
            int(parent) for parent, role in parents
            if str(role) in {"lhs", "rhs"}
            and int(parent) not in sequence_parents
        )
        if len(fill_ids) != 1 or len(count_ids) != 1:
            continue
        fill_data = graph_obj.nodes.get(fill_ids[0], {})
        literal = (fill_data.get("attributes") or {}).get(
            "value", fill_data.get("constant")
        )
        if literal is not None and not isinstance(literal, (bool, int, float)):
            continue
        result_id = int(data.get("value_id", node_id))
        sequence_initializations.append((
            result_id,
            f"fill={literal!r};count={count_ids[0]}",
            1,
        ))
    # An unannotated local can still have a fixed-width row contract when the
    # authored mutation supplies a tuple record.  The mutation extractor has
    # already expanded that tuple into its exact leaf identities.  Reconcile
    # those leaves with the resident declaration before control lowering so a
    # list initially spelled ``[]`` is not frozen as a one-column sequence and
    # then rejected when ``append((left, right))`` reaches it.  Conflicting row
    # widths remain unresolved and are refused later; choosing one would invent
    # an ABI that the source does not state.
    declared_sequence_ids = {
        int(sequence_id) for sequence_id, *_rest in sequence_declarations
    }
    resident_by_value = {
        int(sequence_id): int(sequence_id)
        for sequence_id in declared_sequence_ids
    }
    for history in identity.values():
        history_ids = tuple(map(int, history))
        residents = tuple(
            value_id for value_id in history_ids
            if value_id in declared_sequence_ids
        )
        if len(set(residents)) != 1:
            continue
        resident = residents[0]
        resident_by_value.update({
            value_id: resident for value_id in history_ids
        })
    observed_row_widths: dict[int, set[int]] = {}
    for mutation in _sequence_append_call_mutations(graph_obj):
        if mutation.argument_kind != "row":
            continue
        resident = resident_by_value.get(int(mutation.sequence_value_id))
        width = len(tuple(mutation.argument_value_ids))
        if resident is not None and width > 1:
            observed_row_widths.setdefault(int(resident), set()).add(width)
    inferred_row_widths = {
        sequence_id: next(iter(widths))
        for sequence_id, widths in observed_row_widths.items()
        if len(widths) == 1
    }
    sequence_declarations = [
        (
            sequence_id,
            policy,
            max(column_count, inferred_row_widths.get(sequence_id, 1)),
            writable,
        )
        for sequence_id, policy, column_count, writable
        in sequence_declarations
    ]

    key_width_by_sequence: dict[int, int] = {}
    for _effect_or_result, key_ids, sequence_id, *_rest in (
        *table_lookups, *table_stores, *table_deletions
    ):
        if sequence_id is None:
            continue
        key_width_by_sequence[int(sequence_id)] = max(
            key_width_by_sequence.get(int(sequence_id), 1),
            len(key_ids) if isinstance(key_ids, tuple) else 1,
        )
    sequence_declarations = [
        (
            sequence_id,
            policy,
            (
                max(
                    column_count,
                    key_width_by_sequence.get(sequence_id, 1) + 1,
                )
                if policy == "unique" and column_count > 1
                else column_count
            ),
            writable,
        )
        for sequence_id, policy, column_count, writable
        in sequence_declarations
    ]
    # A record-field dict is a table exactly as a local one is, but declare it
    # only where a table operation actually addresses it: a declaration
    # materializes anonymous descriptor storage into the frame, and doing that
    # in functions that merely ITERATE the mapping displaced their public-span
    # correlation for every unrelated rank-2 field.
    field_table_ids = {
        int(sequence_id)
        for sequence_id in (
            *field_sequence_ids.values(),
            *keyed_field_sequence_ids.values(),
        )
    }
    referenced_table_ids = {
        int(sequence_id)
        for _result, _query, sequence_id in table_lookups
    } | {
        int(sequence_id)
        for _effect, _key, _value, sequence_id in table_stores
    }
    declared_ids = {
        int(sequence_id) for sequence_id, *_rest in sequence_declarations
    }
    # A contract-declared keyed field is writable exactly when the contract
    # says so (``mutable: true``): its store helper is refused as a read-only
    # destination otherwise.
    writable_keyed_table_ids = {
        int(sequence_id)
        for field_name, sequence_id in keyed_field_sequence_ids.items()
        if str(field_name) in keyed_writable_fields
    }
    sequence_declarations.extend(
        (int(sequence_id), "unique", 2, int(sequence_id) in writable_keyed_table_ids)
        for sequence_id in sorted(field_table_ids & referenced_table_ids)
        if int(sequence_id) not in declared_ids
    )
    for sequence_id, policy, column_count, writable in sequence_declarations:
        commit_sequence_contract(
            sequence_contract_scope,
            int(sequence_id),
            str(policy),
            int(column_count),
            bool(writable),
            source="shell sequence declaration",
        )
    return (
        self_value_id,
        tuple(field_ops),
        const_sources,
        len(fields),
        fields,
        record_identity,
        tuple(dict.fromkeys(sequence_initializations)),
        tuple(
            (slot_of[alias], slot_of[target])
            for alias, target in field_aliases.items()
            if alias in slot_of and target in slot_of
        ),
        tuple(dict.fromkeys(sequence_declarations)),
        tuple(dict.fromkeys(sequence_memberships)),
        tuple(dict.fromkeys(table_lookups)),
        dict(table_lookup_defaults),
        tuple(dict.fromkeys(table_stores)),
        tuple(dict.fromkeys(table_deletions)),
        tuple(sorted(retained_sequence_ids)),
        tuple(sorted(nested_sequence_ids)),
        tuple(sorted(nested_tensor_sequence_ids)),
        tuple(sorted(
            (slot, identity, value_id)
            for slot, (identity, value_id) in nested_record_fields.items()
        )),
        tuple(sorted(tombstone_sequence_ids)),
    )


def _sequence_augassign_ops(graph_obj: Any) -> tuple[tuple[int, int, int], ...]:
    """Return proven ``sequence += sequence`` storage mutations.

    The graph's identity history correlates each lexical spelling with its
    successive SSA versions.  Resolve the AugAssign destination back to the
    resident aggregate producer bearing that spelling, and do the same for the
    source.  No operation-name inference is involved: both endpoints must be
    graph nodes already carrying an aggregate storage contract.
    """

    sequence_kinds = {"list", "set", "dict", "bytes", "bytearray"}
    identity = dict(graph_obj.graph.get("identity_table") or {})
    resident_by_value: dict[int, int] = {}
    for _name, history in identity.items():
        residents = tuple(
            int(value_id)
            for value_id in history
            if int(value_id) in graph_obj
            and (graph_obj.nodes[int(value_id)].get("attributes") or {}).get(
                "aggregate_kind"
            ) in sequence_kinds
        )
        if not residents:
            continue
        resident = residents[0]
        for value_id in history:
            resident_by_value[int(value_id)] = resident

    # Conditional/loop joins preserve the authored storage identity when every
    # incoming value already denotes that same resident arena.  Carry that
    # alias through Phi/LoopResult nodes to later AugAssign occurrences; never
    # choose an arbitrary branch when the residents differ or are unresolved.
    changed = True
    while changed:
        changed = False
        for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
            if int(node_id) in resident_by_value:
                continue
            data = graph_obj.nodes[node_id]
            if str(data.get("type") or data.get("op")).lower() not in {
                "phi", "loopresult"
            }:
                continue
            incoming = {
                resident_by_value[int(parent)]
                for parent, role in (data.get("parents") or ())
                if str(role) in {"body", "orelse", "initial", "updated", "value"}
                and int(parent) in resident_by_value
            }
            unresolved = any(
                str(role) in {"body", "orelse", "initial", "updated", "value"}
                and int(parent) not in resident_by_value
                for parent, role in (data.get("parents") or ())
            )
            if len(incoming) == 1 and not unresolved:
                resident_by_value[int(node_id)] = incoming.pop()
                changed = True

    operations = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.AugAssign)
            and isinstance(expression.op, ast.Add)
            and isinstance(expression.target, ast.Name)
        ):
            continue
        parents = {
            str(role): int(parent) for parent, role in (data.get("parents") or ())
        }
        result_id = int(data.get("value_id", node_id))
        destination_id = resident_by_value.get(parents.get("lhs", -1))
        source_id = resident_by_value.get(parents.get("rhs", -1))
        if destination_id is None or source_id is None:
            continue
        operations.append((result_id, destination_id, source_id))
    return tuple(operations)


def _sequence_concat_ops(
    graph_obj: Any,
    *,
    call_result_kinds: Mapping[int, str] | None = None,
    structural_aliases: Mapping[int, tuple[int, str]] | None = None,
) -> tuple[
    tuple[tuple[int, int, int, str, int | None, int | None], ...],
    tuple[tuple[int, int], ...],
    dict[int, int],
]:
    """Recognize value-producing sequence ``+`` without numericizing it.

    Python's ``bytes + bytes`` and ``list + list`` allocate a new logical
    sequence; they are not elementwise arithmetic.  ProcessGraph deliberately
    keeps the authored ``Add`` spelling, so this identity proves sequence
    semantics from the operands' aggregate contracts (including pursued-call
    result contracts) and returns both concat operations and immutable
    materialization aliases such as ``bytes([value]) -> [value]``.
    """

    sequence_kinds = {"list", "bytes", "bytearray"}
    resident_by_value: dict[int, int] = {}
    kind_by_value: dict[int, str] = {}
    singleton_by_resident: dict[int, int] = {}
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        attributes = data.get("attributes") or {}
        kind = str(attributes.get("aggregate_kind") or "")
        if kind not in sequence_kinds:
            continue
        value_id = int(data.get("value_id", node_id))
        if attributes.get("producer_kind") == "aggregate_materialization":
            source_nodes = tuple(
                int(parent)
                for parent, role in (data.get("parents") or ())
                if str(role).startswith("arg:") and parent in graph_obj
            )
            sources = tuple(
                int(graph_obj.nodes[parent].get("value_id", parent))
                for parent in source_nodes
            )
            if len(sources) == 1:
                resident_id = resident_by_value.get(
                    sources[0], sources[0]
                )
                resident_by_value[value_id] = resident_id
                kind_by_value[value_id] = kind
                # ``bytes([opcode])`` is an immutable view of a singleton
                # authored aggregate.  The materializer may carry the leaf
                # ledger even when its transient list source does not; retain
                # that exact scalar identity on the physical resident so
                # concat lowering emits append_scalar and does not demand a
                # sequence descriptor for a one-byte temporary.
                source_expression = (
                    graph_obj.nodes[source_nodes[0]].get("expr_obj")
                    if len(source_nodes) == 1 else None
                )
                source_attributes = (
                    graph_obj.nodes[source_nodes[0]].get("attributes") or {}
                    if len(source_nodes) == 1 else {}
                )
                literal_singleton = (
                    isinstance(source_expression, (ast.List, ast.Tuple, ast.Set))
                    and len(source_expression.elts) == 1
                ) or (
                    source_attributes.get("aggregate_kind") in {
                        "list", "tuple", "set"
                    }
                    and len(tuple(source_attributes.get(
                        "aggregate_leaf_value_ids", ()
                    ))) == 1
                )
                if os.environ.get("TURING_DEBUG_SEQUENCE_CONCAT"):
                    print(
                        "DEBUGMATERIALIZE "
                        f"value={value_id} kind={kind!r} sources={sources!r} "
                        f"source_expr={ast.dump(source_expression, include_attributes=False) if isinstance(source_expression, ast.AST) else None!r} "
                        f"source_kind={source_attributes.get('aggregate_kind')!r} "
                        f"source_type={graph_obj.nodes[source_nodes[0]].get('type')!r} "
                        f"source_constant={graph_obj.nodes[source_nodes[0]].get('constant')!r} "
                        f"source_attributes={source_attributes!r} "
                        f"source_leaves={tuple(source_attributes.get('aggregate_leaf_value_ids', ()))!r} "
                        f"materializer_leaves={tuple(attributes.get('aggregate_leaf_value_ids', ()))!r}",
                        file=sys.stderr,
                    )
                # Prefer the authored singleton aggregate's leaf ledger.  A
                # bytes materializer records its direct argument (the list)
                # as its leaf, while the list records the actual scalar.  The
                # latter is what append_scalar must consume.  Fall back to the
                # materializer ledger only for frontends which omit source
                # aggregate metadata.
                leaves = (
                    tuple(map(int, source_attributes.get(
                        "aggregate_leaf_value_ids", ()
                    )))
                    if literal_singleton else ()
                )
                if not leaves and literal_singleton:
                    leaves = tuple(map(int, attributes.get(
                        "aggregate_leaf_value_ids", ()
                    )))
                if len(leaves) == 1:
                    singleton_by_resident[int(resident_id)] = leaves[0]
                continue
        resident_by_value[value_id] = value_id
        kind_by_value[value_id] = kind
        leaves = tuple(map(int, attributes.get(
            "aggregate_leaf_value_ids", ()
        )))
        if len(leaves) == 1:
            singleton_by_resident[value_id] = leaves[0]

    for value_id, kind in dict(call_result_kinds or {}).items():
        if str(kind) not in sequence_kinds:
            continue
        resident_by_value[int(value_id)] = int(value_id)
        kind_by_value[int(value_id)] = str(kind)
    for value_id, (resident_id, kind) in dict(
        structural_aliases or {}
    ).items():
        if str(kind) not in sequence_kinds:
            continue
        resident_by_value[int(value_id)] = int(resident_id)
        resident_by_value.setdefault(int(resident_id), int(resident_id))
        kind_by_value[int(value_id)] = str(kind)
        kind_by_value.setdefault(int(resident_id), str(kind))
    # IndexedStore and its loop-result versions are deterministic names for
    # the same resident arena.  Retain that correlation while recognizing
    # structural concatenations across control-versioned sequence names.
    storage_aliases = _loop_carried_storage_aliases(graph_obj)
    changed = True
    while changed:
        changed = False
        for alias_id, source_id in storage_aliases.items():
            resident_id = resident_by_value.get(int(source_id))
            kind = kind_by_value.get(int(source_id))
            if resident_id is None or kind not in sequence_kinds:
                continue
            if resident_by_value.get(int(alias_id)) != int(resident_id):
                resident_by_value[int(alias_id)] = int(resident_id)
                kind_by_value[int(alias_id)] = str(kind)
                changed = True
        for node_id, data in graph_obj.nodes(data=True):
            if str(data.get("op") or data.get("type") or "").casefold() not in {
                "phi", "loopresult", "loopexit",
            }:
                continue
            value_id = int(data.get("value_id", node_id))
            resolved_parents = {
                (
                    int(resident_by_value[parent_value]),
                    str(kind_by_value[parent_value]),
                )
                for parent, role in data.get("parents") or ()
                if str(role) not in {"control", "test"}
                and parent in graph_obj
                for parent_value in (
                    int(graph_obj.nodes[parent].get("value_id", parent)),
                )
                if parent_value in resident_by_value
                and parent_value in kind_by_value
            }
            if len(resolved_parents) != 1:
                continue
            resident_id, kind = next(iter(resolved_parents))
            if resident_by_value.get(value_id) != resident_id:
                resident_by_value[value_id] = resident_id
                kind_by_value[value_id] = kind
                changed = True

    operations: list[
        tuple[int, int, int, str, int | None, int | None]
    ] = []
    # Deterministic ids are source ordered, so inner concatenations precede
    # the outer expression that consumes them.
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if str(data.get("type") or data.get("op") or "") != "Add":
            continue
        parents = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        lhs_node = parents.get("lhs")
        rhs_node = parents.get("rhs")
        if lhs_node is None or rhs_node is None:
            continue
        lhs_value = int(graph_obj.nodes[lhs_node].get("value_id", lhs_node))
        rhs_value = int(graph_obj.nodes[rhs_node].get("value_id", rhs_node))
        lhs = resident_by_value.get(lhs_value)
        rhs = resident_by_value.get(rhs_value)
        if lhs is None or rhs is None:
            if os.environ.get("TURING_DEBUG_SEQUENCE_CONCAT"):
                print(
                    "DEBUGSEQMISS "
                    f"fn={graph_obj.graph.get('function_name')} "
                    f"result={int(data.get('value_id', node_id))} "
                    f"lhs_value={lhs_value} lhs_resident={lhs} "
                    f"rhs_value={rhs_value} rhs_resident={rhs} "
                    f"source={ast.unparse(data.get('expr_obj')) if isinstance(data.get('expr_obj'), ast.AST) else None!r}",
                    file=sys.stderr,
                )
            continue
        lhs_kind = kind_by_value.get(lhs_value, kind_by_value.get(lhs))
        rhs_kind = kind_by_value.get(rhs_value, kind_by_value.get(rhs))
        if lhs_kind != rhs_kind:
            if os.environ.get("TURING_DEBUG_SEQUENCE_CONCAT"):
                print(
                    "DEBUGSEQMISS "
                    f"fn={graph_obj.graph.get('function_name')} "
                    f"result={int(data.get('value_id', node_id))} "
                    f"lhs_kind={lhs_kind!r} rhs_kind={rhs_kind!r} "
                    f"source={ast.unparse(data.get('expr_obj')) if isinstance(data.get('expr_obj'), ast.AST) else None!r}",
                    file=sys.stderr,
                )
            continue
        result_id = int(data.get("value_id", node_id))
        result_kind = str(lhs_kind)
        operations.append((
            result_id, int(lhs), int(rhs), result_kind,
            singleton_by_resident.get(int(lhs)),
            singleton_by_resident.get(int(rhs)),
        ))
        if os.environ.get("TURING_DEBUG_SEQUENCE_CONCAT"):
            print(
                "DEBUGSEQ "
                f"fn={graph_obj.graph.get('function_name')} "
                f"result={result_id} lhs={int(lhs)} rhs={int(rhs)} "
                f"lhs_scalar={singleton_by_resident.get(int(lhs))} "
                f"rhs_scalar={singleton_by_resident.get(int(rhs))} "
                f"source={ast.unparse(data.get('expr_obj')) if isinstance(data.get('expr_obj'), ast.AST) else None!r}",
                file=sys.stderr,
            )
        resident_by_value[result_id] = result_id
        kind_by_value[result_id] = result_kind

    aliases = tuple(sorted(
        (int(value_id), int(resident_id))
        for value_id, resident_id in resident_by_value.items()
        if int(value_id) != int(resident_id)
    ))
    singleton_materializations = {
        int(value_id): int(singleton_by_resident[int(resident_id)])
        for value_id, resident_id in aliases
        if int(resident_id) in singleton_by_resident
    }
    return tuple(operations), aliases, singleton_materializations


def _sequence_value_kinds(
    graph_obj: Any,
    *,
    return_sequence_kind_by_reference: Mapping[int, str] | None = None,
) -> dict[int, str]:
    """Resolve sequence semantics through calls and structural expressions.

    A pursued callee's result is represented in its caller by the callee's
    return value identity, not by another aggregate-construction node. Merely
    scanning nodes carrying ``aggregate_kind`` therefore loses a sequence at
    exactly the boundary where an ordinary helper returns it. Resolve direct
    aggregate facts, known call returns, materialization aliases, and sequence
    concatenations as one backend-independent structural closure.
    """

    sequence_kinds = {"list", "bytes", "bytearray"}
    kinds: dict[int, str] = {}
    for node_id, data in graph_obj.nodes(data=True):
        attributes = data.get("attributes") or {}
        kind = str(attributes.get("aggregate_kind") or "")
        if kind not in sequence_kinds:
            continue
        value_id = int(data.get("value_id", node_id))
        kinds[value_id] = kind
        if attributes.get("producer_kind") != "aggregate_materialization":
            continue
        sources = tuple(
            int(graph_obj.nodes[parent].get("value_id", parent))
            for parent, role in (data.get("parents") or ())
            if str(role).startswith("arg:") and parent in graph_obj
        )
        if len(sources) == 1:
            kinds[sources[0]] = kind

    call_result_kinds: dict[int, str] = {}
    return_kinds = dict(return_sequence_kind_by_reference or {})
    for node_id, data in graph_obj.nodes(data=True):
        attributes = data.get("attributes") or {}
        reference = attributes.get(
            "callee_ref", attributes.get("method_ref")
        )
        if reference is None:
            continue
        kind = return_kinds.get(int(reference))
        if kind in sequence_kinds:
            value_id = int(data.get("value_id", node_id))
            call_result_kinds[value_id] = str(kind)
            kinds[value_id] = str(kind)

    structural_aliases = {
        int(result_id): (int(source_id), "bytes")
        for result_id, source_id, _source_name, _transform
        in (
            *_utf8_encode_aliases(graph_obj),
            *(
                record for record in _bytes_join_source_transforms(graph_obj)
                if str(record[3]) == "join_bytes"
            ),
        )
    }
    concatenations, aliases, _singletons = _sequence_concat_ops(
        graph_obj,
        call_result_kinds=call_result_kinds,
        structural_aliases=structural_aliases,
    )
    for result_id, _lhs, _rhs, kind, _lhs_scalar, _rhs_scalar in concatenations:
        kinds[int(result_id)] = str(kind)
    for alias_id, resident_id in aliases:
        resident_kind = kinds.get(int(resident_id))
        if resident_kind is not None:
            kinds[int(alias_id)] = resident_kind
    return kinds


def _promote_conditional_sequence_aliases(
    control: Any,
    graph_obj: Any,
    *,
    call_result_kinds: Mapping[int, str] | None = None,
    structural_aliases: Mapping[int, tuple[int, str]] | None = None,
):
    """Turn branch-carried aggregate versions into resident arena carries.

    Ordinary conditional planning records every authored assignment in the
    scalar-shaped ``carried_aliases`` tuple.  Once source/call analysis proves
    those values are sequences, retain one initial arena, copy the selected
    branch value into it, and correlate the post-branch SSA spelling with that
    arena.  This is an IR correction, not a receipt-only relabeling.
    """

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, SequenceBlock, WhileBlock,
    )

    sequence_kinds = {"list", "bytes", "bytearray"}
    resident_by_value: dict[int, int] = {}
    kind_by_value: dict[int, str] = {}
    for node_id, data in graph_obj.nodes(data=True):
        attributes = data.get("attributes") or {}
        kind = str(attributes.get("aggregate_kind") or "")
        if kind not in sequence_kinds:
            continue
        value_id = int(data.get("value_id", node_id))
        resident_by_value[value_id] = value_id
        kind_by_value[value_id] = kind
    for value_id, kind in dict(call_result_kinds or {}).items():
        if str(kind) in sequence_kinds:
            resident_by_value[int(value_id)] = int(value_id)
            kind_by_value[int(value_id)] = str(kind)
    for value_id, (resident_id, kind) in dict(
        structural_aliases or {}
    ).items():
        if str(kind) not in sequence_kinds:
            continue
        resident_by_value[int(value_id)] = int(resident_id)
        kind_by_value[int(value_id)] = str(kind)
        kind_by_value.setdefault(int(resident_id), str(kind))

    # In-place stores and their Phi/loop-result spellings are storage
    # versions, not scalar values.  Resolve them to their original arena before
    # inspecting conditional carries, otherwise the branch becomes an opaque
    # scalar Phi and every later row projection leaks into the public ABI.
    storage_aliases = _loop_carried_storage_aliases(graph_obj)
    changed = True
    while changed:
        changed = False
        for alias_id, source_id in storage_aliases.items():
            resident_id = resident_by_value.get(int(source_id))
            kind = kind_by_value.get(int(source_id))
            if resident_id is None or kind not in sequence_kinds:
                continue
            if resident_by_value.get(int(alias_id)) != int(resident_id):
                resident_by_value[int(alias_id)] = int(resident_id)
                kind_by_value[int(alias_id)] = str(kind)
                changed = True
        for node_id, data in graph_obj.nodes(data=True):
            if str(data.get("op") or data.get("type") or "").casefold() not in {
                "phi", "loopresult", "loopexit",
            }:
                continue
            value_id = int(data.get("value_id", node_id))
            resolved_parents = {
                (
                    int(resident_by_value[parent_value]),
                    str(kind_by_value[parent_value]),
                )
                for parent, role in data.get("parents") or ()
                if str(role) not in {"control", "test"}
                and parent in graph_obj
                for parent_value in (
                    int(graph_obj.nodes[parent].get("value_id", parent)),
                )
                if parent_value in resident_by_value
                and parent_value in kind_by_value
            }
            if len(resolved_parents) != 1:
                continue
            resident_id, kind = next(iter(resolved_parents))
            if resident_by_value.get(value_id) != resident_id:
                resident_by_value[value_id] = resident_id
                kind_by_value[value_id] = kind
                changed = True

    promoted_aliases: dict[int, tuple[int, str]] = {}
    destination_ids: set[int] = set()

    def promote(block):
        if isinstance(block, ConditionalBlock):
            scalar = []
            sequences = list(block.carried_sequence_aliases)
            for carried in block.carried_aliases:
                true_id, false_id, initial_id, merged_id = map(int, carried)
                initial_resident = resident_by_value.get(initial_id)
                initial_kind = kind_by_value.get(initial_id)
                true_resident = resident_by_value.get(true_id)
                false_resident = resident_by_value.get(false_id)
                true_kind = kind_by_value.get(true_id)
                false_kind = kind_by_value.get(false_id)
                if (
                    initial_resident is None
                    or initial_kind not in sequence_kinds
                    or true_resident is None
                    or false_resident is None
                    or true_kind != initial_kind
                    or false_kind != initial_kind
                ):
                    scalar.append(carried)
                    continue
                destination = int(initial_resident)
                sequences.append((
                    int(true_resident), int(false_resident),
                    destination, merged_id,
                ))
                destination_ids.add(destination)
                resident_by_value[merged_id] = destination
                kind_by_value[merged_id] = initial_kind
                promoted_aliases[merged_id] = (destination, initial_kind)
            return replace(
                block,
                body=promote(block.body),
                orelse=(
                    None if block.orelse is None else promote(block.orelse)
                ),
                carried_aliases=tuple(scalar),
                carried_sequence_aliases=tuple(sequences),
            )
        if isinstance(block, SequenceBlock):
            return replace(block, blocks=tuple(promote(x) for x in block.blocks))
        if isinstance(block, LoopBlock):
            promoted_body = promote(block.body)
            scalar_carries = []
            sequence_updates: set[tuple[int, int]] = set()
            for updated_id, initial_id in block.carried_aliases:
                updated_id = int(updated_id)
                initial_id = int(initial_id)
                updated_resident = resident_by_value.get(updated_id)
                initial_resident = resident_by_value.get(initial_id)
                if (
                    updated_resident is None
                    or initial_resident is None
                    or updated_resident != initial_resident
                    or kind_by_value.get(updated_id) not in sequence_kinds
                    or kind_by_value.get(initial_id) not in sequence_kinds
                ):
                    scalar_carries.append((updated_id, initial_id))
                    continue
                sequence_updates.add((updated_id, initial_id))
                kind = str(kind_by_value[initial_id])
                promoted_aliases[updated_id] = (
                    int(initial_resident), kind,
                )
                destination_ids.add(int(initial_resident))
            scalar_ports = []
            for port_id, initial_id, updated_id in block.result_ports:
                key = (int(updated_id), int(initial_id))
                if key not in sequence_updates:
                    scalar_ports.append((
                        int(port_id), int(initial_id), int(updated_id)
                    ))
                    continue
                resident_id = int(resident_by_value[int(initial_id)])
                kind = str(kind_by_value[int(initial_id)])
                resident_by_value[int(port_id)] = resident_id
                kind_by_value[int(port_id)] = kind
                promoted_aliases[int(port_id)] = (resident_id, kind)
            return replace(
                block,
                body=promoted_body,
                carried_aliases=tuple(scalar_carries),
                result_ports=tuple(scalar_ports),
            )
        if isinstance(block, WhileBlock):
            return replace(
                block,
                condition=promote(block.condition),
                body=promote(block.body),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=promote(block.callee))
        return block

    promoted = replace(control, root=promote(control.root))
    return promoted, promoted_aliases, tuple(sorted(destination_ids))


def _constant_struct_pack_materializations(graph_obj: Any):
    """Fold fully source-static ``struct.pack`` calls to byte-sequence facts."""

    import struct

    materializations = []
    for node_id, data in sorted(graph_obj.nodes(data=True)):
        attributes = data.get("attributes") or {}
        if attributes.get("extraction_identity") != "_struct.pack":
            continue
        arguments = tuple(
            int(parent)
            for parent, role in sorted(
                data.get("parents") or (),
                key=lambda item: int(str(item[1]).split(":", 1)[1])
                if str(item[1]).startswith("arg:") else 1 << 30,
            )
            if str(role).startswith("arg:") and int(parent) in graph_obj
        )
        values = []
        for argument in arguments:
            argument_data = graph_obj.nodes[argument]
            argument_attributes = argument_data.get("attributes") or {}
            if "value" in argument_attributes:
                values.append(argument_attributes["value"])
            elif argument_data.get("constant") is not None:
                values.append(argument_data["constant"])
            else:
                break
        if len(values) != len(arguments) or not values:
            continue
        try:
            payload = struct.pack(*values)
        except (struct.error, TypeError, ValueError):
            continue
        value_id = int(data.get("value_id", node_id))
        updated = dict(attributes)
        updated.update({
            "producer_kind": "constant_sequence",
            "aggregate_kind": "bytes",
            "sequence_key_columns": (),
            "sequence_column_count": 1,
            "sequence_writable": False,
            "constant_bytes": bytes(payload),
        })
        data["attributes"] = updated
        materializations.append((
            value_id,
            bytes(payload),
            int(node_id),
            "_struct.pack",
        ))
    return tuple(materializations)


def _constant_byte_literal_materializations(graph_obj: Any):
    """Publish authored byte literals through the resident sequence ABI."""

    materializations = []
    for node_id, data in sorted(graph_obj.nodes(data=True)):
        attributes = data.get("attributes") or {}
        literal = attributes.get("value", data.get("constant"))
        if not isinstance(literal, bytes):
            continue
        value_id = int(data.get("value_id", node_id))
        updated = dict(attributes)
        updated.update({
            "producer_kind": "constant_sequence",
            "aggregate_kind": "bytes",
            "sequence_key_columns": (),
            "sequence_column_count": 1,
            "sequence_writable": False,
            "constant_bytes": bytes(literal),
        })
        data["attributes"] = updated
        materializations.append((
            value_id, bytes(literal), int(node_id), None,
        ))
    return tuple(materializations)


def _source_sequence_snapshots(graph_obj: Any):
    """Tuple conversion captures contents and length in separate storage."""
    from .control_source import ControlSequenceMutation
    mutations = []
    for node_id, data in graph_obj.nodes(data=True):
        attrs = data.get("attributes") or {}
        if (attrs.get("aggregate_kind") != "tuple"
                or attrs.get("producer_kind") != "aggregate_materialization"):
            continue
        sources = [int(parent) for parent, role in data.get("parents") or ()
                   if str(role) == "arg:0"]
        if len(sources) != 1:
            continue
        source = sources[0]
        if (graph_obj.nodes.get(source, {}).get("attributes") or {}).get("aggregate_kind") not in {"list", "tuple"}:
            continue
        mutations.append(ControlSequenceMutation(
            int(node_id), "replace", (source,), int(node_id), policy="duplicates",
        ))
    return tuple(mutations)


def _source_mapping_mutations(graph_obj: Any):
    """Retain copies and writes to graph-owned dictionary materializers."""
    from .control_source import ControlSequenceMutation

    aliases = _loop_carried_storage_aliases(graph_obj)
    materializers = {}
    for node_id, data in graph_obj.nodes(data=True):
        attrs = data.get("attributes") or {}
        if (attrs.get("aggregate_kind") == "dict"
                and attrs.get("producer_kind") == "aggregate_materialization"
                and not attrs.get("binding_name")):
            materializers[int(node_id)] = data
    mutations = []
    for node_id, data in materializers.items():
        arguments = [int(parent) for parent, role in data.get("parents") or ()
                     if str(role).startswith("arg:")]
        if len(arguments) != 1:
            continue
        source = arguments[0]
        source_data = graph_obj.nodes.get(source, {})
        expression = source_data.get("expr_obj")
        if isinstance(expression, ast.BoolOp) and isinstance(expression.op, ast.Or):
            source = next((int(parent) for parent, role in source_data.get("parents") or ()
                           if role == "value:0"), source)
        source = int(aliases.get(source, source))
        if (graph_obj.nodes.get(source, {}).get("attributes") or {}).get("aggregate_kind") != "dict":
            continue
        mutations.append(ControlSequenceMutation(
            int(data.get("value_id", node_id)), "replace", (source,),
            int(data.get("value_id", node_id)), policy="unique",
        ))
    for node_id, data in graph_obj.nodes(data=True):
        if str(data.get("type") or data.get("op")).lower() != "indexedstore":
            continue
        roles = {str(role): int(parent) for parent, role in data.get("parents") or ()}
        base = roles.get("base")
        base = aliases.get(base, base)
        if base not in materializers or "index" not in roles or "value" not in roles:
            continue
        mutations.append(ControlSequenceMutation(
            int(graph_obj.nodes[base].get("value_id", base)), "update",
            (roles["index"], roles["value"]), int(data.get("value_id", node_id)),
            policy="unique", argument_kind="mapping_items",
        ))
    return tuple(mutations)


def _identity_return_aliases(graph_obj: Any, function_table: Any) -> dict[int, int]:
    """Prove caller aliases using callee return slots that return a formal."""
    if function_table is None:
        return {}
    result = {}
    for call_id, data in graph_obj.nodes(data=True):
        reference = (data.get("attributes") or {}).get("callee_ref")
        if reference is None:
            continue
        child = getattr(function_table.entry(reference), "graph", None)
        child = getattr(child, "G", None)
        if child is None:
            continue
        sites = tuple((child.graph.get("return_slot_values") or {}).values())
        if not sites or len({len(site) for site in sites}) != 1:
            continue
        parameters = tuple(child.graph.get("function_parameters") or ())
        actuals = {str(role): int(parent) for parent, role in data.get("parents") or ()}
        for index, slots in enumerate(zip(*sites)):
            if len(set(slots)) != 1 or slots[0] is None:
                continue
            formal = child.nodes.get(int(slots[0]), {})
            attrs = formal.get("attributes") or {}
            name = attrs.get("binding_name")
            if attrs.get("binding_kind") != "parameter" or name not in parameters:
                continue
            actual = actuals.get(f"arg:{parameters.index(name)}")
            if actual is None:
                continue
            if len(sites[0]) == 1:
                result[int(call_id)] = actual
            for node_id, projection in graph_obj.nodes(data=True):
                if str(projection.get("type") or projection.get("op") or "").casefold() in {"indexedstore", "subscriptstore", "setitem"}:
                    continue
                roles = {str(role): int(parent) for parent, role in projection.get("parents") or ()}
                if roles.get("base") != int(call_id):
                    continue
                key = (graph_obj.nodes.get(roles.get("index"), {}).get("attributes") or {}).get("value")
                if key == index:
                    result[int(node_id)] = actual
    return result


def _static_mapping_capacity_bounds(
    graph_obj: Any,
    *,
    nonmutating_call_ids: Iterable[int] = (),
) -> dict[int, int]:
    """Bound local keyed arenas by their complete constant-key universe.

    Repeated writes, including writes in loops, cannot increase this bound.
    Copies inherit the source universe. Dynamic keys and external sources
    deliberately have no bound here; they need a runtime capacity contract.
    """
    aliases = _loop_carried_storage_aliases(graph_obj)
    nonmutating_calls = set(map(int, nonmutating_call_ids))
    keys, copies, unknown = {}, {}, set()
    for node_id, data in graph_obj.nodes(data=True):
        expression = data.get("expr_obj")
        attributes = data.get("attributes") or {}
        if (attributes.get("aggregate_kind") == "dict"
                and attributes.get("materialization_kind") == "unrolled_loop"):
            universe = keys.setdefault(int(node_id), set())
            for row_id in attributes.get("materialized_value_ids", ()):
                row = graph_obj.nodes.get(int(row_id), {})
                leaves = tuple(int(parent) for parent, role in row.get("parents", ()) if role == "elts")
                key_data = graph_obj.nodes.get(leaves[0], {}) if leaves else {}
                try:
                    if "value" in (key_data.get("attributes") or {}):
                        key = key_data["attributes"]["value"]
                    else:
                        key = ast.literal_eval(key_data.get("expr_obj"))
                    universe.add(key)
                except (ValueError, TypeError):
                    unknown.add(int(node_id))
        if isinstance(expression, ast.Dict):
            try:
                keys[int(node_id)] = {ast.literal_eval(key) for key in expression.keys}
            except (ValueError, TypeError):
                unknown.add(int(node_id))
    for mutation in _source_mapping_mutations(graph_obj):
        destination = int(mutation.sequence_value_id)
        if mutation.operator == "replace":
            copies[destination] = int(mutation.argument_value_ids[0])
            keys.setdefault(destination, set())
        elif mutation.operator == "update":
            for key_id in mutation.argument_value_ids[::2]:
                data = graph_obj.nodes.get(int(key_id), {})
                try:
                    key = ast.literal_eval(data.get("expr_obj"))
                    keys.setdefault(destination, set()).add(key)
                except (ValueError, TypeError):
                    unknown.add(destination)
    for _node_id, data in graph_obj.nodes(data=True):
        roles = {str(role): int(parent) for parent, role in data.get("parents") or ()}
        operation = str(data.get("type") or data.get("op") or "").casefold()
        if operation == "indexedstore":
            destination = int(aliases.get(roles.get("base"), roles.get("base", -1)))
            if destination in keys:
                try:
                    key = ast.literal_eval(graph_obj.nodes[roles["index"]].get("expr_obj"))
                    keys[destination].add(key)
                except (KeyError, ValueError, TypeError):
                    unknown.add(destination)
        elif (operation in {"call", "plancall", "update", "setdefault"}
              and int(_node_id) not in nonmutating_calls
              and int(_node_id) not in copies):
            for parent in roles.values():
                destination = int(aliases.get(parent, parent))
                if destination in keys:
                    unknown.add(destination)
    changed = True
    while changed:
        changed = False
        for destination, source in copies.items():
            if source not in keys or source in unknown:
                if destination not in unknown:
                    unknown.add(destination)
                    changed = True
            else:
                previous = len(keys[destination])
                keys[destination].update(keys[source])
                changed |= len(keys[destination]) != previous
    return {node_id: len(universe) for node_id, universe in keys.items()
            if node_id not in unknown}


def _static_sequence_capacity_bounds(
    graph_obj: Any,
    *,
    nonmutating_call_ids: Iterable[int] = (),
) -> dict[int, int]:
    bounds = _static_mapping_capacity_bounds(
        graph_obj,
        nonmutating_call_ids=nonmutating_call_ids,
    )
    local_lists = {int(node_id): len(data["expr_obj"].elts)
                   for node_id, data in graph_obj.nodes(data=True)
                   if isinstance(data.get("expr_obj"), ast.List)}
    unknown = set()
    loops = [data["expr_obj"] for _, data in graph_obj.nodes(data=True)
             if isinstance(data.get("expr_obj"), (ast.For, ast.While))]
    for mutation in _sequence_append_call_mutations(graph_obj):
        sequence_id = int(mutation.sequence_value_id)
        if sequence_id not in local_lists or mutation.operator == "clear":
            continue
        expression = graph_obj.nodes.get(int(mutation.effect_node_id), {}).get("expr_obj")
        line = getattr(expression, "lineno", None)
        if (mutation.operator != "append" or line is None
                or any(loop.lineno <= line <= loop.end_lineno for loop in loops)):
            unknown.add(sequence_id)
        else:
            local_lists[sequence_id] += 1
    for _node_id, data in graph_obj.nodes(data=True):
        expression = data.get("expr_obj")
        if not isinstance(expression, ast.Call):
            continue
        identity = (data.get("attributes") or {}).get("extraction_identity")
        if identity in {"builtins.tuple", "builtins.len", "builtins.bool"}:
            continue
        for parent, role in data.get("parents") or ():
            if str(role).startswith("arg:") and int(parent) in local_lists:
                unknown.add(int(parent))
    bounds.update({key: count for key, count in local_lists.items() if key not in unknown})
    for mutation in _source_sequence_snapshots(graph_obj):
        source = int(mutation.argument_value_ids[0])
        if source in bounds:
            bounds[int(mutation.sequence_value_id)] = bounds[source]
    return bounds


def _linked_sequence_propagation_kind(
    mapped_arguments: Iterable[Any],
) -> str | None:
    """Return the exact ABI provenance that lets sequence storage escape."""

    accounting = tuple(
        dict(argument.accounting or {}) for argument in mapped_arguments
    )
    if any(item.get("program_abi_parameter") for item in accounting):
        return "program_abi_parameter"
    returned_record_identities = {
        (
            item.get("program_abi_record"),
            item.get("program_abi_keyed_owner")
            or str(item.get("program_abi_field")).split(".", 1)[0],
            item.get("returned_record_storage"),
        )
        for item in accounting
        if item.get("program_abi_record") is not None
        and item.get("program_abi_field") is not None
        and item.get("returned_record_storage") is not None
    }
    if accounting and len(returned_record_identities) == 1:
        return "exact_returned_record_storage"
    return None


def _sequence_append_call_mutations(graph_obj: Any):
    """Recover authored resident ``append/add/clear`` calls as lexical effects."""

    from .control_source import ControlExpression, ControlSequenceMutation
    from .string_table import string_token

    def retained_argument_expressions(
        record: Mapping[str, Any],
    ) -> tuple[Any, ...]:
        expression = record.get("expression")
        if not isinstance(expression, ast.Call) or len(expression.args) != 1:
            return ()
        argument = expression.args[0]
        if not isinstance(argument, ast.Constant) or not isinstance(
            argument.value, (str, bool, int, float)
        ):
            return ()
        literal = (
            string_token(argument.value)
            if isinstance(argument.value, str)
            else argument.value
        )
        # Structural folding may remove the literal's graph node after this
        # source-effect snapshot. Keep its value on the mutation itself so
        # control lowering emits a local constant rather than inventing an
        # unexplained function formal for the vanished node id.
        return (ControlExpression("const", literal=literal),)

    sequence_kinds = {"list", "set", "bytes", "bytearray"}
    mutations = [
        ControlSequenceMutation(
            sequence_value_id=int(record["sequence_value_id"]),
            operator=str(record["operator"]),
            argument_value_ids=tuple(map(
                int, record["argument_value_ids"]
            )),
            effect_node_id=int(node_id),
            policy=record.get("policy"),
            argument_expressions=retained_argument_expressions(record),
        )
        for node_id, record in sorted(
            (
                graph_obj.graph.get("source_sequence_mutation_records")
                or {}
            ).items(),
            key=lambda item: int(item[0]),
        )
    ]
    mutations.extend(_source_mapping_mutations(graph_obj))
    mutations.extend(_source_sequence_snapshots(graph_obj))
    recorded_effect_ids = {
        int(mutation.effect_node_id) for mutation in mutations
    }
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Attribute)
            and expression.func.attr in {"append", "add", "clear"}
        ):
            continue
        if int(node_id) in recorded_effect_ids:
            continue
        parents = tuple(data.get("parents") or ())
        destination_node = next((
            int(parent) for parent, role in parents
            if str(role) == "operand" and int(parent) in graph_obj
        ), None)
        arguments = tuple(
            int(parent) for parent, role in parents
            if str(role).startswith("arg:") and int(parent) in graph_obj
        )
        arity = 0 if expression.func.attr == "clear" else 1
        if destination_node is None or len(arguments) != arity:
            continue
        destination = graph_obj.nodes[destination_node]
        attributes = destination.get("attributes") or {}
        if attributes.get("aggregate_kind") not in sequence_kinds:
            continue
        mutations.append(ControlSequenceMutation(
            sequence_value_id=int(destination.get(
                "value_id", destination_node
            )),
            operator=str(expression.func.attr),
            argument_value_ids=tuple(int(graph_obj.nodes[argument].get(
                "value_id", argument
            )) for argument in arguments),
            effect_node_id=int(data.get("value_id", node_id)),
            policy=(
                "unique" if attributes.get("aggregate_kind") == "set"
                else "duplicates"
            ),
        ))
    nodes_by_value = {
        int(data.get("value_id", node_id)): data
        for node_id, data in graph_obj.nodes(data=True)
    }
    expanded_mutations = []
    for mutation in mutations:
        arguments: list[int] = []
        for value_id in mutation.argument_value_ids:
            attributes = (
                nodes_by_value.get(int(value_id), {}).get("attributes") or {}
            )
            leaves = tuple(map(
                int, attributes.get("aggregate_leaf_value_ids", ())
            ))
            if attributes.get("aggregate_kind") == "tuple" and leaves:
                arguments.extend(leaves)
            else:
                arguments.append(int(value_id))
        expanded_mutations.append(replace(
            mutation,
            argument_value_ids=tuple(arguments),
            argument_kind=(
                "row" if len(arguments) > 1 and not mutation.argument_kind.startswith("mapping_")
                else mutation.argument_kind
            ),
        ))
    return tuple(expanded_mutations)


def _joined_byte_sequence_ids(
    graph_obj: Any,
    *,
    call_result_kinds: Mapping[int, str],
    declared_sequence_ids: Iterable[int],
    structural_byte_sequence_ids: Iterable[int] = (),
    transformed_call_source_ids: Iterable[int] = (),
) -> tuple[int, ...]:
    """Find resident ``list[bytes]`` identities needing dual ABI views.

    The authored outer list owns an element count, while its eventual empty
    byte join owns a flattened byte stream. Parameters already express these
    as ``row_count``/``join_bytes`` source transforms; this recovers the same
    representation for locals without inspecting Python values.
    """

    declared = set(map(int, declared_sequence_ids))
    node_by_value = {
        int(data.get("value_id", node_id)): data
        for node_id, data in graph_obj.nodes(data=True)
    }
    byte_values = {
        int(value_id)
        for value_id, data in node_by_value.items()
        if str((data.get("attributes") or {}).get("aggregate_kind"))
        in {"bytes", "bytearray"}
    }
    byte_values.update(
        int(value_id)
        for value_id, kind in call_result_kinds.items()
        if str(kind) in {"bytes", "bytearray"}
    )
    byte_values.update(map(int, structural_byte_sequence_ids))
    seeds: set[int] = set(map(int, transformed_call_source_ids))
    for value_id, data in node_by_value.items():
        attributes = data.get("attributes") or {}
        if attributes.get("aggregate_kind") != "list":
            continue
        leaves = tuple(map(
            int, attributes.get("aggregate_leaf_value_ids", ())
        ))
        if not leaves:
            leaves = tuple(
                int(graph_obj.nodes[parent].get("value_id", parent))
                for parent, role in (data.get("parents") or ())
                if str(role).startswith("elts") and parent in graph_obj
            )
        if leaves and all(int(leaf) in byte_values for leaf in leaves):
            seeds.add(int(value_id))
    append_mutations = _sequence_append_call_mutations(graph_obj)
    for mutation in append_mutations:
        if (
            mutation.operator == "append"
            and len(mutation.argument_value_ids) == 1
            and int(mutation.argument_value_ids[0]) in byte_values
        ):
            seeds.add(int(mutation.sequence_value_id))

    if os.environ.get("TURING_DEBUG_JOINED_SEQUENCE"):
        print(
            "DEBUGJOINED "
            f"fn={graph_obj.graph.get('function_name')} "
            f"bytes={tuple(sorted(byte_values))!r} "
            f"seeds={tuple(sorted(seeds))!r} "
            f"mutations={tuple((int(item.sequence_value_id), tuple(map(int, item.argument_value_ids))) for item in append_mutations)!r} "
            f"transformed={tuple((int(value_id), str((node_by_value.get(int(value_id), {}).get('attributes') or {}).get('binding_name')), ast.dump(node_by_value.get(int(value_id), {}).get('expr_obj'), include_attributes=False) if isinstance(node_by_value.get(int(value_id), {}).get('expr_obj'), ast.AST) else None) for value_id in sorted(map(int, transformed_call_source_ids)))!r} "
            f"identities={tuple((str(name), tuple(map(int, history))) for name, history in (graph_obj.graph.get('identity_table') or {}).items() if str(name) in {'types', 'entries'})!r} "
            f"declared={tuple(sorted(declared))!r}",
            file=sys.stderr,
        )

    mutation_destinations = {
        int(item.sequence_value_id) for item in append_mutations
    }
    joined = {
        int(value_id)
        for value_id in seeds
        if (
            int(value_id) in declared
            or int(value_id) in mutation_destinations
            or (
                node_by_value.get(int(value_id), {}).get("attributes") or {}
            ).get("aggregate_kind") == "list"
            or isinstance(
                (
                    (graph_obj.nodes.get(int(value_id), {}).get("attributes")
                     or {}).get(
                        "value",
                        graph_obj.nodes.get(int(value_id), {}).get("constant"),
                    )
                ),
                list,
            )
        )
    }
    for history in (graph_obj.graph.get("identity_table") or {}).values():
        identities = set(map(int, history))
        if identities & seeds:
            joined.update(identities & declared)
    return tuple(sorted(joined))


def _joined_list_literal_mutations(
    graph_obj: Any, joined_sequence_ids: Iterable[int]
) -> tuple[Any, ...]:
    """Materialize each authored list element into its resident dual view."""

    from .control_source import ControlSequenceMutation

    joined = set(map(int, joined_sequence_ids))
    mutations = []
    emitted: set[tuple[int, int, int]] = set()

    def append_mutation(
        sequence_id: int, effect_node_id: int, value_id: int,
    ) -> None:
        key = (int(sequence_id), int(effect_node_id), int(value_id))
        if key in emitted:
            return
        emitted.add(key)
        mutations.append(ControlSequenceMutation(
            sequence_value_id=int(sequence_id),
            operator="append",
            argument_value_ids=(int(value_id),),
            effect_node_id=int(effect_node_id),
            policy="duplicates",
            argument_kind="joined_literal_element",
        ))

    nodes = tuple(graph_obj.nodes(data=True))

    def expression_node(expression: ast.AST) -> tuple[int, int] | None:
        exact = [
            (int(node_id), int(data.get("value_id", node_id)))
            for node_id, data in nodes
            if data.get("expr_obj") is expression
        ]
        if len(exact) == 1:
            return exact[0]
        position = (
            int(getattr(expression, "lineno", -1) or -1),
            int(getattr(expression, "col_offset", -1) or -1),
            int(getattr(expression, "end_lineno", -1) or -1),
            int(getattr(expression, "end_col_offset", -1) or -1),
            type(expression),
        )
        positioned = [
            (int(node_id), int(data.get("value_id", node_id)))
            for node_id, data in nodes
            for candidate in (data.get("expr_obj"),)
            if isinstance(candidate, ast.AST)
            and (
                int(getattr(candidate, "lineno", -2) or -2),
                int(getattr(candidate, "col_offset", -2) or -2),
                int(getattr(candidate, "end_lineno", -2) or -2),
                int(getattr(candidate, "end_col_offset", -2) or -2),
                type(candidate),
            ) == position
        ]
        return positioned[0] if len(positioned) == 1 else None

    for node_id, data in sorted(
        nodes, key=lambda item: int(item[0])
    ):
        sequence_id = int(data.get("value_id", node_id))
        if sequence_id not in joined:
            continue
        expression = data.get("expr_obj")
        if not isinstance(expression, ast.List):
            continue
        elements = sorted(
            [
                (
                int(parent), str(role),
                int(graph_obj.nodes[parent].get("value_id", parent)),
                )
                for parent, role in (data.get("parents") or ())
                if str(role).startswith("elts") and parent in graph_obj
            ],
            key=lambda item: (
                int(item[1].split(":", 1)[1])
                if ":" in item[1] and item[1].split(":", 1)[1].isdigit()
                else item[0]
            ),
        )
        for parent, _role, value_id in elements:
            append_mutation(sequence_id, parent, value_id)

    # The source realizer may specialize an inline dynamic list into an empty
    # structural resident while retaining the authored list only on the Call
    # that consumes it (``_vector([uleb(index)])``). Its elements are still
    # ordinary ProcessGraph nodes. Correlate those exact AST objects/source
    # spans back to their deterministic value identities and initialize the
    # resident before the consuming call.
    for _call_node_id, data in sorted(nodes, key=lambda item: int(item[0])):
        expression = data.get("expr_obj")
        if not isinstance(expression, ast.Call) or not expression.args:
            continue
        literal = expression.args[0]
        if not isinstance(literal, ast.List):
            continue
        sequence_ids = tuple(dict.fromkeys(
            int(graph_obj.nodes[parent].get("value_id", parent))
            for parent, role in (data.get("parents") or ())
            if str(role) == "arg:0" and parent in graph_obj
        ))
        if len(sequence_ids) != 1 or sequence_ids[0] not in joined:
            continue
        for element in literal.elts:
            correlated = expression_node(element)
            if correlated is None:
                continue
            effect_node_id, value_id = correlated
            append_mutation(sequence_ids[0], effect_node_id, value_id)
    return tuple(mutations)


def _dict_literal_mutations(graph_obj: Any) -> tuple[Any, ...]:
    """Materialize authored dynamic dict rows at the literal's source site.

    Compile-time mappings use ``literal_table=`` initialization, but a dict
    whose values are computed SSA results cannot be initialized in the entry
    prelude.  Its AST already provides an exact ordered key/value relation;
    retain each row as an ordinary unique-sequence insertion at its key's
    lexical position inside the literal. Data scheduling separately ensures
    that the corresponding value producer completes first. String keys become
    the repository's content-addressed token, the same representation used by
    dynamic keyed lookups.
    """

    from .control_source import ControlExpression, ControlSequenceMutation
    from .string_table import string_token

    nodes = tuple(graph_obj.nodes(data=True))

    def expression_value(expression: ast.AST) -> tuple[int, int] | None:
        exact = tuple(
            (int(node_id), int(data.get("value_id", node_id)))
            for node_id, data in nodes
            if data.get("expr_obj") is expression
        )
        if len(exact) == 1:
            return exact[0]
        position = (
            int(getattr(expression, "lineno", -1) or -1),
            int(getattr(expression, "col_offset", -1) or -1),
            int(getattr(expression, "end_lineno", -1) or -1),
            int(getattr(expression, "end_col_offset", -1) or -1),
            type(expression),
        )
        positioned = tuple(
            (int(node_id), int(data.get("value_id", node_id)))
            for node_id, data in nodes
            for candidate in (data.get("expr_obj"),)
            if isinstance(candidate, ast.AST)
            and (
                int(getattr(candidate, "lineno", -2) or -2),
                int(getattr(candidate, "col_offset", -2) or -2),
                int(getattr(candidate, "end_lineno", -2) or -2),
                int(getattr(candidate, "end_col_offset", -2) or -2),
                type(candidate),
            ) == position
        )
        return positioned[0] if len(positioned) == 1 else None

    mutations = []
    for node_id, data in sorted(nodes, key=lambda item: int(item[0])):
        expression = data.get("expr_obj")
        attributes = data.get("attributes") or {}
        if (attributes.get("aggregate_kind") == "dict"
                and attributes.get("materialization_kind") == "unrolled_loop"):
            sequence_id = int(data.get("value_id", node_id))
            mutations.append(ControlSequenceMutation(
                sequence_value_id=sequence_id, operator="clear",
                argument_value_ids=(), effect_node_id=int(node_id), policy="unique",
            ))
            for row_id in attributes.get("materialized_value_ids", ()):
                row = graph_obj.nodes.get(int(row_id), {})
                leaves = tuple(int(parent) for parent, role in row.get("parents", ())
                               if role == "elts")
                if len(leaves) != 2:
                    raise ValueError(f"Dictionary row {row_id} must publish one key and value")
                mutations.append(ControlSequenceMutation(
                    sequence_value_id=sequence_id, operator="update",
                    argument_value_ids=tuple(int(graph_obj.nodes[parent].get("value_id", parent)) for parent in leaves),
                    effect_node_id=int(row_id), policy="unique",
                    argument_kind="mapping_items",
                ))
            continue
        if not (
            isinstance(expression, ast.Dict)
            and attributes.get("aggregate_kind") == "dict"
            and len(expression.keys) == len(expression.values)
        ):
            continue
        sequence_id = int(data.get("value_id", node_id))
        key_parents = tuple(
            (int(parent), int(graph_obj.nodes[parent].get("value_id", parent)))
            for parent, role in data.get("parents") or ()
            if str(role).startswith("keys") and parent in graph_obj
        )
        # Each execution of a literal constructs a fresh mapping. Keep one
        # lexical owner even for constant rows and for literals inside loops.
        mutations.append(ControlSequenceMutation(
            sequence_value_id=sequence_id, operator="clear",
            argument_value_ids=(), effect_node_id=int(node_id), policy="unique",
        ))
        value_parents = tuple(
            (int(parent), int(graph_obj.nodes[parent].get("value_id", parent)))
            for parent, role in data.get("parents") or ()
            if str(role).startswith("values") and parent in graph_obj
        )
        for index, (key_expression, value_expression) in enumerate(zip(
            expression.keys, expression.values
        )):
            if key_expression is None:
                continue
            key = (
                key_parents[index]
                if len(key_parents) == len(expression.keys)
                else expression_value(key_expression)
            )
            value = (
                value_parents[index]
                if len(value_parents) == len(expression.values)
                else expression_value(value_expression)
            )
            if key is None or value is None:
                continue
            key_node_id, key_value_id = key
            _value_node_id, value_value_id = value
            key_literal = (
                key_expression.value
                if isinstance(key_expression, ast.Constant)
                else None
            )
            key_expression_ir = None
            if isinstance(key_literal, str):
                key_expression_ir = ControlExpression(
                    "const", value_id=key_value_id,
                    literal=string_token(key_literal),
                )
            elif isinstance(key_literal, (bool, int, float)):
                key_expression_ir = ControlExpression(
                    "const", value_id=key_value_id, literal=key_literal,
                )
            mutations.append(ControlSequenceMutation(
                sequence_value_id=sequence_id,
                operator="update",
                argument_value_ids=(key_value_id, value_value_id),
                # The stored value can name an SSA producer authored much
                # earlier than the literal. Its producer position is not the
                # store's effect position: using it moved the first row ahead
                # of the literal's clear. The key is an exact AST child of
                # this literal and gives every row a stable authored order.
                effect_node_id=key_node_id,
                policy="unique",
                argument_kind="mapping_items",
                argument_expressions=(key_expression_ir, None),
            ))
    return tuple(mutations)


def _graph_control_expression(
    graph_obj: Any, node_id: int, visiting: frozenset[int] = frozenset(),
    *, resident: frozenset[int] = frozenset(),
):
    """Translate a retained scalar predicate from ProcessGraph structure.

    ``resident`` names every value a scheduled region owns.  The shell
    consumes such a value through the region's publication; re-deriving it
    from the node's parents would give one source value a second physical
    definition (and, for a loop-carried update, a stale one).
    """

    from .control_source import ControlExpression

    node_id = int(node_id)
    if node_id in visiting or node_id not in graph_obj:
        return ControlExpression("value", value_id=node_id)
    if node_id in resident:
        return ControlExpression("value", value_id=node_id)
    data = graph_obj.nodes[node_id]
    expression = data.get("expr_obj")
    attributes = data.get("attributes") or {}
    literal = attributes.get("value", data.get("constant"))
    if isinstance(expression, ast.Constant):
        literal = expression.value
        if literal is None:
            return ControlExpression("const", value_id=node_id, literal=None)
    if isinstance(literal, (bool, int, float)) and str(
        data.get("type") or ""
    ).casefold() in {"constant", "const"}:
        return ControlExpression("const", value_id=node_id, literal=literal)
    if attributes.get("aggregate_kind") in {
        "list", "set", "dict", "tuple", "bytes", "bytearray",
    }:
        return ControlExpression(
            "sequence_nonempty",
            (ControlExpression("value", value_id=node_id),),
            value_id=node_id,
            literal=attributes.get("aggregate_kind") in {"set", "dict"},
        )
    parents = tuple(data.get("parents") or ())
    ordered = tuple(
        int(parent)
        for parent, role in sorted(
            parents,
            key=lambda item: (
                int(str(item[1]).split(":")[-1])
                if str(item[1]).split(":")[-1].isdigit() else 0
            ),
        )
        if str(role) not in {"callee", "ops", "operator"}
    )
    if isinstance(expression, ast.BoolOp):
        operator = "and" if isinstance(expression.op, ast.And) else "or"
        operands = tuple(
            _graph_control_expression(
                graph_obj, parent, visiting | {node_id}, resident=resident,
            )
            for parent in ordered
        )
        if operands:
            result = operands[0]
            for operand in operands[1:]:
                result = ControlExpression(
                    operator, (result, operand), value_id=node_id
                )
            return result
    operation = {
        "add": "add", "sub": "sub", "mul": "mul",
        "div": "div", "truediv": "div",
        "less": "lt", "lt": "lt",
        "lessequal": "le", "less_equal": "le", "le": "le",
        "greater": "gt", "gt": "gt",
        "greaterequal": "ge", "greater_equal": "ge", "ge": "ge",
        "equal": "eq", "eq": "eq",
        "notequal": "ne", "not_equal": "ne", "ne": "ne",
        "logical_and": "and", "land": "and",
        "logical_or": "or", "lor": "or",
        "logical_not": "not", "lnot": "not",
        "neg": "neg", "usub": "neg",
        "bitand": "bitand", "bitor": "bitor",
        "bitxor": "bitxor", "shl": "shl", "shr": "shr",
        "invert": "invert",
        "item": "item",
        "float": "float", "int": "int", "bool": "bool",
        "isfinite": "isfinite",
    }.get(str(data.get("op") or data.get("type") or "").casefold())
    if operation is not None:
        arity = 1 if operation in {
            "not", "neg", "invert", "item", "float", "int", "bool",
            "isfinite",
        } else 2
        operands = tuple(
            _graph_control_expression(
                graph_obj, parent, visiting | {node_id}, resident=resident,
            )
            for parent in ordered[:arity]
        )
        if len(operands) == arity:
            return ControlExpression(operation, operands, value_id=node_id)
    return ControlExpression("value", value_id=node_id)


def _region_resident_value_ids(dispatch_subgraphs: Iterable[Any]) -> frozenset[int]:
    """Every graph value a scheduled region actually publishes.

    ``deployment_nodes`` includes shader-local intermediates.  The coordinator
    cannot consume those identities; only ``deployment_outputs`` receive Store
    nodes and cross the region boundary.  Treating ownership as publication
    suppresses control-expression lowering and leaves the unpublished local as
    a fabricated function formal.
    """

    return frozenset(
        int(node_id)
        for subgraph in dispatch_subgraphs
        for node_id in subgraph.G.graph.get("deployment_outputs", ())
    )


def _attach_graph_control_expressions(
    control: Any, graph_obj: Any, *, resident: frozenset[int] = frozenset(),
):
    """Recover structured predicates for every retained conditional."""

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, SequenceBlock, WhileBlock,
    )

    def attach(block):
        if isinstance(block, ConditionalBlock):
            return replace(
                block,
                body=attach(block.body),
                orelse=(None if block.orelse is None else attach(block.orelse)),
                predicate_expression=_graph_control_expression(
                    graph_obj, int(block.predicate_value_id),
                    resident=resident,
                ),
            )
        if isinstance(block, SequenceBlock):
            return replace(
                block, blocks=tuple(attach(item) for item in block.blocks)
            )
        if isinstance(block, LoopBlock):
            return replace(block, body=attach(block.body))
        if isinstance(block, WhileBlock):
            return replace(
                block,
                condition=attach(block.condition),
                body=attach(block.body),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=attach(block.callee))
        return block

    return replace(control, root=attach(control.root))


def _nest_lexical_conditionals_in_loops(
    control: Any, graph: Any, dispatch_subgraphs: Iterable[Any],
):
    """Move a conditional authored inside a retained loop into that loop.

    The control overlay embeds a nested conditional by replacing its region
    span inside the parent.  A conditional that owns no numerical region
    (its arm holds only effects or calls) has no span to replace, so it fell
    to the root sequence after the loop: its predicate then read loop-local
    values in ``while_exit`` and nothing it guarded ran per iteration.  The
    authored span is the identity: a conditional whose source position lies
    inside a retained loop's span belongs in that loop's body, ordered among
    the body's statements by source position.
    """

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, LoopControlBlock,
        SequenceBlock, SequenceMutationBlock, StatementBlock, WhileBlock,
    )

    def node_position(node_id: int) -> tuple[int, int, int]:
        return _authored_node_position(graph.G, int(node_id))

    # Sequence effects and numerical regions share one authored ordering.
    # A region is atomic, so its position is the last authored member it must
    # complete, not the first member that happened to seed it.  Reuse the
    # canonical rule used by scalar-field effects; independently taking the
    # minimum here moved a late mapping store ahead of its mapping clear.
    region_positions = _dispatch_region_completion_positions(
        graph.G, dispatch_subgraphs,
    )

    def block_position(block) -> tuple[int, int, int]:
        if isinstance(block, SequenceMutationBlock):
            return node_position(int(block.mutation.effect_node_id))
        if isinstance(block, StatementBlock) and len(block.lines) == 1:
            line = block.lines[0]
            if line.startswith("__scheduled_region_") and line.endswith("__"):
                return region_positions.get(
                    int(line[len("__scheduled_region_"):-2]),
                    (1 << 30, 0, 0),
                )
            if line.startswith("__plan_callsite_") and line.endswith("__"):
                return node_position(int(line[len("__plan_callsite_"):-2]))
        if isinstance(block, ConditionalBlock) and block.source_node_id is not None:
            return node_position(int(block.source_node_id))
        if isinstance(block, LoopControlBlock) and block.site_node_id is not None:
            return _loop_control_block_position(graph.G, block, node_position)
        if isinstance(block, (LoopBlock, WhileBlock)):
            source_id = getattr(block, "source_loop_node_id", None)
            if source_id is not None:
                return node_position(int(source_id))
        if isinstance(block, CallBlock):
            return node_position(int(block.callsite_id))
        if isinstance(block, SequenceBlock) and block.blocks:
            return min(map(block_position, block.blocks))
        return (1 << 30, 0, 0)

    def loop_span(block) -> tuple[int, int] | None:
        source_id = getattr(block, "source_loop_node_id", None)
        if source_id is None:
            return None
        expression = graph.G.nodes.get(int(source_id), {}).get("expr_obj")
        start = getattr(expression, "lineno", None)
        end = getattr(expression, "end_lineno", None)
        if start is None or end is None:
            return None
        return int(start), int(end)

    spans: list[tuple[int, int, int]] = []  # (start, end, loop source id)

    def collect_loops(block):
        if isinstance(block, (LoopBlock, WhileBlock)):
            span = loop_span(block)
            if span is not None:
                spans.append((span[0], span[1], int(block.source_loop_node_id)))
            collect_loops(block.body)
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                collect_loops(child)
        elif isinstance(block, ConditionalBlock):
            collect_loops(block.body)
            if block.orelse is not None:
                collect_loops(block.orelse)
        elif isinstance(block, CallBlock):
            collect_loops(block.callee)

    collect_loops(control.root)
    if not spans:
        return control

    def innermost_loop(line: int) -> int | None:
        candidates = [
            (end - start, loop_id) for start, end, loop_id in spans
            if start <= line <= end
        ]
        return min(candidates)[1] if candidates else None

    misplaced: list = []

    def strip(block, ancestors: tuple[int, ...]):
        """Remove conditionals that belong in a loop not among ``ancestors``."""

        if isinstance(block, SequenceBlock):
            kept = []
            for child in block.blocks:
                projected = strip(child, ancestors)
                if projected is not None:
                    kept.append(projected)
            return SequenceBlock(tuple(kept))
        if isinstance(block, ConditionalBlock):
            if block.source_node_id is not None:
                owner = innermost_loop(
                    node_position(int(block.source_node_id))[0]
                )
                if owner is not None and owner not in ancestors:
                    misplaced.append((owner, block))
                    return None
            return replace(
                block,
                body=strip(block.body, ancestors),
                orelse=(
                    None if block.orelse is None
                    else strip(block.orelse, ancestors)
                ),
            )
        if isinstance(block, (LoopBlock, WhileBlock)):
            own = getattr(block, "source_loop_node_id", None)
            inner = ancestors if own is None else (*ancestors, int(own))
            return replace(block, body=strip(block.body, inner))
        if isinstance(block, CallBlock):
            return replace(block, callee=strip(block.callee, ancestors))
        return block

    root = strip(control.root, ())
    if not misplaced:
        return control

    def insert_ordered(block, item):
        decorated = [
            (block_position(child), index, child)
            for index, child in enumerate(_flattened_sequence_children(block))
        ]
        decorated.append((block_position(item), len(decorated), item))
        return SequenceBlock(tuple(
            child for _position, _index, child in sorted(
                decorated, key=lambda entry: (entry[0], entry[1])
            )
        ))

    def insert_into_loop(block, loop_id: int, item):
        if isinstance(block, (LoopBlock, WhileBlock)):
            if int(getattr(block, "source_loop_node_id", -1) or -1) == loop_id:
                return replace(block, body=insert_ordered(block.body, item)), True
            body, inserted = insert_into_loop(block.body, loop_id, item)
            return (replace(block, body=body), True) if inserted else (block, False)
        if isinstance(block, SequenceBlock):
            for index, child in enumerate(block.blocks):
                projected, inserted = insert_into_loop(child, loop_id, item)
                if inserted:
                    return replace(block, blocks=(
                        *block.blocks[:index], projected,
                        *block.blocks[index + 1:],
                    )), True
            return block, False
        if isinstance(block, ConditionalBlock):
            body, inserted = insert_into_loop(block.body, loop_id, item)
            if inserted:
                return replace(block, body=body), True
            if block.orelse is not None:
                orelse, inserted = insert_into_loop(block.orelse, loop_id, item)
                if inserted:
                    return replace(block, orelse=orelse), True
            return block, False
        if isinstance(block, CallBlock):
            callee, inserted = insert_into_loop(block.callee, loop_id, item)
            return (replace(block, callee=callee), True) if inserted else (block, False)
        return block, False

    # Outer conditionals first, so an inner one lands inside its parent's
    # already-placed arm by ordinary source ordering.
    for loop_id, block in sorted(
        misplaced,
        key=lambda item: node_position(int(item[1].source_node_id)),
    ):
        root, inserted = insert_into_loop(root, loop_id, block)
        if not inserted:
            raise FortranEmissionError(
                f"conditional {block.source_node_id} is authored inside loop "
                f"{loop_id} but that loop is absent from the control tree"
            )
    return replace(control, root=root)


def _plan_callsite_projection_ids(graph_obj: Any, hierarchy_plan: Any) -> dict[int, tuple[int, ...]]:
    """Every caller-side projection of each planned call's bound results.

    A call result that is a record or tuple has no physical value of its
    own; the caller reads it through ``GetAttr``/``Indexed`` nodes.  Those
    nodes are the values the rest of the caller consumes, so a scheduler
    that orders statements by value dependencies must see them as the
    call's publications.
    """

    from .hierarchical_plan import PlanCall

    if hierarchy_plan is None:
        return {}
    result: dict[int, tuple[int, ...]] = {}
    for item in getattr(hierarchy_plan, "items", ()):
        if not isinstance(item, PlanCall):
            continue
        roots = [
            int(caller_id) for _callee_id, caller_id in item.result_bindings
        ] or [int(value_id) for value_id in item.result_value_ids]
        found: set[int] = set()
        pending = list(roots)
        while pending:
            current = pending.pop()
            if current not in graph_obj:
                continue
            for successor in graph_obj.successors(current):
                data = graph_obj.nodes[successor]
                operation = str(
                    data.get("op") or data.get("type") or ""
                ).casefold()
                if operation not in {"getattr", "indexed"}:
                    continue
                if not any(
                    int(parent) == current
                    and str(role) in {"value", "base", "operand", "object"}
                    for parent, role in data.get("parents") or ()
                ):
                    continue
                value_id = int(data.get("value_id", successor))
                if value_id in found:
                    continue
                found.add(value_id)
                pending.append(int(successor))
        if found:
            result[int(item.callsite_id)] = tuple(sorted(found))
    return result


def _flattened_sequence_children(block) -> tuple:
    """A sequence's children with nested sequences opened up.

    Nested ``SequenceBlock``s are grouping only.  Ordering a sequence by
    source position must see each authored statement on its own: a nested
    group takes the position of its earliest member, and dragged a later
    conditional ahead of the statement producing its predicate.
    """

    from .control_source import SequenceBlock

    if not isinstance(block, SequenceBlock):
        return (block,)
    flat = []
    for child in block.blocks:
        flat.extend(_flattened_sequence_children(child))
    return tuple(flat)


def _loop_control_block_position(
    graph_obj: Any, block: Any, node_position: Any,
) -> tuple[int, int, int]:
    """Lexical position of a ``LoopControlBlock`` for source-ordered placement.

    A ``break``/``continue`` sits at its statement.  A ``return`` is anchored
    at its returned expression -- for ``return a, f(x), g(y)`` that is the
    Tuple, whose source position is the START of the expression (the opening
    column), i.e. BEFORE every call written inside it.  Sorting the edge by
    that start put it ahead of the ``__plan_callsite_N__`` markers for
    ``f(x)`` and ``g(y)``, so the edge consumed values produced after it and
    the SSA scheduler refused with ``control effect order conflicts with
    value dependencies`` (step_with_dt_control_used's in-loop ``return
    metrics, _restore_type(dt_next, ref), _restore_type(dt_tensor, ref)``).
    A return executes once its expression is fully evaluated, so its position
    is the END of that expression: the latest end coordinate over the site
    and the exact slot values the edge carries (``return_value_ids``), which
    every call inside the expression precedes.
    """

    site_id = int(block.site_node_id)
    candidates = [node_position(site_id)]
    if block.action != "return":
        return candidates[0]
    for value_id in (site_id, *(
        int(value_id) for value_id in block.return_value_ids
        if value_id is not None
    )):
        if value_id not in graph_obj:
            continue
        expression = graph_obj.nodes[value_id].get("expr_obj")
        end_line = getattr(expression, "end_lineno", None)
        if end_line is None:
            continue
        candidates.append((
            int(end_line),
            int(getattr(expression, "end_col_offset", 0) or 0),
            site_id,
        ))
    return max(candidates)


def _authored_node_position(graph_obj: Any, node_id: int) -> tuple[int, int, int]:
    """Source position of a graph node, or of the control record it left.

    A conditional whose ``If`` node the structural fold removed still exists
    as a control block naming that node; its authored position is retained
    in the graph's source control records.  Without this fallback such a
    block had no position, so no lexical placement could order it, and it
    was lowered ahead of its predicate's producer.
    """

    data = graph_obj.nodes.get(int(node_id)) if int(node_id) in graph_obj else None
    expression = None if data is None else data.get("expr_obj")
    if isinstance(expression, ast.comprehension):
        # comprehension is a control AST node without its own location;
        # its authored target still places the producer before its consumers.
        expression = expression.target
    span = {} if data is None else (data.get("source_span") or {})
    if data is None or (
        getattr(expression, "lineno", None) is None and not span.get("line")
    ):
        from .glsl_deployment_strategy import _source_control_records
        record = _source_control_records(graph_obj).get(int(node_id))
        recorded = None if record is None else record.get("expression")
        if getattr(recorded, "lineno", None) is not None:
            return (
                int(recorded.lineno),
                int(getattr(recorded, "col_offset", 0) or 0),
                int(node_id),
            )
    return (
        int(getattr(expression, "lineno", span.get("line", 1 << 30)) or (1 << 30)),
        int(getattr(expression, "col_offset", span.get("column", 0)) or 0),
        int(node_id),
    )


def _dispatch_region_completion_positions(
    graph_obj: Any,
    dispatch_subgraphs: Iterable[Any],
) -> dict[int, tuple[int, int, int]]:
    """Place each atomic region where its last authored member completes."""

    return {
        index: max(
            (
                _authored_node_position(graph_obj, int(node_id))
                for node_id in subgraph.G.graph.get("deployment_nodes", ())
            ),
            default=(1 << 30, 0, index),
        )
        for index, subgraph in enumerate(dispatch_subgraphs)
    }


def _insert_lexically(root, graph: Any, dispatch_subgraphs: Iterable[Any], item, node_id: int):
    """Insert ``item`` at the authored position of graph node ``node_id``.

    Innermost conditional arm that owns the node (branch compartments), else
    the innermost retained loop whose span contains it, else the root
    sequence; within the chosen sequence, ordered by source position.
    """

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, LoopControlBlock,
        ScalarFieldWriteBlock, SequenceBlock, SequenceMutationBlock, SequenceQueryBlock,
        StatementBlock, WhileBlock,
    )
    from .glsl_deployment_strategy import _branch_compartments

    def node_position(candidate: int) -> tuple[int, int, int]:
        return _authored_node_position(graph.G, int(candidate))

    region_positions = {
        int(index): min(
            (
                node_position(int(member))
                for member in subgraph.G.graph.get("deployment_nodes", ())
            ),
            default=(1 << 30, 0, int(index)),
        )
        for index, subgraph in enumerate(dispatch_subgraphs)
    }

    def block_position(block) -> tuple[int, int, int]:
        if isinstance(block, ScalarFieldWriteBlock):
            return node_position(int(block.effect_node_id))
        if isinstance(block, SequenceMutationBlock):
            return node_position(int(block.mutation.effect_node_id))
        if isinstance(block, SequenceQueryBlock) and block.source_call_node_id is not None:
            return node_position(int(block.source_call_node_id))
        if isinstance(block, StatementBlock) and len(block.lines) == 1:
            line = block.lines[0]
            if line.startswith("__scheduled_region_") and line.endswith("__"):
                return region_positions.get(
                    int(line[len("__scheduled_region_"):-2]),
                    (1 << 30, 0, 0),
                )
            if line.startswith("__plan_callsite_") and line.endswith("__"):
                return node_position(int(line[len("__plan_callsite_"):-2]))
        if isinstance(block, ConditionalBlock) and block.source_node_id is not None:
            return node_position(int(block.source_node_id))
        if isinstance(block, LoopControlBlock) and block.site_node_id is not None:
            return _loop_control_block_position(graph.G, block, node_position)
        if isinstance(block, (LoopBlock, WhileBlock)):
            source_id = getattr(block, "source_loop_node_id", None)
            if source_id is not None:
                return node_position(int(source_id))
        if isinstance(block, CallBlock):
            return node_position(int(block.callsite_id))
        if isinstance(block, SequenceBlock) and block.blocks:
            return min(map(block_position, block.blocks))
        return (1 << 30, 0, 0)

    def insert_ordered(block, candidate):
        decorated = [
            (block_position(child), index, child)
            for index, child in enumerate(_flattened_sequence_children(block))
        ]
        decorated.append((block_position(candidate), len(decorated), candidate))
        return SequenceBlock(tuple(
            child for _position, _index, child in sorted(
                decorated, key=lambda entry: (entry[0], entry[1])
            )
        ))

    present: set[int] = set()
    loop_spans: list[tuple[int, int, int]] = []

    def survey(block):
        if isinstance(block, ConditionalBlock):
            if block.source_node_id is not None:
                present.add(int(block.source_node_id))
            survey(block.body)
            if block.orelse is not None:
                survey(block.orelse)
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                survey(child)
        elif isinstance(block, (LoopBlock, WhileBlock)):
            source_id = getattr(block, "source_loop_node_id", None)
            if source_id is not None:
                expression = graph.G.nodes.get(int(source_id), {}).get("expr_obj")
                start = getattr(expression, "lineno", None)
                end = getattr(expression, "end_lineno", None)
                if start is not None and end is not None:
                    loop_spans.append((int(start), int(end), int(source_id)))
            survey(block.body)
        elif isinstance(block, CallBlock):
            survey(block.callee)

    survey(root)

    def insert_in_conditional(block, owner_id, arm):
        if isinstance(block, ConditionalBlock):
            if int(block.source_node_id or -1) == int(owner_id):
                if str(arm) == "body":
                    return replace(block, body=insert_ordered(block.body, item)), True
                return replace(
                    block,
                    orelse=insert_ordered(block.orelse or SequenceBlock(()), item),
                ), True
            body, inserted = insert_in_conditional(block.body, owner_id, arm)
            if inserted:
                return replace(block, body=body), True
            if block.orelse is not None:
                orelse, inserted = insert_in_conditional(block.orelse, owner_id, arm)
                if inserted:
                    return replace(block, orelse=orelse), True
            return block, False
        if isinstance(block, SequenceBlock):
            children = []
            inserted = False
            for child in block.blocks:
                projected, child_inserted = (
                    insert_in_conditional(child, owner_id, arm)
                    if not inserted else (child, False)
                )
                children.append(projected)
                inserted |= child_inserted
            return SequenceBlock(tuple(children)), inserted
        if isinstance(block, (LoopBlock, WhileBlock)):
            body, inserted = insert_in_conditional(block.body, owner_id, arm)
            return replace(block, body=body), inserted
        if isinstance(block, CallBlock):
            callee, inserted = insert_in_conditional(block.callee, owner_id, arm)
            return replace(block, callee=callee), inserted
        return block, False

    def insert_into_loop(block, loop_id: int):
        if isinstance(block, (LoopBlock, WhileBlock)):
            if int(getattr(block, "source_loop_node_id", -1) or -1) == loop_id:
                return replace(block, body=insert_ordered(block.body, item)), True
            body, inserted = insert_into_loop(block.body, loop_id)
            return (replace(block, body=body), True) if inserted else (block, False)
        if isinstance(block, SequenceBlock):
            for index, child in enumerate(block.blocks):
                projected, inserted = insert_into_loop(child, loop_id)
                if inserted:
                    return replace(block, blocks=(
                        *block.blocks[:index], projected, *block.blocks[index + 1:],
                    )), True
            return block, False
        if isinstance(block, ConditionalBlock):
            body, inserted = insert_into_loop(block.body, loop_id)
            if inserted:
                return replace(block, body=body), True
            if block.orelse is not None:
                orelse, inserted = insert_into_loop(block.orelse, loop_id)
                if inserted:
                    return replace(block, orelse=orelse), True
            return block, False
        if isinstance(block, CallBlock):
            callee, inserted = insert_into_loop(block.callee, loop_id)
            return (replace(block, callee=callee), True) if inserted else (block, False)
        return block, False

    memberships = _branch_compartments(graph)
    guards = [
        (int(owner), str(arm))
        for owner, arm in memberships.get(int(node_id), ())
        if str(arm) in {"body", "orelse"} and int(owner) in present
    ]
    if guards:
        owner, arm = max(guards, key=lambda entry: node_position(entry[0]))
        root, inserted = insert_in_conditional(root, owner, arm)
        if inserted:
            return root, True
    line = node_position(int(node_id))[0]
    candidates = [
        (end - start, loop_id) for start, end, loop_id in loop_spans
        if start <= line <= end
    ]
    if candidates:
        root, inserted = insert_into_loop(root, min(candidates)[1])
        if inserted:
            return root, True
    return insert_ordered(root, item), True


def _place_plan_callsites_lexically(
    control: Any, graph: Any, hierarchy_plan: Any, dispatch_subgraphs: Iterable[Any],
):
    """Insert every planned callsite marker at its authored position.

    The callsite scheduler placed a pending call before the next retained
    region in hierarchy order.  When intervening control (a ``for`` loop
    that consumes the call's results) sits between the call and that region,
    the marker landed after that control: ``advance`` was emitted in the
    exit block of the loop over ``targets.error_limits`` that reads the
    metrics it publishes.  The authored position is the identity: the
    marker goes into the innermost conditional arm that owns the call, else
    the innermost loop whose span contains it, ordered by source position.
    The scheduler treats a marker already present as placed.
    """

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, LoopControlBlock,
        SequenceBlock, SequenceMutationBlock, StatementBlock, WhileBlock,
    )
    from .glsl_deployment_strategy import _branch_compartments
    from .hierarchical_plan import PlanCall

    if hierarchy_plan is None:
        return control
    planned_calls = {
        int(item.callsite_id): item
        for item in getattr(hierarchy_plan, "items", ())
        if isinstance(item, PlanCall)
    }
    callsite_ids = list(planned_calls)
    if not callsite_ids:
        return control

    def node_position(node_id: int) -> tuple[int, int, int]:
        return _authored_node_position(graph.G, int(node_id))

    region_positions = {
        int(index): min(
            (
                node_position(int(node_id))
                for node_id in subgraph.G.graph.get("deployment_nodes", ())
            ),
            default=(1 << 30, 0, int(index)),
        )
        for index, subgraph in enumerate(dispatch_subgraphs)
    }

    def block_position(block) -> tuple[int, int, int]:
        if isinstance(block, SequenceMutationBlock):
            return node_position(int(block.mutation.effect_node_id))
        if isinstance(block, StatementBlock) and len(block.lines) == 1:
            line = block.lines[0]
            if line.startswith("__scheduled_region_") and line.endswith("__"):
                return region_positions.get(
                    int(line[len("__scheduled_region_"):-2]),
                    (1 << 30, 0, 0),
                )
            if line.startswith("__plan_callsite_") and line.endswith("__"):
                return node_position(int(line[len("__plan_callsite_"):-2]))
        if isinstance(block, ConditionalBlock) and block.source_node_id is not None:
            return node_position(int(block.source_node_id))
        if isinstance(block, LoopControlBlock) and block.site_node_id is not None:
            return _loop_control_block_position(graph.G, block, node_position)
        if isinstance(block, (LoopBlock, WhileBlock)):
            source_id = getattr(block, "source_loop_node_id", None)
            if source_id is not None:
                return node_position(int(source_id))
        if isinstance(block, CallBlock):
            return node_position(int(block.callsite_id))
        if isinstance(block, SequenceBlock) and block.blocks:
            return min(map(block_position, block.blocks))
        return (1 << 30, 0, 0)

    def insert_ordered(block, item):
        decorated = [
            (block_position(child), index, child)
            for index, child in enumerate(_flattened_sequence_children(block))
        ]
        decorated.append((block_position(item), len(decorated), item))
        return SequenceBlock(tuple(
            child for _position, _index, child in sorted(
                # A return anchored at its result call has the same source
                # position as that call. Evaluate the value before taking
                # the terminal edge, even when the edge was inserted first.
                decorated, key=lambda entry: (
                    entry[0], isinstance(entry[2], LoopControlBlock), entry[1]
                )
            )
        ))

    present: set[int] = set()
    present_loops: set[int] = set()
    loop_spans: list[tuple[int, int, int]] = []

    def survey(block):
        if isinstance(block, ConditionalBlock):
            if block.source_node_id is not None:
                present.add(int(block.source_node_id))
            survey(block.body)
            if block.orelse is not None:
                survey(block.orelse)
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                survey(child)
        elif isinstance(block, (LoopBlock, WhileBlock)):
            source_id = getattr(block, "source_loop_node_id", None)
            if source_id is not None:
                present_loops.add(int(source_id))
                expression = graph.G.nodes.get(int(source_id), {}).get("expr_obj")
                start = getattr(expression, "lineno", None)
                end = getattr(expression, "end_lineno", None)
                if start is not None and end is not None:
                    loop_spans.append((int(start), int(end), int(source_id)))
            survey(block.body)
        elif isinstance(block, CallBlock):
            survey(block.callee)

    survey(control.root)

    def insert_in_conditional(block, owner_id, arm, item):
        if isinstance(block, ConditionalBlock):
            if int(block.source_node_id or -1) == int(owner_id):
                if str(arm) == "body":
                    return replace(block, body=insert_ordered(block.body, item)), True
                return replace(
                    block,
                    orelse=insert_ordered(block.orelse or SequenceBlock(()), item),
                ), True
            body, inserted = insert_in_conditional(block.body, owner_id, arm, item)
            if inserted:
                return replace(block, body=body), True
            if block.orelse is not None:
                orelse, inserted = insert_in_conditional(
                    block.orelse, owner_id, arm, item
                )
                if inserted:
                    return replace(block, orelse=orelse), True
            return block, False
        if isinstance(block, SequenceBlock):
            children = []
            inserted = False
            for child in block.blocks:
                projected, child_inserted = (
                    insert_in_conditional(child, owner_id, arm, item)
                    if not inserted else (child, False)
                )
                children.append(projected)
                inserted |= child_inserted
            return SequenceBlock(tuple(children)), inserted
        if isinstance(block, (LoopBlock, WhileBlock)):
            body, inserted = insert_in_conditional(block.body, owner_id, arm, item)
            return replace(block, body=body), inserted
        if isinstance(block, CallBlock):
            callee, inserted = insert_in_conditional(block.callee, owner_id, arm, item)
            return replace(block, callee=callee), inserted
        return block, False

    def insert_into_loop(block, loop_id: int, item):
        if isinstance(block, (LoopBlock, WhileBlock)):
            source_loop_id = getattr(block, "source_loop_node_id", None)
            if (
                source_loop_id is not None
                and int(source_loop_id) == int(loop_id)
            ):
                return replace(block, body=insert_ordered(block.body, item)), True
            body, inserted = insert_into_loop(block.body, loop_id, item)
            return (replace(block, body=body), True) if inserted else (block, False)
        if isinstance(block, SequenceBlock):
            for index, child in enumerate(block.blocks):
                projected, inserted = insert_into_loop(child, loop_id, item)
                if inserted:
                    return replace(block, blocks=(
                        *block.blocks[:index], projected,
                        *block.blocks[index + 1:],
                    )), True
            return block, False
        if isinstance(block, ConditionalBlock):
            body, inserted = insert_into_loop(block.body, loop_id, item)
            if inserted:
                return replace(block, body=body), True
            if block.orelse is not None:
                orelse, inserted = insert_into_loop(block.orelse, loop_id, item)
                if inserted:
                    return replace(block, orelse=orelse), True
            return block, False
        if isinstance(block, CallBlock):
            callee, inserted = insert_into_loop(block.callee, loop_id, item)
            return (replace(block, callee=callee), True) if inserted else (block, False)
        return block, False

    memberships = _branch_compartments(graph)
    root = control.root
    for callsite_id in sorted(callsite_ids, key=node_position):
        if int(callsite_id) not in graph.G:
            continue
        marker = StatementBlock((f"__plan_callsite_{int(callsite_id)}__",))
        guards = [
            (int(owner), str(arm))
            for owner, arm in memberships.get(int(callsite_id), ())
            if str(arm) in {"body", "orelse"} and int(owner) in present
        ]
        inserted = False
        if guards:
            owner, arm = max(guards, key=lambda item: node_position(item[0]))
            root, inserted = insert_in_conditional(root, owner, arm, marker)
        if not inserted:
            # PlanCall carries the exact lexical loop ancestry.  Prefer it to
            # source spans: comprehension AST nodes commonly have no usable
            # span in persisted graphs, which previously hoisted their calls
            # to function entry before loop-target projections existed.
            planned_loop_id = next((
                int(loop_id)
                for loop_id in reversed(
                    planned_calls[int(callsite_id)].enclosing_loop_ids
                )
                if int(loop_id) in present_loops
            ), None)
            if planned_loop_id is not None:
                root, inserted = insert_into_loop(
                    root, planned_loop_id, marker
                )
        if not inserted:
            line = node_position(int(callsite_id))[0]
            candidates = [
                (end - start, loop_id) for start, end, loop_id in loop_spans
                if start <= line <= end
            ]
            if candidates:
                root, inserted = insert_into_loop(root, min(candidates)[1], marker)
        if not inserted:
            root = insert_ordered(root, marker)
    return replace(control, root=root)


def _stamp_conditional_callsite_ownership(
    control: Any, graph: Any, hierarchy_plan: Any,
):
    """Record, on each retained conditional, the planned calls its arms own.

    Conditionals overlaid on numerical regions already carry
    ``body_callsite_ids``/``orelse_callsite_ids`` from the planner.  A
    conditional inside a retained loop body is built by the loop composer
    and carries none, so the callsite scheduler treated a call authored in
    its arm as a trailing call of the loop and appended its marker after the
    body's terminal edge, in unreachable code.  The graph's branch
    compartments are the exact authored ownership; stamp the innermost
    conditional present in the tree with each such callsite.
    """

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, SequenceBlock, WhileBlock,
    )
    from .glsl_deployment_strategy import _branch_compartments
    from .hierarchical_plan import PlanCall

    if hierarchy_plan is None:
        return control
    callsite_ids = {
        int(item.callsite_id)
        for item in getattr(hierarchy_plan, "items", ())
        if isinstance(item, PlanCall)
    }
    if not callsite_ids:
        return control

    present: set[int] = set()

    def collect(block):
        if isinstance(block, ConditionalBlock):
            if block.source_node_id is not None:
                present.add(int(block.source_node_id))
            collect(block.body)
            if block.orelse is not None:
                collect(block.orelse)
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                collect(child)
        elif isinstance(block, (LoopBlock, WhileBlock)):
            collect(block.body)
        elif isinstance(block, CallBlock):
            collect(block.callee)

    collect(control.root)
    if not present:
        return control

    def node_position(node_id: int) -> tuple[int, int, int]:
        return _authored_node_position(graph.G, int(node_id))

    memberships = _branch_compartments(graph)
    owned: dict[tuple[int, str], set[int]] = {}
    for callsite_id in callsite_ids:
        guards = [
            (int(owner), str(arm))
            for owner, arm in memberships.get(int(callsite_id), ())
            if str(arm) in {"body", "orelse"} and int(owner) in present
        ]
        if not guards:
            continue
        # The innermost owner starts last in source order.
        owner, arm = max(guards, key=lambda item: node_position(item[0]))
        owned.setdefault((owner, arm), set()).add(int(callsite_id))
    if not owned:
        return control

    def stamp(block):
        if isinstance(block, ConditionalBlock):
            body = stamp(block.body)
            orelse = None if block.orelse is None else stamp(block.orelse)
            if block.source_node_id is None:
                return replace(block, body=body, orelse=orelse)
            source = int(block.source_node_id)
            return replace(
                block, body=body, orelse=orelse,
                body_callsite_ids=tuple(sorted({
                    *map(int, block.body_callsite_ids),
                    *owned.get((source, "body"), ()),
                })),
                orelse_callsite_ids=tuple(sorted({
                    *map(int, block.orelse_callsite_ids),
                    *owned.get((source, "orelse"), ()),
                })),
            )
        if isinstance(block, SequenceBlock):
            return replace(
                block, blocks=tuple(stamp(child) for child in block.blocks)
            )
        if isinstance(block, (LoopBlock, WhileBlock)):
            return replace(block, body=stamp(block.body))
        if isinstance(block, CallBlock):
            return replace(block, callee=stamp(block.callee))
        return block

    return replace(control, root=stamp(control.root))


def _consume_resident_control_values(control: Any, resident: frozenset[int]):
    """Consume every region-owned value a control expression names.

    Control expressions are composed in two places: the loop composer builds
    return/break guards, while predicates and mutation guards before regions
    are carved, and the shell recovers conditional predicates afterwards
    (``_graph_control_expression``).  Both re-derive a scalar from its graph
    parents.  Once a scheduled region owns that node, the region is its one
    physical producer: the shell consumes the publication.  Re-deriving it
    would define the same source value twice, and for a loop-carried update
    the shell's copy would read the pre-update Phi.

    A subtree rooted at a resident value becomes ``value``.  A predicate whose
    root is itself resident and equal to the block's predicate id keeps no
    expression at all; for a while loop this is the designed path, where the
    condition region publishes the latch predicate.
    """

    from .control_source import (
        CallBlock, ConditionalBlock, ControlExpression, ControlSequenceMutation,
        LoopBlock, LoopControlBlock, ParallelDeployment, ResourceScopeBlock,
        SequenceBlock, SequenceMutationBlock, StateMachineTick,
        ValidationBlock, WhileBlock,
    )

    if not resident:
        return control

    def expression(item):
        if item is None:
            return None
        if (
            item.op not in {"value", "const", "sequence_nonempty"}
            and item.value_id is not None
            and int(item.value_id) in resident
        ):
            return ControlExpression("value", value_id=int(item.value_id))
        operands = tuple(expression(operand) for operand in item.operands)
        if all(a is b for a, b in zip(operands, item.operands)):
            return item
        return replace(item, operands=operands)

    def predicate(item, predicate_value_id):
        rewritten = expression(item)
        if (
            rewritten is not None
            and rewritten.op == "value"
            and predicate_value_id is not None
            and rewritten.value_id is not None
            and int(rewritten.value_id) == int(predicate_value_id)
            and int(predicate_value_id) in resident
        ):
            return None
        return rewritten

    def mutation(item: ControlSequenceMutation) -> ControlSequenceMutation:
        return replace(
            item,
            predicate_expression=expression(item.predicate_expression),
            argument_expressions=tuple(
                expression(argument) for argument in item.argument_expressions
            ),
        )

    def visit(block):
        if isinstance(block, SequenceBlock):
            return replace(block, blocks=tuple(visit(child) for child in block.blocks))
        if isinstance(block, ConditionalBlock):
            return replace(
                block,
                body=visit(block.body),
                orelse=None if block.orelse is None else visit(block.orelse),
                predicate_expression=predicate(
                    block.predicate_expression, block.predicate_value_id
                ),
            )
        if isinstance(block, LoopControlBlock):
            return replace(
                block,
                predicate_expression=predicate(
                    block.predicate_expression, block.predicate_value_id
                ),
            )
        if isinstance(block, ValidationBlock):
            return replace(
                block,
                predicate_expression=predicate(
                    block.predicate_expression, block.predicate_value_id
                ),
            )
        if isinstance(block, WhileBlock):
            return replace(
                block,
                condition=visit(block.condition),
                body=visit(block.body),
                predicate_expression=predicate(
                    block.predicate_expression, block.predicate_value_id
                ),
                sequence_mutations=tuple(map(mutation, block.sequence_mutations)),
                terminal_controls=tuple(map(visit, block.terminal_controls)),
            )
        if isinstance(block, LoopBlock):
            return replace(
                block,
                body=visit(block.body),
                sequence_mutations=tuple(map(mutation, block.sequence_mutations)),
            )
        if isinstance(block, SequenceMutationBlock):
            return replace(block, mutation=mutation(block.mutation))
        if isinstance(block, StateMachineTick):
            return replace(
                block,
                cases=tuple((value, visit(body)) for value, body in block.cases),
                default=None if block.default is None else visit(block.default),
            )
        if isinstance(block, ParallelDeployment):
            return replace(block, lanes=tuple(map(visit, block.lanes)))
        if isinstance(block, CallBlock):
            return replace(block, callee=visit(block.callee))
        if isinstance(block, ResourceScopeBlock):
            return replace(block, body=visit(block.body))
        return block

    return replace(control, root=visit(control.root))


def _install_lexical_sequence_mutations(
    control: Any,
    graph: Any,
    dispatch_subgraphs: Iterable[Any],
    *,
    extra_mutations: Iterable[Any] = (),
    scalar_writes: Iterable[Any] = (),
):
    """Place non-loop sequence effects into their authored control scope."""

    from .control_source import (
        CallBlock,
        ConditionalBlock,
        ControlExpression,
        LoopBlock,
        LoopControlBlock,
        SequenceBlock,
        SequenceMutationBlock,
        ScalarFieldWriteBlock,
        StatementBlock,
        WhileBlock,
    )
    from .glsl_deployment_strategy import (
        _branch_compartments,
        _retained_control_value_id,
        _source_control_records,
    )

    mutations = tuple((
        *_sequence_append_call_mutations(graph.G),
        *tuple(extra_mutations),
        *tuple(scalar_writes),
    ))
    if not mutations:
        return control, ()

    memberships = _branch_compartments(graph)

    def enclosing_loop_span(loop_block) -> tuple[int, int] | None:
        source_id = getattr(loop_block, "source_loop_node_id", None)
        if source_id is None:
            return None
        expression = graph.G.nodes.get(int(source_id), {}).get("expr_obj")
        start = getattr(expression, "lineno", None)
        end = getattr(expression, "end_lineno", None)
        if start is None or end is None:
            return None
        return int(start), int(end)

    def insert_in_enclosing_loop(block, item_block, node_id: int):
        """Insert ``item_block`` ordered by position inside the innermost loop
        whose authored span contains ``node_id``; at this level otherwise.

        A guard synthesized for an effect authored inside a loop body used to
        be ordered among the ROOT statements, which put it after the loop:
        the effect never ran and its predicate read loop-local values in
        ``while_exit``.
        """

        line = node_position(int(node_id))[0]

        def descend(candidate):
            if isinstance(candidate, SequenceBlock):
                for index, child in enumerate(candidate.blocks):
                    replaced, inserted = descend(child)
                    if inserted:
                        return replace(
                            candidate,
                            blocks=(*candidate.blocks[:index], replaced,
                                    *candidate.blocks[index + 1:]),
                        ), True
                return candidate, False
            if isinstance(candidate, ConditionalBlock):
                body, inserted = descend(candidate.body)
                if inserted:
                    return replace(candidate, body=body), True
                if candidate.orelse is not None:
                    orelse, inserted = descend(candidate.orelse)
                    if inserted:
                        return replace(candidate, orelse=orelse), True
                return candidate, False
            if isinstance(candidate, CallBlock):
                callee, inserted = descend(candidate.callee)
                return (replace(candidate, callee=callee), True) if inserted else (candidate, False)
            if isinstance(candidate, (LoopBlock, WhileBlock)):
                span = enclosing_loop_span(candidate)
                if span is None or not (span[0] <= line <= span[1]):
                    return candidate, False
                body, inserted = descend(candidate.body)
                if not inserted:
                    body = insert_ordered(candidate.body, item_block)
                return replace(candidate, body=body), True
            return candidate, False

        replaced, inserted = descend(block)
        if inserted:
            return replaced
        return insert_ordered(block, item_block)

    existing_effect_ids: set[int] = set()

    def gather(block):
        if isinstance(block, ScalarFieldWriteBlock):
            existing_effect_ids.add(int(block.effect_node_id))
        elif isinstance(block, SequenceMutationBlock):
            existing_effect_ids.add(int(block.mutation.effect_node_id))
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                gather(child)
        elif isinstance(block, ConditionalBlock):
            gather(block.body)
            if block.orelse is not None:
                gather(block.orelse)
        elif isinstance(block, (LoopBlock, WhileBlock)):
            existing_effect_ids.update(
                int(item.effect_node_id) for item in block.sequence_mutations
            )
            if isinstance(block, WhileBlock):
                gather(block.condition)
            gather(block.body)
        elif isinstance(block, CallBlock):
            gather(block.callee)

    gather(control.root)
    mutations = tuple(
        item for item in mutations
        if int(item.effect_node_id) not in existing_effect_ids
    )

    def node_position(node_id: int) -> tuple[int, int, int]:
        return _authored_node_position(graph.G, int(node_id))

    region_positions = {
        int(index): min(
            (
                node_position(int(node_id))
                for node_id in subgraph.G.graph.get("deployment_nodes", ())
            ),
            default=(1 << 30, 0, int(index)),
        )
        for index, subgraph in enumerate(dispatch_subgraphs)
    }

    def block_position(block) -> tuple[int, int, int]:
        if isinstance(block, ScalarFieldWriteBlock):
            return node_position(int(block.effect_node_id))
        if isinstance(block, SequenceMutationBlock):
            return node_position(int(block.mutation.effect_node_id))
        if isinstance(block, StatementBlock) and len(block.lines) == 1:
            line = block.lines[0]
            if line.startswith("__scheduled_region_") and line.endswith("__"):
                return region_positions.get(
                    int(line[len("__scheduled_region_"):-2]),
                    (1 << 30, 0, 0),
                )
            if line.startswith("__plan_callsite_") and line.endswith("__"):
                return node_position(int(line[len("__plan_callsite_"):-2]))
        if isinstance(block, ConditionalBlock) and block.source_node_id is not None:
            return node_position(int(block.source_node_id))
        if isinstance(block, LoopControlBlock) and block.site_node_id is not None:
            return _loop_control_block_position(graph.G, block, node_position)
        if isinstance(block, (LoopBlock, WhileBlock)):
            source_id = getattr(block, "source_loop_node_id", None)
            if source_id is not None:
                return node_position(int(source_id))
        if isinstance(block, CallBlock):
            return node_position(int(block.callsite_id))
        if isinstance(block, SequenceBlock) and block.blocks:
            return min(map(block_position, block.blocks))
        return (1 << 30, 0, 0)

    def insert_ordered(block, mutation_block):
        decorated = [
            (block_position(child), index, child)
            for index, child in enumerate(_flattened_sequence_children(block))
        ]
        decorated.append((
            block_position(mutation_block), len(decorated), mutation_block,
        ))
        return SequenceBlock(tuple(
            child for _position, _index, child in sorted(
                decorated, key=lambda item: (item[0], item[1])
            )
        ))

    retained_mutation_records = (
        graph.G.graph.get("source_sequence_mutation_records") or {}
    )

    def insert_in_conditional(block, owner_id, arm, mutation_block):
        if isinstance(block, ConditionalBlock):
            if int(block.source_node_id or -1) == int(owner_id):
                if str(arm) == "body":
                    return replace(
                        block,
                        body=insert_ordered(block.body, mutation_block),
                    ), True
                return replace(
                    block,
                    orelse=insert_ordered(
                        block.orelse or SequenceBlock(()), mutation_block,
                    ),
                ), True
            body, inserted = insert_in_conditional(
                block.body, owner_id, arm, mutation_block
            )
            if inserted:
                return replace(block, body=body), True
            if block.orelse is not None:
                orelse, inserted = insert_in_conditional(
                    block.orelse, owner_id, arm, mutation_block
                )
                if inserted:
                    return replace(block, orelse=orelse), True
            return block, False
        if isinstance(block, SequenceBlock):
            children = []
            inserted = False
            for child in block.blocks:
                projected, child_inserted = insert_in_conditional(
                    child, owner_id, arm, mutation_block
                )
                children.append(projected)
                inserted |= child_inserted
            return SequenceBlock(tuple(children)), inserted
        if isinstance(block, LoopBlock):
            body, inserted = insert_in_conditional(
                block.body, owner_id, arm, mutation_block
            )
            return replace(block, body=body), inserted
        if isinstance(block, WhileBlock):
            body, inserted = insert_in_conditional(
                block.body, owner_id, arm, mutation_block
            )
            return replace(block, body=body), inserted
        if isinstance(block, CallBlock):
            callee, inserted = insert_in_conditional(
                block.callee, owner_id, arm, mutation_block
            )
            return replace(block, callee=callee), inserted
        return block, False

    # A retained loop's effects were lowered after its body, each behind its
    # own guard predicate.  When the body is lexical control ending in a
    # terminal edge (break, continue, return), "after the body" is
    # unreachable code: the effect never runs, and every value it consumes
    # there (the guard's own operands above all) drags the call producing
    # that value out of the body with it.  An authored effect belongs at its
    # authored position inside the body.  When its guarding conditional is
    # present in the tree it is installed in that arm like any other effect
    # (the arm is its guard).  Otherwise -- the conditional owned no region
    # and was projected away -- it keeps its composed guard and is ordered
    # among the body's statements by source position.
    def conditional_owner_ids(block) -> set[int]:
        owners: set[int] = set()
        if isinstance(block, ConditionalBlock):
            if block.source_node_id is not None:
                owners.add(int(block.source_node_id))
            owners |= conditional_owner_ids(block.body)
            if block.orelse is not None:
                owners |= conditional_owner_ids(block.orelse)
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                owners |= conditional_owner_ids(child)
        elif isinstance(block, (LoopBlock, WhileBlock)):
            owners |= conditional_owner_ids(block.body)
        elif isinstance(block, CallBlock):
            owners |= conditional_owner_ids(block.callee)
        return owners

    arm_relocated: list = []

    def relocate(block):
        if isinstance(block, SequenceBlock):
            return replace(
                block, blocks=tuple(relocate(child) for child in block.blocks)
            )
        if isinstance(block, ConditionalBlock):
            return replace(
                block,
                body=relocate(block.body),
                orelse=None if block.orelse is None else relocate(block.orelse),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=relocate(block.callee))
        if isinstance(block, (LoopBlock, WhileBlock)):
            body = relocate(block.body)
            owners = conditional_owner_ids(body)
            kept = []
            for item in block.sequence_mutations:
                effect_id = int(item.effect_node_id)
                guards = tuple(
                    (int(owner), str(arm))
                    for owner, arm in memberships.get(effect_id, ())
                    if str(arm) in {"body", "orelse"} and int(owner) in owners
                )
                if guards:
                    arm_relocated.append(
                        replace(item, predicate_expression=None)
                    )
                    continue
                if (
                    effect_id in graph.G
                    and node_position(effect_id)[0] < (1 << 30)
                ):
                    body = insert_ordered(body, SequenceMutationBlock(item))
                    continue
                kept.append(item)
            return replace(block, body=body, sequence_mutations=tuple(kept))
        return block

    control = replace(control, root=relocate(control.root))
    if arm_relocated:
        relocated_ids = {int(item.effect_node_id) for item in arm_relocated}
        mutations = (
            *arm_relocated,
            *(
                item for item in mutations
                if int(item.effect_node_id) not in relocated_ids
            ),
        )

    root = control.root
    unplaced = []
    for mutation in mutations:
        mutation_block = (mutation if isinstance(mutation, ScalarFieldWriteBlock)
                          else SequenceMutationBlock(mutation))
        guarded = tuple(dict.fromkeys((
            *tuple(
            (int(owner), str(arm))
            for owner, arm in memberships.get(int(mutation.effect_node_id), ())
            if str(arm) in {"body", "orelse"}
            ),
            *tuple(
                (int(owner), str(arm))
                for owner, arm in (
                    retained_mutation_records.get(
                        int(mutation.effect_node_id), {}
                    ).get("branch_memberships", ())
                )
                if str(arm) in {"body", "orelse"}
            ),
        )))
        if os.environ.get("TURING_DEBUG_SEQUENCE_MUTATION"):
            print(
                "DEBUGMUTATION "
                f"fn={graph.G.graph.get('function_name')} "
                f"effect={int(mutation.effect_node_id)} "
                f"sequence={getattr(mutation, 'sequence_value_id', None)} "
                f"guarded={guarded}",
                file=sys.stderr,
            )
        inserted = False
        # Innermost authored condition has the latest source position.
        for owner_id, arm in sorted(
            guarded, key=lambda item: node_position(item[0]), reverse=True,
        ):
            root, inserted = insert_in_conditional(
                root, owner_id, arm, mutation_block
            )
            if inserted:
                break
        if not inserted:
            # A branch containing only structural storage effects owns no
            # numerical region, so ordinary region overlay has no marker from
            # which to materialize its ConditionalBlock.  Reconstruct that
            # authored branch from the retained pre-fold control record, then
            # place the complete wrapper inside its nearest surviving outer
            # conditional (or at the lexical root).
            synthesized = None
            remaining_guards = guarded
            if guarded:
                owner_id, arm = sorted(
                    guarded,
                    key=lambda item: node_position(item[0]),
                    reverse=True,
                )[0]
                record = _source_control_records(graph.G).get(owner_id)
                owner_node_id = (
                    int(owner_id) if int(owner_id) in graph.G else next((
                        int(node_id)
                        for node_id, data in graph.G.nodes(data=True)
                        if int(data.get("value_id", node_id)) == int(owner_id)
                    ), None)
                )
                owner_data = (
                    {} if owner_node_id is None
                    else graph.G.nodes[int(owner_node_id)]
                )
                expression = (
                    record.get("expression")
                    if record is not None
                    else owner_data.get("expr_obj")
                )
                recorded_predicate_id = (
                    None if record is None else record.get("predicate_id")
                )
                if recorded_predicate_id is None:
                    recorded_predicate_id = next((
                        int(parent)
                        for parent, role in owner_data.get("parents", ())
                        if str(role) == "test"
                    ), None)
                predicate_id = (
                    None if not isinstance(expression, (ast.If, ast.IfExp))
                    else _retained_control_value_id(
                        graph.G,
                        recorded_predicate_id,
                        expression.test,
                    )
                )
                if predicate_id is None and isinstance(
                    expression, (ast.If, ast.IfExp)
                ):
                    direct_test = next((
                        int(parent)
                        for parent, role in owner_data.get("parents", ())
                        if str(role) == "test" and int(parent) in graph.G
                    ), None)
                    if direct_test is not None:
                        predicate_id = int(
                            graph.G.nodes[direct_test].get(
                                "value_id", direct_test
                            )
                        )
                if (
                    predicate_id is None
                    and recorded_predicate_id is not None
                    and isinstance(expression, (ast.If, ast.IfExp))
                ):
                    # The conditional node may have been folded out after its
                    # immutable source-control record was published.  That
                    # record already speaks in the canonical value identity
                    # consumed by region/control SSA; retain it directly.
                    predicate_id = int(recorded_predicate_id)
                if os.environ.get("TURING_DEBUG_SEQUENCE_MUTATION"):
                    print(
                        "DEBUGMUTATION-GUARD "
                        f"effect={int(mutation.effect_node_id)} "
                        f"owner={owner_id} owner_node={owner_node_id} "
                        f"recorded_predicate={recorded_predicate_id} "
                        f"predicate={predicate_id} "
                        f"expression={type(expression).__name__}",
                        file=sys.stderr,
                    )
                if predicate_id is not None:
                    empty = SequenceBlock(())
                    synthesized = ConditionalBlock(
                        int(predicate_id),
                        mutation_block if arm == "body" else empty,
                        mutation_block if arm == "orelse" else None,
                        predicate_expression=_graph_control_expression(
                            graph.G, int(predicate_id),
                            resident=_region_resident_value_ids(
                                dispatch_subgraphs
                            ),
                        ),
                        source_node_id=int(owner_id),
                    )
                    remaining_guards = tuple(
                        item for item in guarded if item != (owner_id, arm)
                    )
            if synthesized is not None:
                for owner_id, arm in sorted(
                    remaining_guards,
                    key=lambda item: node_position(item[0]),
                    reverse=True,
                ):
                    root, inserted = insert_in_conditional(
                        root, owner_id, arm, synthesized
                    )
                    if inserted:
                        break
                if not inserted:
                    root = insert_in_enclosing_loop(
                        root, synthesized, int(mutation.effect_node_id)
                    )
            elif guarded:
                unplaced.append(int(mutation.effect_node_id))
            else:
                root = insert_in_enclosing_loop(
                    root, mutation_block, int(mutation.effect_node_id)
                )
    return replace(control, root=root), tuple(unplaced)


def _control_expression_value_ids(expression: Any) -> frozenset[int]:
    if expression is None:
        return frozenset()
    return frozenset((
        *((int(expression.value_id),) if expression.value_id is not None else ()),
        *(
            value_id
            for operand in expression.operands
            for value_id in _control_expression_value_ids(operand)
        ),
    ))


def _install_external_reference_calls(control: Any, graph: Any, dispatch_subgraphs):
    """Retain native boundaries and dispatcher operations as lexical control.

    This is intentionally the last control transformation. Earlier region and
    hierarchy passes therefore cannot mistake an external capability for a
    Python function to pursue or for a numerical region to fuse.
    """

    from .control_source import (
        CallBlock, ConditionalBlock, DispatchBlock, ExternalReferenceCallBlock, LoopBlock,
        ResourceScopeBlock, SequenceBlock, StatementBlock, WhileBlock,
    )
    from .glsl_deployment_strategy import _ast_source_signature, _branch_compartments

    graph_obj = graph.G
    memberships = {node: set(owners) for node, owners in _branch_compartments(graph).items()}
    expression_nodes = {id(data.get("expr_obj")): int(node_id)
                        for node_id, data in graph_obj.nodes(data=True)
                        if isinstance(data.get("expr_obj"), ast.AST)}
    signature_nodes = {}
    for node_id, data in graph_obj.nodes(data=True):
        expression = data.get("expr_obj")
        if isinstance(expression, ast.AST) and getattr(expression, "lineno", None) is not None:
            signature_nodes.setdefault(_ast_source_signature(expression), []).append(int(node_id))
    resource_nodes = {
        int(node_id): data["expr_obj"]
        for node_id, data in graph_obj.nodes(data=True)
        if isinstance(data.get("expr_obj"), ast.Try)
        and getattr(data["expr_obj"], "_turing_resource_scope", None)
    }
    source_order = {}
    node_source_order = {}
    def index_source(node, loop_owners=()):
        if not isinstance(node, ast.AST):
            return
        source_order[id(node)] = len(source_order)
        node_id = expression_nodes.get(id(node))
        if node_id is None and getattr(node, "lineno", None) is not None:
            candidates = signature_nodes.get(_ast_source_signature(node), ())
            if len(candidates) == 1:
                node_id = candidates[0]
        if node_id is not None:
            node_source_order[node_id] = source_order[id(node)]
            memberships.setdefault(node_id, set()).update(loop_owners)
        for field, value in ast.iter_fields(node):
            owners = loop_owners
            if isinstance(node, (ast.For, ast.While)) and node_id is not None:
                owners += ((node_id, field),)
            for child in value if isinstance(value, list) else (value,):
                if isinstance(child, ast.AST):
                    index_source(child, owners)
    for statement in graph_obj.graph.get("function_body", ()):
        index_source(statement)

    def node_position(node_id):
        data = graph_obj.nodes.get(int(node_id), {})
        expression = data.get("expr_obj")
        span = data.get("source_span") or {}
        return (
            int(getattr(expression, "lineno", span.get("line", 1 << 30)) or (1 << 30)),
            int(getattr(expression, "col_offset", span.get("column", 0)) or 0),
            node_source_order.get(int(node_id), int(node_id)),
        )

    region_positions = {
        int(index): min(
            (node_position(node_id) for node_id in subgraph.G.graph.get(
                "deployment_nodes", ()
            )),
            default=(1 << 30, 0, int(index)),
        )
        for index, subgraph in enumerate(dispatch_subgraphs)
    }

    def block_position(block):
        if isinstance(block, ResourceScopeBlock):
            return node_position(block.source_scope_id)
        if isinstance(block, (ExternalReferenceCallBlock, DispatchBlock)):
            return node_position(block.callsite_id)
        if isinstance(block, StatementBlock) and len(block.lines) == 1:
            line = block.lines[0]
            if line.startswith("__scheduled_region_") and line.endswith("__"):
                return region_positions.get(
                    int(line[len("__scheduled_region_"):-2]),
                    (1 << 30, 0, 0),
                )
        if isinstance(block, ConditionalBlock) and block.source_node_id is not None:
            return node_position(block.source_node_id)
        if isinstance(block, (LoopBlock, WhileBlock)):
            source_id = block.source_loop_node_id
            if source_id is not None:
                return node_position(source_id)
        if isinstance(block, CallBlock):
            return node_position(block.callsite_id)
        if isinstance(block, SequenceBlock) and block.blocks:
            return min(map(block_position, block.blocks))
        return (1 << 30, 0, 0)

    def insert_ordered(block, external):
        decorated = [
            (block_position(child), index, child)
            for index, child in enumerate(_flattened_sequence_children(block))
        ]
        decorated.append((block_position(external), len(decorated), external))
        return SequenceBlock(tuple(
            child for _position, _index, child in sorted(
                decorated, key=lambda item: (item[0], item[1])
            )
        ))

    def insert_in_conditional(block, owner_id, arm, external):
        if isinstance(block, ResourceScopeBlock):
            if block.source_scope_id == owner_id and arm == "body":
                return replace(block, body=insert_ordered(block.body, external)), True
            body, inserted = insert_in_conditional(block.body, owner_id, arm, external)
            return replace(block, body=body), inserted
        if isinstance(block, ConditionalBlock):
            if int(block.source_node_id or -1) == int(owner_id):
                if arm == "body":
                    return replace(block, body=insert_ordered(block.body, external)), True
                return replace(
                    block,
                    orelse=insert_ordered(block.orelse or SequenceBlock(()), external),
                ), True
            body, inserted = insert_in_conditional(block.body, owner_id, arm, external)
            if inserted:
                return replace(block, body=body), True
            if block.orelse is not None:
                orelse, inserted = insert_in_conditional(
                    block.orelse, owner_id, arm, external
                )
                if inserted:
                    return replace(block, orelse=orelse), True
        elif isinstance(block, SequenceBlock):
            children = []
            for child in block.blocks:
                projected, inserted = insert_in_conditional(
                    child, owner_id, arm, external
                )
                children.append(projected)
                if inserted:
                    children.extend(block.blocks[len(children):])
                    return SequenceBlock(tuple(children)), True
        elif isinstance(block, (LoopBlock, WhileBlock)):
            if block.source_loop_node_id == owner_id:
                if arm == "body":
                    return replace(block, body=insert_ordered(block.body, external)), True
                if arm == "test" and isinstance(block, WhileBlock):
                    return replace(block, condition=insert_ordered(block.condition, external)), True
            body, inserted = insert_in_conditional(
                block.body, owner_id, arm, external
            )
            if inserted:
                return replace(block, body=body), True
        elif isinstance(block, CallBlock):
            callee, inserted = insert_in_conditional(
                block.callee, owner_id, arm, external
            )
            if inserted:
                return replace(block, callee=callee), True
        return block, False

    root = control.root
    unplaced = []
    installed = []
    pending_dispatch = {}
    for node_id, data in sorted(graph_obj.nodes(data=True), key=lambda item: node_position(item[0])):
        expression = data.get("expr_obj")
        contract = dict(
            data.get("extraction_contract")
            or (data.get("attributes") or {}).get("extraction_contract")
            or getattr(expression, "_extraction_contract", None)
            or {}
        )
        dispatch = (data.get("attributes") or {}).get("dispatch_operation")
        if not isinstance(expression, ast.Call) or (
            contract.get("action") != "use_native" and not dispatch
        ):
            continue
        if dispatch and (
            any(not (
                scope[0] in {"Try", "If"}
                or scope[0] in {"For", "While"} and scope[2] == "body"
                or scope[0] == "While" and scope[2] == "test"
            ) for scope in dispatch.get("control_scopes", ()))
            or any(
                isinstance(graph_obj.nodes.get(owner, {}).get("expr_obj"), ast.Try)
                and owner not in resource_nodes
                for owner, _arm in memberships.get(int(node_id), ())
            )
        ):
            raise FortranEmissionError(
                "dispatcher operation requires retained control scope lowering: "
                f"operation={dispatch['operation']}, scopes={dispatch['control_scopes']}"
            )
        if os.environ.get("TURING_DEBUG_EXTERNAL_REFERENCE"):
            print(
                "DEBUG-EXTERNAL-REFERENCE "
                f"function={graph_obj.graph.get('function_name')} "
                f"callsite={int(node_id)} identity={contract.get('identity')} "
                f"parents={data.get('parents')} "
                f"parameters={contract.get('parameters')}",
                file=sys.stderr,
            )
        parameters = dict(contract.get("parameters") or {})
        result_dtype = parameters.get("result_dtype")
        if dispatch:
            operation = str(dispatch["operation"])
            result_dtype = (
                "opaque_ref" if operation.endswith("_create") else
                "bool" if operation in {
                    "condition_acquire", "condition_wait", "event_wait",
                    "event_is_set", "thread_is_alive",
                } else "none"
            )
        if result_dtype is None:
            unplaced.append((int(node_id), "native boundary has no recorded result_dtype"))
            continue

        parents = tuple(data.get("parents") or ())

        def parent_value_id(parent_id):
            if parent_id not in graph_obj:
                return None
            return int(graph_obj.nodes[parent_id].get("value_id", parent_id))

        arguments = tuple(
            result for parent_id in ordered_arguments(parents)
            for result in (parent_value_id(parent_id),) if result is not None
        )
        keywords = tuple(
            (name, result)
            for parent_id, role in parents
            for name in (keyword_argument_name(role),)
            if name is not None
            for result in (parent_value_id(parent_id),)
            if result is not None
        )
        if len(arguments) != len(expression.args) or len(keywords) != len(expression.keywords):
            if dispatch:
                raise FortranEmissionError(
                    f"dispatcher arguments lack SSA identities: {dispatch['operation']} at node {node_id}"
                )
            unplaced.append((int(node_id), "native boundary arguments lack SSA identities"))
            continue
        external = DispatchBlock(
            callsite_id=int(node_id), operation=str(dispatch["operation"]),
            argument_value_ids=arguments, keyword_argument_value_ids=keywords,
            result_value_id=int(data.get("value_id", node_id)),
            result_dtype=str(result_dtype),
        ) if dispatch else ExternalReferenceCallBlock(
            callsite_id=int(node_id),
            identity=str(contract["identity"]),
            argument_value_ids=arguments,
            keyword_argument_value_ids=keywords,
            result_value_id=int(data.get("value_id", node_id)),
            result_dtype=str(result_dtype),
            shell_abi=str(parameters["shell_abi"]),
            external_domain=str(parameters["external_domain"]),
            native_abi=str(parameters.get("native_abi") or ""),
            runtime_owner=str(parameters.get("runtime_owner") or ""),
            shell_profiles=tuple(map(str, parameters.get("shell_profiles") or ())),
        )
        if dispatch:
            pending_dispatch[int(node_id)] = external
            continue
        guarded = tuple(
            (int(owner), str(arm))
            for owner, arm in memberships.get(int(node_id), ())
            if str(arm) in {"body", "orelse"}
        )
        inserted = False
        for owner_id, arm in sorted(
            guarded, key=lambda item: node_position(item[0]), reverse=True
        ):
            root, inserted = insert_in_conditional(root, owner_id, arm, external)
            if inserted:
                break
        if guarded and not inserted:
            unplaced.append((int(node_id), "native boundary conditional scope is not retained"))
            continue
        if not inserted:
            root = insert_ordered(root, external)
        if not dispatch:
            installed.append(int(node_id))

    def anchors(block):
        if isinstance(block, ResourceScopeBlock):
            return {block.source_scope_id}
        if isinstance(block, (DispatchBlock, ExternalReferenceCallBlock, CallBlock)):
            return {block.callsite_id}
        if isinstance(block, ConditionalBlock):
            return {block.source_node_id} if block.source_node_id is not None else set()
        if isinstance(block, (LoopBlock, WhileBlock)):
            return {block.source_loop_node_id} if block.source_loop_node_id is not None else set()
        if isinstance(block, SequenceBlock):
            return set().union(*(anchors(child) for child in block.blocks))
        if isinstance(block, StatementBlock) and len(block.lines) == 1:
            match = re.fullmatch(r"__scheduled_region_(\d+)__", block.lines[0])
            if match:
                return set(dispatch_subgraphs[int(match[1])].G.graph.get("deployment_nodes", ()))
        return set()

    def wrap_scope(block, scope_id, cleanup):
        def owned(child):
            nodes = anchors(child)
            inside = {node for node in nodes if (scope_id, "body") in memberships.get(node, ())}
            if inside and inside != nodes and not isinstance(child, SequenceBlock):
                raise FortranEmissionError("resource scope crosses a compiled region boundary")
            return bool(nodes) and inside == nodes
        if owned(block):
            return ResourceScopeBlock(block, cleanup, scope_id), True
        if isinstance(block, SequenceBlock):
            indices = [index for index, child in enumerate(block.blocks) if owned(child)]
            if indices:
                first, last = indices[0], indices[-1]
                if indices != list(range(first, last + 1)):
                    raise FortranEmissionError("resource scope has noncontiguous control ownership")
                grouped = ResourceScopeBlock(SequenceBlock(block.blocks[first:last + 1]), cleanup, scope_id)
                return SequenceBlock((*block.blocks[:first], grouped, *block.blocks[last + 1:])), True
            for index, child in enumerate(block.blocks):
                projected, found = wrap_scope(child, scope_id, cleanup)
                if found:
                    return SequenceBlock((*block.blocks[:index], projected, *block.blocks[index + 1:])), True
        elif isinstance(block, (ConditionalBlock, LoopBlock, WhileBlock, ResourceScopeBlock)):
            body, found = wrap_scope(block.body, scope_id, cleanup)
            if found:
                return replace(block, body=body), True
            if isinstance(block, ConditionalBlock) and block.orelse is not None:
                orelse, found = wrap_scope(block.orelse, scope_id, cleanup)
                if found:
                    return replace(block, orelse=orelse), True
        return block, False

    # Materialize lexical cleanup around the existing numerical/control body.
    # Nested scopes are wrapped first; their source node anchors then belong
    # to the enclosing scope just like any other authored body statement.
    for scope_id, expression in sorted(resource_nodes.items(),
                                      key=lambda item: len(memberships.get(item[0], ())), reverse=True):
        cleanup_ids = [node_id for node_id in pending_dispatch
                       if (scope_id, "finalbody") in memberships.get(node_id, ())]
        if len(cleanup_ids) != 1 or pending_dispatch[cleanup_ids[0]].operation != "condition_release":
            raise FortranEmissionError("resource scope has no exact condition release cleanup")
        cleanup = (replace(pending_dispatch.pop(cleanup_ids[0]), result_value_id=None),)
        root, found = wrap_scope(root, scope_id, cleanup)
        if not found:
            # A scope containing only dispatcher effects has no numeric marker.
            # Root scopes can still be anchored explicitly; a missing enclosing
            # branch/loop must not be guessed into existence here.
            if any(owner not in resource_nodes for owner, _ in memberships.get(scope_id, ())):
                raise FortranEmissionError("resource scope's enclosing control is not retained")
            root = insert_ordered(root, ResourceScopeBlock(SequenceBlock(()), cleanup, scope_id))
    for node_id, operation in pending_dispatch.items():
        guarded = [(owner, arm) for owner, arm in memberships.get(node_id, ())
                   if arm in {"body", "orelse", "test"}]
        inserted = False
        for owner, arm in sorted(guarded, key=lambda item: len(memberships.get(item[0], ())), reverse=True):
            root, inserted = insert_in_conditional(root, owner, arm, operation)
            # A missing inner owner cannot be replaced with an outer one:
            # that would hoist a wait out of its loop or conditional.
            break
        if guarded and not inserted:
            raise FortranEmissionError("dispatcher operation's control owner is not retained")
        if not inserted:
            root = insert_ordered(root, operation)
    return replace(control, root=root), tuple(installed), tuple(unplaced)


def _control_block_consumes_values(block: Any, value_ids: Iterable[int]) -> bool:
    """Whether a control subtree observes any exact SSA identity."""

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, SequenceBlock,
        ScalarFieldWriteBlock, SequenceMutationBlock, SequenceQueryBlock, ValidationBlock,
        WhileBlock,
    )

    wanted = set(map(int, value_ids))
    if not wanted:
        return False
    if isinstance(block, ScalarFieldWriteBlock):
        return bool(_control_expression_value_ids(block.value_expression).intersection(wanted))
    if isinstance(block, ConditionalBlock):
        if (
            int(block.predicate_value_id) in wanted
            or _control_expression_value_ids(
                block.predicate_expression
            ).intersection(wanted)
        ):
            return True
        return (
            _control_block_consumes_values(block.body, wanted)
            or block.orelse is not None
            and _control_block_consumes_values(block.orelse, wanted)
        )
    if isinstance(block, ValidationBlock):
        return (
            int(block.predicate_value_id) in wanted
            or bool(_control_expression_value_ids(
                block.predicate_expression
            ).intersection(wanted))
        )
    if isinstance(block, SequenceMutationBlock):
        mutation = block.mutation
        return bool(
            set(map(int, mutation.argument_value_ids)).intersection(wanted)
            or _control_expression_value_ids(
                mutation.predicate_expression
            ).intersection(wanted)
        )
    if isinstance(block, SequenceQueryBlock):
        consumed = {
            int(block.sequence_value_id),
            *map(int, block.reduction_prefix_value_ids),
            *map(int, block.reduction_suffix_value_ids),
        }
        if block.default_value_id is not None:
            consumed.add(int(block.default_value_id))
        return bool(consumed.intersection(wanted))
    if isinstance(block, CallBlock):
        return bool(
            {int(caller) for caller, _callee in block.argument_bindings}
            .intersection(wanted)
            or _control_block_consumes_values(block.callee, wanted)
        )
    if isinstance(block, SequenceBlock):
        return any(
            _control_block_consumes_values(child, wanted)
            for child in block.blocks
        )
    if isinstance(block, LoopBlock):
        return _control_block_consumes_values(block.body, wanted)
    if isinstance(block, WhileBlock):
        return (
            _control_block_consumes_values(block.condition, wanted)
            or _control_block_consumes_values(block.body, wanted)
        )
    return False


def _schedule_sequence_query_dependencies(root: Any) -> Any:
    """Place a producer-loop/query unit before its first lexical consumer."""

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, SequenceBlock,
        SequenceQueryBlock, WhileBlock,
    )

    if isinstance(root, SequenceBlock):
        scheduled_children = [
            _schedule_sequence_query_dependencies(child)
            for child in root.blocks
        ]
        # Sequential composition is associative: nested SequenceBlocks carry
        # no scope or closure.  Flatten them before dependency scheduling so
        # a generator loop appended in one planner group can move ahead of a
        # consumer retained in an earlier group.
        children = [
            grandchild
            for child in scheduled_children
            for grandchild in (
                child.blocks if isinstance(child, SequenceBlock) else (child,)
            )
        ]
        changed = True
        while changed:
            changed = False
            for loop_index, loop in enumerate(children):
                if (
                    not isinstance(loop, LoopBlock)
                    or loop.source_loop_node_id is None
                ):
                    continue
                query_indexes = [
                    index
                    for index, candidate in enumerate(children)
                    if isinstance(candidate, SequenceQueryBlock)
                    and candidate.producer_loop_node_id is not None
                    and int(candidate.producer_loop_node_id)
                    == int(loop.source_loop_node_id)
                ]
                queries = [children[index] for index in query_indexes]
                if not queries:
                    continue
                produced = {
                    int(value_id)
                    for query in queries
                    for value_id in (
                        query.result_value_id, *query.result_alias_ids,
                    )
                }
                unit_indexes = {loop_index, *query_indexes}
                consumer_index = next((
                    index
                    for index, candidate in enumerate(children)
                    if index not in unit_indexes
                    and _control_block_consumes_values(candidate, produced)
                ), None)
                # Source-position insertion and later structural recovery may
                # separate a generator loop from its query, or even leave the
                # query before the loop.  The pair is one semantic producer
                # unit.  Normalize it at its earliest existing position, and
                # move it farther forward when an earlier consumer requires
                # that dominance edge.
                anchor = min(unit_indexes)
                if consumer_index is not None:
                    anchor = min(anchor, consumer_index)
                rebuilt = [
                    candidate
                    for index, candidate in enumerate(children)
                    if index not in unit_indexes
                ]
                adjusted_anchor = sum(
                    1
                    for index in range(anchor)
                    if index not in unit_indexes
                )
                rebuilt[adjusted_anchor:adjusted_anchor] = [loop, *queries]
                if rebuilt != children:
                    children = rebuilt
                    changed = True
                    break
        return replace(root, blocks=tuple(children))
    if isinstance(root, ConditionalBlock):
        return replace(
            root,
            body=_schedule_sequence_query_dependencies(root.body),
            orelse=(
                None if root.orelse is None
                else _schedule_sequence_query_dependencies(root.orelse)
            ),
        )
    if isinstance(root, LoopBlock):
        return replace(
            root, body=_schedule_sequence_query_dependencies(root.body)
        )
    if isinstance(root, WhileBlock):
        return replace(
            root,
            condition=_schedule_sequence_query_dependencies(root.condition),
            body=_schedule_sequence_query_dependencies(root.body),
        )
    if isinstance(root, CallBlock):
        return replace(
            root, callee=_schedule_sequence_query_dependencies(root.callee)
        )
    return root


def _install_lexical_sequence_queries(
    control: Any,
    graph: Any,
    dispatch_subgraphs: Iterable[Any],
):
    """Replace supported generator consumers with resident sequence queries."""

    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, SequenceBlock,
        SequenceQueryBlock, StatementBlock, WhileBlock,
    )

    graph_obj = graph.G
    queries = []
    unsupported = []
    for node_id, data in sorted(graph_obj.nodes(data=True)):
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id in {"bool", "len", "next", "sum", "max"}
        ):
            continue
        positioned_arguments = tuple(sorted(
            (
                int(str(role).split(":", 1)[1]),
                int(parent),
            )
            for parent, role in data.get("parents") or ()
            if str(role).startswith("arg:") and int(parent) in graph_obj
        ))
        arguments = tuple(parent for _position, parent in positioned_arguments)
        if not arguments:
            continue
        identity = (data.get("attributes") or {}).get("extraction_identity")
        result_id = int(data.get("value_id", node_id))
        result_alias_ids = tuple(dict.fromkeys(
            int(graph_obj.nodes[child].get("value_id", child))
            for child, role in data.get("children") or ()
            if str(role) == "lhs"
            and int(child) in graph_obj
            and isinstance(
                graph_obj.nodes[int(child)].get("expr_obj"), ast.Name
            )
        ))
        if expression.func.id == "max":
            starred = tuple(
                (position, wrapper_id)
                for position, wrapper_id in positioned_arguments
                if isinstance(
                    graph_obj.nodes[wrapper_id].get("expr_obj"), ast.Starred
                )
            )
            if len(starred) != 1:
                continue
            starred_position, wrapper_id = starred[0]
            sequence_id = next((
                int(parent)
                for parent, role in graph_obj.nodes[wrapper_id].get("parents") or ()
                if str(role) == "value" and int(parent) in graph_obj
            ), None)
            if sequence_id is None:
                unsupported.append(int(node_id))
                continue
            sequence_data = graph_obj.nodes[sequence_id]
            sequence_attributes = sequence_data.get("attributes") or {}
            if not (
                sequence_data.get("type") == "LoopResult"
                and sequence_attributes.get("result_kind") == "collection"
            ):
                unsupported.append(int(node_id))
                continue
            prefix = tuple(
                parent for position, parent in positioned_arguments
                if position < starred_position
            )
            suffix = tuple(
                parent for position, parent in positioned_arguments
                if position > starred_position
            )
            if not prefix:
                unsupported.append(int(node_id))
                continue
            queries.append(SequenceQueryBlock(
                result_value_id=result_id,
                sequence_value_id=sequence_id,
                operation="maximum",
                source_call_node_id=int(node_id),
                extraction_identity=identity,
                result_alias_ids=result_alias_ids,
                producer_loop_node_id=int(sequence_attributes["loop_id"]),
                reduction_prefix_value_ids=prefix,
                reduction_suffix_value_ids=suffix,
            ))
            continue
        sequence_id = arguments[0]
        sequence_data = graph_obj.nodes[sequence_id]
        sequence_attributes = sequence_data.get("attributes") or {}
        producer_loop_node_id = None
        if (
            sequence_data.get("type") == "LoopResult"
            and sequence_attributes.get("result_kind") == "collection"
        ):
            producer_loop_node_id = int(sequence_attributes["loop_id"])
        elif (
            expression.func.id == "len"
            and sequence_attributes.get("aggregate_kind")
            in {"list", "bytes", "bytearray", "tuple"}
            and sequence_attributes.get("producer_kind")
            in {"sequence_materialization", "aggregate_materialization"}
        ):
            producer_loop_node_id = next((
                int(parent)
                for parent, role in sequence_data.get("parents") or ()
                if str(role) == "generators"
            ), None)
        local_list_truth = (
            expression.func.id in {"bool", "len"}
            and len(arguments) == 1
            and sequence_attributes.get("aggregate_kind") in {"list", "tuple"}
            and sequence_attributes.get("producer_kind") in {"aggregate", "aggregate_materialization"}
            and (data.get("attributes") or {}).get("extraction_identity")
                == f"builtins.{expression.func.id}"
        )
        if producer_loop_node_id is None and not local_list_truth:
            continue
        if os.environ.get("TURING_DEBUG_BUILTIN_SELECTION"):
            print(
                "DEBUGQUERY "
                f"fn={graph_obj.graph.get('function_name')} "
                f"call={int(node_id)} result={result_id} "
                f"aliases={result_alias_ids} sequence={sequence_id}",
                file=sys.stderr,
            )
        if expression.func.id in {"len", "bool"}:
            queries.append(SequenceQueryBlock(
                result_value_id=result_id,
                sequence_value_id=sequence_id,
                operation="truth" if expression.func.id == "bool" else "length",
                source_call_node_id=int(node_id),
                extraction_identity=identity,
                result_alias_ids=result_alias_ids,
                producer_loop_node_id=producer_loop_node_id,
            ))
            continue
        if expression.func.id == "next":
            if len(arguments) != 2:
                unsupported.append(int(node_id))
                continue
            queries.append(SequenceQueryBlock(
                result_value_id=result_id,
                sequence_value_id=sequence_id,
                operation="first_or_default",
                default_value_id=int(arguments[1]),
                source_call_node_id=int(node_id),
                extraction_identity=identity,
                result_alias_ids=result_alias_ids,
                producer_loop_node_id=producer_loop_node_id,
            ))
            continue

        materializer_id = sequence_attributes.get("materializer_node_id")
        materializer = (
            {} if materializer_id not in graph_obj
            else graph_obj.nodes[int(materializer_id)]
        )
        element_id = next((
            int(parent)
            for parent, role in materializer.get("parents") or ()
            if str(role) == "elt" and int(parent) in graph_obj
        ), None)
        element_data = (
            {} if element_id is None else graph_obj.nodes[element_id]
        )
        element_literal = (element_data.get("attributes") or {}).get(
            "value", element_data.get("constant")
        )
        explicit_start = (
            None if len(arguments) == 1
            else (graph_obj.nodes[arguments[1]].get("attributes") or {}).get(
                "value", graph_obj.nodes[arguments[1]].get("constant")
            )
        )
        if element_literal != 1 or explicit_start not in {None, 0}:
            unsupported.append(int(node_id))
            continue
        queries.append(SequenceQueryBlock(
            result_value_id=result_id,
            sequence_value_id=sequence_id,
            operation="length",
            source_call_node_id=int(node_id),
            extraction_identity=identity,
            result_alias_ids=result_alias_ids,
            producer_loop_node_id=producer_loop_node_id,
        ))

    if not queries:
        return control, tuple(unsupported)

    def insert_after_producer(block, query):
        if (
            os.environ.get("TURING_DEBUG_BUILTIN_SELECTION")
            and isinstance(block, LoopBlock)
        ):
            print(
                "DEBUGQUERYLOOP "
                f"call={query.source_call_node_id} "
                f"candidate={block.source_loop_node_id}",
                file=sys.stderr,
            )
        if (
            isinstance(block, LoopBlock)
            and block.source_loop_node_id is not None
            and int(block.source_loop_node_id)
            == int(query.producer_loop_node_id)
        ):
            return SequenceBlock((block, query)), True
        if isinstance(block, SequenceBlock):
            children = []
            inserted = False
            for child in block.blocks:
                projected, child_inserted = insert_after_producer(child, query)
                children.append(projected)
                inserted |= child_inserted
            return SequenceBlock(tuple(children)), inserted
        if isinstance(block, ConditionalBlock):
            body, inserted = insert_after_producer(block.body, query)
            orelse = block.orelse
            if not inserted and orelse is not None:
                orelse, inserted = insert_after_producer(orelse, query)
            return replace(block, body=body, orelse=orelse), inserted
        if isinstance(block, LoopBlock):
            body, inserted = insert_after_producer(block.body, query)
            return replace(block, body=body), inserted
        if isinstance(block, WhileBlock):
            body, inserted = insert_after_producer(block.body, query)
            return replace(block, body=body), inserted
        if isinstance(block, CallBlock):
            callee, inserted = insert_after_producer(block.callee, query)
            return replace(block, callee=callee), inserted
        return block, False

    region_nodes = {
        index: set(map(int, region.G.graph.get("deployment_nodes", ())))
        for index, region in enumerate(dispatch_subgraphs)
    }

    def insert_at_query_region(block, query):
        # The region marker retains the authored use position, including its
        # enclosing branch/loop. Never hoist truth to sequence construction.
        if isinstance(block, StatementBlock) and len(block.lines) == 1:
            match = re.fullmatch(r"__scheduled_region_(\d+)__", block.lines[0])
            if match and query.source_call_node_id in region_nodes.get(int(match[1]), set()):
                return SequenceBlock((query, block)), True
        if isinstance(block, SequenceBlock):
            children, inserted = [], False
            for child in block.blocks:
                child, found = insert_at_query_region(child, query)
                children.append(child)
                inserted |= found
            return replace(block, blocks=tuple(children)), inserted
        if isinstance(block, (ConditionalBlock, LoopBlock, WhileBlock)):
            body, inserted = insert_at_query_region(block.body, query)
            updates = {"body": body}
            if isinstance(block, ConditionalBlock) and block.orelse is not None:
                updates["orelse"], found = insert_at_query_region(block.orelse, query)
                inserted |= found
            if isinstance(block, WhileBlock):
                updates["condition"], found = insert_at_query_region(block.condition, query)
                inserted |= found
            return replace(block, **updates), inserted
        if isinstance(block, CallBlock):
            callee, inserted = insert_at_query_region(block.callee, query)
            return replace(block, callee=callee), inserted
        return block, False

    root = control.root
    unplaced = list(unsupported)
    for query in queries:
        if query.producer_loop_node_id is None:
            # A local list's truth (``if reasons:``) is an authored
            # statement: it goes at its source position in its own scope.
            # Anchoring it to whichever region happens to contain the
            # ``bool`` node put it after the conditionals that consume it
            # once regions were ordered by the hierarchy, and their merge
            # rebinding then made the query define the merged id.
            if int(query.source_call_node_id) in graph_obj:
                root, inserted = _insert_lexically(
                    root, graph, dispatch_subgraphs, query,
                    int(query.source_call_node_id),
                )
            else:
                root, inserted = insert_at_query_region(root, query)
            if not inserted:
                unplaced.append(int(query.source_call_node_id))
            continue
        root, inserted = insert_after_producer(root, query)
        if os.environ.get("TURING_DEBUG_BUILTIN_SELECTION"):
            print(
                "DEBUGQUERYPLACE "
                f"fn={graph_obj.graph.get('function_name')} "
                f"call={query.source_call_node_id} "
                f"producer={query.producer_loop_node_id} inserted={inserted}",
                file=sys.stderr,
            )
        if not inserted:
            unplaced.append(int(query.source_call_node_id))
    # When a numerical region contains only source calls replaced by resident
    # queries, its old marker would emit a second, now-dead helper call.  That
    # helper still names the starred wrapper as a scalar capture, recreating
    # the invented formal this transform exists to remove.  Retire only whole
    # regions whose complete source-node set is covered by installed queries;
    # mixed regions retain their downstream numerical work.
    query_call_ids = {
        int(query.source_call_node_id)
        for query in queries
        if query.source_call_node_id is not None
    }
    replaced_region_indices = {
        int(index)
        for index, nodes in region_nodes.items()
        if nodes and nodes.issubset(query_call_ids)
    }

    def remove_replaced_regions(block):
        if isinstance(block, StatementBlock) and len(block.lines) == 1:
            match = re.fullmatch(r"__scheduled_region_(\d+)__", block.lines[0])
            if match and int(match[1]) in replaced_region_indices:
                return SequenceBlock(())
        if isinstance(block, SequenceBlock):
            return replace(
                block,
                blocks=tuple(
                    projected
                    for child in block.blocks
                    for projected in (remove_replaced_regions(child),)
                    if not (
                        isinstance(projected, SequenceBlock)
                        and not projected.blocks
                    )
                ),
            )
        if isinstance(block, ConditionalBlock):
            return replace(
                block,
                body=remove_replaced_regions(block.body),
                orelse=(
                    None if block.orelse is None
                    else remove_replaced_regions(block.orelse)
                ),
            )
        if isinstance(block, LoopBlock):
            return replace(block, body=remove_replaced_regions(block.body))
        if isinstance(block, WhileBlock):
            return replace(
                block,
                condition=remove_replaced_regions(block.condition),
                body=remove_replaced_regions(block.body),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=remove_replaced_regions(block.callee))
        return block

    root = remove_replaced_regions(root)
    root = _schedule_sequence_query_dependencies(root)
    return replace(
        control,
        root=root,
        region_indices=tuple(
            int(index) for index in control.region_indices
            if int(index) not in replaced_region_indices
        ),
    ), tuple(unplaced)


def _utf8_encode_aliases(
    graph_obj: Any,
) -> tuple[tuple[int, int, str, str], ...]:
    """Return exact ``str.encode('utf-8')`` source-boundary aliases.

    Encoding is an ABI transform: the authored caller still accepts ``str``;
    the native function receives its deterministic UTF-8 byte sequence.  Only
    the explicit UTF-8 spelling is admitted, so locale/default-codec behavior
    is never inferred.
    """

    aliases = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if str(data.get("op") or data.get("type") or "").casefold() != "encode":
            continue
        parents = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        operand_node = parents.get("operand")
        encoding_node = parents.get("arg:0")
        if operand_node is None or encoding_node is None:
            continue
        operand = graph_obj.nodes.get(operand_node, {})
        encoding = graph_obj.nodes.get(encoding_node, {})
        operand_attributes = operand.get("attributes") or {}
        encoding_value = (encoding.get("attributes") or {}).get(
            "value", encoding.get("constant")
        )
        source_name = operand_attributes.get("binding_name")
        if (
            operand_attributes.get("binding_kind") != "parameter"
            or source_name is None
            or str(encoding_value).casefold().replace("_", "-") != "utf-8"
        ):
            continue
        aliases.append((
            int(data.get("value_id", node_id)),
            int(operand.get("value_id", operand_node)),
            str(source_name),
            "utf8",
        ))
    return tuple(aliases)


def _bytes_join_source_transforms(
    graph_obj: Any,
) -> tuple[tuple[int, int, str, str], ...]:
    """Describe ``b''.join(list(parameter))`` as native byte views.

    The list view carries authored row count while the join view carries the
    flattened bytes.  Both name the same authored iterable so a wrapper can
    materialize it exactly once and publish the two deterministic ABI views.
    """

    transforms = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        if str(data.get("op") or data.get("type") or "").casefold() != "join":
            continue
        parents = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        separator_id = parents.get("operand")
        materialized_id = parents.get("arg:0")
        if separator_id is None or materialized_id is None:
            continue
        separator = graph_obj.nodes.get(separator_id, {})
        separator_value = (separator.get("attributes") or {}).get(
            "value", separator.get("constant")
        )
        materialized = graph_obj.nodes.get(materialized_id, {})
        materialized_attributes = materialized.get("attributes") or {}
        if (
            separator_value != b""
            or materialized_attributes.get("producer_kind")
            != "aggregate_materialization"
            or materialized_attributes.get("aggregate_kind") != "list"
            or materialized_attributes.get("static_python_reference") != "list"
        ):
            continue
        sources = tuple(map(
            int, materialized_attributes.get("materialized_source_value_ids", ())
        ))
        if len(sources) != 1:
            continue
        source = graph_obj.nodes.get(sources[0], {})
        source_name = (source.get("attributes") or {}).get("binding_name")
        if source_name is None:
            continue
        transforms.extend((
            (
                int(materialized.get("value_id", materialized_id)),
                int(materialized.get("value_id", materialized_id)),
                str(source_name),
                "row_count",
            ),
            (
                int(data.get("value_id", node_id)),
                int(data.get("value_id", node_id)),
                str(source_name),
                "join_bytes",
            ),
        ))
    return tuple(transforms)


def _scalar_source_transforms(
    graph_obj: Any,
    sequence_transforms: Iterable[tuple[int, int, str, str]],
) -> tuple[tuple[int, str, str], ...]:
    """Describe scalar ABI projections such as source-backed ``len``.

    A linked call can legitimately consume a scalar whose producer is a
    structural sequence operation omitted from the numerical SSA region.
    Retaining only that scalar as an anonymous function argument leaves a
    native wrapper no exact way to construct it.  Record the authored source
    and projection at the compilation boundary instead.
    """

    transformed_values = {
        int(result_id): (
            str(source_name),
            (
                "utf8_length" if str(transform) == "utf8"
                else "materialized_length" if str(transform) == "row_count"
                else "sequence_length"
            ),
        )
        for result_id, _source_id, source_name, transform
        in sequence_transforms
    }
    records: list[tuple[int, str, str]] = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id == "len"
        ):
            continue
        arguments = tuple(
            int(parent)
            for parent, role in data.get("parents") or ()
            if str(role).startswith("arg:") and int(parent) in graph_obj
        )
        if len(arguments) != 1:
            continue
        argument = graph_obj.nodes[arguments[0]]
        argument_id = int(argument.get("value_id", arguments[0]))
        source = transformed_values.get(argument_id)
        if source is None:
            attributes = argument.get("attributes") or {}
            source_name = attributes.get("binding_name")
            if (
                attributes.get("binding_kind") == "parameter"
                and source_name is not None
            ):
                source = (str(source_name), "sequence_length")
            elif (
                attributes.get("producer_kind")
                == "aggregate_materialization"
            ):
                materialized_sources = tuple(map(
                    int, attributes.get("materialized_source_value_ids", ())
                ))
                if len(materialized_sources) == 1:
                    source_data = next((
                        candidate
                        for candidate_id, candidate in graph_obj.nodes(data=True)
                        if int(candidate.get("value_id", candidate_id))
                        == materialized_sources[0]
                    ), None)
                    source_attributes = (
                        {} if source_data is None
                        else source_data.get("attributes") or {}
                    )
                    source_name = source_attributes.get("binding_name")
                    if source_name is not None:
                        source = (
                            str(source_name), "materialized_length"
                        )
        if source is not None:
            records.append((
                int(data.get("value_id", node_id)), source[0], source[1]
            ))
    return tuple(records)


def _sequence_append_fill_ops(
    graph_obj: Any,
) -> tuple[
    tuple[int, int, int | float | bool | None, int, int], ...
]:
    """Return exact ``resident += literal_sequence * runtime_count`` rows."""

    sequence_kinds = {"list", "bytes", "bytearray"}
    operations = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.AugAssign)
            and isinstance(expression.op, ast.Add)
        ):
            continue
        by_role = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        lhs_id = by_role.get("lhs")
        rhs_id = by_role.get("rhs")
        if lhs_id is None or rhs_id is None:
            continue
        lhs = graph_obj.nodes.get(lhs_id, {})
        rhs = graph_obj.nodes.get(rhs_id, {})
        if (lhs.get("attributes") or {}).get(
            "aggregate_kind"
        ) not in sequence_kinds:
            continue
        if str(rhs.get("type") or rhs.get("op")) not in {"Mul", "Mult"}:
            continue
        operands = {
            str(role): int(parent)
            for parent, role in (rhs.get("parents") or ())
        }
        literal_id = operands.get("lhs")
        count_id = operands.get("rhs")
        if literal_id is None or count_id is None:
            continue
        literal_data = graph_obj.nodes.get(literal_id, {})
        literal = (literal_data.get("attributes") or {}).get(
            "value", literal_data.get("constant")
        )
        if isinstance(literal, (bytes, bytearray)) and len(literal) == 1:
            literal = int(literal[0])
        elif not isinstance(literal, (bool, int, float)) and literal is not None:
            continue
        operations.append((
            int(data.get("value_id", node_id)),
            int(lhs.get("value_id", lhs_id)),
            literal,
            int(graph_obj.nodes[count_id].get("value_id", count_id)),
            int(rhs.get("value_id", rhs_id)),
        ))
    return tuple(operations)


def _sequence_append_slice_ops(
    graph_obj: Any,
) -> tuple[tuple[int, int, int, int, int, int], ...]:
    """Return exact ``resident += resident[lower:upper]`` mutations.

    Only an authored unit-stride slice with explicit lower and upper values is
    admitted here.  The SSA helper performs Python-compatible bound clipping;
    other slice forms remain in the ordinary lowering ledger.
    """

    sequence_kinds = {"list", "bytes", "bytearray"}

    def _sequence_like(node: Mapping[str, Any]) -> bool:
        attributes = node.get("attributes") or {}
        if attributes.get("aggregate_kind") in sequence_kinds:
            return True
        # A structurally specialized sequence presents as its captured
        # initial value: a Constant whose payload is itself a sequence
        # object (re's ``out``/``tail`` arrive as Constant [] with
        # structural_specialization=True while their sequence descriptors
        # live on under the same value ids).
        return (
            str(node.get("type") or node.get("op")) == "Constant"
            and isinstance(
                attributes.get("value"), (list, bytes, bytearray)
            )
        )

    operations = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        data = graph_obj.nodes[node_id]
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.AugAssign)
            and isinstance(expression.op, ast.Add)
        ):
            continue
        by_role = {
            str(role): int(parent)
            for parent, role in (data.get("parents") or ())
        }
        lhs_id = by_role.get("lhs")
        rhs_id = by_role.get("rhs")
        if lhs_id is None or rhs_id is None:
            continue
        lhs = graph_obj.nodes.get(lhs_id, {})
        rhs = graph_obj.nodes.get(rhs_id, {})
        if str(rhs.get("type") or rhs.get("op")) != "Indexed":
            # Whole-sequence extend: ``resident += other_resident`` (re's
            # ``out += tail``). Same helper, bounds spanning the whole
            # source (the lowering clips into [0, source_length], so the
            # emitter passes 0 and a beyond-length constant). No extra
            # expression node exists to suppress, hence the None slice id.
            if _sequence_like(lhs) and _sequence_like(rhs):
                operations.append((
                    int(data.get("value_id", node_id)),
                    int(lhs.get("value_id", lhs_id)),
                    int(rhs.get("value_id", rhs_id)),
                    None,
                    None,
                    None,
                ))
            continue
        if (lhs.get("attributes") or {}).get(
            "aggregate_kind"
        ) not in sequence_kinds:
            continue
        indexed = {
            str(role): int(parent)
            for parent, role in (rhs.get("parents") or ())
        }
        source_id = indexed.get("base")
        slice_id = indexed.get("index")
        if source_id is None or slice_id is None:
            continue
        source = graph_obj.nodes.get(source_id, {})
        slice_data = graph_obj.nodes.get(slice_id, {})
        if (source.get("attributes") or {}).get(
            "aggregate_kind"
        ) not in sequence_kinds:
            continue
        if str(slice_data.get("type") or slice_data.get("op")) != "Slice":
            continue
        bounds = {
            str(role): int(parent)
            for parent, role in (slice_data.get("parents") or ())
        }
        lower_id = bounds.get("lower")
        upper_id = bounds.get("upper")
        if lower_id is None or upper_id is None or "step" in bounds:
            continue
        operations.append((
            int(data.get("value_id", node_id)),
            int(lhs.get("value_id", lhs_id)),
            int(source.get("value_id", source_id)),
            int(graph_obj.nodes[lower_id].get("value_id", lower_id)),
            int(graph_obj.nodes[upper_id].get("value_id", upper_id)),
            int(rhs.get("value_id", rhs_id)),
        ))
    return tuple(operations)


def _sequence_bit_pack_ops(
    graph_obj: Any,
) -> tuple[tuple[int, int, int, tuple[int, ...]], ...]:
    """Recognize complete translate/reverse/fixed-bit-word materialization.

    This is the structural meaning of ``_mk_bitmap``: a 0/1 byte arena is
    packed little-endian into fixed-width words.  Recognition follows the AST
    dataflow (translate -> reverse slice -> fixed slice -> int(base=2) ->
    list comprehension), never the function name.
    """

    operations = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        result = graph_obj.nodes[node_id]
        if (result.get("attributes") or {}).get(
            "aggregate_kind"
        ) != "list":
            continue
        expression = result.get("expr_obj")
        if not isinstance(expression, ast.ListComp) or len(expression.generators) != 1:
            continue
        element_parents = tuple(
            int(parent) for parent, role in (result.get("parents") or ())
            if str(role) == "elt" and parent in graph_obj
        )
        if len(element_parents) != 1:
            continue
        conversion = graph_obj.nodes[element_parents[0]]
        conversion_expression = conversion.get("expr_obj")
        if not (
            isinstance(conversion_expression, ast.Call)
            and len(conversion_expression.args) == 2
            and isinstance(conversion_expression.args[1], ast.Constant)
            and conversion_expression.args[1].value == 2
        ):
            continue
        conversion_roles = {
            str(role): int(parent)
            for parent, role in (conversion.get("parents") or ())
        }
        slice_value_id = conversion_roles.get("arg:0")
        if slice_value_id is None or slice_value_id not in graph_obj:
            continue
        sliced = graph_obj.nodes[slice_value_id]
        sliced_roles = {
            str(role): int(parent)
            for parent, role in (sliced.get("parents") or ())
        }
        reversed_id = sliced_roles.get("base")
        inner_slice_id = sliced_roles.get("index")
        if reversed_id is None or inner_slice_id is None:
            continue
        reversed_value = graph_obj.nodes[reversed_id]
        reversed_roles = {
            str(role): int(parent)
            for parent, role in (reversed_value.get("parents") or ())
        }
        translated_id = reversed_roles.get("base")
        reverse_slice_id = reversed_roles.get("index")
        if translated_id is None or reverse_slice_id is None:
            continue
        translated = graph_obj.nodes[translated_id]
        translated_roles = {
            str(role): int(parent)
            for parent, role in (translated.get("parents") or ())
        }
        source_id = translated_roles.get("operand")
        if source_id is None:
            continue
        source = graph_obj.nodes[source_id]
        if (source.get("attributes") or {}).get(
            "aggregate_kind"
        ) not in {"bytes", "bytearray", "list"}:
            continue
        reverse_slice = graph_obj.nodes[reverse_slice_id]
        reverse_step = tuple(
            int(parent) for parent, role in (reverse_slice.get("parents") or ())
            if str(role) == "step"
        )
        if len(reverse_step) != 1:
            continue
        step_expression = graph_obj.nodes[reverse_step[0]].get("expr_obj")
        if not (
            isinstance(step_expression, ast.UnaryOp)
            and isinstance(step_expression.op, ast.USub)
            and isinstance(step_expression.operand, ast.Constant)
            and step_expression.operand.value == 1
        ):
            continue
        inner_slice = graph_obj.nodes[inner_slice_id]
        lower_ids = tuple(
            int(parent) for parent, role in (inner_slice.get("parents") or ())
            if str(role) == "lower"
        )
        if len(lower_ids) != 1:
            continue
        lower = graph_obj.nodes[lower_ids[0]]
        lower_roles = {
            str(role): int(parent)
            for parent, role in (lower.get("parents") or ())
        }
        width_node_id = lower_roles.get("rhs")
        if width_node_id is None:
            continue
        width_id = int(graph_obj.nodes[width_node_id].get(
            "value_id", width_node_id
        ))
        consumed = tuple(dict.fromkeys((
            int(translated.get("value_id", translated_id)),
            int(reversed_value.get("value_id", reversed_id)),
            int(lower.get("value_id", lower_ids[0])),
            int(sliced.get("value_id", slice_value_id)),
            int(result.get("value_id", node_id)),
        )))
        operations.append((
            int(result.get("value_id", node_id)),
            int(source.get("value_id", source_id)),
            width_id,
            consumed,
        ))
    return tuple(operations)


def _sequence_prepend_concat_ops(
    graph_obj: Any,
) -> tuple[tuple[int, int, int, int, int], ...]:
    """Recognize ``[scalar] + sequence`` consumed by ``base[0:0] = ...``."""

    sequence_kinds = {"list", "bytearray"}
    resident_by_value: dict[int, int] = {}
    for history in (graph_obj.graph.get("identity_table") or {}).values():
        residents = tuple(
            int(value_id) for value_id in history
            if int(value_id) in graph_obj
            and (graph_obj.nodes[int(value_id)].get("attributes") or {}).get(
                "aggregate_kind"
            ) in sequence_kinds
        )
        if not residents:
            continue
        resident = residents[0]
        for value_id in history:
            resident_by_value[int(value_id)] = resident
    operations = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        store = graph_obj.nodes[node_id]
        if str(store.get("type") or store.get("op")) != "IndexedStore":
            continue
        roles = {
            str(role): int(parent)
            for parent, role in (store.get("parents") or ())
        }
        base_id = roles.get("base")
        index_id = roles.get("index")
        value_id = roles.get("value")
        if None in (base_id, index_id, value_id):
            continue
        base = graph_obj.nodes[base_id]
        index = graph_obj.nodes[index_id]
        concatenation = graph_obj.nodes[value_id]
        resident_id = resident_by_value.get(
            int(base.get("value_id", base_id))
        )
        if resident_id is None:
            continue
        bounds = {
            str(role): int(parent)
            for parent, role in (index.get("parents") or ())
        }
        if set(bounds) != {"lower", "upper"}:
            continue
        bound_values = []
        for bound_id in bounds.values():
            bound_data = graph_obj.nodes[bound_id]
            bound_values.append((bound_data.get("attributes") or {}).get(
                "value", bound_data.get("constant")
            ))
        if bound_values != [0, 0]:
            continue
        if str(concatenation.get("type") or concatenation.get("op")) != "Add":
            continue
        concat_roles = {
            str(role): int(parent)
            for parent, role in (concatenation.get("parents") or ())
        }
        singleton_id = concat_roles.get("lhs")
        tail_id = concat_roles.get("rhs")
        if singleton_id is None or tail_id is None:
            continue
        singleton = graph_obj.nodes[singleton_id]
        leaves = tuple((singleton.get("attributes") or {}).get(
            "aggregate_leaf_value_ids", ()
        ))
        if (
            (singleton.get("attributes") or {}).get("aggregate_kind") != "list"
            or len(leaves) != 1
        ):
            continue
        operations.append((
            int(store.get("value_id", node_id)),
            int(resident_id),
            int(leaves[0]),
            int(concatenation.get("value_id", value_id)),
            int(graph_obj.nodes[tail_id].get("value_id", tail_id)),
        ))
    return tuple(operations)


def _sequence_prepend_packed_call_ops(
    graph_obj: Any,
) -> tuple[tuple[int, int, int, int, int, int, int], ...]:
    """Correlate prefix splice with the pursued byte-packing call edge."""

    sequence_kinds = {"list", "bytes", "bytearray"}
    resident_by_value: dict[int, int] = {}
    for history in (graph_obj.graph.get("identity_table") or {}).values():
        residents = tuple(
            int(value_id) for value_id in history
            if int(value_id) in graph_obj
            and (graph_obj.nodes[int(value_id)].get("attributes") or {}).get(
                "aggregate_kind"
            ) in sequence_kinds
        )
        if not residents:
            continue
        resident = residents[0]
        for value_id in history:
            resident_by_value[int(value_id)] = resident
    operations = []
    for (
        store_result_id, destination_id, prefix_id, concat_result_id,
        tail_result_id,
    ) in _sequence_prepend_concat_ops(graph_obj):
        tail_node = next((
            (node_id, data)
            for node_id, data in graph_obj.nodes(data=True)
            if int(data.get("value_id", node_id)) == int(tail_result_id)
        ), None)
        if tail_node is None:
            continue
        _tail_node_id, tail = tail_node
        attributes = tail.get("attributes") or {}
        if attributes.get("callee_ref") is None:
            continue
        arguments = tuple(
            int(graph_obj.nodes[parent].get("value_id", parent))
            for parent, role in (tail.get("parents") or ())
            if str(role).startswith(("arg:", "kw:"))
        )
        if len(arguments) != 1:
            continue
        source_id = resident_by_value.get(int(arguments[0]))
        if source_id is None:
            continue
        operations.append((
            int(store_result_id), int(destination_id), int(prefix_id),
            int(source_id), int(concat_result_id), int(tail_result_id),
            int(_tail_node_id),
        ))
    return tuple(dict.fromkeys(operations))


def _sequence_inplace_bit_pack_call_ops(
    graph: Any,
) -> tuple[tuple[int, int, int, int, int], ...]:
    """Return pursued calls whose callee is a structural bit-pack program."""

    graph_obj = graph.G
    function_table = getattr(graph, "function_table", None)
    if function_table is None:
        return ()
    sequence_kinds = {"list", "bytes", "bytearray"}
    resident_by_value: dict[int, int] = {}
    for history in (graph_obj.graph.get("identity_table") or {}).values():
        residents = tuple(
            int(value_id) for value_id in history
            if int(value_id) in graph_obj
            and (graph_obj.nodes[int(value_id)].get("attributes") or {}).get(
                "aggregate_kind"
            ) in sequence_kinds
        )
        if not residents:
            continue
        resident = residents[0]
        for value_id in history:
            resident_by_value[int(value_id)] = resident
    operations = []
    for node_id in sorted(graph_obj.nodes(), key=lambda value: int(value)):
        call = graph_obj.nodes[node_id]
        attributes = call.get("attributes") or {}
        reference = attributes.get("callee_ref")
        if reference is None:
            continue
        try:
            callee = function_table.entry(int(reference)).graph
        except (KeyError, TypeError, ValueError):
            continue
        if callee is None:
            continue
        contracts = _sequence_bit_pack_ops(callee.G)
        if len(contracts) != 1:
            continue
        _callee_destination, _callee_source, _width_id, _consumed = contracts[0]
        arguments = tuple(
            int(graph_obj.nodes[parent].get("value_id", parent))
            for parent, role in (call.get("parents") or ())
            if str(role).startswith(("arg:", "kw:"))
        )
        if len(arguments) != 1:
            continue
        resident_id = resident_by_value.get(int(arguments[0]))
        if resident_id is None:
            continue
        entry = function_table.entry(int(reference))
        callable_object = getattr(entry, "python_callable", None)
        if callable_object is None and "." in str(entry.qualified_name):
            parts = str(entry.qualified_name).split(".")
            for split in range(len(parts) - 1, 0, -1):
                try:
                    candidate = importlib.import_module(".".join(parts[:split]))
                except ImportError:
                    continue
                try:
                    for attribute in parts[split:]:
                        candidate = getattr(candidate, attribute)
                except AttributeError:
                    continue
                callable_object = candidate
                break
        if callable_object is None:
            continue
        try:
            signature = inspect.signature(callable_object)
        except (TypeError, ValueError):
            continue
        parameters = tuple(signature.parameters.values())
        if len(parameters) < 2:
            continue
        width_default = parameters[1].default
        if not isinstance(width_default, int) or width_default <= 0:
            continue
        operations.append((
            int(call.get("value_id", node_id)),
            int(resident_id),
            int(width_default),
            int(reference),
            int(node_id),
        ))
    return tuple(dict.fromkeys(operations))


def _nested_row_projection_ops(
    graph_obj: Any, control: Any,
) -> tuple[tuple[int, int, int, str], ...]:
    """Find fixed-column reads from a projected/destructured loop row."""

    aliases_by_value: dict[int, frozenset[int]] = {}
    for history in (graph_obj.graph.get("identity_table") or {}).values():
        values = frozenset(map(int, history))
        for value_id in values:
            aliases_by_value[int(value_id)] = values
    operations = []
    for _iterable, target_id, induction, _projection in (
        getattr(control, "projected_iterable_bindings", ())
    ):
        aliases = aliases_by_value.get(
            int(target_id), frozenset((int(target_id),))
        )
        for node_id, data in graph_obj.nodes(data=True):
            if str(data.get("type")) not in {"Indexed", "indexed"}:
                continue
            roles = {
                str(role): int(parent)
                for parent, role in (data.get("parents") or ())
            }
            base = roles.get("base")
            index = roles.get("index")
            if base not in aliases or index is None or index not in graph_obj:
                continue
            index_data = graph_obj.nodes[index]
            expression = index_data.get("expr_obj")
            literal = (
                expression.value
                if isinstance(expression, ast.Constant)
                else (index_data.get("attributes") or {}).get(
                    "value", index_data.get("value")
                )
            )
            if not isinstance(literal, int) or isinstance(literal, bool):
                continue
            operations.append((
                int(target_id), int(literal),
                int(data.get("value_id", node_id)), str(induction),
            ))
    return tuple(dict.fromkeys(operations))


def _rewrite_optional_row_handle_none_predicate(
    expression: Any, handle_ids: Iterable[int],
) -> Any:
    """Compare optional record row handles with their physical -1 sentinel."""

    if expression is None:
        return None
    handles = set(map(int, handle_ids))
    operands = tuple(
        _rewrite_optional_row_handle_none_predicate(operand, handles)
        for operand in expression.operands
    )
    rewritten = replace(expression, operands=operands)
    if rewritten.op not in {"eq", "ne"} or len(operands) != 2:
        return rewritten
    for handle_index, none_index in ((0, 1), (1, 0)):
        handle = operands[handle_index]
        none = operands[none_index]
        if (
            handle.value_id is None
            or int(handle.value_id) not in handles
            or none.op != "const"
            or none.literal is not None
        ):
            continue
        replaced = list(operands)
        replaced[none_index] = replace(none, literal=-1)
        return replace(rewritten, operands=tuple(replaced))
    return rewritten


def _record_sequence_projection_bindings(
    graph_obj: Any, control: Any,
) -> tuple[
    Any,
    tuple[tuple[int, int, str, object], ...],
    tuple[tuple[int, str, str], ...],
]:
    """Project fields of ``Sequence[Record]`` rows at their loop binding.

    The authored parameter is a columnar resident sequence. A lexical loop
    target names the current row, while each ``target.field`` names one exact
    column load at the same induction. This preserves the ordinary intuitive
    source and gives downstream regions/calls real in-loop producers instead
    of promoting field values to anonymous public inputs.
    """

    records = _graph_sequence_record_abi(graph_obj)
    identities = graph_obj.graph.get("identity_table") or {}
    aliases_by_value: dict[int, frozenset[int]] = {}
    for history in identities.values():
        aliases = frozenset(map(int, history))
        for value_id in aliases:
            aliases_by_value[int(value_id)] = aliases
    parameter_by_sequence: dict[int, tuple[str, Mapping[str, Any]]] = {}
    for parameter_name, record in records.items():
        for value_id in identities.get(str(parameter_name), ()):
            parameter_by_sequence[int(value_id)] = (
                str(parameter_name), record,
            )
    row_loop_bindings = tuple(dict.fromkeys((
        *tuple(getattr(control, "iterable_bindings", ())),
        *tuple(
            (int(iterable_id), int(target_id), str(induction))
            for iterable_id, target_id, induction, projection
            in getattr(control, "projected_iterable_bindings", ())
            if projection is None
        ),
    )))
    bindings: list[tuple[int, int, str, object]] = []
    fields: list[tuple[int, str, str]] = []
    direct_rows: dict[int, tuple[int, Mapping[str, Any]]] = {}
    for iterable_id, target_id, _induction in row_loop_bindings:
        selected = parameter_by_sequence.get(int(iterable_id))
        if selected is None:
            iterable_aliases = aliases_by_value.get(
                int(iterable_id), frozenset((int(iterable_id),))
            )
            selected = next((
                record for candidate, record in parameter_by_sequence.items()
                if candidate in iterable_aliases
            ), None)
        if selected is not None:
            _parameter_name, record = selected
            direct_rows[int(target_id)] = (int(iterable_id), record)

    # A filtered comprehension over a record sequence stores integer row
    # handles into its derived resident sequence.  Recover that relationship
    # from the exact mutation argument identity; no Python row object is
    # reconstructed and no name spelling participates in the correlation.
    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, SequenceBlock,
        SequenceMutationBlock, SequenceQueryBlock, WhileBlock,
    )

    mutations = []
    queries = []

    def gather_mutations(block):
        if isinstance(block, SequenceMutationBlock):
            mutations.append(block.mutation)
        elif isinstance(block, SequenceQueryBlock):
            queries.append(block)
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                gather_mutations(child)
        elif isinstance(block, ConditionalBlock):
            gather_mutations(block.body)
            if block.orelse is not None:
                gather_mutations(block.orelse)
        elif isinstance(block, (LoopBlock, WhileBlock)):
            mutations.extend(block.sequence_mutations)
            if isinstance(block, WhileBlock):
                gather_mutations(block.condition)
            gather_mutations(block.body)
        elif isinstance(block, CallBlock):
            gather_mutations(block.callee)

    gather_mutations(control.root)
    derived_sequences: dict[int, tuple[int, Mapping[str, Any]]] = {}
    for mutation in mutations:
        if str(mutation.operator) not in {"append", "add"}:
            continue
        arguments = set(map(int, mutation.argument_value_ids))
        for target_id, origin in direct_rows.items():
            target_aliases = aliases_by_value.get(
                int(target_id), frozenset((int(target_id),))
            )
            if arguments.intersection(target_aliases):
                derived_sequences[int(mutation.sequence_value_id)] = origin
                effect_id = int(mutation.effect_node_id)
                if effect_id in graph_obj:
                    # Hierarchical composition namespaces resident storage,
                    # while a later authored loop still names the source
                    # materializer result.  The mutation's retained effect
                    # node is their exact correlation receipt.
                    derived_sequences[int(graph_obj.nodes[effect_id].get(
                        "value_id", effect_id
                    ))] = origin

    optional_projections: dict[
        int, tuple[tuple[int, int, int, int, str], ...]
    ] = {}
    # ``mapping.pop(key, None)`` has the same physical optional-handle ABI as
    # ``first_or_default``: its lookup result is -1 when absent.  Register the
    # exact effect identity even when no parameter-record projection exists so
    # an authored ``result is None`` predicate is rewritten consistently.
    for mutation in mutations:
        if (
            str(mutation.operator) == "pop"
            and mutation.argument_kind == "mapping_pop_default_none"
        ):
            optional_projections[int(mutation.effect_node_id)] = ()
    optional_query_calls: set[int] = set()
    for query in queries:
        if str(query.operation) != "first_or_default":
            continue
        origin = derived_sequences.get(int(query.sequence_value_id))
        if origin is None:
            continue
        origin_sequence_id, record = origin
        receivers = {
            int(query.result_value_id), *map(int, query.result_alias_ids)
        }
        physical_columns = {}
        physical_column = 0
        for field_name, receipt in dict(record.get("fields") or {}).items():
            if bool(receipt.get("optional")):
                physical_column += 1
            physical_columns[str(field_name)] = (
                physical_column, str(receipt.get("dtype") or "unknown")
            )
            physical_column += 1
        projected = []
        for node_id, data in graph_obj.nodes(data=True):
            if str(data.get("op") or data.get("type") or "").casefold() != "getattr":
                continue
            attribute = str(
                (data.get("attributes") or {}).get("attribute") or ""
            )
            if attribute not in physical_columns or not any(
                int(graph_obj.nodes[parent].get("value_id", parent)) in receivers
                and str(role) in {"value", "object", "base", "receiver"}
                for parent, role in (data.get("parents") or ())
                if parent in graph_obj
            ):
                continue
            column, dtype = physical_columns[attribute]
            result_id = int(data.get("value_id", node_id))
            projected.append((
                int(origin_sequence_id), int(query.result_value_id),
                result_id, int(column), str(dtype),
            ))
            fields.append((result_id, attribute, str(dtype)))
        if projected:
            optional_projections[int(query.result_value_id)] = tuple(projected)
            if query.source_call_node_id is not None:
                optional_query_calls.add(int(query.source_call_node_id))

    for iterable_id, target_id, induction in row_loop_bindings:
        selected = parameter_by_sequence.get(int(iterable_id))
        if selected is None:
            iterable_aliases = aliases_by_value.get(
                int(iterable_id), frozenset((int(iterable_id),))
            )
            selected = next((
                record for candidate, record in parameter_by_sequence.items()
                if candidate in iterable_aliases
            ), None)
        derived = False
        if selected is None:
            selected = derived_sequences.get(int(iterable_id))
            derived = selected is not None
        if selected is None:
            continue
        if derived:
            origin_sequence_id, record = selected
        else:
            _parameter_name, record = selected
            origin_sequence_id = int(iterable_id)
        field_contracts = tuple(dict(record.get("fields") or {}).items())
        field_columns = {}
        physical_column = 0
        for field_name, field_receipt in field_contracts:
            if bool(field_receipt.get("optional")):
                # Presence precedes value.  Attribute access selects the value
                # column; an explicit ``is None`` field test can consume the
                # adjacent presence column without overloading its payload.
                physical_column += 1
            field_columns[str(field_name)] = physical_column
            physical_column += 1
        # Loop targets with the same authored spelling are distinct SSA
        # identities (two separate ``for row in ...`` bindings are the common
        # case).  The graph's GetAttr receiver already carries the exact target
        # value; consulting the scope-free name history here conflates those
        # loops and places a later field load in the earlier coordinator.
        target_aliases = frozenset((int(target_id),))
        if not derived:
            # The conceptual row itself is a stable integer handle.  Field
            # values are loaded from the source columns below; retaining a
            # second flat-element load for the row would confuse column zero
            # with the record identity when a comprehension republishes it.
            bindings.append((
                int(origin_sequence_id), int(target_id), str(induction),
                "induction",
            ))
        for node_id, data in graph_obj.nodes(data=True):
            if str(data.get("op") or data.get("type") or "").casefold() != "getattr":
                continue
            attribute = str(
                (data.get("attributes") or {}).get("attribute") or ""
            )
            if attribute not in field_columns or not any(
                int(graph_obj.nodes[parent].get("value_id", parent))
                in target_aliases
                and str(role) in {"value", "object", "base", "receiver"}
                for parent, role in (data.get("parents") or ())
                if parent in graph_obj
            ):
                continue
            result_id = int(data.get("value_id", node_id))
            receipt = dict(next(
                field_receipt
                for field_name, field_receipt in field_contracts
                if str(field_name) == attribute
            ))
            bindings.append((
                int(origin_sequence_id), result_id, str(induction),
                (
                    (
                        "column_at_value", int(field_columns[attribute]),
                        int(target_id),
                    )
                    if derived else int(field_columns[attribute])
                ),
            ))
            fields.append((
                result_id, attribute, str(receipt.get("dtype") or "unknown")
            ))
    def expression_values(expression):
        if expression is None:
            return frozenset()
        return frozenset((
            *((int(expression.value_id),) if expression.value_id is not None else ()),
            *(value for operand in expression.operands for value in expression_values(operand)),
        ))

    def attach_optional(block):
        if isinstance(block, SequenceQueryBlock):
            return replace(
                block,
                row_handle=(
                    block.source_call_node_id is not None
                    and int(block.source_call_node_id) in optional_query_calls
                ),
            )
        if isinstance(block, SequenceBlock):
            return replace(
                block,
                blocks=tuple(attach_optional(child) for child in block.blocks),
            )
        if isinstance(block, ConditionalBlock):
            body = attach_optional(block.body)
            orelse = (
                None if block.orelse is None
                else attach_optional(block.orelse)
            )
            predicate_expression = (
                _rewrite_optional_row_handle_none_predicate(
                    block.predicate_expression, optional_projections
                )
            )
            values = expression_values(predicate_expression)
            entry = tuple(
                projection
                for handle_id, projections in optional_projections.items()
                if int(handle_id) in values
                and predicate_expression is not None
                and predicate_expression.op == "ne"
                for projection in projections
            )
            return replace(
                block, body=body, orelse=orelse,
                predicate_expression=predicate_expression,
                entry_record_projections=tuple(dict.fromkeys((
                    *block.entry_record_projections, *entry,
                ))),
            )
        if isinstance(block, LoopBlock):
            return replace(block, body=attach_optional(block.body))
        if isinstance(block, WhileBlock):
            return replace(
                block,
                condition=attach_optional(block.condition),
                body=attach_optional(block.body),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=attach_optional(block.callee))
        return block

    control = replace(control, root=attach_optional(control.root))
    return (
        control,
        tuple(dict.fromkeys(bindings)),
        tuple(dict.fromkeys(fields)),
    )


def _sequence_row_operations(
    graph_obj: Any,
    sequence_declarations: Iterable[tuple[int, str, int, bool]],
) -> tuple[tuple[Any, ...], ...]:
    """Recover positional reads/writes of fixed-width sequence rows."""

    widths = {
        int(sequence_id): int(column_count)
        for sequence_id, _policy, column_count, _writable
        in sequence_declarations
        if int(column_count) > 1
    }
    if not widths:
        return ()
    identities = graph_obj.graph.get("identity_table") or {}
    resident_by_value = {
        int(value_id): int(sequence_id)
        for sequence_id in widths
        for history in identities.values()
        if int(sequence_id) in set(map(int, history))
        for value_id in history
    }
    resident_by_value.update({sequence_id: sequence_id for sequence_id in widths})
    changed = True
    aliases = _loop_carried_storage_aliases(graph_obj)
    while changed:
        changed = False
        for alias_id, source_id in aliases.items():
            resident = resident_by_value.get(int(source_id))
            if resident is not None and resident_by_value.get(int(alias_id)) != resident:
                resident_by_value[int(alias_id)] = resident
                changed = True
        for node_id, data in graph_obj.nodes(data=True):
            if str(data.get("op") or data.get("type") or "").casefold() not in {
                "phi", "loopresult", "loopexit",
            }:
                continue
            residents = {
                resident_by_value[int(graph_obj.nodes[parent].get(
                    "value_id", parent
                ))]
                for parent, role in data.get("parents") or ()
                if str(role) not in {"control", "test"}
                and parent in graph_obj
                and int(graph_obj.nodes[parent].get(
                    "value_id", parent
                )) in resident_by_value
            }
            if len(residents) == 1:
                value_id = int(data.get("value_id", node_id))
                resident = next(iter(residents))
                if resident_by_value.get(value_id) != resident:
                    resident_by_value[value_id] = resident
                    changed = True

    def roles(data: Mapping[str, Any]) -> dict[str, int]:
        return {
            str(role): int(parent)
            for parent, role in data.get("parents") or ()
            if parent in graph_obj
        }

    def value_id(node_id: int) -> int:
        return int(graph_obj.nodes[node_id].get("value_id", node_id))

    def integer_literal(node_id: int) -> int | None:
        data = graph_obj.nodes[node_id]
        expression = data.get("expr_obj")
        literal = (
            expression.value if isinstance(expression, ast.Constant)
            else (data.get("attributes") or {}).get(
                "value", data.get("constant")
            )
        )
        return (
            int(literal)
            if isinstance(literal, int) and not isinstance(literal, bool)
            else None
        )

    operations: list[tuple[Any, ...]] = []
    for node_id, data in sorted(graph_obj.nodes(data=True)):
        kind = str(data.get("op") or data.get("type") or "").casefold()
        node_roles = roles(data)
        if kind == "indexed":
            outer_id = node_roles.get("base")
            column_node = node_roles.get("index")
            if outer_id is None or column_node is None:
                continue
            outer = graph_obj.nodes[outer_id]
            if str(outer.get("op") or outer.get("type") or "").casefold() != "indexed":
                continue
            outer_roles = roles(outer)
            base_node = outer_roles.get("base")
            row_index_node = outer_roles.get("index")
            if base_node is None or row_index_node is None:
                continue
            sequence_id = resident_by_value.get(value_id(base_node))
            column = integer_literal(column_node)
            if (
                sequence_id is None or column is None or column < 0
                or column >= widths[sequence_id]
            ):
                continue
            operations.append((
                "load", value_id(node_id), int(sequence_id),
                value_id(row_index_node), integer_literal(row_index_node),
                int(column), value_id(outer_id),
            ))
        elif kind == "indexedstore":
            base_node = node_roles.get("base")
            row_index_node = node_roles.get("index")
            row_value_node = node_roles.get("value")
            if base_node is None or row_index_node is None or row_value_node is None:
                continue
            sequence_id = resident_by_value.get(value_id(base_node))
            row_attributes = graph_obj.nodes[row_value_node].get("attributes") or {}
            leaves = tuple(map(
                int, row_attributes.get("aggregate_leaf_value_ids", ())
            ))
            if (
                sequence_id is None
                or row_attributes.get("aggregate_kind") != "tuple"
                or len(leaves) != widths[sequence_id]
            ):
                continue
            operations.append((
                "store", value_id(node_id), int(sequence_id),
                value_id(row_index_node), integer_literal(row_index_node),
                leaves, value_id(row_value_node),
            ))
    return tuple(operations)


_UNTYPED = {"", "unknown", "none", "None"}
_INTEGRAL_DTYPES = {
    "int", "int8", "int16", "int32", "int64",
    "uint8", "uint16", "uint32", "uint64", "bool",
}


def _key_columns_integral(descriptor: Any) -> bool:
    """Whether every column this descriptor calls a key is integral.

    A key column is an index; a float cannot be one, and a string key is
    an fnv1a-64 token that float64's 53-bit mantissa silently rounds.  A
    descriptor failing this is invalid on its own terms, independently of
    which pass built it -- which is what lets a consumer refuse it without
    having to know the right answer.
    """
    dtypes = tuple(getattr(descriptor, "column_dtypes", ()) or ())
    for column in getattr(descriptor, "key_columns", ()) or ():
        if int(column) >= len(dtypes):
            return False
        if str(dtypes[int(column)]) not in _INTEGRAL_DTYPES:
            return False
    return True


def _declared_column_dtype(value: Any, default: str) -> str:
    """The dtype a sequence column actually holds, declaration first.

    Two failures this replaces, both seen on the real dt-system build:

    ``str(value.dtype or default)`` only falls back when dtype is None.
    The compiler's "I could not work it out" sentinel is the STRING
    ``"unknown"``, which is truthy, so it sailed through and a column
    declared int64 was published as ``unknown``.

    Worse, a key column that had been inferred from its neighbours came
    out ``float64``.  A string-token key is an fnv1a-**64** value and
    float64 carries only 53 bits exactly, so every token above 2**53 is
    silently rounded -- the key then never matches its own lookup and the
    channel goes missing rather than failing loudly.  Inference must not
    be able to decide this: ``physical_dtype`` is the declared contract
    the ABI already recorded beside the value, so it is consulted first
    and the categorical default (int64 for a key column) stands behind it.
    """
    accounting = dict(getattr(value, "accounting", None) or {})
    declared = accounting.get("physical_dtype")
    if declared is not None and str(declared) not in _UNTYPED:
        return str(declared)
    inferred = getattr(value, "dtype", None)
    if inferred is not None and str(inferred) not in _UNTYPED:
        return str(inferred)
    return str(default)


def _sequence_column_dtype_contracts(
    graph_obj: Any,
    sequence_declarations: Iterable[tuple[int, str, int, bool]],
) -> dict[int, tuple[str, ...]]:
    """Recover fixed-row column dtypes from authored annotations.

    A declaration such as ``runs: list[tuple[int, int]]`` is a physical
    contract for both resident columns, not merely evidence that the row has
    width two.  Keep that contract beside the compile artifact so row loads,
    stores, and append helpers share one type before target inference runs.
    """

    declared = {
        int(sequence_id): int(column_count)
        for sequence_id, _policy, column_count, _writable
        in sequence_declarations
    }
    if not declared:
        return {}
    identities = graph_obj.graph.get("identity_table") or {}
    scalar_dtypes = {
        "bool": "bool",
        "int": "int64",
        "float": "float64",
    }
    contracts: dict[int, tuple[str, ...]] = {}
    repository_records = dict(
        (graph_obj.graph.get("program_abi") or {}).get("records") or {}
    )
    sequence_record_by_value: dict[int, Mapping[str, Any]] = {}
    for binding_name, sequence_record in _graph_sequence_record_abi(
        graph_obj
    ).items():
        for value_id in identities.get(str(binding_name), ()):
            sequence_record_by_value[int(value_id)] = sequence_record
    for parameter_name, record in dict(
        graph_obj.graph.get("parameter_record_abi") or {}
    ).items():
        parameter_ids = set(map(
            int, identities.get(str(parameter_name), ())
        ))
        if not parameter_ids:
            continue
        for field_name, field in dict(record.get("fields") or {}).items():
            if str(field.get("storage") or "") != "table":
                continue
            dtypes = tuple(
                str(column.get("dtype") or "unknown")
                for column in field.get("columns") or ()
            )
            for node_id, data in graph_obj.nodes(data=True):
                attributes = data.get("attributes") or {}
                value_id = int(data.get("value_id", node_id))
                if (
                    value_id in declared
                    and str(data.get("type") or data.get("op") or "").casefold()
                    == "getattr"
                    and str(attributes.get("attribute") or "")
                    == str(field_name)
                    and any(
                        int(parent) in parameter_ids
                        and str(role) in {
                            "value", "object", "base", "receiver",
                        }
                        for parent, role in data.get("parents") or ()
                    )
                    and len(dtypes) == declared[value_id]
                ):
                    contracts[value_id] = dtypes
    for node_id, data in graph_obj.nodes(data=True):
        value_id = int(data.get("value_id", node_id))
        if value_id not in declared or str(
            data.get("type") or data.get("op") or ""
        ).casefold() != "getattr":
            continue
        receiver_id = next((
            int(parent)
            for parent, role in data.get("parents") or ()
            if str(role) in {"value", "object", "base", "receiver"}
            and int(parent) in graph_obj
        ), None)
        if receiver_id is None:
            continue
        receiver = graph_obj.nodes[receiver_id]
        if str(receiver.get("type") or receiver.get("op") or "").casefold() not in {
            "indexed", "load",
        }:
            continue
        row_source = next((
            int(parent)
            for parent, role in receiver.get("parents") or ()
            if str(role) == "base" and int(parent) in graph_obj
        ), None)
        record = (
            None if row_source is None
            else sequence_record_by_value.get(row_source)
        )
        attribute = str((data.get("attributes") or {}).get("attribute") or "")
        field = (
            None if record is None
            else dict(record.get("fields") or {}).get(attribute)
        )
        if not isinstance(field, Mapping) or str(
            field.get("storage") or ""
        ) != "table":
            continue
        dtypes = tuple(
            str(column.get("dtype") or "unknown")
            for column in field.get("columns") or ()
        )
        if len(dtypes) == declared[value_id]:
            contracts[value_id] = dtypes
    for parameter_name, annotation in (
        _current_authored_parameter_annotations(graph_obj).items()
    ):
        sequence_id = next((
            int(value_id)
            for value_id in identities.get(str(parameter_name), ())
            if int(value_id) in declared
        ), None)
        if sequence_id is None:
            continue
        layout = _authored_row_layout(annotation, repository_records)
        if layout is not None and any(
            kind == "record" for kind, _identity, _width in layout
        ):
            row_dtypes: list[str] = []
            for kind, identity, _width in layout:
                if kind == "record":
                    record = next(
                        record for candidate, record
                        in repository_records.items()
                        if str(candidate) == identity
                    )
                    row_dtypes.extend(
                        dtype for _name, dtype
                        in _record_row_physical_columns(record)
                    )
                else:
                    row_dtypes.append("unknown")
            if len(row_dtypes) == declared[int(sequence_id)]:
                contracts[int(sequence_id)] = tuple(row_dtypes)
            continue
        contract = _authored_sequence_annotation_contract(annotation)
        if contract is None:
            continue
        _policy, _column_count, _writable, dtypes = contract
        if len(dtypes) == declared[int(sequence_id)]:
            contracts[int(sequence_id)] = tuple(map(str, dtypes))
    for parameter_name, record in _graph_sequence_record_abi(graph_obj).items():
        dtypes = tuple(dtype for _name, dtype in _record_row_physical_columns(record))
        if not dtypes:
            continue
        sequence_id = next((
            int(value_id)
            for value_id in identities.get(str(parameter_name), ())
            if int(value_id) in declared
        ), None)
        if (
            sequence_id is not None
            and len(dtypes) == declared[int(sequence_id)]
        ):
            contracts[int(sequence_id)] = dtypes
    for binding_name, annotation in dict(
        graph_obj.graph.get("type_annotations") or {}
    ).items():
        if not isinstance(annotation, str) or not annotation.strip():
            continue
        try:
            outer = ast.parse(annotation, mode="eval").body
        except SyntaxError:
            continue
        history = tuple(map(int, identities.get(str(binding_name), ())))
        sequence_id = next(
            (value_id for value_id in history if value_id in declared), None
        )
        direct_contract = _authored_sequence_annotation_contract(annotation)
        if direct_contract is not None and sequence_id is not None:
            _policy, _column_count, _writable, dtypes = direct_contract
            if len(dtypes) == declared[sequence_id]:
                contracts[int(sequence_id)] = tuple(map(str, dtypes))
                continue
        if not isinstance(outer, ast.Subscript):
            continue
        row = outer.slice
        if not isinstance(row, ast.Subscript):
            continue
        tuple_name = row.value
        if not (
            isinstance(tuple_name, ast.Name) and tuple_name.id in {"tuple", "Tuple"}
            or isinstance(tuple_name, ast.Attribute)
            and tuple_name.attr in {"tuple", "Tuple"}
        ):
            continue
        columns = (
            tuple(row.slice.elts)
            if isinstance(row.slice, ast.Tuple)
            else (row.slice,)
        )
        dtypes: list[str] = []
        for column in columns:
            spelling = (
                column.id if isinstance(column, ast.Name)
                else column.attr if isinstance(column, ast.Attribute)
                else ""
            )
            dtype = scalar_dtypes.get(str(spelling))
            if dtype is None:
                dtypes = []
                break
            dtypes.append(dtype)
        if not dtypes:
            continue
        if sequence_id is None or len(dtypes) != declared[sequence_id]:
            continue
        contracts[int(sequence_id)] = tuple(dtypes)
    def literal_dtype(value: Any) -> str | None:
        if isinstance(value, bool):
            return "bool"
        if isinstance(value, int):
            return "int64"
        if isinstance(value, float):
            return "float64"
        if isinstance(value, str):
            return "int64"
        return None

    for node_id, data in graph_obj.nodes(data=True):
        value_id = int(data.get("value_id", node_id))
        if value_id not in declared:
            continue
        items = (data.get("attributes") or {}).get(
            "compile_time_mapping_items"
        )
        attrs = data.get("attributes") or {}
        explicit_dtypes = tuple(map(
            str, attrs.get("sequence_column_dtypes", ())
        ))
        if (
            explicit_dtypes
            and len(explicit_dtypes) == declared[value_id]
            and value_id not in contracts
        ):
            contracts[value_id] = explicit_dtypes
        if attrs.get("mapping_key_dtype") and attrs.get("mapping_value_dtype") and declared[value_id] == 2:
            contracts[value_id] = (str(attrs["mapping_key_dtype"]), str(attrs["mapping_value_dtype"]))
        if items is None and isinstance(data.get("expr_obj"), ast.Dict):
            try:
                items = tuple(ast.literal_eval(data["expr_obj"]).items())
            except (ValueError, TypeError):
                pass
        if items is None:
            continue
        rows = tuple(items)
        if not rows:
            continue
        key_dtypes = {literal_dtype(key) for key, _item in rows}
        value_dtypes = {literal_dtype(item) for _key, item in rows}
        if None not in key_dtypes | value_dtypes and (
            len(key_dtypes) == len(value_dtypes) == 1
        ):
            contracts[value_id] = (
                next(iter(key_dtypes)), next(iter(value_dtypes))
            )
    mapping_mutations = _source_mapping_mutations(graph_obj)
    for mutation in mapping_mutations:
        destination = int(mutation.sequence_value_id)
        if mutation.operator != "update" or destination in contracts:
            continue
        dtypes = tuple(literal_dtype(
            (graph_obj.nodes.get(int(value), {}).get("attributes") or {}).get("value")
        ) for value in mutation.argument_value_ids)
        if len(dtypes) == 2 and None not in dtypes:
            contracts[destination] = dtypes
    # A snapshot shares its source's row schema, but owns different storage.
    # Infer homogeneous scalar append rows together, never from only the
    # first write (which could choose a Boolean schema before a float row).
    append_dtypes: dict[int, set[str | None]] = {}
    for mutation in _sequence_append_call_mutations(graph_obj):
        destination = int(mutation.sequence_value_id)
        if mutation.operator != "append" or declared.get(destination) != 1:
            continue
        if len(mutation.argument_value_ids) != 1:
            continue
        value = graph_obj.nodes.get(int(mutation.argument_value_ids[0]), {})
        expression = value.get("expr_obj")
        literal = expression.value if isinstance(expression, ast.Constant) else (value.get("attributes") or {}).get("value")
        append_dtypes.setdefault(destination, set()).add(literal_dtype(literal))
    for destination, dtypes in append_dtypes.items():
        if destination not in contracts and len(dtypes) == 1 and None not in dtypes:
            contracts[destination] = (next(iter(dtypes)),)
    copies = [mutation for mutation in (*mapping_mutations, *_source_sequence_snapshots(graph_obj))
              if mutation.operator == "replace"]
    declaration_specs = {
        int(sequence_id): (str(policy), int(column_count))
        for sequence_id, policy, column_count, _writable
        in sequence_declarations
    }
    materialized_copies: list[tuple[int, int]] = []
    for node_id, data in graph_obj.nodes(data=True):
        destination = int(data.get("value_id", node_id))
        attributes = data.get("attributes") or {}
        sources = tuple(map(
            int, attributes.get(
                "materialized_source_value_ids", ()
            )
        ))
        if (
            destination in declaration_specs
            and len(sources) == 1
            and sources[0] in declaration_specs
            and declaration_specs[destination] == declaration_specs[sources[0]]
        ):
            materialized_copies.append((destination, sources[0]))
        if (
            data.get("type") == "Phi"
            and attributes.get("aggregate_kind")
            and destination in declaration_specs
        ):
            for parent_id, _role in data.get("parents", ()):
                parent_id = int(parent_id)
                if (
                    parent_id in declaration_specs
                    and declaration_specs[destination]
                    == declaration_specs[parent_id]
                ):
                    materialized_copies.append((destination, parent_id))
    changed = True
    while changed:
        changed = False
        for mutation in copies:
            source = contracts.get(int(mutation.argument_value_ids[0]))
            destination = int(mutation.sequence_value_id)
            if source is not None and destination in declared and destination not in contracts:
                contracts[destination] = source
                changed = True
            source_id = int(mutation.argument_value_ids[0])
            expression = graph_obj.nodes.get(source_id, {}).get("expr_obj")
            if (source_id not in contracts and destination in contracts
                    and isinstance(expression, ast.Dict) and not expression.keys):
                # An empty constructor has no conflicting row type. Its copy
                # consumer supplies the storage schema, not runtime contents.
                contracts[source_id] = contracts[destination]
                changed = True
        for destination, source_id in materialized_copies:
            source = contracts.get(source_id)
            destination_contract = contracts.get(destination)
            if source is not None and destination_contract is None:
                contracts[destination] = source
                changed = True
            elif destination_contract is not None and source is None:
                contracts[source_id] = destination_contract
                changed = True
    return contracts


def _sequence_record_identity_contracts(
    graph_obj: Any,
    sequence_declarations: Iterable[tuple[int, str, int, bool]],
) -> dict[int, str]:
    """Correlate resident sequence IDs with declared record-row identities."""

    declared = {int(item[0]) for item in sequence_declarations}
    identities = graph_obj.graph.get("identity_table") or {}
    records = _graph_sequence_record_abi(graph_obj)
    abi_identities = tuple(map(
        str, dict((graph_obj.graph.get("program_abi") or {}).get("records") or {})
    ))
    result: dict[int, str] = {}
    for binding_name, record in records.items():
        sequence_id = next((
            int(value_id)
            for value_id in identities.get(str(binding_name), ())
            if int(value_id) in declared
        ), None)
        if sequence_id is None:
            continue
        identity = str(record.get("identity") or "")
        canonical = tuple(
            candidate for candidate in abi_identities
            if candidate == identity or candidate.rsplit(".", 1)[-1] == identity
        )
        if len(canonical) == 1:
            identity = canonical[0]
        if identity:
            result[int(sequence_id)] = identity
    return result


def _authored_source_sequence_ids(
    graph_obj: Any,
    sequence_declarations: Iterable[tuple[int, str, int, bool]],
) -> tuple[int, ...]:
    """Identify resident arenas whose initial contents come from the caller."""

    declared = {
        int(sequence_id) for sequence_id, *_rest in sequence_declarations
    }
    if not declared:
        return ()
    identity = graph_obj.graph.get("identity_table") or {}
    source_ids = {
        int(value_id)
        for parameter_name in graph_obj.graph.get("function_parameters") or ()
        for value_id in identity.get(str(parameter_name), ())
        if int(value_id) in declared
    }
    self_fields = {
        str(field_name)
        for field_name, receipt in dict(
            dict(
                (graph_obj.graph.get("parameter_record_abi") or {}).get(
                    "self"
                ) or {}
            ).get("fields") or {}
        ).items()
        if str(receipt.get("storage") or "") == "span"
    }
    for node_id, data in graph_obj.nodes(data=True):
        value_id = int(data.get("value_id", node_id))
        if value_id not in declared:
            continue
        attributes = data.get("attributes") or {}
        if str(attributes.get("binding_kind") or "") in {
            "parameter", "closure", "external",
        }:
            source_ids.add(value_id)
            continue
        operation = str(data.get("op") or data.get("type") or "").casefold()
        if (
            operation == "getattr"
            and str(attributes.get("attribute") or "") in self_fields
        ):
            source_ids.add(value_id)
    return tuple(sorted(source_ids))


def _linked_authored_parameter_aliases(
    caller: Any,
    callee: Any,
    caller_graph: Any,
    callee_graph: Any,
    argument_bindings: Any,
    caller_record_table: Any = None,
    callee_record_table: Any = None,
) -> dict[str, str]:
    """Map a linked callee formal onto an outer authored formal exactly.

    Method record fields retain their local spelling (usually ``self``).
    When the exact PlanCall binding says an authored caller parameter such as
    ``body`` supplies that receiver, the public ABI must expose
    ``body.field`` rather than ``self.field``.  Only deterministic formal
    identities participate; later same-spelling SSA versions are not aliases.
    """

    def identities(
        function: Any, graph: Any, record_table: Any,
    ) -> dict[int, str]:
        metadata = dict(getattr(function, "metadata", {}) or {})
        found = {
            int(value_id): str(name)
            for name, value_id in metadata.get("parameter_names", ())
        }
        graph_metadata = (
            dict(getattr(graph, "graph", {}) or {})
            if graph is not None else {}
        )
        identity_table = dict(graph_metadata.get("identity_table") or {})
        parameter_roots = {
            *map(str, dict(metadata.get("parameter_record_abi") or {})),
            *map(str, dict(metadata.get("parameter_value_abi") or {})),
            *map(str, graph_metadata.get("function_parameters", ()) or ()),
        }
        for name in sorted(parameter_roots):
            history = tuple(identity_table.get(name, ()))
            if history:
                found.setdefault(int(history[0]), name)
        # Method shells can remove the shapeless aggregate formal after all
        # fields are projected. The record descriptor still owns its exact
        # deterministic aggregate identity even when the final shell no
        # longer carries the ProcessGraph identity catalogue.
        records = dict(getattr(record_table, "records", {}) or {})
        for name, receipt in dict(
            metadata.get("parameter_record_abi") or {}
        ).items():
            identity = str(dict(receipt or {}).get("identity") or "")
            candidates = [
                int(record_id)
                for record_id, descriptor in records.items()
                if str(getattr(descriptor, "identity", "")) == identity
            ]
            if len(candidates) == 1:
                found.setdefault(candidates[0], str(name))
        return found

    caller_names = identities(caller, caller_graph, caller_record_table)
    callee_names = identities(callee, callee_graph, callee_record_table)
    aliases: dict[str, str] = {}
    ambiguous: set[str] = set()
    for caller_id, callee_id in argument_bindings:
        caller_name = caller_names.get(int(caller_id))
        callee_name = callee_names.get(int(callee_id))
        if caller_name is None or callee_name is None:
            continue
        previous = aliases.setdefault(callee_name, caller_name)
        if previous != caller_name:
            ambiguous.add(callee_name)
    for name in ambiguous:
        aliases.pop(name, None)
    return aliases


def _bind_sequence_storage_members(
    storage_bindings: dict[int, int],
    callee_sequence: Any,
    caller_sequence: Any,
    *,
    provisional_targets: Collection[int] = (),
) -> bool:
    """Bind every physical member of one exact sequence argument."""

    if (
        callee_sequence is None
        or caller_sequence is None
        or len(callee_sequence.column_value_ids)
        != len(caller_sequence.column_value_ids)
    ):
        return False
    provisional_targets = set(map(int, provisional_targets))

    def bind(callee_id: int, caller_id: int) -> None:
        callee_id = int(callee_id)
        caller_id = int(caller_id)
        incumbent = storage_bindings.get(callee_id)
        if incumbent is None or int(incumbent) in provisional_targets:
            storage_bindings[callee_id] = caller_id

    # The descriptor handle is part of the structural frame contract too.
    # Record propagation consults it when rebuilding a nested sequence field;
    # binding only the columns and counters leaves an otherwise exact record
    # with two different sequence identities at the caller boundary.
    bind(int(callee_sequence.sequence_id), int(caller_sequence.sequence_id))
    for callee_id, caller_id in zip(
        map(int, callee_sequence.column_value_ids),
        map(int, caller_sequence.column_value_ids),
    ):
        bind(callee_id, caller_id)
    bind(
        int(callee_sequence.length_address_id),
        int(caller_sequence.length_address_id),
    )
    bind(
        int(callee_sequence.capacity_value_id),
        int(caller_sequence.capacity_value_id),
    )
    for attribute in ("status_address_id", "live_flags_value_id"):
        callee_member = getattr(callee_sequence, attribute, None)
        caller_member = getattr(caller_sequence, attribute, None)
        if callee_member is not None and caller_member is not None:
            bind(int(callee_member), int(caller_member))
    return True


def _sequence_length_values(
    graph_obj: Any,
    sequence_declarations: Iterable[tuple[int, str, int, bool]],
    aliases: Mapping[int, int] | Iterable[tuple[int, int]] = (),
) -> dict[int, int]:
    """Map authored ``len(sequence)`` results to resident descriptors."""

    declared = {
        int(sequence_id)
        for sequence_id, _policy, _columns, _writable
        in sequence_declarations
    }
    resident = {value_id: value_id for value_id in declared}
    resident.update({
        int(alias): int(source)
        for alias, source in dict(aliases).items()
    })
    changed = True
    while changed:
        changed = False
        for alias, source in tuple(resident.items()):
            target = resident.get(int(source))
            if target is not None and resident.get(int(alias)) != target:
                resident[int(alias)] = int(target)
                changed = True
    values = {}
    for node_id, data in graph_obj.nodes(data=True):
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id == "len"
        ):
            continue
        arguments = tuple(
            int(parent)
            for parent, role in data.get("parents") or ()
            if str(role).startswith("arg:") and parent in graph_obj
        )
        if len(arguments) != 1:
            continue
        argument_id = int(graph_obj.nodes[arguments[0]].get(
            "value_id", arguments[0]
        ))
        sequence_id = resident.get(argument_id)
        if sequence_id in declared:
            values[int(data.get("value_id", node_id))] = int(sequence_id)
    return values


def _call_argument_identity(
    owner_function: Any, value: Any, parameter_names_by_id: Mapping[int, str],
) -> tuple[str, Any] | None:
    """The one stable identity a call argument or formal carries, if any.

    Three sources, checked in order, all already computed elsewhere in this
    module for other reasons -- this does not invent new facts, it is the
    first place that reads them uniformly regardless of what KIND of value
    is being asked about:

    - a materialized record field carries its own name (``program_abi_field``,
      e.g. ``"error_channels.keys"``, ``"hard_failure"``);
    - a frame-storage slot appended to complete a callee's grown signature
      carries the id of the formal it was propagated for
      (``propagated_formal_id``);
    - an ordinary value that IS one of its own function's declared
      parameters (state, dt, a plain scalar -- forwarded straight through,
      not derived from a record at all) carries that parameter's own
      source-level name, via the function's ``parameter_names`` metadata.

    Anything reaching none of these three is a genuinely anonymous
    intermediate value used directly as an argument; there is no fact
    anywhere recording what it is, and this function says so honestly
    (``None``) rather than falling back to guessing from position.
    """

    accounting = dict(value.accounting or {})
    field = accounting.get("program_abi_field")
    if field is not None:
        return ("field", str(field))
    propagated = accounting.get("propagated_formal_id")
    if propagated is not None:
        return ("propagated", int(propagated))
    name = parameter_names_by_id.get(int(value.id))
    if name is not None:
        return ("parameter", str(name))
    return None


def _propagate_record_field_demand(all_functions: Mapping[str, Any]) -> None:
    """Grow a caller's formals to include every record field a callee it
    calls needs, transitively, before anything tries to align call shapes.

    A field is materialized into a function's OWN formal list only for
    fields that function's OWN body directly references (the ``if not
    candidates: continue`` skip in the nested-record materializer).  That
    is correct in isolation and wrong across a call: a function that only
    FORWARDS a whole record (``_propose_dt_pen(metrics, targets, dx,
    distribution)`` from inside ``step_with_dt_control_used``, never
    touching ``targets.cfl`` itself) never gets that field materialized,
    even though its callee needs it expanded.  There is no "whole record
    pointer" to extract the field from at this level once fields ARE
    materialized -- each becomes its own independent physical value, the
    same way :func:`_prune_unused_callee_formals`'s frame-storage
    completion (``linked_call_frame_storage``) grows a caller for a
    propagated storage slot it does not itself use, just for a different
    kind of need: a record field instead of frame storage.  That existing
    completion runs too late to help here -- at the very end of this
    module's lowering, well after the call-shape unification this feeds
    already has to have run -- so this is the same technique, run early.

    Growing is the only thing this does: it only ever APPENDS a new
    formal, copying the callee's own field metadata verbatim (with
    ``program_abi_field_written`` reset to ``False`` -- the caller is
    forwarding, never writing, whatever it does not already write itself),
    to both the caller's formal list and this one call's argument list.
    Nothing is removed, reordered, or guessed at; the CORRESPONDING
    reorder, once every needed field genuinely exists somewhere in the
    caller, is :func:`_harmonize_call_argument_shapes`'s job, called right
    after this.  Iterated to a fixed point exactly like frame-storage
    completion, so demand reaches as far up the call graph as it needs to.
    """

    from ..transmogrifier.ssa import SSAValue

    grew = True
    while grew:
        grew = False
        for caller in all_functions.values():
            caller_fields = {
                ((formal.accounting or {}).get("program_abi_record"),
                 (formal.accounting or {}).get("program_abi_field")): formal
                for formal in caller.args
                if (formal.accounting or {}).get("program_abi_field") is not None
            }
            for block in caller.blocks.values():
                for instruction in block.instrs:
                    if (
                        instruction.op not in {"Call", "call"}
                        or instruction.attributes.get("tensor_operation")
                    ):
                        continue
                    callee = all_functions.get(str(
                        instruction.attributes.get("callee") or ""
                    ))
                    if callee is None:
                        continue
                    supplied = {
                        ((argument.accounting or {}).get("program_abi_record"),
                         (argument.accounting or {}).get("program_abi_field"))
                        for argument in instruction.args
                        if (argument.accounting or {}).get(
                            "program_abi_field"
                        ) is not None
                    }
                    declared = instruction.attributes.get("callee_input_ids")
                    if declared is not None and len(declared) != len(instruction.args):
                        raise ValueError("native call input receipt and operands disagree")
                    for formal in callee.args:
                        formal_accounting = dict(formal.accounting or {})
                        field = formal_accounting.get("program_abi_field")
                        if field is None:
                            continue
                        key = (formal_accounting.get("program_abi_record"), field)
                        if (int(formal.id) in declared if declared is not None else key in supplied):
                            continue
                        existing = caller_fields.get(key)
                        if existing is not None:
                            # Already materialized somewhere in the caller
                            # (a different call, or its own body) -- this
                            # call just needs to carry the SAME value, not
                            # a new one.
                            instruction.args.append(existing)
                        else:
                            propagated = SSAValue(
                                GLOBAL_MONOTONIC_IDS.mint(),
                                dtype=formal.dtype,
                                shape=tuple(formal.shape or ()),
                                device=formal.device,
                                accounting={
                                    **formal_accounting,
                                    "program_abi_field_written": False,
                                },
                            )
                            caller.args.append(propagated)
                            caller_fields[key] = propagated
                            instruction.args.append(propagated)
                        if declared is not None:
                            declared = (*declared, int(formal.id))
                            instruction.attributes["callee_input_ids"] = declared
                        supplied.add(key)
                        grew = True


def _harmonize_call_argument_shapes(all_functions: Mapping[str, Any]) -> None:
    """Make every call site into one specialized callee agree on argument
    shape, before any dtype/rank fact is unified over them.

    Two callees sharing a record-typed value (or a caller's own forwarded
    parameter) each materialize their OWN formal list independently, from
    their OWN body's references -- one skips a field the other keeps, and
    the same logical value ends up at different positions.  The call-type
    unification loop that runs after this one trusts plain position; a
    mispaired (actual, formal) can never converge there, because the pair
    names two different things to begin with (this is the exact defect
    diagnosed on the managed tire build across 2026-09-03/04, down to the
    specific value: an ``error_channels.keys`` array bound against a
    ``hard_failure`` scalar formal, purely from an unrelated argument-count
    drift earlier in the same call's argument list).

    This realigns each call's argument list to its callee's formal order by
    IDENTITY (:func:`_call_argument_identity`), not position -- the callee's
    own formal list is never touched, so nothing a DIFFERENT caller depends
    on can be removed.  A call is only ever changed when every one of its
    identified arguments has an exact, unambiguous counterpart among the
    callee's identified formals; anything left unidentified on either side
    must already agree in count, in its own existing relative order, or the
    call is named precisely and left for the caller (a human) to resolve --
    never silently paired by leftover position, which is how this defect
    was produced in the first place.
    """

    calls_by_callee: dict[str, list[tuple[Any, Any]]] = {}
    for caller in all_functions.values():
        for block in caller.blocks.values():
            for instruction in block.instrs:
                if (
                    instruction.op not in {"Call", "call"}
                    or instruction.attributes.get("tensor_operation")
                ):
                    continue
                callee_name = str(instruction.attributes.get("callee") or "")
                if callee_name not in all_functions:
                    continue
                calls_by_callee.setdefault(callee_name, []).append(
                    (caller, instruction)
                )

    parameter_names_cache: dict[str, dict[int, str]] = {}

    def parameter_names_of(function: Any) -> dict[int, str]:
        cached = parameter_names_cache.get(function.name)
        if cached is not None:
            return cached
        names = {
            int(value_id): str(name)
            for name, value_id in (
                (function.metadata or {}).get("parameter_names", ())
            )
        }
        parameter_names_cache[function.name] = names
        return names

    for callee_name, sites in calls_by_callee.items():
        callee = all_functions[callee_name]
        callee_names = parameter_names_of(callee)
        formal_identities = [
            _call_argument_identity(callee, formal, callee_names)
            for formal in callee.args
        ]
        formal_positions: dict[tuple[str, Any], int] = {}
        ambiguous_formal = False
        for position, identity in enumerate(formal_identities):
            if identity is None:
                continue
            if identity in formal_positions:
                ambiguous_formal = True
                break
            formal_positions[identity] = position
        unnamed_formal_count = sum(
            1 for identity in formal_identities if identity is None
        )
        if unnamed_formal_count == len(formal_identities) and not any(
            instruction.attributes.get("callee_input_ids") is not None
            for _caller, instruction in sites
        ):
            # No formal on this callee carries any identity at all -- not a
            # record consumer, not one of an authored function's own named
            # parameters.  This is a compiler-synthesized positional
            # primitive (a generated sequence-insert helper, for example),
            # for which position IS the whole and correct contract; there is
            # nothing here for identity to improve on, so leave it exactly
            # as it already works.
            continue
        for caller, instruction in sites:
            declared = instruction.attributes.get("callee_input_ids")
            if declared is not None:
                if len(declared) != len(instruction.args) or len(set(declared)) != len(declared):
                    raise ValueError(f"invalid native input binding receipt for {callee_name}")
                bound = dict(zip(declared, instruction.args))
                formal_ids = tuple(int(formal.id) for formal in callee.args)
                if all(value_id in bound for value_id in formal_ids):
                    instruction.args = [bound[value_id] for value_id in formal_ids]
                    instruction.attributes["callee_input_ids"] = formal_ids
                # An incomplete exact binding cannot be repaired from names.
                continue
            if ambiguous_formal:
                continue
            caller_names = parameter_names_of(caller)
            actual_identities = [
                _call_argument_identity(caller, actual, caller_names)
                for actual in instruction.args
            ]
            if actual_identities == formal_identities:
                continue
            actual_positions: dict[tuple[str, Any], int] = {}
            ambiguous_actual = False
            for position, identity in enumerate(actual_identities):
                if identity is None:
                    continue
                if identity in actual_positions:
                    ambiguous_actual = True
                    break
                actual_positions[identity] = position
            if ambiguous_actual:
                continue
            if set(actual_positions) != set(formal_positions):
                # An identified field/parameter appears on one side and
                # not the other: this call cannot supply what the callee
                # needs, or supplies something it has no formal for.  Not
                # a position problem this pass can fix by realigning.
                continue
            unnamed_actual_positions = [
                position for position, identity in enumerate(actual_identities)
                if identity is None
            ]
            if len(unnamed_actual_positions) != unnamed_formal_count:
                # The identified portion matches perfectly; the remainder
                # on each side has no identity at all to align by, and
                # there are different numbers of them.  Naming this
                # precisely, instead of leaving it to surface later as an
                # unrelated dtype conflict between two named fields three
                # positions further down the list.
                raise ValueError(
                    "call argument shapes cannot be harmonized: "
                    f"{caller.name!r} -> {callee_name!r} supplies "
                    f"{len(unnamed_actual_positions)} argument(s) with no "
                    "identity (not a record field, not a propagated frame "
                    "slot, not one of the caller's own named parameters), "
                    f"the callee has {unnamed_formal_count} such formal "
                    "position(s); an unidentified remainder must already "
                    "agree in count to be aligned safely; unidentified "
                    "actuals="
                    f"{[(int(instruction.args[p].id), str(instruction.args[p].dtype), sorted((instruction.args[p].accounting or {}).keys())) for p in unnamed_actual_positions]!r} "
                    "unidentified formals="
                    f"{[(int(formal.id), str(formal.dtype), sorted((formal.accounting or {}).keys())) for formal, identity in zip(callee.args, formal_identities) if identity is None]!r} "
                    "formal consumers="
                    f"{[(int(formal.id), [(str(block_name), str(consumer.op), str(consumer.attributes.get('callee') or consumer.attributes.get('binding') or '')) for block_name, block in callee.blocks.items() for consumer in block.instrs if any(int(argument.id) == int(formal.id) for argument in consumer.args)]) for formal, identity in zip(callee.args, formal_identities) if identity is None]!r} "
                    "call actuals="
                    f"{[(int(a.id), str(a.dtype), identity) for a, identity in zip(instruction.args, actual_identities)]!r} "
                    "callee formals="
                    f"{[(int(f.id), str(f.dtype), identity) for f, identity in zip(callee.args, formal_identities)]!r} "
                    "call attributes="
                    f"{sorted(instruction.attributes.keys())!r}"
                )
            realigned = [None] * len(callee.args)
            for identity, formal_position in formal_positions.items():
                realigned[formal_position] = instruction.args[
                    actual_positions[identity]
                ]
            for unnamed_formal_position, unnamed_actual_position in zip(
                (
                    position for position, identity in enumerate(formal_identities)
                    if identity is None
                ),
                unnamed_actual_positions,
            ):
                realigned[unnamed_formal_position] = instruction.args[
                    unnamed_actual_position
                ]
            assert all(value is not None for value in realigned)
            instruction.args = realigned


def _rehome_structured_while_predicate_regions(
    control: Any,
    dispatch_subgraphs: Iterable[Any],
) -> tuple[Any, tuple[tuple[int, int, tuple[int, ...], str], ...]]:
    """Move exact structured-predicate regions into their owning while.

    Persisted shell plans can predate structural control recovery.  In that
    form, an arithmetic region used by ``(tensor - carried).item() > eps``
    remains in the flat schedule even though the WhileBlock's expression
    consumes its result on both the entry and latch evaluations.  Rehome only
    a region whose complete deployment-node set consists of computed (not
    captured leaf) identities in exactly one while predicate.  Ambiguous or
    mixed regions retain their incumbent placement.
    """

    from .control_source import (
        CallBlock,
        ConditionalBlock,
        LoopBlock,
        SequenceBlock,
        StatementBlock,
        WhileBlock,
    )

    region_nodes = {
        int(index): frozenset(map(
            int, subgraph.G.graph.get("deployment_nodes", ())
        ))
        for index, subgraph in enumerate(dispatch_subgraphs)
    }

    def marker_region(block: Any) -> int | None:
        if not isinstance(block, StatementBlock) or len(block.lines) != 1:
            return None
        match = re.fullmatch(r"__scheduled_region_(\d+)__", str(block.lines[0]))
        return None if match is None else int(match.group(1))

    present_regions: set[int] = set()

    def computed_expression_ids(expression: Any) -> frozenset[int]:
        if expression is None or str(expression.op) == "value":
            return frozenset()
        found = {
            int(expression.value_id)
            for _ in (0,)
            if expression.value_id is not None
        }
        for operand in expression.operands:
            found.update(computed_expression_ids(operand))
        return frozenset(found)

    loop_candidates: dict[int, set[int]] = {}

    def discover(block: Any) -> None:
        region = marker_region(block)
        if region is not None:
            present_regions.add(region)
        if isinstance(block, SequenceBlock):
            for child in block.blocks:
                discover(child)
        elif isinstance(block, ConditionalBlock):
            discover(block.body)
            if block.orelse is not None:
                discover(block.orelse)
        elif isinstance(block, LoopBlock):
            discover(block.body)
        elif isinstance(block, WhileBlock):
            loop_id = block.source_loop_node_id
            computed = computed_expression_ids(block.predicate_expression)
            if loop_id is not None and computed:
                loop_candidates[int(loop_id)] = {
                    region_index
                    for region_index, nodes in region_nodes.items()
                    if nodes and nodes.issubset(computed)
                }
            discover(block.condition)
            discover(block.body)
        elif isinstance(block, CallBlock):
            discover(block.callee)

    discover(control.root)
    owners: dict[int, list[int]] = {}
    for loop_id, candidates in loop_candidates.items():
        for region_index in candidates & present_regions:
            owners.setdefault(int(region_index), []).append(int(loop_id))
    owned = {
        int(region_index): int(loop_ids[0])
        for region_index, loop_ids in owners.items()
        if len(set(loop_ids)) == 1
    }
    if not owned:
        return control, ()

    region_order = {
        int(region_index): position
        for position, region_index in enumerate(control.region_indices)
    }
    by_loop: dict[int, list[int]] = {}
    for region_index, loop_id in owned.items():
        by_loop.setdefault(loop_id, []).append(region_index)
    for regions in by_loop.values():
        regions.sort(key=lambda value: region_order.get(value, value))

    def rewrite(block: Any) -> Any:
        region = marker_region(block)
        if region in owned:
            return SequenceBlock(())
        if isinstance(block, SequenceBlock):
            children = tuple(rewrite(child) for child in block.blocks)
            return replace(block, blocks=tuple(
                grandchild
                for child in children
                for grandchild in (
                    child.blocks if isinstance(child, SequenceBlock) else (child,)
                )
            ))
        if isinstance(block, ConditionalBlock):
            return replace(
                block,
                body=rewrite(block.body),
                orelse=(
                    None if block.orelse is None else rewrite(block.orelse)
                ),
            )
        if isinstance(block, LoopBlock):
            return replace(block, body=rewrite(block.body))
        if isinstance(block, WhileBlock):
            condition = rewrite(block.condition)
            prefix = tuple(
                StatementBlock((f"__scheduled_region_{region_index}__",))
                for region_index in by_loop.get(
                    (
                        -1
                        if block.source_loop_node_id is None
                        else int(block.source_loop_node_id)
                    ),
                    (),
                )
            )
            existing = (
                condition.blocks
                if isinstance(condition, SequenceBlock) else (condition,)
            )
            return replace(
                block,
                condition=SequenceBlock((*prefix, *existing)),
                body=rewrite(block.body),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=rewrite(block.callee))
        return block

    receipts = tuple(
        (
            int(loop_id),
            int(region_index),
            tuple(sorted(region_nodes[region_index])),
            "structured_while_predicate_operation",
        )
        for region_index, loop_id in sorted(owned.items())
    )
    return replace(control, root=rewrite(control.root)), receipts


def _apply_phi_initial_identity_repairs_to_control(control, receipts):
    """Project graph Phi-incumbent repairs into already-planned Control IR."""
    if control is None or not receipts:
        return control
    repairs = {
        (
            int(receipt["phi_value_id"]),
            int(receipt["missing_initial_value_id"]),
        ): int(receipt["resident_initial_value_id"])
        for receipt in receipts
    }
    from .control_source import (
        CallBlock, ConditionalBlock, LoopBlock, ParallelDeployment,
        ResourceScopeBlock, SequenceBlock, StateMachineTick, WhileBlock,
    )

    def rewrite(block):
        if isinstance(block, ConditionalBlock):
            carried = []
            for true_id, false_id, initial_id, merged_id in (
                block.carried_aliases
            ):
                replacement = repairs.get((
                    int(merged_id), int(initial_id)
                ))
                if replacement is None:
                    carried.append((
                        true_id, false_id, initial_id, merged_id,
                    ))
                    continue
                carried.append((
                    replacement if int(true_id) == int(initial_id)
                    else int(true_id),
                    replacement if int(false_id) == int(initial_id)
                    else int(false_id),
                    replacement,
                    int(merged_id),
                ))
            return replace(
                block,
                body=rewrite(block.body),
                orelse=(
                    None if block.orelse is None else rewrite(block.orelse)
                ),
                carried_aliases=tuple(carried),
            )
        if isinstance(block, SequenceBlock):
            return replace(
                block, blocks=tuple(rewrite(item) for item in block.blocks)
            )
        if isinstance(block, LoopBlock):
            return replace(block, body=rewrite(block.body))
        if isinstance(block, WhileBlock):
            return replace(
                block,
                condition=rewrite(block.condition),
                body=rewrite(block.body),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=rewrite(block.callee))
        if isinstance(block, ParallelDeployment):
            return replace(
                block, lanes=tuple(rewrite(lane) for lane in block.lanes)
            )
        if isinstance(block, StateMachineTick):
            return replace(
                block,
                cases=tuple((case, rewrite(body)) for case, body in block.cases),
                default=(
                    None if block.default is None else rewrite(block.default)
                ),
            )
        if isinstance(block, ResourceScopeBlock):
            return replace(block, body=rewrite(block.body))
        return block

    return replace(control, root=rewrite(control.root))


def _drop_formals_and_call_operands(
    all_functions: Mapping[str, Any],
    function: Any,
    dropped_positions: Iterable[int],
) -> None:
    """Drop formals by position and the matching operand at every call site.

    A formal exists only together with the operand every caller feeds it.
    Dropping the formal alone leaves each call site one operand too long,
    and the public-span origin walk skips calls whose arity disagrees --
    silently severing every span reached through this function for every
    caller above it.  ``callee_input_ids`` receipts are trimmed in step.
    """

    dropped = set(map(int, dropped_positions))
    if not dropped:
        return
    original_arity = len(function.args)
    function.args = [
        value
        for position, value in enumerate(function.args)
        if position not in dropped
    ]
    function_symbol = next(
        (
            candidate_symbol
            for candidate_symbol, candidate in all_functions.items()
            if candidate is function
        ),
        None,
    )
    if function_symbol is None:
        return
    for caller in all_functions.values():
        for block in caller.blocks.values():
            for instruction in block.instrs:
                if (
                    instruction.op != "Call"
                    or str(
                        instruction.attributes.get("callee") or ""
                    ) != function_symbol
                    or len(instruction.args) != original_arity
                ):
                    continue
                instruction.args = [
                    argument
                    for position, argument in enumerate(instruction.args)
                    if position not in dropped
                ]
                declared = instruction.attributes.get("callee_input_ids")
                if declared is not None:
                    instruction.attributes["callee_input_ids"] = tuple(
                        value_id for position, value_id in enumerate(declared)
                        if position not in dropped
                    )


def _strip_dead_cell_bookkeeping(function: Any, members: set[int]) -> set[int]:
    """Remove the bookkeeping of storage cells nothing reads anymore.

    ``members`` are cell ids (a retired sequence's handle, columns, length,
    capacity, status).  Their bookkeeping is the address derivation over a
    cell (``GetElementPtr``/casts, ``ssa_local_sequence_length``) and the
    stores through those addresses (``ssa_local_sequence_initialize``,
    ``ssa_sequence_clear``).  A store touches the derived address, not the
    cell, so the closure runs forward over address derivation first; then
    every instruction that touches a member and whose result feeds nothing
    else is removed, to a fixed point, so the derivation goes once its
    store is gone.  A ``Load`` whose result is consumed is a real read and
    keeps the cell alive: it is left in place and the caller keeps the
    formal.  Returns the enlarged member set.
    """

    members = set(map(int, members))
    address_ops = {"GetElementPtr", "gep", "Cast", "cast_like", "BitCast"}
    grown = True
    while grown:
        grown = False
        for block in function.blocks.values():
            for instruction in block.instrs:
                if instruction.res is None or instruction.op not in address_ops:
                    continue
                if any(int(argument.id) in members for argument in instruction.args):
                    if int(instruction.res.id) not in members:
                        members.add(int(instruction.res.id))
                        grown = True
    changed = True
    while changed:
        changed = False
        consumers: dict[int, int] = {}
        for block in function.blocks.values():
            for instruction in block.instrs:
                for argument in instruction.args:
                    consumers[int(argument.id)] = (
                        consumers.get(int(argument.id), 0) + 1
                    )
        for block in function.blocks.values():
            kept = []
            for instruction in block.instrs:
                touches = any(
                    int(argument.id) in members for argument in instruction.args
                )
                result_id = (
                    None if instruction.res is None else int(instruction.res.id)
                )
                unused_result = (
                    result_id is None or consumers.get(result_id, 0) == 0
                )
                if (
                    touches
                    and unused_result
                    and instruction.op not in {
                        "Call", "call", "Ret", "ret", "Br", "CondBr",
                    }
                ):
                    if result_id is not None:
                        members.add(result_id)
                    changed = True
                    continue
                kept.append(instruction)
            block.instrs = kept
    return members


def _prune_dead_local_sequences(
    all_functions: Mapping[str, Any],
    all_sequence_tables: Mapping[str, Any],
) -> int:
    """Remove sequence descriptors whose storage the function never has.

    Structural specialization can select away the producer of a local
    sequence -- ``channels = metrics.error_channels or {}`` keeps the field
    and drops the ``{}`` -- while the descriptor minted for that literal
    survives, together with the length/status cells it was given as leased
    frame formals and the entry ``clear`` store into them.  Nothing ever
    defines the descriptor's handle or columns, so nothing can read the
    sequence; the leftover is a formal every caller must lease storage for
    and a store into it, i.e. exactly the "no caller can know what to pass"
    signature (identity_concordance: ``descriptor-member-unknown``).

    A descriptor is dead when neither its handle nor any column is a formal
    or defined by an instruction of the function.  Its bookkeeping is
    removed (any instruction touching only its cells whose result is
    otherwise unused), the descriptor is unregistered, and member formals
    left without a consumer are dropped with their call operands.  Returns
    the number of descriptors removed.
    """

    removed = 0
    for symbol, function in all_functions.items():
        table = all_sequence_tables.get(str(symbol))
        if table is None or not table.sequences:
            continue
        formal_ids = {int(value.id) for value in function.args}
        defined_ids = {
            int(instruction.res.id)
            for block in function.blocks.values()
            for instruction in block.instrs
            if instruction.res is not None
        }
        for sequence_id, descriptor in tuple(table.sequences.items()):
            handle = int(descriptor.sequence_id)
            columns = tuple(map(int, descriptor.column_value_ids))
            if any(
                value_id in formal_ids or value_id in defined_ids
                for value_id in (handle, *columns)
            ):
                continue
            members = {
                handle, *columns,
                int(descriptor.length_address_id),
                int(descriptor.capacity_value_id),
                *((int(descriptor.status_address_id),)
                  if descriptor.status_address_id is not None else ()),
                *((int(descriptor.live_flags_value_id),)
                  if descriptor.live_flags_value_id is not None else ()),
            }
            members = _strip_dead_cell_bookkeeping(function, members)
            still_consumed = {
                int(argument.id)
                for block in function.blocks.values()
                for instruction in block.instrs
                for argument in instruction.args
            }
            # Stamp every RETAINED member before the descriptor goes.
            #
            # Below, a member formal that nothing consumes is dropped -- but
            # one that is still consumed is kept, and once the descriptor is
            # unregistered nothing can say what that formal was.  The pass
            # that builds ``storage_formals`` learns a cell's identity by
            # walking the surviving descriptors, so an orphaned member is
            # never stamped, never enters the ledger, and arrives at the
            # full-native contract as a formal with no accounting at all --
            # "no caller can know what to pass" -- even though its caller
            # does lease it a slot.
            #
            # This is the last moment the identity exists, so record it
            # here, with the same keys the descriptor walk would have
            # written. Measured on the two-piece llvm_dt_system product:
            # exactly two such formals, both sequence length-address cells.
            ordered_members = (
                *map(int, descriptor.column_value_ids),
                int(descriptor.length_address_id),
                int(descriptor.capacity_value_id),
                *((int(descriptor.status_address_id),)
                  if descriptor.status_address_id is not None else ()),
                *((int(descriptor.live_flags_value_id),)
                  if descriptor.live_flags_value_id is not None else ()),
            )
            member_positions = {
                value_id: index
                for index, value_id in enumerate(ordered_members)
            }
            for argument in function.args:
                value_id = int(argument.id)
                if (
                    value_id not in members
                    or value_id not in still_consumed
                ):
                    continue
                accounting = dict(argument.accounting or {})
                if any(accounting.get(key) not in {None, ""} for key in (
                    "program_abi_parameter",
                    "linked_call_frame_storage",
                    "returned_record_storage",
                    "compiler_frame_storage",
                )):
                    continue
                argument.accounting = {
                    **accounting,
                    "compiler_frame_storage": str(function.name),
                    "compiler_frame_sequence_id": int(sequence_id),
                    # -1 marks the descriptor handle itself, which the
                    # descriptor walk never indexes as a member.
                    "compiler_frame_member": int(
                        member_positions.get(value_id, -1)
                    ),
                    "compiler_frame_orphaned_descriptor": True,
                }
            del table.sequences[sequence_id]
            removed += 1
            _drop_formals_and_call_operands(
                all_functions, function, [
                    position
                    for position, value in enumerate(function.args)
                    if int(value.id) in members
                    and int(value.id) not in still_consumed
                ],
            )
            formal_ids = {int(value.id) for value in function.args}
    return removed

_LITERAL_ABSENT = object()


def _class_surface_ssa_program(
    compilation: Any,
    artifact_name: str,
    *,
    tensor_ssa_reference: Any = None,
    progress: Callable[[str], None] | None = None,
):
    """Lower every planned method of a whole object to one reusable SSA unit.

    This is the whole-object emission path and it performs NO numeric
    projection.  Each method lowers its own control program plus the operator
    regions the planner already carved out -- straight through
    ``lower_control_sections_to_ssa`` -- so a method with no numeric region (a
    void constructor) and a method with one (a ``mul``) lower the same way, and
    neither builds or validates a ``FusedProgram``.  Every method becomes its
    own linkable export; nothing is folded into a single entry and nothing is
    pruned.

    This boundary deliberately precedes Fortran emission so the fully lowered
    whole-object SSA can be inspected and verified before target emission.
    """

    from ..transmogrifier.ssa import (
        IRModule, SSAMachineControlTable, SSAMachineIndirectTable,
    )
    from .glsl_deployment_strategy import _walk_planned_shells
    from .precompile_to_ssa import (
        SSALoweringShortfall,
        lower_control_sections_to_ssa,
        resolve_sequence_schemas,
    )
    from .identity_concordance import current_identity_book
    from .string_table import StringTable

    program_started = time.monotonic()
    previous_report = program_started

    def report(message: str) -> None:
        nonlocal previous_report
        if progress is None:
            return
        now = time.monotonic()
        progress(
            f"ssa-program +{now - program_started:.1f}s "
            f"(phase +{now - previous_report:.1f}s): {message}"
        )
        previous_report = now

    report(f"start {artifact_name}")

    # The reference is cached compilation INPUT. Linking borrows its Function
    # objects and metadata settlement mutates them (observed with fill_double
    # and binary_value while lowering the energy helper). Own one copy for the
    # entire source program, shared by all its regions, so another compilation
    # cannot inherit this program's shapes or dtypes. Preserve all value ids.
    if tensor_ssa_reference is not None:
        from copy import deepcopy

        tensor_ssa_reference = deepcopy(tensor_ssa_reference)

    # One table for the whole object: every method's string constants tokenize
    # into it, and it persists token -> word for reverse lookup.
    string_table = StringTable()

    all_functions: dict[str, Any] = {}
    all_tensor_tables: dict[str, Any] = {}
    all_sequence_tables: dict[str, Any] = {}
    all_record_tables: dict[str, Any] = {}
    all_reference_tables: dict[str, Any] = {}
    module_metadata: dict[str, Any] = {}
    # The active compile's shared book (``current_identity_book()`` -- the
    # SAME instance every other pass reaches, including tensor_ssa_lowering.py
    # via ``identity_book(module)``, and the top-level entry point's crash
    # log, none of which need this specific ``module`` object to find it):
    # one row per (function, value id, kind of fact), one column per call
    # site processed, so an argument-binding decision made here and a shape
    # fact settled later, both about the same numbered value, land on pages
    # that can be read against each other.
    module_metadata["identity_book"] = current_identity_book()
    argument_binding_page = module_metadata["identity_book"].page(
        "argument_binding"
    )
    module_metadata["specialized_dependency_extensions"] = tuple(
        getattr(compilation.deployment, "specialized_dependency_extensions", ())
    )
    machine_control_links: list[Any] = []
    machine_indirect_links: list[Any] = []
    pending_call_records: list[tuple[str, Any, Any, Any, Any]] = []

    def dependency_closure(graph: Any, seeds: Any) -> set[int]:
        """Follow the ProcessGraph's already-authored value dependencies."""

        retained = set(map(int, seeds))
        stack = list(retained)
        while stack:
            value_id = stack.pop()
            data = graph.nodes.get(int(value_id), {})
            for parent, role in data.get("parents") or ():
                parent = int(parent)
                if str(role) == "callee" or parent in retained:
                    continue
                retained.add(parent)
                stack.append(parent)
        return retained
    class_table = None
    source_function_table = getattr(
        getattr(compilation.deployment, "process_graph", None),
        "function_table",
        None,
    )
    deployment_graph = getattr(
        getattr(compilation.deployment, "process_graph", None), "G", None
    )
    program_abi = (
        {}
        if deployment_graph is None
        else dict(deployment_graph.graph.get("program_abi") or {})
    )
    function_symbols: dict[int, str] = {}
    shell_symbols: dict[int, str] = {}
    section_outputs: dict[str, tuple[Any, ...]] = {}
    export_symbols: list[str] = []
    lowering_failures: list[tuple[str, Any]] = []
    # The definition catalogue is not the program.  `_walk_planned_shells`
    # says so itself: compiling ONE entrypoint must not mistake catalogue
    # entries for executed children.  Its `function_shells` are the
    # UNSPECIALIZED graphs -- no caller, so no callsite literal and no caller
    # shape -- while `callsite_function_shells` is the activation tree that
    # actually runs, each shell carrying the facts its caller proved.  Gating
    # on `runtime_closure_only` alone lowered both, so a helper whose count
    # arrives as `n=2` at every real callsite was ALSO lowered from a copy
    # where `n` is a bare formal, and that copy is what could not emit its
    # `arange`.  The catalogue belongs only to a whole-source compile, which
    # is exactly what `prepare_complete_catalogue` states.
    discovered_planned_shells = tuple(_walk_planned_shells(
        compilation.deployment,
        include_function_registry=bool(getattr(
            compilation.deployment, "prepare_complete_catalogue", False
        )),
    ))
    planned_shells = tuple(
        shell
        for shell in discovered_planned_shells
        for planned_graph in (
            getattr(getattr(shell, "process_graph", None), "G", None),
        )
        for function_reference in (
            None if planned_graph is None
            else planned_graph.graph.get("function_ref"),
        )
        if not (
            function_reference is not None
            and source_function_table is not None
            and source_function_table.entry(
                int(function_reference)
            ).metadata.get("host_ssa_module") is not None
            and bool(source_function_table.entry(
                int(function_reference)
            ).metadata.get("host_repository_ssa_complete", False))
        )
    )
    report(
        f"discovered {len(planned_shells)} planned function shell(s) "
        f"from {len(discovered_planned_shells)} candidate(s)"
    )
    # Settle exact Program-ABI value contracts across source call edges before
    # any individual function partitions its numerical regions. Per-function
    # lowering is intentionally independent, so waiting for the later SSA call
    # linker loses the rank needed to select gather/matmul kernels inside a
    # callee. These facts come only from explicit ABI declarations and exact
    # PlanCall argument bindings; no extent is inferred or guessed here.
    linked_value_abi_by_graph: dict[int, dict[int, dict[str, Any]]] = {}
    # The concordance is where a shape becomes readable across stages, so
    # every fact this phase settles is written there as it is settled: the
    # declared contract, each propagation over a call edge, and each formal
    # proved to have no single shape.  A row is one value identity; its
    # history is the order in which this phase learned about it.
    from .identity_concordance import current_identity_book as _shape_book

    shape_page = _shape_book().page("value_shape")

    def note_shape(owner: Any, value_id: int, fact: Any) -> None:
        row = (str(owner.graph.get("function_name")), int(value_id))
        previous = shape_page.latest(row)
        # A fact is the shape, not who said it.  Two callsites agreeing is one
        # fact recorded once; otherwise every additional caller reads as a
        # change and a round trip between equal shapes reads as oscillation.
        if previous is not None and tuple(previous[1:]) == tuple(fact[1:]):
            return
        shape_page.set(row, len(shape_page.history(row)), fact)
    planned_graphs_by_shell: dict[int, Any] = {}
    for planned_shell in planned_shells:
        planned_graph = getattr(
            getattr(planned_shell, "process_graph", None), "G", None
        )
        if planned_graph is None:
            continue
        planned_graphs_by_shell[id(planned_shell)] = planned_graph
        function_name = planned_graph.graph.get("function_name")
        if function_name is None:
            continue
        if program_abi and not planned_graph.graph.get("parameter_record_abi"):
            selected = _record_receipts_for_function(
                program_abi,
                str(function_name),
                planned_graph.graph.get("function_parameters") or (),
                method_owner=planned_graph.graph.get("method_owner"),
            )
            if selected:
                planned_graph.graph["parameter_record_abi"] = selected
        _lower_optional_record_presence_graph(planned_graph)
        if program_abi and not planned_graph.graph.get("parameter_value_abi"):
            parameters = set(map(
                str, planned_graph.graph.get("function_parameters") or ()
            ))
            selected_values = {
                str(binding.get("parameter")): dict(binding)
                for binding in tuple(program_abi.get("values") or ())
                if str(binding.get("parameter") or "") in parameters
                and fnmatchcase(
                    str(function_name), str(binding.get("function") or "")
                )
            }
            if selected_values:
                planned_graph.graph["parameter_value_abi"] = selected_values

        identities = planned_graph.graph.get("identity_table") or {}
        value_contracts = linked_value_abi_by_graph.setdefault(
            id(planned_graph), {}
        )
        for parameter_name, value_abi in dict(
            planned_graph.graph.get("parameter_value_abi") or {}
        ).items():
            contract = {
                key: value_abi[key]
                for key in ("dtype", "rank", "shape", "storage")
                if value_abi.get(key) is not None
            }
            for value_id in identities.get(str(parameter_name), ()):
                value_contracts[int(value_id)] = dict(contract)
                note_shape(planned_graph, int(value_id), (
                    "contract",
                    tuple(contract.get("shape") or ()),
                    str(contract.get("dtype") or ""),
                    str(contract.get("storage") or ""),
                ))

        for parameter_name, record in dict(
            planned_graph.graph.get("parameter_record_abi") or {}
        ).items():
            owner_ids = set(map(
                int, identities.get(str(parameter_name), ())
            ))
            fields = dict(record.get("fields") or {})
            for node_id, data in planned_graph.nodes(data=True):
                if str(
                    data.get("type") or data.get("op") or ""
                ).casefold() != "getattr":
                    continue
                field_name = str(
                    (data.get("attributes") or {}).get("attribute") or ""
                )
                field = dict(fields.get(field_name) or {})
                if not field or not any(
                    (
                        int(parent) in owner_ids
                        or int(planned_graph.nodes[parent].get(
                            "value_id", parent
                        )) in owner_ids
                    )
                    and str(role) in {"value", "object", "base", "receiver"}
                    for parent, role in data.get("parents") or ()
                    if parent in planned_graph
                ):
                    continue
                contract = {
                    key: field[key]
                    for key in ("dtype", "rank", "shape", "storage")
                    if field.get(key) is not None
                }
                contract["program_abi_field_identity"] = (
                    str(record.get("identity") or parameter_name),
                    str(field_name),
                )
                if (
                    contract.get("shape") is None
                    and field.get("fixed_length") is not None
                ):
                    contract["shape"] = [int(field["fixed_length"])]
                value_contracts[int(data.get("value_id", node_id))] = contract

    # Every exact call edge this phase will settle over, recorded once so a
    # missing edge is visible as an absence rather than inferred from a fact
    # that never arrives.  A scalar argument with no edge here can never
    # receive its caller's literal, however well the propagation works.
    edge_page = _shape_book().page("call_edge")
    linked_value_edges = []
    from .hierarchical_plan import PlanCall as _ABIPlanCall
    for planned_shell in planned_shells:
        caller_graph = planned_graphs_by_shell.get(id(planned_shell))
        if caller_graph is None:
            continue
        callsite_shells = getattr(
            planned_shell, "callsite_function_shells", {}
        )
        for planned_call in getattr(planned_shell, "hierarchy_plan", ()).items:
            if not isinstance(planned_call, _ABIPlanCall):
                continue
            child_shell = callsite_shells.get(int(planned_call.callsite_id))
            callee_graph = planned_graphs_by_shell.get(id(child_shell))
            if callee_graph is None:
                continue
            for caller_id, callee_id in planned_call.argument_bindings:
                linked_value_edges.append((
                    caller_graph, int(caller_id), callee_graph, int(callee_id),
                ))
                # One row per EDGE.  A formal legitimately has many callers;
                # putting them on one row made a normal fan-in look like a
                # value changing its mind.
                edge_row = (
                    str(callee_graph.graph.get("function_name")),
                    int(callee_id),
                    str(caller_graph.graph.get("function_name")),
                    int(caller_id),
                )
                edge_page.set(edge_row, 0, "argument")
            # Results carry the same exact value contract in the opposite
            # direction.  Keeping them in this fixed point lets a shaped
            # callee return feed the next call before either caller partitions
            # its regions (LU -> forward substitution -> back substitution).
            linked_value_edges.extend(
                (callee_graph, int(callee_id), caller_graph, int(caller_id))
                for callee_id, caller_id in planned_call.result_bindings
            )
    from .glsl_deployment_strategy import (
        _fold_callsite_structural_values,
        _tensor_descriptor,
        descriptor_states_a_shape as _descriptor_states_a_shape,
    )
    graph_wrappers = {
        id(planned_shell.process_graph.G): planned_shell.process_graph
        for planned_shell in planned_shells
        if getattr(planned_shell, "process_graph", None) is not None
    }
    # A formal proved to have no single shape.  Kept OUTSIDE the contract:
    # contracts are copied wholesale onto the next callee, so a marker stored
    # in one would travel a call edge per round and mark formals downstream
    # that are not polymorphic at all -- a change every round, which is a
    # creeping fixed point rather than a settling one.
    polymorphic_formals: set[tuple[int, int]] = set()
    # A formal given two different literals by two callsites is parametric,
    # exactly as a formal given two shapes is.
    literal_conflicts: set[tuple[int, str]] = set()
    changed = True
    settlement_round = 0
    while changed:
        changed = False
        settlement_round += 1
        # This loop runs until nothing changes and has no bound of its own,
        # so it says which round it is on: a phase that cannot announce
        # progress is indistinguishable from one that will never finish.
        settled = sum(
            len(contracts) for contracts in linked_value_abi_by_graph.values()
        )
        report(
            f"abi: settlement round {settlement_round}, "
            f"{settled} contract(s) over {len(linked_value_edges)} call "
            f"edge(s), {len(polymorphic_formals)} shape-polymorphic formal(s)"
        )
        settlement_witnesses = []
        # A phase with no bound of its own must say which round it is on AND
        # how much it is still moving: a count that climbs by one per round is
        # a fact creeping along a call chain, a count that does not move at all
        # while the loop repeats is something toggling.
        report(
            f"abi: settlement round {settlement_round}, "
            f"{settled} contract(s) over {len(linked_value_edges)} call "
            f"edge(s), {len(polymorphic_formals)} shape-polymorphic formal(s)"
        )
        # Literal arguments settle across a call edge the same way shapes do.
        # A callee cannot fold ``arange(n)`` while ``n`` is its own formal,
        # and the callsite specialization that would have supplied the
        # literal runs BEFORE the folds that make it one -- ``n`` is
        # ``get_shape()[-1]`` until this loop's own fold resolves it.
        # Carrying it here lets the next round's re-fold consume it, which is
        # what a fixed point is for: one fact unblocks the next.
        round_constants: dict[int, dict[int, Any]] = {}
        round_parameters: dict[int, dict[int, str]] = {}

        def graph_constants(candidate: Any) -> dict[int, Any]:
            table = round_constants.get(id(candidate))
            if table is None:
                table = {}
                for node_id, node_data in candidate.nodes(data=True):
                    if str(node_data.get("type")) not in {
                        "Constant", "Const", "const",
                    }:
                        continue
                    literal = node_data.get("constant")
                    if literal is None:
                        literal = (
                            node_data.get("attributes") or {}
                        ).get("value")
                    table[int(node_data.get("value_id", node_id))] = literal
                round_constants[id(candidate)] = table
            return table

        def parameter_of(candidate: Any, value_id: int) -> str | None:
            table = round_parameters.get(id(candidate))
            if table is None:
                table = {}
                declared = set(map(
                    str, candidate.graph.get("function_parameters") or ()
                ))
                for name, history in (
                    candidate.graph.get("identity_table") or {}
                ).items():
                    if str(name) not in declared:
                        continue
                    for member in history or ():
                        table[int(member)] = str(name)
                round_parameters[id(candidate)] = table
            return table.get(int(value_id))

        # Publish the current facts before deriving shapes of expressions.
        # A direct record-field ledger alone cannot shape a callee receiving
        # an indexed/reshaped expression of that field. Fold those structural
        # expressions in each callsite's graph, then propagate their proven
        # descriptors over the same exact argument bindings.
        for graph_id, wrapper in graph_wrappers.items():
            wrapper.G.graph["linked_value_abi"] = (
                linked_value_abi_by_graph.setdefault(graph_id, {})
            )
            _fold_callsite_structural_values(wrapper)
        for caller_graph, caller_id, callee_graph, callee_id in linked_value_edges:
            source = linked_value_abi_by_graph.get(
                id(caller_graph), {}
            ).get(int(caller_id))
            if source is None or source.get("shape") is None:
                descriptor = _tensor_descriptor(
                    graph_wrappers[id(caller_graph)], int(caller_id),
                )
                if (
                    _descriptor_states_a_shape(descriptor)
                    and descriptor.get("metadata_state") != "dynamic"
                ):
                    extents = tuple(descriptor["shape"])
                    source = {
                        **dict(source or {}),
                        "dtype": descriptor["dtype"],
                        "rank": len(extents),
                        "storage": "span" if extents else "scalar",
                    }
                    # A shape is recorded only when the descriptor states
                    # EXTENTS.  An empty shape from this query is equally
                    # "a rank-0 scalar" and "recovery stopped", and writing
                    # it as a contract is final: the merge below only fills
                    # a MISSING key, so a real shape arriving later can never
                    # replace it.  Rank and storage still carry the scalar
                    # case, and leaving shape unset lets the truth land.
                    if extents:
                        source["shape"] = extents
            if source is None:
                continue
            destination = linked_value_abi_by_graph.setdefault(
                id(callee_graph), {}
            )
            literal = graph_constants(caller_graph).get(
                int(caller_id), _LITERAL_ABSENT
            )
            if literal is _LITERAL_ABSENT:
                # This caller instance did not fold it; another copy of the
                # same function may have.  The book is keyed by identity.
                literal = _shape_book().page("proven_literal").latest(
                    (
                        str(caller_graph.graph.get("function_name")),
                        int(caller_id),
                    ),
                    _LITERAL_ABSENT,
                )
            existing = destination.get(int(callee_id))
            marker = (id(callee_graph), int(callee_id))
            if existing is None:
                destination[int(callee_id)] = dict(source)
                note_shape(callee_graph, int(callee_id), (
                    f"from {caller_graph.graph.get('function_name')}"
                    f" value {int(caller_id)}",
                    tuple(source.get("shape") or ()),
                    str(source.get("dtype") or ""),
                    str(source.get("storage") or ""),
                ))
                changed = True
                continue
            if marker in polymorphic_formals:
                # A formal with no single shape has no single rank either.
                # Left unguarded, one callsite writes rank 2 and the other
                # writes rank 0 on every pass: a change every round that moves
                # no count at all, which is a loop that never ends.  Storage
                # and dtype still agree and are still carried.
                existing.pop("shape", None)
                existing.pop("rank", None)
            elif source.get("shape") is not None:
                exact_rank = len(tuple(source["shape"]))
                if existing.get("rank") != exact_rank:
                    existing["rank"] = exact_rank
                    changed = True
                    settlement_witnesses.append((
                        str(callee_graph.graph.get("function_name")),
                        int(callee_id), "rank",
                    ))
            field_identity_key = "program_abi_field_identity"
            ambiguous_field_key = "program_abi_field_identity_ambiguous"
            if source.get(ambiguous_field_key):
                if (
                    existing.pop(field_identity_key, None) is not None
                    or not existing.get(ambiguous_field_key)
                ):
                    existing[ambiguous_field_key] = True
                    changed = True
            for key, value in source.items():
                if key == ambiguous_field_key:
                    continue
                if key == field_identity_key:
                    if existing.get(ambiguous_field_key):
                        continue
                    incumbent = existing.get(key)
                    if incumbent is None:
                        existing[key] = value
                        changed = True
                    elif tuple(incumbent) != tuple(value):
                        existing.pop(key, None)
                        existing[ambiguous_field_key] = True
                        changed = True
                    continue
                if key not in existing:
                    if key == "shape":
                        # A shape arriving on a formal that already had a
                        # contract is the event worth seeing; only the first
                        # install was being recorded.
                        note_shape(callee_graph, int(callee_id), (
                            f"merged from "
                            f"{caller_graph.graph.get('function_name')}"
                            f" value {int(caller_id)}",
                            tuple(value or ()),
                            str(source.get("dtype") or ""),
                            str(source.get("storage") or ""),
                        ))
                    if key in {"shape", "rank"} and (
                        marker in polymorphic_formals
                    ):
                        # Already proved to have no single shape.  Re-adding
                        # one callsite's shape here and having the other pop
                        # it again is a cycle, and this loop runs until
                        # nothing changes.
                        continue
                    existing[key] = value
                    changed = True
                    settlement_witnesses.append((
                        str(callee_graph.graph.get("function_name")),
                        int(callee_id), str(key),
                    ))
                elif key == "shape" and tuple(existing[key]) != tuple(value):
                    # A shared helper reached with two exact shapes is
                    # ordinary polymorphism -- ``_row(U, ...)`` on a matrix
                    # and ``_row(x, ...)`` on a column are the same authored
                    # function -- and callsite specialization downstream is
                    # what resolves it.  THIS settlement holds one contract
                    # per callee formal, so it simply has no single shape to
                    # state: drop it and say so, rather than refusing a
                    # program whose callees are about to be specialized
                    # anyway.  Everything the two callsites DO agree on
                    # (dtype, storage, rank when equal) is kept.
                    from .identity_concordance import current_identity_book

                    page = current_identity_book().page(
                        "linked_value_abi_polymorphism"
                    )
                    row = (
                        str(callee_graph.graph.get("function_name")),
                        int(callee_id),
                    )
                    page.set(row, len(page.history(row)), (
                        str(caller_graph.graph.get("function_name")),
                        int(caller_id),
                        tuple(existing[key]),
                        tuple(value),
                    ))
                    existing.pop("shape", None)
                    if len(tuple(value)) != int(
                        existing.get("rank", len(tuple(value)))
                    ):
                        existing.pop("rank", None)
                    note_shape(callee_graph, int(callee_id), (
                        "polymorphic",
                        tuple(value),
                        str(source.get("dtype") or ""),
                        str(source.get("storage") or ""),
                    ))
                    if marker not in polymorphic_formals:
                        polymorphic_formals.add(marker)
                        changed = True
    # One page per store, so a value whose stores disagree is a row rather
    # than a hunt.
    _node_page = _shape_book().page("shape.node")
    _linked_page = _shape_book().page("shape.linked")
    for _graph in planned_graphs_by_shell.values():
        _name = str(_graph.graph.get("function_name"))
        _contracts = linked_value_abi_by_graph.get(id(_graph), {})
        for _node_id, _data in _graph.nodes(data=True):
            _value_id = int(_data.get("value_id", _node_id))
            _row = (_name, _value_id)
            _tensor = _data.get("tensor") or {}
            _extents = tuple(_tensor.get("shape") or ())
            if _extents:
                _node_page.set(_row, 0, _extents)
            _contract = _contracts.get(_value_id) or {}
            _declared = tuple(_contract.get("shape") or ())
            if _declared:
                _linked_page.set(_row, 0, tuple(map(int, _declared)))

    # One page per store, so a value whose stores disagree is a row rather
    # than a hunt.
    _node_page = _shape_book().page("shape.node")
    _linked_page = _shape_book().page("shape.linked")
    for _graph in planned_graphs_by_shell.values():
        _name = str(_graph.graph.get("function_name"))
        _contracts = linked_value_abi_by_graph.get(id(_graph), {})
        for _node_id, _data in _graph.nodes(data=True):
            _value_id = int(_data.get("value_id", _node_id))
            _row = (_name, _value_id)
            _tensor = _data.get("tensor") or {}
            _extents = tuple(_tensor.get("shape") or ())
            if _extents:
                _node_page.set(_row, 0, _extents)
            _contract = _contracts.get(_value_id) or {}
            _declared = tuple(_contract.get("shape") or ())
            if _declared:
                _linked_page.set(_row, 0, tuple(map(int, _declared)))

    for planned_graph in planned_graphs_by_shell.values():
        contracts = linked_value_abi_by_graph.get(id(planned_graph), {})
        if contracts:
            planned_graph.graph["linked_value_abi"] = {
                int(value_id): dict(contract)
                for value_id, contract in contracts.items()
            }
    # Hierarchy plans freeze each numerical region's value shapes.  The
    # exact call-edge ABI contracts above are deliberately settled before
    # region partitioning, so plans made earlier during graph preparation
    # are now stale by construction.  Rebuild every function plan here,
    # after the fixed point, so reshape/gather/matmul see the contracts that
    # this phase just established.  This remains a shared repository-SSA
    # boundary; no backend-specific shape recovery is involved.
    for planned_shell in planned_shells:
        planned_shell.refresh_hierarchy_plan()
    source_name_references: dict[str, set[int]] = {}
    for planned_shell in planned_shells:
        planned_graph = getattr(
            getattr(planned_shell, "process_graph", None), "G", None
        )
        if planned_graph is None:
            continue
        planned_name = planned_graph.graph.get("function_name")
        planned_reference = planned_graph.graph.get("function_ref")
        if planned_name is not None and planned_reference is not None:
            source_name_references.setdefault(
                str(planned_name), set()
            ).add(int(planned_reference))
    # Decompiled host modules share repository IR containers and FunctionTable
    # ownership. Merge them before source methods so calls link to exact roots;
    # the explicit completeness fact below distinguishes legalized repository
    # SSA from retained machine-state dialect inside those containers.
    if source_function_table is not None:
        for entry in source_function_table:
            host_module = entry.metadata.get("host_ssa_module")
            host_root = entry.metadata.get("host_ssa_root")
            if host_module is None or host_root is None:
                continue
            all_functions.update(host_module.functions)
            section_outputs.update(dict(
                entry.metadata.get("host_ssa_outputs") or {}
            ))
            function_symbols[int(entry.reference.address)] = str(host_root)
            all_tensor_tables.update(getattr(host_module, "tensor_tables", {}))
            all_sequence_tables.update(getattr(host_module, "sequence_tables", {}))
            all_record_tables.update(getattr(host_module, "record_tables", {}))
            all_reference_tables.update(
                getattr(host_module, "reference_tables", {})
            )
            machine_control_links.extend(
                getattr(
                    getattr(host_module, "machine_control_table", None),
                    "links", (),
                )
            )
            machine_indirect_links.extend(
                getattr(
                    getattr(host_module, "machine_indirect_table", None),
                    "links", (),
                )
            )
            host_blockers = tuple(entry.metadata.get("host_ssa_blockers", ()))
            host_hard_blockers = tuple(entry.metadata.get(
                "host_ssa_hard_blockers", host_blockers,
            ))
            host_legalization_shortfalls = tuple(entry.metadata.get(
                "host_ssa_legalization_shortfalls", (),
            ))
            host_unresolved_dependencies = tuple(entry.metadata.get(
                "host_ssa_unresolved_dependencies", (),
            ))
            host_repository_ssa_complete = bool(entry.metadata.get(
                "host_repository_ssa_complete", False,
            ))
            host_machine_state_complete = bool(entry.metadata.get(
                "host_machine_state_complete", False,
            ))
            host_native_module = entry.metadata.get("host_native_module")
            host_root_function = all_functions.get(str(host_root))
            if host_root_function is not None:
                from .native_code_retention import (
                    WINDOWS_AMD64_NATIVE_LINKER,
                    select_host_implementation,
                )
                implementation_decision = select_host_implementation(
                    repository_ssa_complete=host_repository_ssa_complete,
                    machine_state_ssa_complete=host_machine_state_complete,
                    retained_native_module=host_native_module,
                    target=WINDOWS_AMD64_NATIVE_LINKER,
                )
                host_root_function.metadata.update({
                    "host_ssa_complete": (
                        host_repository_ssa_complete
                    ),
                    "host_machine_state_complete": (
                        host_machine_state_complete
                    ),
                    "host_ssa_blockers": host_blockers,
                    "host_ssa_hard_blockers": host_hard_blockers,
                    "host_ssa_legalization_shortfalls": (
                        host_legalization_shortfalls
                    ),
                    "host_ssa_unresolved_dependencies": (
                        host_unresolved_dependencies
                    ),
                    "host_ssa_cache_key": entry.metadata.get(
                        "host_ssa_cache_key"
                    ),
                    "host_native_module": host_native_module,
                    "implementation_variants": entry.metadata.get(
                        "implementation_variants", ("repository-ssa",)
                    ),
                    "implementation_decision": implementation_decision,
                    "selected_implementation": implementation_decision.implementation.value,
                    "implementation_deployable": implementation_decision.deployable,
                })
    retained_storage_identities: set[str] = set()
    report("sequence-schema survey complete; lowering function shells")
    for shell_index, shell in enumerate(planned_shells, 1):
        graph = getattr(shell, "process_graph", None)
        graph_obj = graph.G if graph is not None else None
        if graph_obj is None:
            continue
        field_contract = _field_slot_ops(graph_obj)
        for _effect, _key, sequence_id, storage_identity in field_contract[12]:
            if sequence_id is not None:
                retained_storage_identities.add(str(storage_identity))
    # A sequence's numeric id is a global identity across the whole program
    # (it traces back to one shared ProcessGraph node's value_id), but each
    # shell (method) below lowers with its own local, independently-inferred
    # view of any sequence it touches. Two shells touching the same sequence
    # can therefore disagree not just on element dtype but on the sequence's
    # actual shape (how many storage cells it has) -- a real memory-layout
    # bug, not a cosmetic one. Survey every shell's raw declarations here,
    # before any shell's lowering commits to a shape, and resolve one
    # structural schema per sequence_id that every shell's lowering below
    # will be handed and required to agree with. See
    # ResolvedSequenceSchema in precompile_to_ssa.py for the full rationale.
    keyed_table_fields = frozenset(
        str(_field_name)
        for _record in dict(program_abi.get("records") or {}).values()
        for _field_name, _field in dict(_record.get("fields") or {}).items()
        if str(_field.get("storage") or "") == "keyed"
    )
    keyed_writable_fields = frozenset(
        str(_field_name)
        for _record in dict(program_abi.get("records") or {}).values()
        for _field_name, _field in dict(_record.get("fields") or {}).items()
        if str(_field.get("storage") or "") == "keyed"
        and bool(_field.get("mutable", False))
    )
    shell_sequence_evidence: list[dict[str, Any]] = []
    for shell in planned_shells:
        graph = getattr(shell, "process_graph", None)
        graph_obj = graph.G if graph is not None else None
        if graph_obj is None:
            continue
        (
            _self_id, _field_ops, _const_sources, _field_count, _field_names,
            _record_identity, sequence_initializations, _field_aliases,
            sequence_declarations, _sequence_memberships, _table_lookups,
            _table_lookup_defaults, _table_stores, table_deletions,
            retained_sequence_ids, nested_sequence_ids,
            nested_tensor_sequence_ids, _nested_record_fields,
            tombstone_sequence_ids,
        ) = _field_slot_ops(
            graph_obj,
            retained_storage_identities=frozenset(retained_storage_identities),
            keyed_table_fields=keyed_table_fields,
            keyed_writable_fields=keyed_writable_fields,
        )
        shell_sequence_evidence.append({
            "function_name": str(
                graph_obj.graph.get("function_name") or "<module>"
            ),
            "sequence_names": {
                int(sequence_id): tuple(
                    str(name)
                    for name, history in dict(
                        graph_obj.graph.get("identity_table") or {}
                    ).items()
                    if int(sequence_id) in set(map(int, history))
                )
                for sequence_id, *_rest in sequence_declarations
            },
            "sequence_declarations": sequence_declarations,
            "sequence_initializations": sequence_initializations,
            "table_deletions": table_deletions,
            "deletion_sequence_ids": tombstone_sequence_ids,
            "retained_sequence_ids": retained_sequence_ids,
            "nested_sequence_ids": nested_sequence_ids,
            "nested_tensor_sequence_ids": nested_tensor_sequence_ids,
        })
    # ProcessGraph value ids are local to a compiled function until repository
    # SSA linking freshens and binds call frames.  Surveying every shell in one
    # raw-id namespace aliases unrelated locals (for example value 50 was both
    # ``run_superstep.unresolved`` and ``step_with_dt_control_used.reasons``).
    # Resolve all variants of one function together, but never equate storage
    # merely because two pre-link functions minted the same integer id.
    evidence_by_function: dict[str, list[dict[str, Any]]] = {}
    for evidence in shell_sequence_evidence:
        evidence_by_function.setdefault(
            str(evidence.get("function_name") or "<module>"), []
        ).append(evidence)
    resolved_sequence_schemas_by_function: dict[
        str, dict[int, Any]
    ] = {}
    sequence_schema_shortfalls = []
    for evidence_function, evidence_group in evidence_by_function.items():
        resolved, shortfalls = resolve_sequence_schemas(
            evidence_group,
            location=f"sequence-schema-survey:{evidence_function}",
        )
        resolved_sequence_schemas_by_function[evidence_function] = resolved
        sequence_schema_shortfalls.extend(shortfalls)
    if sequence_schema_shortfalls:
        lowering_failures.extend(
            ("<sequence-schema-survey>", item)
            for item in sequence_schema_shortfalls
        )
    for shell in planned_shells:
        graph = getattr(shell, "process_graph", None)
        graph_obj = graph.G if graph is not None else None
        function_name = (
            graph_obj.graph.get("function_name") if graph_obj is not None else None
        )
        if function_name is None:
            continue
        report(
            f"function {shell_index}/{len(planned_shells)} {function_name}: "
            f"local control/region lowering start; graph_nodes={len(graph_obj)}"
        )
        if os.environ.get("TURING_DEBUG_BUILTIN_SELECTION"):
            for _node_id, _node_data in graph_obj.nodes(data=True):
                _expression = _node_data.get("expr_obj")
                _is_selection_call = (
                    isinstance(_expression, ast.Call)
                    and (
                        isinstance(_expression.func, ast.Name)
                        and _expression.func.id in {"next", "sum", "bytes"}
                        or isinstance(_expression.func, ast.Attribute)
                        and _expression.func.attr == "pack"
                    )
                )
                if not (
                    _is_selection_call
                    or isinstance(_expression, (ast.GeneratorExp, ast.comprehension))
                ):
                    continue
                print(
                    "DEBUGBUILTIN "
                    f"fn={function_name} node={int(_node_id)} "
                    f"value={_node_data.get('value_id', _node_id)} "
                    f"expr={ast.unparse(_expression)!r} "
                    f"parents={tuple(_node_data.get('parents') or ())!r} "
                    f"children={tuple(_node_data.get('children') or ())!r} "
                    f"attrs={dict(_node_data.get('attributes') or {})!r}",
                    file=sys.stderr,
                )
                if _is_selection_call:
                    _frontier = [
                        int(parent)
                        for parent, _role in _node_data.get("parents") or ()
                    ]
                    _seen = set()
                    for _depth in range(4):
                        _next_frontier = []
                        for _related_id in _frontier:
                            if (
                                _related_id in _seen
                                or _related_id not in graph_obj
                            ):
                                continue
                            _seen.add(_related_id)
                            _related = graph_obj.nodes[_related_id]
                            _related_expression = _related.get("expr_obj")
                            print(
                                "DEBUGBUILTINANCESTOR "
                                f"fn={function_name} depth={_depth} "
                                f"node={_related_id} "
                                f"kind={_related.get('type')!r} "
                                f"expr={None if _related_expression is None else ast.unparse(_related_expression)!r} "
                                f"parents={tuple(_related.get('parents') or ())!r} "
                                f"attrs={dict(_related.get('attributes') or {})!r}",
                                file=sys.stderr,
                            )
                            _next_frontier.extend(
                                int(parent)
                                for parent, _role in _related.get("parents") or ()
                            )
                        _frontier = _next_frontier
        if program_abi and not graph_obj.graph.get("parameter_record_abi"):
            selected = _record_receipts_for_function(
                program_abi,
                str(function_name),
                graph_obj.graph.get("function_parameters") or (),
                method_owner=graph_obj.graph.get("method_owner"),
            )
            if selected:
                graph_obj.graph["parameter_record_abi"] = selected
        from .glsl_deployment_strategy import (
            _repair_missing_phi_initial_identities,
        )

        phi_initial_identity_receipts = (
            _repair_missing_phi_initial_identities(graph_obj)
        )
        _lower_optional_record_presence_graph(graph_obj)
        if program_abi and not graph_obj.graph.get("parameter_value_abi"):
            parameters = set(map(
                str, graph_obj.graph.get("function_parameters") or ()
            ))
            selected_values = {}
            for binding in tuple(program_abi.get("values") or ()):
                parameter = str(binding.get("parameter") or "")
                if (
                    parameter in parameters
                    and fnmatchcase(
                        str(function_name), str(binding.get("function") or "")
                    )
                ):
                    selected_values[parameter] = dict(binding)
            if selected_values:
                graph_obj.graph["parameter_value_abi"] = selected_values
        control = getattr(shell, "shell_control_program", None)
        control = _apply_phi_initial_identity_repairs_to_control(
            control, phi_initial_identity_receipts,
        )
        import os as _os, sys as _sys
        if _os.environ.get("TURING_DEBUG_REGION_ORDER"):
            def _walk_markers(block, acc):
                cls = type(block).__name__
                if cls == "StatementBlock":
                    for line in block.lines:
                        if line.startswith("__scheduled_region_"):
                            acc.append(line)
                elif cls == "SequenceBlock":
                    for child in block.blocks:
                        _walk_markers(child, acc)
                elif cls == "LoopBlock":
                    acc.append(f"LOOP[{block.induction}](")
                    _walk_markers(block.body, acc)
                    acc.append(")")
                elif cls == "WhileBlock":
                    acc.append("WHILE(")
                    _walk_markers(block.body, acc)
                    acc.append(")")
                elif cls == "ConditionalBlock":
                    acc.append("IF(")
                    _walk_markers(block.body, acc)
                    if block.orelse is not None:
                        acc.append("ELSE(")
                        _walk_markers(block.orelse, acc)
                        acc.append(")")
                    acc.append(")")
                elif cls == "CallBlock":
                    acc.append("CALL(")
                    _walk_markers(block.callee, acc)
                    acc.append(")")
                return acc
            _markers = _walk_markers(control.root, []) if control is not None else None
            print(
                f"DEBUGCLASSSHELL fn={function_name} "
                f"control_is_none={control is None} "
                f"region_indices={getattr(control, 'region_indices', None)} "
                f"root_markers={_markers}",
                file=_sys.stderr,
            )
        if control is None:
            continue
        predicate_region_ownership_receipts = ()
        # The hierarchy is the final numerical-ownership authority. Callsite
        # attachment can remove a pre-carved region whose only nodes are now
        # direct call-result projections; its earlier control marker must be
        # removed at the same boundary or ControlSSABuilder will synthesize a
        # call to a nonexistent ``numerical_region_N``. Projecting here is
        # target-neutral and uses the existing control-IR projection pass.
        from .hierarchical_plan import PlanClosure

        hierarchy_plan = getattr(shell, "hierarchy_plan", None)
        planned_region_indices = {
            int(item.name.rsplit("_", 1)[1])
            for item in getattr(hierarchy_plan, "items", ())
            if isinstance(item, PlanClosure)
            and str(item.name).startswith("region_")
        }
        if not set(map(int, control.region_indices)).issubset(
            planned_region_indices
        ):
            from .control_source import project_control_regions

            control = project_control_regions(
                control,
                tuple(
                    int(region_index)
                    for region_index in control.region_indices
                    if int(region_index) in planned_region_indices
                ),
            )
        external_call_node_ids = {
            int(node_id)
            for node_id, node_data in graph_obj.nodes(data=True)
            if str((node_data.get("attributes") or {}).get(
                "extraction_action"
            ) or (node_data.get("extraction_contract") or {}).get(
                "action"
            )) == "use_native"
        }
        external_only_region_indices = {
            int(region_index)
            for region_index, subgraph in enumerate(
                getattr(shell, "dispatch_subgraphs", ())
            )
            for deployment_nodes in (set(map(
                int, subgraph.G.graph.get("deployment_nodes", ())
            )),)
            if deployment_nodes
            and deployment_nodes.issubset(external_call_node_ids)
        }
        if os.environ.get("TURING_DEBUG_EXTERNAL_REFERENCE"):
            print(
                "DEBUG-EXTERNAL-REGIONS "
                f"function={function_name} calls={sorted(external_call_node_ids)} "
                f"regions={tuple(tuple(map(int, subgraph.G.graph.get('deployment_nodes', ()))) for subgraph in getattr(shell, 'dispatch_subgraphs', ()))} "
                f"external_only={sorted(external_only_region_indices)}",
                file=sys.stderr,
            )
        if external_only_region_indices:
            # Capture historically presented a native-boundary Call as a
            # numerical op as well (``_pickle.load`` became a tensor ``load``),
            # so repository SSA contained both a guessed intrinsic and the
            # real shell capability call. The boundary occurrence owns the
            # operation. Remove only regions made entirely from those exact
            # call nodes; a mixed numerical region remains a loud backend
            # shortfall until it can be split without discarding operands.
            from .control_source import project_control_regions

            control = project_control_regions(
                control,
                tuple(
                    int(region_index)
                    for region_index in control.region_indices
                    if int(region_index) not in external_only_region_indices
                ),
            )
        control, predicate_region_ownership_receipts = (
            _rehome_structured_while_predicate_regions(
                control,
                getattr(shell, "dispatch_subgraphs", ()),
            )
        )
        # Some precompile-only shells retain the flat region schedule even
        # though branch compartments were already proven during partitioning.
        # Reapply the backend-neutral ordinary-conditional overlay here before
        # repository SSA sees the program.  Existing loop/while control is the
        # outer control and strict region containment nests each conditional
        # at its real lexical marker.
        from .control_source import overlay_scheduled_control
        from .glsl_deployment_strategy import (
            _ast_source_signature,
            _ordinary_conditional_control_programs,
            _source_control_expression,
        )
        def _source_conditional_ids(block):
            from .control_source import (
                CallBlock, ConditionalBlock, LoopBlock, ParallelDeployment,
                SequenceBlock, StateMachineTick, WhileBlock,
            )
            found = set()
            if isinstance(block, ConditionalBlock):
                if block.source_node_id is not None:
                    found.add(int(block.source_node_id))
                found.update(_source_conditional_ids(block.body))
                if block.orelse is not None:
                    found.update(_source_conditional_ids(block.orelse))
            elif isinstance(block, SequenceBlock):
                for child in block.blocks:
                    found.update(_source_conditional_ids(child))
            elif isinstance(block, LoopBlock):
                found.update(_source_conditional_ids(block.body))
            elif isinstance(block, WhileBlock):
                found.update(_source_conditional_ids(block.condition))
                found.update(_source_conditional_ids(block.body))
            elif isinstance(block, CallBlock):
                found.update(_source_conditional_ids(block.callee))
            elif isinstance(block, ParallelDeployment):
                for lane in block.lanes:
                    found.update(_source_conditional_ids(lane))
            elif isinstance(block, StateMachineTick):
                for _case, body in block.cases:
                    found.update(_source_conditional_ids(body))
                if block.default is not None:
                    found.update(_source_conditional_ids(block.default))
            return found

        def _lowered_source_control_ids(block):
            from .control_source import (
                CallBlock, ConditionalBlock, LoopBlock, ParallelDeployment,
                SequenceBlock, StateMachineTick, WhileBlock,
            )
            found = set()
            if isinstance(block, ConditionalBlock):
                if block.source_node_id is not None:
                    found.add(int(block.source_node_id))
                found.update(_lowered_source_control_ids(block.body))
                if block.orelse is not None:
                    found.update(_lowered_source_control_ids(block.orelse))
            elif isinstance(block, SequenceBlock):
                for child in block.blocks:
                    found.update(_lowered_source_control_ids(child))
            elif isinstance(block, LoopBlock):
                if block.source_loop_node_id is not None:
                    found.add(int(block.source_loop_node_id))
                found.update(_lowered_source_control_ids(block.body))
            elif isinstance(block, WhileBlock):
                if block.source_loop_node_id is not None:
                    found.add(int(block.source_loop_node_id))
                found.update(_lowered_source_control_ids(block.condition))
                found.update(_lowered_source_control_ids(block.body))
            elif isinstance(block, CallBlock):
                found.update(_lowered_source_control_ids(block.callee))
            elif isinstance(block, ParallelDeployment):
                for lane in block.lanes:
                    found.update(_lowered_source_control_ids(lane))
            elif isinstance(block, StateMachineTick):
                for _case, body in block.cases:
                    found.update(_lowered_source_control_ids(body))
                if block.default is not None:
                    found.update(_lowered_source_control_ids(block.default))
            return found

        represented_conditionals = _source_conditional_ids(control.root)
        conditional_controls = _ordinary_conditional_control_programs(
            graph,
            control.region_indices,
            getattr(shell, "dispatch_subgraphs", ()),
        )
        if represented_conditionals:
            from .control_source import (
                ConditionalBlock, SequenceBlock,
                enrich_represented_conditionals,
            )

            control, enrichment_receipts = enrich_represented_conditionals(
                control,
                conditional_controls,
                enrich_loop_continuations=False,
            )
            if enrichment_receipts:
                enrichment_ledger = list(graph_obj.graph.get(
                    "conditional_control_enrichment_receipts", ()
                ))
                for receipt in enrichment_receipts:
                    if receipt not in enrichment_ledger:
                        enrichment_ledger.append(receipt)
                graph_obj.graph[
                    "conditional_control_enrichment_receipts"
                ] = tuple(enrichment_ledger)

            def represented(program):
                return any(
                    isinstance(block, ConditionalBlock)
                    and block.source_node_id is not None
                    and int(block.source_node_id) in represented_conditionals
                    for block in program.root.blocks
                )

            conditional_controls = tuple(
                program
                for program in conditional_controls
                if not represented(program)
            )
        specialized_conditional_node_ids = tuple(dict.fromkeys(
            int(node_id) for node_id in (
                *control.specialized_conditional_node_ids,
                *tuple(graph_obj.graph.get(
                    "structurally_specialized_conditional_node_ids", ()
                )),
            )
        ))
        from .control_source import SequenceBlock, StatementBlock
        lowered_conditional_count = 0
        if conditional_controls:
            from .control_source import ConditionalBlock

            # Several conditions in one ``if/elif`` cascade can share a
            # scheduled predicate region.  Each isolated conditional view
            # names that prefix, but nesting all views would execute it once
            # per level.  Hoist only repeated top-level predicate prefixes
            # back to the flat schedule; branch regions remain owned by their
            # lexical conditional and are embedded below as usual.
            prefix_counts: dict[int, int] = {}
            prefixes_by_control: list[tuple[int, ...]] = []
            for conditional_control in conditional_controls:
                prefixes = []
                for block in conditional_control.root.blocks:
                    if isinstance(block, ConditionalBlock):
                        break
                    if (
                        isinstance(block, StatementBlock)
                        and len(block.lines) == 1
                        and block.lines[0].startswith("__scheduled_region_")
                    ):
                        region = int(
                            block.lines[0][len("__scheduled_region_"):-2]
                        )
                        prefixes.append(region)
                        prefix_counts[region] = prefix_counts.get(region, 0) + 1
                prefixes_by_control.append(tuple(prefixes))
            shared_prefixes = {
                region for region, count in prefix_counts.items() if count > 1
            }
            if shared_prefixes:
                conditional_controls = tuple(
                    replace(
                        conditional_control,
                        root=SequenceBlock(tuple(
                            block
                            for block in conditional_control.root.blocks
                            if not (
                                isinstance(block, StatementBlock)
                                and len(block.lines) == 1
                                and block.lines[0].startswith(
                                    "__scheduled_region_"
                                )
                                and int(block.lines[0][
                                    len("__scheduled_region_"):-2
                                ]) in shared_prefixes
                            )
                        )),
                        region_indices=tuple(
                            region
                            for region in conditional_control.region_indices
                            if int(region) not in shared_prefixes
                        ),
                    )
                    for conditional_control in conditional_controls
                )

            def conditional_of(program):
                return next((
                    block for block in program.root.blocks
                    if isinstance(block, ConditionalBlock)
                ), None)

            conditional_blocks = tuple(map(
                conditional_of, conditional_controls
            ))
            source_expressions = {
                int(block.source_node_id): _source_control_expression(
                    graph_obj, int(block.source_node_id)
                )
                for block in conditional_blocks
                if block is not None and block.source_node_id is not None
            }
            parent_by_child: dict[int, int] = {}
            for child_index, child in enumerate(conditional_blocks, start=1):
                if child is None or child.source_node_id is None:
                    continue
                candidates = []
                for parent_index, parent in enumerate(
                    conditional_blocks, start=1
                ):
                    if (
                        parent is None
                        or parent_index == child_index
                        or parent.source_node_id is None
                    ):
                        continue
                    expression = source_expressions.get(
                        int(parent.source_node_id)
                    )
                    if expression is None:
                        continue
                    descendants = {
                        _ast_source_signature(member) for statement in (
                            *expression.body, *expression.orelse
                        ) for member in ast.walk(statement)
                    }
                    child_expression = source_expressions.get(
                        int(child.source_node_id)
                    )
                    if (
                        child_expression is not None
                        and _ast_source_signature(child_expression) in descendants
                    ):
                        span = int(getattr(
                            expression, "end_lineno", expression.lineno
                        )) - int(expression.lineno)
                        candidates.append((span, parent_index))
                if candidates:
                    parent_by_child[child_index] = min(candidates)[1]
            # Index zero is the already-scheduled outer control program;
            # conditional programs begin at one.  The AST supplies exact
            # lexical containment, including equal-region nesting such as an
            # ``if`` whose entire arm is another ``if``.  Only maximal source
            # conditionals attach directly to the schedule root; every nested
            # conditional attaches to its nearest lexical conditional.
            direct_children: dict[int, list[int]] = {}
            for child_index in range(1, len(conditional_controls) + 1):
                direct_children.setdefault(
                    parent_by_child.get(child_index, 0), []
                ).append(child_index)
            # A conditional that owns no numerical region (a guard clause
            # whose arm is only a return or a call) has no schedule marker
            # to replace.  Anchor it before the first scheduled region that
            # lexically follows it, so the overlay places it instead of
            # dropping it (which silently ran the function as if the guard
            # were false).
            def earliest_region_line(region_index: int) -> int | None:
                subgraph = (
                    getattr(shell, "dispatch_subgraphs", ())
                    [int(region_index)]
                    if int(region_index) < len(
                        getattr(shell, "dispatch_subgraphs", ())
                    ) else None
                )
                if subgraph is None:
                    return None
                lines = []
                for node_id in subgraph.G.graph.get("deployment_nodes", ()):
                    node = graph_obj.nodes.get(int(node_id)) or {}
                    line = (node.get("source_span") or {}).get("line")
                    if line is None:
                        line = getattr(node.get("expr_obj"), "lineno", None)
                    if line is not None and int(line) >= 0:
                        lines.append(int(line))
                return min(lines) if lines else None

            region_lines = {
                int(region_index): earliest_region_line(int(region_index))
                for region_index in control.region_indices
            }
            anchored_controls = []
            for conditional_control, block in zip(
                conditional_controls, conditional_blocks
            ):
                if (
                    conditional_control.region_indices
                    or block is None
                    or block.source_node_id is None
                ):
                    anchored_controls.append(conditional_control)
                    continue
                expression = source_expressions.get(int(block.source_node_id))
                conditional_line = getattr(expression, "lineno", None)
                anchor = None
                if conditional_line is not None:
                    anchor = next((
                        int(region_index)
                        for region_index in control.region_indices
                        if region_lines.get(int(region_index)) is not None
                        and region_lines[int(region_index)] > int(conditional_line)
                    ), None)
                anchored_controls.append(
                    replace(conditional_control, anchor_region=anchor)
                )
            conditional_controls = tuple(anchored_controls)
            control = overlay_scheduled_control(
                control.region_indices,
                (control, *conditional_controls),
                known_nesting={
                    parent: tuple(children)
                    for parent, children in direct_children.items()
                },
            )
            def marker_counts(block, counts):
                from .control_source import (
                    CallBlock, ConditionalBlock, LoopBlock,
                    ParallelDeployment, SequenceBlock, StateMachineTick,
                    StatementBlock, WhileBlock,
                )
                if isinstance(block, StatementBlock):
                    if (
                        len(block.lines) == 1
                        and block.lines[0].startswith("__scheduled_region_")
                    ):
                        index = int(
                            block.lines[0][len("__scheduled_region_"):-2]
                        )
                        counts[index] = counts.get(index, 0) + 1
                elif isinstance(block, SequenceBlock):
                    for child in block.blocks:
                        marker_counts(child, counts)
                elif isinstance(block, ConditionalBlock):
                    marker_counts(block.body, counts)
                    if block.orelse is not None:
                        marker_counts(block.orelse, counts)
                elif isinstance(block, (LoopBlock,)):
                    marker_counts(block.body, counts)
                elif isinstance(block, WhileBlock):
                    marker_counts(block.condition, counts)
                    marker_counts(block.body, counts)
                elif isinstance(block, StateMachineTick):
                    for _case, body in block.cases:
                        marker_counts(body, counts)
                    if block.default is not None:
                        marker_counts(block.default, counts)
                elif isinstance(block, ParallelDeployment):
                    for lane in block.lanes:
                        marker_counts(lane, counts)
                elif isinstance(block, CallBlock):
                    marker_counts(block.callee, counts)
            counts = {}
            marker_counts(control.root, counts)
            duplicates = {
                region: count for region, count in counts.items()
                if count != 1
            }
            if duplicates:
                raise FortranEmissionError(
                    "conditional control duplicated scheduled regions in "
                    f"{function_name!r}: {duplicates!r}"
                )
            lowered_conditional_count = len(conditional_controls)
        control = _nest_lexical_conditionals_in_loops(
            control, graph, getattr(shell, "dispatch_subgraphs", ()),
        )
        # Loop recurrence selection needs the complete conditional topology.
        # Some conditionals already live in the source loop and are enriched
        # above, while others are ordinary controls inserted by the overlay.
        # Running the finite continuation walk before that overlay truncates a
        # legal chain at the last pre-existing conditional.  Defer this one
        # operation until every conditional has been nested, then derive the
        # unique terminal continuation once from the complete graph.
        from .control_source import enrich_represented_conditionals
        control, continuation_receipts = enrich_represented_conditionals(
            control, (), enrich_loop_continuations=True,
        )
        if continuation_receipts:
            enrichment_ledger = list(graph_obj.graph.get(
                "conditional_control_enrichment_receipts", ()
            ))
            for receipt in continuation_receipts:
                if receipt not in enrichment_ledger:
                    enrichment_ledger.append(receipt)
            graph_obj.graph[
                "conditional_control_enrichment_receipts"
            ] = tuple(enrichment_ledger)
        control = _place_plan_callsites_lexically(
            control, graph, getattr(shell, "hierarchy_plan", None),
            getattr(shell, "dispatch_subgraphs", ()),
        )
        control, lexical_sequence_shortfalls = _install_lexical_sequence_mutations(
            control,
            graph,
            getattr(shell, "dispatch_subgraphs", ()),
            extra_mutations=_dict_literal_mutations(graph_obj),
        )
        control, lexical_query_shortfalls = _install_lexical_sequence_queries(
            control,
            graph,
            getattr(shell, "dispatch_subgraphs", ()),
        )
        structurally_owned_regions = {
            int(index)
            for reduction in getattr(shell, "loop_shader_reductions", ())
            if reduction.control_program is not None
            for index in reduction.structurally_owned_region_indices
        } | {
            int(index)
            for reduction in getattr(shell, "loop_shader_reductions", ())
            for index in reduction.domain_region_indices
        }
        resident_value_ids = _region_resident_value_ids(
            subgraph for index, subgraph in enumerate(getattr(shell, "dispatch_subgraphs", ()))
            if index not in structurally_owned_regions
        )
        control = _attach_graph_control_expressions(
            control, graph_obj, resident=resident_value_ids,
        )
